// [ADR-138] mock env-dispatcher: dispatchEnvChange delegates to impl mocks
const _SKY_KEYS_M = [
    'skyMode',
    'skyColorTop',
    'skyColorMid',
    'skyColorBot',
    'skyTexture',
    'skyRotationY',
    'skyRotationSpeed',
    'skyBrightness',
    'starsEnabled',
    'starsTexture',
    'iblIntensity',
    'sunAngle',
    'azimuth',
];
const _GROUND_KEYS_M = [
    'groundType',
    'groundStyle',
    'groundColor',
    'groundColor2',
    'groundTexture',
    'groundLevel',
    'groundPitch',
    'groundRoll',
    'groundScrollSpeedX',
    'groundScrollSpeedZ',
    'groundTileScale',
    'groundReflectionEnabled',
    'groundReflectionQuality',
    'groundEdgeFadeStart',
    'groundEdgeFadeEnd',
    'terrainHeight',
    'terrainScale',
    'terrainSeed',
    'terrainOctaves',
    'groundGradient',
    'groundFade',
    'groundCheckerColor1',
    'groundCheckerColor2',
    'groundMode',
    'groundVisibleEnabled',
    'groundAlpha',
    'groundTextureEnabled',
    'groundTextureScale',
    'groundTextureRotation',
    'groundTerrainHeight',
    'groundTerrainScale',
    'groundTerrainSeed',
