    'groundLineColor',
    'groundEdgeFade',
    'groundPattern',
    'groundReflectionBlend',
    'groundNormalTexture',
    'groundNormalStrength',
    'groundElevationColoringEnabled',
];
const _FOG_KEYS_M = ['fogEnabled', 'fogColor', 'fogDensity', 'fogMode', 'fogStart', 'fogEnd'];
const _WATER_KEYS_M = [
    'waterEnabled',
    'waterColor',
    'waterOpacity',
    'waterLevel',
    'waterWaveSpeed',
    'waterWaveHeight',
    'waterWaveLength',
    'waterReflectionEnabled',
    'waterReflectionQuality',
    'waterRefraction',
    'waterRefractionIndex',
