    'waterPresetName',
    'waterAnimSpeed',
    'environmentPreset',
];
const _PARTICLE_KEYS_M = [
    'particleEnabled',
    'particleType',
    'particleDensity',
    'particleSize',
    'particleSpeed',
    'particleEmitRate',
    'particleSplashEnabled',
    'particleCustomTexture',
    'windEnabled',
    'windStrength',
    'windDirection',
];
const _CLOUD_KEYS_M = [
