} from '../scene/scene';

function makeMockMat(origR = 1, origG = 1, origB = 1) {
    const mat = new StandardMaterial('skin');
    mat.diffuseColor.r = origR;
    mat.diffuseColor.g = origG;
    mat.diffuseColor.b = origB;
    return mat;
}

class SpyColor3 {
    r = 0;
    g = 0;
    b = 0;
    set = vi.fn((r: number, g: number, b: number) => {
        this.r = r;
        this.g = g;
        this.b = b;
    });
    clone() {
        return { r: this.r, g: this.g, b: this.b, set: this.set, clone: () => this };
    }
}

function applyPerMatToBabylonMat(
    mat: {
        diffuseColor: SpyColor3;
        specularColor: SpyColor3;
        specularPower: number;
        ambientColor: SpyColor3;
    },
    origDiffuse: { r: number; g: number; b: number },
    params: { diffuseMul: number; specularMul: number; shininess: number; ambientMul: number }
): void {
    mat.diffuseColor.set(
        origDiffuse.r * params.diffuseMul,
        origDiffuse.g * params.diffuseMul,
        origDiffuse.b * params.diffuseMul
    );
    mat.specularColor.set(
        0.8 * params.specularMul,
        0.8 * params.specularMul,
        0.8 * params.specularMul
    );
    mat.specularPower = params.shininess;
    mat.ambientColor.set(0.3 * params.ambientMul, 0.3 * params.ambientMul, 0.3 * params.ambientMul);
}

describe('_applyAll ordering: per-material overrides category on re-apply', () => {
    const TEST_ID = '_applyAll_test';

    beforeEach(() => {
        _catState.clear();
        _matState.clear();
        _matEnabled.clear();
        const old = modelRegistry.get(TEST_ID);
        if (old) {
            modelRegistry.delete(TEST_ID);
        }
    });

    afterEach(() => {
        if (modelRegistry.get(TEST_ID)) {
            modelRegistry.delete(TEST_ID);
        }
    });

    it('per-material diffuse overrides category after category re-apply', () => {
        const mats = [makeMockMat(1, 1, 1)];
        // @ts-expect-error duck-typed mock material
        modelRegistry.set(TEST_ID, { meshes: [{ material: mats[0] }] });
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 0.5,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        expect(mats[0].diffuseColor.r).toBeCloseTo(0.5);
        setMatParams(TEST_ID, 0, { diffuseMul: 0.9, specularMul: 1, shininess: 50, ambientMul: 1 });
        expect(mats[0].diffuseColor.r).toBeCloseTo(0.9);
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 0.3,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        expect(mats[0].diffuseColor.r).toBeCloseTo(0.9);
    });

    it('per-material specular overrides category after category re-apply', () => {
        const mats = [makeMockMat(1, 1, 1)];
        // @ts-expect-error duck-typed mock material
        modelRegistry.set(TEST_ID, { meshes: [{ material: mats[0] }] });
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 0.5,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        setMatParams(TEST_ID, 0, { diffuseMul: 1, specularMul: 2, shininess: 50, ambientMul: 1 });
        expect(mats[0].specularColor.r).toBeCloseTo(1.6);
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 0.2,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        expect(mats[0].specularColor.r).toBeCloseTo(1.6);
    });

    it('per-material shininess survives category re-apply', () => {
        const mats = [makeMockMat(1, 1, 1)];
        // @ts-expect-error duck-typed mock material
        modelRegistry.set(TEST_ID, { meshes: [{ material: mats[0] }] });
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        setMatParams(TEST_ID, 0, { diffuseMul: 1, specularMul: 1, shininess: 120, ambientMul: 1 });
        expect(mats[0].specularPower).toBe(120);
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 1,
            shininess: 30,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        expect(mats[0].specularPower).toBe(120);
    });

    it('per-material ambient overrides category after category re-apply', () => {
        const mats = [makeMockMat(1, 1, 1)];
        // @ts-expect-error duck-typed mock material
        modelRegistry.set(TEST_ID, { meshes: [{ material: mats[0] }] });
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 1,
            shininess: 50,
            ambientMul: 0.5,
        });
        _applyAll(TEST_ID);
        setMatParams(TEST_ID, 0, { diffuseMul: 1, specularMul: 1, shininess: 50, ambientMul: 1.5 });
        expect(mats[0].ambientColor.r).toBeCloseTo(0.45);
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 1,
            specularMul: 1,
            shininess: 50,
            ambientMul: 0.1,
        });
        _applyAll(TEST_ID);
        expect(mats[0].ambientColor.r).toBeCloseTo(0.45);
    });

    it('multiple material indices are independent under re-apply', () => {
        const m1 = makeMockMat(1, 1, 1);
        const m2 = makeMockMat(1, 1, 1);
        // @ts-expect-error duck-typed mock material
        modelRegistry.set(TEST_ID, { meshes: [{ material: m1 }, { material: m2 }] });
        setMatCatParams(TEST_ID, '皮肤', {
            diffuseMul: 0.5,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        _applyAll(TEST_ID);
        setMatParams(TEST_ID, 0, { diffuseMul: 0.9, specularMul: 1, shininess: 50, ambientMul: 1 });
        _applyAll(TEST_ID);
        expect(m1.diffuseColor.r).toBeCloseTo(0.9);
        expect(m2.diffuseColor.r).toBeCloseTo(0.5);
        _applyAll(TEST_ID);
        expect(m1.diffuseColor.r).toBeCloseTo(0.9);
        expect(m2.diffuseColor.r).toBeCloseTo(0.5);
    });
});

describe('per-material params write through to Babylon material properties', () => {
    it('writes diffuseMul → diffuseColor.set with correct multiplier', () => {
        const mat = {
            diffuseColor: new SpyColor3(),
            specularColor: new SpyColor3(),
            specularPower: 50,
            ambientColor: new SpyColor3(),
        };
        const orig = { r: 0.8, g: 0.6, b: 0.4 };
        applyPerMatToBabylonMat(mat, orig, {
            diffuseMul: 0.5,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        expect(mat.diffuseColor.set).toHaveBeenCalledTimes(1);
        expect(mat.diffuseColor.set).toHaveBeenCalledWith(0.4, 0.3, 0.2);
    });

    it('writes specularMul → specularColor.set with correct multiplier', () => {
        const mat = {
            diffuseColor: new SpyColor3(),
            specularColor: new SpyColor3(),
            specularPower: 50,
            ambientColor: new SpyColor3(),
        };
        applyPerMatToBabylonMat(
            mat,
            { r: 1, g: 1, b: 1 },
            { diffuseMul: 1, specularMul: 1.5, shininess: 50, ambientMul: 1 }
        );
        expect(mat.specularColor.set).toHaveBeenCalledTimes(1);
        expect(mat.specularColor.r).toBeCloseTo(1.2, 10);
    });

    it('writes shininess → specularPower assignment', () => {
        const mat = {
            diffuseColor: new SpyColor3(),
            specularColor: new SpyColor3(),
            specularPower: 50,
            ambientColor: new SpyColor3(),
        };
        applyPerMatToBabylonMat(
            mat,
            { r: 1, g: 1, b: 1 },
            { diffuseMul: 1, specularMul: 1, shininess: 120, ambientMul: 1 }
        );
        expect(mat.specularPower).toBe(120);
    });

    it('writes ambientMul → ambientColor.set with correct multiplier', () => {
        const mat = {
            diffuseColor: new SpyColor3(),
            specularColor: new SpyColor3(),
            specularPower: 50,
            ambientColor: new SpyColor3(),
        };
        applyPerMatToBabylonMat(
            mat,
            { r: 1, g: 1, b: 1 },
            { diffuseMul: 1, specularMul: 1, shininess: 50, ambientMul: 2 }
        );
        expect(mat.ambientColor.set).toHaveBeenCalledWith(0.6, 0.6, 0.6);
    });

    it('write-through is idempotent', () => {
        const mat = {
            diffuseColor: new SpyColor3(),
            specularColor: new SpyColor3(),
            specularPower: 50,
            ambientColor: new SpyColor3(),
        };
        const orig = { r: 1, g: 1, b: 1 };
        applyPerMatToBabylonMat(mat, orig, {
            diffuseMul: 0.5,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        applyPerMatToBabylonMat(mat, orig, {
            diffuseMul: 0.5,
            specularMul: 1,
            shininess: 50,
            ambientMul: 1,
        });
        expect(mat.diffuseColor.set).toHaveBeenCalledTimes(2);
        expect(mat.diffuseColor.r).toBeCloseTo(0.5);
    });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SlideMenu } from '../../menus/menu';
import type { PopupLevel, PopupRow } from '../../core/config';
import { makeTestLevel, makeTestMenu } from '../fixtures/menu';

// ─── SlideMenu 测试：焦点全面（setupFocus/clearFocus/applyFocus/activateFocused） ───

describe('SlideMenu — 焦点全面 (setupFocus/clearFocus/applyFocus/activateFocused)', () => {
    let container: HTMLElement;
    let menu: SlideMenu;

    beforeEach(() => {
        const m = makeTestMenu();
        container = m.container;
        menu = m.menu;
    });

    async function initWithItems(items: PopupRow[]): Promise<void> {
        const p = new Promise<void>((resolve) => {
            const orig = (menu as any).onAfterRender;
            (menu as any).onAfterRender = () => {
                (menu as any).onAfterRender = orig;
                orig?.();
                resolve();
            };
        });
        menu.reset({ label: 'F', dir: '', items });
        await p;
    }

    it('setupFocus 初始化焦点为 0 并应用样式', async () => {
        await initWithItems([{ kind: 'action' as const, label: 'A', icon: 'i', target: 'a' }]);
        expect((menu as any).focusIndex).toBe(0);
        expect(container.querySelector('.slide-focused')).toBeTruthy();
    });

    it('setupFocus 空列表时 focusIndex 为 -1', async () => {
        await initWithItems([]);
        expect((menu as any).focusIndex).toBe(-1);
        expect(container.querySelector('.slide-focused')).toBeFalsy();
    });

    it('clearFocus 移除焦点样式', async () => {
        await initWithItems([
            { kind: 'action' as const, label: 'A', icon: 'i', target: 'a' },
            { kind: 'action' as const, label: 'B', icon: 'i', target: 'b' },
        ]);
        (menu as any).clearFocus();
        expect(container.querySelector('.slide-focused')).toBeFalsy();
    });

    it('panelItems 纳入滑块行(.cs-row 含 .cs-bar)与开关行(.toggle-row)', async () => {
        // 用 renderCustom 注入真实控件行 DOM，验证方向键导航范围已扩展
        const level: PopupLevel = {
            label: 'F',
            dir: '',
            items: [],
            renderCustom: (c) => {
                const sliderRow = document.createElement('div');
                sliderRow.className = 'cs-row';
                const bar = document.createElement('div');
                bar.className = 'cs-bar';
                bar.tabIndex = 0;
                sliderRow.appendChild(bar);
                c.appendChild(sliderRow);
                const toggleRow = document.createElement('div');
                toggleRow.className = 'toggle-row';
                const input = document.createElement('input');
                input.type = 'checkbox';
                toggleRow.appendChild(input);
                c.appendChild(toggleRow);
                // 无控件的提示行（.cs-row 但无 .cs-bar）—— 不应被纳入
                const hintRow = document.createElement('div');
                hintRow.className = 'cs-row';
                c.appendChild(hintRow);
            },
        };
        const p = new Promise<void>((resolve) => {
            (menu as any).onAfterRender = () => resolve();
        });
        menu.reset(level);
        await p;

        const items = (menu as any).panelItems as HTMLElement[];
        expect(
            items.some((el) => el.classList.contains('cs-row') && el.querySelector('.cs-bar'))
        ).toBe(true);
        expect(items.some((el) => el.classList.contains('toggle-row'))).toBe(true);
        // 无 .cs-bar 的提示行被排除
        expect(items.filter((el) => el.classList.contains('cs-row')).length).toBe(1);
    });

    it('panelItems 纳入模式切换器(.cs-row+.cs-top[role=listbox])与 type-row', async () => {
        // 回归防护：mode-slider / type-row 曾因无 .cs-bar 而被遗漏，契约制应纳入
        const level: PopupLevel = {
            label: 'F',
            dir: '',
            items: [],
            renderCustom: (c) => {
                // 模式切换器（listbox，无 .cs-bar）
                const modeRow = document.createElement('div');
                modeRow.className = 'cs-row';
                const top = document.createElement('div');
                top.className = 'cs-top';
                top.tabIndex = 0;
                top.setAttribute('role', 'listbox');
                modeRow.appendChild(top);
                c.appendChild(modeRow);
                // type-row
                const typeRow = document.createElement('div');
                typeRow.className = 'type-row';
                c.appendChild(typeRow);
            },
        };
        const p = new Promise<void>((resolve) => {
            (menu as any).onAfterRender = () => resolve();
        });
        menu.reset(level);
        await p;

        const items = (menu as any).panelItems as HTMLElement[];
        expect(items.some((el) => el.classList.contains('cs-row'))).toBe(true);
        expect(items.some((el) => el.classList.contains('type-row'))).toBe(true);
        // 模式切换器声明了 ←→ 调值让位
        const modeItem = items.find((el) => el.classList.contains('cs-row'))!;
        expect(modeItem.getAttribute('data-nav-adjust')).toBe('horizontal');
        expect(modeItem.getAttribute('data-nav-focus')).toBe('.cs-top[role="listbox"]');
    });

    it('preset-group chips 组标记为二维导航站（data-nav-group）', async () => {
        const level: PopupLevel = {
            label: 'F',
            dir: '',
            items: [],
            renderCustom: (c) => {
                const group = document.createElement('div');
                group.className = 'preset-group';
                for (let i = 0; i < 3; i++) {
                    const chip = document.createElement('button');
                    chip.className = 'preset-chip' + (i === 1 ? ' active' : '');
                    chip.textContent = `chip-${i}`;
                    group.appendChild(chip);
                }
                c.appendChild(group);
            },
        };
        const p = new Promise<void>((resolve) => {
            (menu as any).onAfterRender = () => resolve();
        });
        menu.reset(level);
        await p;

        const items = (menu as any).panelItems as HTMLElement[];
        const groupRow = items.find((el) => el.classList.contains('preset-group'))!;
        expect(groupRow).toBeTruthy();
        expect(groupRow.getAttribute('data-nav-group')).toBe('.preset-chip:not(.badge)');
        // 组行隐含 ←→ 让位
        expect(groupRow.getAttribute('data-nav-adjust')).toBe('horizontal');
    });

    it('applyFocus 给当前焦点索引添加样式', async () => {
        await initWithItems([
