describe('Water 小波开关 — smallWaveEnabled 门控 shader 振幅', () => {
    function captureSmallWave(state: Partial<typeof envState>): number | undefined {
        const calls: Array<[string, number]> = [];
        const spy = vi.spyOn(ShaderMaterial.prototype, 'setFloat').mockImplementation(function (
            this: ShaderMaterial,
            name: string,
            value: number
        ) {
            calls.push([name, value]);
            return this;
        });
        try {
            createWater(makeWaterState({ waterLevel: 0, smallWaveHeight: 1.0, ...state }));
        } finally {
            spy.mockRestore();
        }
        // 取最后一次写入（同步函数在 createWater 内被调用）
        const hit = [...calls].reverse().find(([n]) => n === 'smallWaveHeight');
        return hit?.[1];
    }

    it('smallWaveEnabled=true 时 shader 收到原振幅', () => {
        expect(captureSmallWave({ smallWaveEnabled: true })).toBe(1.0);
    });

    it('smallWaveEnabled=false 时 shader 收到 0 振幅', () => {
        expect(captureSmallWave({ smallWaveEnabled: false })).toBe(0);
    });

    it('字段缺失时兜底为开启（?? true）', () => {
        const s = makeWaterState({ waterLevel: 0, smallWaveHeight: 0.8 });
        delete (s as Record<string, unknown>).smallWaveEnabled;
        const calls: Array<[string, number]> = [];
        const spy = vi.spyOn(ShaderMaterial.prototype, 'setFloat').mockImplementation(function (
            this: ShaderMaterial,
            name: string,
            value: number
        ) {
            calls.push([name, value]);
            return this;
        });
        try {
            createWater(s);
        } finally {
            spy.mockRestore();
        }
        const hit = [...calls].reverse().find(([n]) => n === 'smallWaveHeight');
        expect(hit?.[1]).toBe(0.8);
    });
});

// ──────────────── 大波 / 焦散开关门控（ADR-211 Part3）────────────────
describe('Water 大波/焦散开关 — enabled 门控 shader uniform', () => {
    // 捕获 createWater 内 _syncWaterUniforms 对指定 uniform 的最后一次写入
    function captureUniform(uniform: string, state: Partial<typeof envState>): number | undefined {
        const calls: Array<[string, number]> = [];
        const spy = vi.spyOn(ShaderMaterial.prototype, 'setFloat').mockImplementation(function (
            this: ShaderMaterial,
            name: string,
            value: number
        ) {
            calls.push([name, value]);
            return this;
        });
        try {
            createWater(makeWaterState({ waterLevel: 0, ...state }));
        } finally {
            spy.mockRestore();
        }
        return [...calls].reverse().find(([n]) => n === uniform)?.[1];
    }

    it('bigWaveEnabled=true 时 bigWaveHeight 送原振幅', () => {
        expect(captureUniform('bigWaveHeight', { bigWaveEnabled: true, bigWaveHeight: 1.0 })).toBe(
            1.0
        );
    });

    it('bigWaveEnabled=false 时 bigWaveHeight 送 0', () => {
        expect(captureUniform('bigWaveHeight', { bigWaveEnabled: false, bigWaveHeight: 1.0 })).toBe(
            0
        );
    });

    it('causticEnabled=true 时 uCausticIntensity 送原强度', () => {
        expect(
            captureUniform('uCausticIntensity', { causticEnabled: true, causticIntensity: 0.3 })
        ).toBe(0.3);
    });

    it('causticEnabled=false 时 uCausticIntensity 送 0', () => {
        expect(
            captureUniform('uCausticIntensity', { causticEnabled: false, causticIntensity: 0.3 })
        ).toBe(0);
    });

    // ADR-217: 地水无限尺寸单源 — 水面地平线淡出距离据 effectiveGroundSize 派生
    it('groundInfiniteEnabled=false 时 uHorizonStart 基于 groundSize（非无限）', () => {
        // uHorizonStart = effectiveGroundSize(500, false) * 0.7 = 350
        expect(
            captureUniform('uHorizonStart', { groundSize: 500, groundInfiniteEnabled: false })
        ).toBe(350);
    });

    it('groundInfiniteEnabled=true 时 uHorizonStart 推到无限尺寸 2000（与地面延伸对齐）', () => {
        // uHorizonStart = effectiveGroundSize(500, true) * 0.7 = 2000 * 0.7 = 1400
        // 验证开无限后水面淡出不再卡在 350（消除甜甜圈）
        expect(
            captureUniform('uHorizonStart', { groundSize: 500, groundInfiniteEnabled: true })
        ).toBe(1400);
    });
});

