        expect(released.has('上半身')).toBe(true);
        // 释放后 getOwnedBones 为空
        expect(getOwnedBones('m1', 'body-posture').size).toBe(0);
    });

    it('[conflict-visibility] 落败模块记录被抢占骨骼', () => {
