beforeEach(() => {
    vi.clearAllMocks();
    mocks.implReturn = mocks.mockImpl;
    mocks.windActive = true;
    mocks.windRaw = { x: 3, y: 0, z: 4 };
    mocks.onSyncObservable._notify = () => {};
    mocks.bundleA.applyCentralForce.mockClear();
    mocks.bundleB.applyCentralForce.mockClear();
    mocks.bodyA.applyCentralForce.mockClear();
    mocks.bodyB.applyCentralForce.mockClear();
    mocks.applyForceToModelRigidBodiesNative.mockClear();
    mocks.applyWindForceToModelRigidBodiesNative.mockClear();
    // 将 observe mock 连接到 _notify 回调机制
    mockObserve.mockImplementation((_obs: unknown, cb: () => void) => {
        mocks.onSyncObservable._notify = () => cb();
        return mocks.observerHandle;
    });
    disposeWindPhysics();
});

afterEach(() => {
    disposeWindPhysics();
});

describe('wind-physics 状态机', () => {
    describe('initWindPhysics', () => {
        it('JS 运行时空转（不订阅、不抛异常）', () => {
            const runtime = makeJsRuntime();
            initWindPhysics(runtime);

            expect(observe).not.toHaveBeenCalled();
            expect(getPhysicsImpl).not.toHaveBeenCalled();
        });

        it('WASM 运行时且 impl 就绪：立即订阅 onSyncObservable', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            expect(getPhysicsImpl).toHaveBeenCalledWith(runtime);
            expect(observe).toHaveBeenCalledTimes(1);
        });

        it('WASM 运行时但 impl 未就绪：注册 runtime 但不订阅（由 retry 补）', () => {
            mocks.implReturn = null;
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            expect(getPhysicsImpl).toHaveBeenCalledWith(runtime);
            expect(observe).not.toHaveBeenCalled();
        });

        it('幂等：重复调用不重复订阅', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);
            initWindPhysics(runtime);
            initWindPhysics(runtime);

            expect(observe).toHaveBeenCalledTimes(1);
        });
    });

    describe('retryWindPhysicsSubscription', () => {
        it('impl 就绪后补订阅成功', () => {
            mocks.implReturn = null;
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);
            expect(observe).not.toHaveBeenCalled();

            // 模拟模型加载后 impl 就绪
            mocks.implReturn = mocks.mockImpl;
            retryWindPhysicsSubscription(runtime);

            expect(observe).toHaveBeenCalledTimes(1);
        });

        it('impl 仍不可用时重试不订阅（不抛异常）', () => {
            mocks.implReturn = null;
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            retryWindPhysicsSubscription(runtime);

            expect(observe).not.toHaveBeenCalled();
        });

        it('已订阅后重试不重复订阅', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);
            expect(observe).toHaveBeenCalledTimes(1);

            retryWindPhysicsSubscription(runtime);

            expect(observe).toHaveBeenCalledTimes(1);
        });

        it('省略 runtime 参数时重试所有已注册 runtime', () => {
            mocks.implReturn = null;
            const rt1 = makeWasmRuntime();
            const rt2 = makeWasmRuntime();
            initWindPhysics(rt1);
            initWindPhysics(rt2);
            expect(observe).not.toHaveBeenCalled();

            mocks.implReturn = mocks.mockImpl;
            retryWindPhysicsSubscription(); // 全局重试

            expect(observe).toHaveBeenCalledTimes(2);
        });
    });

    describe('disposeWindPhysics', () => {
        it('移除所有 observer 并清空注册表', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);
            expect(observe).toHaveBeenCalledTimes(1);

            disposeWindPhysics();

            expect(mocks.observerHandle.dispose).toHaveBeenCalledTimes(1);
        });

        it('dispose 后再 initWindPhysics 可重新订阅', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);
            disposeWindPhysics();

            vi.clearAllMocks();
            initWindPhysics(runtime);

            expect(observe).toHaveBeenCalledTimes(1);
        });

        it('空 dispose 不抛异常', () => {
            expect(() => disposeWindPhysics()).not.toThrow();
        });
    });

    describe('_onPhysicsSync — 风力施加', () => {
        it('风力活跃时对所有 Bundle 的所有刚体施加风力', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            // 手动触发 onSync 回调
            mocks.onSyncObservable._notify();

            // 验证风力向量 = 方向 × 速度 × WIND_FORCE_SCALE(1.0)
            const expectedForce = new Vector3(3, 0, 4);

            // bundleA 有 3 个刚体，bundleB 有 2 个
            expect(mocks.bundleA.applyCentralForce).toHaveBeenCalledTimes(3);
            expect(mocks.bundleB.applyCentralForce).toHaveBeenCalledTimes(2);
            const call0 = mocks.bundleA.applyCentralForce.mock.calls[0];
            expect(call0[0]).toBe(0); // 第 0 个刚体
            expect(call0[1].x).toBeCloseTo(expectedForce.x);
            expect(call0[1].y).toBeCloseTo(expectedForce.y);
            expect(call0[1].z).toBeCloseTo(expectedForce.z);

            // 路径1 修正：单数容器（虚拟裙骨/地面）也受风，每个刚体调用 1 次
            expect(mocks.bodyA.applyCentralForce).toHaveBeenCalledTimes(1);
            expect(mocks.bodyB.applyCentralForce).toHaveBeenCalledTimes(1);
            const sCall0 = mocks.bodyA.applyCentralForce.mock.calls[0];
            expect(sCall0[0].x).toBeCloseTo(expectedForce.x);
            expect(sCall0[0].y).toBeCloseTo(expectedForce.y);
            expect(sCall0[0].z).toBeCloseTo(expectedForce.z);

            // 路径2（ADR-200 wind mass-aware）：原生刚体走 wasm 质量感知导出，actor 模型调用 1 次
            expect(mocks.applyWindForceToModelRigidBodiesNative).toHaveBeenCalledTimes(1);
            const wCall0 = mocks.applyWindForceToModelRigidBodiesNative.mock.calls[0];
            expect(wCall0[0]).toBe(mocks.wasmInstance); // 传入 wasm 实例
            expect(wCall0[1]).toBe(mocks.actorModel); // 传入 actor 的 mmdModel
            expect(wCall0[2].x).toBeCloseTo(15); // 独立系数 MODEL_WIND_FORCE_SCALE(5.0)：(3,0,4)×5
            expect(wCall0[2].z).toBeCloseTo(20);
            // 质量感知参数：referenceMass=1.0, minScale=0.2
            expect(wCall0[3]).toBeCloseTo(1.0);
            expect(wCall0[4]).toBeCloseTo(0.2);
            // 降级路径不应触发（wind mass-aware 导出可用）
            expect(mocks.applyForceToModelRigidBodiesNative).not.toHaveBeenCalled();
        });

        it('风力不活跃时跳过（不施加力）', () => {
            mocks.windActive = false;
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            mocks.onSyncObservable._notify();

            expect(mocks.bundleA.applyCentralForce).not.toHaveBeenCalled();
            expect(mocks.bundleB.applyCentralForce).not.toHaveBeenCalled();
            expect(mocks.bodyA.applyCentralForce).not.toHaveBeenCalled();
            expect(mocks.bodyB.applyCentralForce).not.toHaveBeenCalled();
        });

        it('Bundle 列表为空时不抛异常', () => {
            // 清空 bundle 列表
            vi.mocked(getRigidBodyBundleMap).mockReturnValueOnce([]);
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            expect(() => mocks.onSyncObservable._notify()).not.toThrow();
        });

        it('对 actor 模型的原生刚体施力，跳过 stage（ADR-200）', () => {
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            mocks.onSyncObservable._notify();

            // modelRegistry 有 1 actor + 1 stage，仅 actor 被施力（wind mass-aware 签名：wasmInstance, model, force, refMass, minScale）
            expect(mocks.applyWindForceToModelRigidBodiesNative).toHaveBeenCalledTimes(1);
            const call0 = mocks.applyWindForceToModelRigidBodiesNative.mock.calls[0];
            expect(call0[0]).toBe(mocks.wasmInstance); // 传入 wasm 实例
            expect(call0[1]).toBe(mocks.actorModel); // 传入 actor 的 mmdModel
            // 模型原生刚体用独立系数 MODEL_WIND_FORCE_SCALE(5.0)：(3,0,4) × 5 = (15,0,20)
            expect(call0[2].x).toBeCloseTo(15);
            expect(call0[2].z).toBeCloseTo(20);
            // 降级路径不应触发
            expect(mocks.applyForceToModelRigidBodiesNative).not.toHaveBeenCalled();
        });

        it('wind mass-aware 导出缺失时降级到旧版等力施力', () => {
            // 模拟 wind mass-aware 导出返回 0（缺导出/无 bundle）
            mocks.applyWindForceToModelRigidBodiesNative.mockReturnValueOnce(0);
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            mocks.onSyncObservable._notify();

            // wind mass-aware 被调用一次
            expect(mocks.applyWindForceToModelRigidBodiesNative).toHaveBeenCalledTimes(1);
            // 降级：旧版 applyForceToModelRigidBodiesNative 也被调用一次
            expect(mocks.applyForceToModelRigidBodiesNative).toHaveBeenCalledTimes(1);
            const fallCall = mocks.applyForceToModelRigidBodiesNative.mock.calls[0];
            expect(fallCall[0]).toBe(mocks.wasmInstance);
            expect(fallCall[1]).toBe(mocks.actorModel);
        });

        it('风力不活跃时不对模型原生刚体施力', () => {
            mocks.windActive = false;
            const runtime = makeWasmRuntime();
            initWindPhysics(runtime);

            mocks.onSyncObservable._notify();

            expect(mocks.applyForceToModelRigidBodiesNative).not.toHaveBeenCalled();
        });
    });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import {
    ErrorRingBuffer,
    errorBuffer,
    captureError,
    getErrors,
    clearErrors,
    installErrorCaptureOn,
    installGlobalErrorCapture,
    installLoggingPatch,
    uninstallLoggingPatch,
    toDiagnosticContext,
    type ErrorEntry,
    type GlobalErrorTarget,
} from '../ai/error-buffer';

/** 构造可注入的假全局目标，记录监听并在 dispatch 时回放。 */
function fakeTarget() {
    const handlers: Record<string, Array<(ev: unknown) => void>> = {};
    const target: GlobalErrorTarget & { dispatch(type: string, ev: unknown): void } = {
        addEventListener(type, fn) {
            (handlers[type] ||= []).push(fn);
        },
        removeEventListener(type, fn) {
            handlers[type] = (handlers[type] || []).filter((h) => h !== fn);
        },
        dispatch(type, ev) {
            (handlers[type] || []).forEach((h) => h(ev));
        },
    };
    return target;
}

describe('ErrorRingBuffer 环形语义', () => {
    it('新建容量为正整数，非法容量抛 RangeError', () => {
        expect(() => new ErrorRingBuffer(0)).toThrow(RangeError);
        expect(() => new ErrorRingBuffer(1.5)).toThrow(RangeError);
        expect(new ErrorRingBuffer(3).capacity).toBe(3);
    });

    it('push 后 size / toArray 顺序 / newest / oldest 正确', () => {
        const buf = new ErrorRingBuffer(3);
        buf.push({ kind: 'log', tag: 'a', message: 'm1', timestamp: 1, severity: 'warn' });
        buf.push({ kind: 'log', tag: 'b', message: 'm2', timestamp: 2, severity: 'warn' });
        expect(buf.size).toBe(2);
        expect(buf.full).toBe(false);
        const arr = buf.toArray();
        expect(arr.map((e) => e.message)).toEqual(['m1', 'm2']);
        expect(buf.oldest?.message).toBe('m1');
        expect(buf.newest?.message).toBe('m2');
    });

    it('超过容量时覆盖最旧条目，size 封顶', () => {
        const buf = new ErrorRingBuffer(3);
        for (let i = 1; i <= 5; i++) {
            buf.push({ kind: 'log', tag: 't', message: `m${i}`, timestamp: i, severity: 'warn' });
        }
        expect(buf.size).toBe(3);
        expect(buf.full).toBe(true);
        expect(buf.toArray().map((e) => e.message)).toEqual(['m3', 'm4', 'm5']);
        expect(buf.oldest?.message).toBe('m3');
        expect(buf.newest?.message).toBe('m5');
    });

    it('clear 后 size 归零、toArray 为空', () => {
        const buf = new ErrorRingBuffer(2);
        buf.push({ kind: 'log', tag: 't', message: 'x', timestamp: 1, severity: 'warn' });
        buf.clear();
        expect(buf.size).toBe(0);
        expect(buf.toArray()).toEqual([]);
        expect(buf.newest).toBeUndefined();
        expect(buf.oldest).toBeUndefined();
    });

    it('toArray 返回新数组，不暴露内部存储（外部修改不影响缓冲）', () => {
        const buf = new ErrorRingBuffer(2);
        buf.push({ kind: 'log', tag: 't', message: 'x', timestamp: 1, severity: 'warn' });
        const arr = buf.toArray();
        arr.push({} as ErrorEntry);
        expect(buf.size).toBe(1);
    });
});

describe('captureError 归一化', () => {
    it('Error 对象提取 name/message/stack', () => {
        const buf = new ErrorRingBuffer(5);
        const e = new TypeError('bad');
        const entry = captureError('mod', 'oops', e, 'log', { buffer: buf });
        expect(entry.kind).toBe('log');
        expect(entry.tag).toBe('mod');
        expect(entry.message).toBe('oops');
        expect(entry.name).toBe('TypeError');
        expect(entry.stack).toContain('bad');
        expect(buf.size).toBe(1);
    });

    it('字符串错误仅填 message', () => {
        const buf = new ErrorRingBuffer(5);
        const entry = captureError('mod', 'msg', 'plain string', 'uncaught', { buffer: buf });
        expect(entry.message).toBe('msg');
        expect(entry.name).toBeUndefined();
        expect(entry.stack).toBeUndefined();
    });

    it('类错误对象（含 message/name/stack）被归一化，但显式 message 仍优先', () => {
        const buf = new ErrorRingBuffer(5);
        const entry = captureError(
            'mod',
            'msg',
            { name: 'Custom', message: 'hi', stack: 's1\ns2' },
            'log',
            {
                buffer: buf,
            }
        );
        expect(entry.name).toBe('Custom');
        expect(entry.message).toBe('msg'); // 显式摘要优先于 err.message
        expect(entry.stack).toBe('s1\ns2');
    });

    it('err 为 undefined 时各字段缺省', () => {
        const buf = new ErrorRingBuffer(5);
        const entry = captureError('mod', 'msg', undefined, 'log', { buffer: buf });
        expect(entry.name).toBeUndefined();
        expect(entry.stack).toBeUndefined();
    });

    it('stack 按 maxStack 截断', () => {
        const buf = new ErrorRingBuffer(5);
        const longStack = 'a'.repeat(100);
        const entry = captureError('mod', 'msg', { message: 'm', stack: longStack }, 'log', {
            buffer: buf,
            maxStack: 10,
        });
        expect(entry.stack?.length).toBe(10);
    });

    it('默认写入全局 errorBuffer（不污染自定义 buffer）', () => {
        clearErrors();
        const custom = new ErrorRingBuffer(5);
        captureError('mod', 'only-custom', undefined, 'log', { buffer: custom });
        expect(custom.size).toBe(1);
        expect(errorBuffer.size).toBe(0);
    });
});

describe('installLoggingPatch（console.error 自动入环）', () => {
    beforeEach(() => clearErrors());

    it('patch 后 console.error 自动入环且保留原始输出', () => {
        const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
        try {
            installLoggingPatch();
            const err = new Error('boom');
            console.error('[test] failed', err);
            // 原始 console.error 仍被调用（此处被 spy 接收）
            expect(spy).toHaveBeenCalled();
            const entries = getErrors();
            expect(entries).toHaveLength(1);
            expect(entries[0].kind).toBe('log');
            expect(entries[0].tag).toBe('test');
            expect(entries[0].message).toBe('failed');
            expect(entries[0].name).toBe('Error');
        } finally {
            uninstallLoggingPatch();
            spy.mockRestore();
        }
    });

    it('installLoggingPatch 幂等：重复调用不双重入环', () => {
        const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
        try {
            installLoggingPatch();
            installLoggingPatch();
            console.error('[test] once');
            expect(getErrors()).toHaveLength(1);
        } finally {
            uninstallLoggingPatch();
            spy.mockRestore();
        }
    });

    it('uninstallLoggingPatch 后 console.error 不再入环', () => {
        const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
        try {
            installLoggingPatch();
            uninstallLoggingPatch();
            console.error('[test] nope');
            expect(getErrors()).toHaveLength(0);
        } finally {
            spy.mockRestore();
        }
    });
});

describe('installErrorCaptureOn（注入假 target）', () => {
    it('error 事件入环为 uncaught', () => {
        const buf = new ErrorRingBuffer(5);
        const target = fakeTarget();
        const dispose = installErrorCaptureOn(target, buf);
        target.dispatch('error', { message: 'boom', error: new Error('x') });
        expect(buf.size).toBe(1);
        expect(buf.newest?.kind).toBe('uncaught');
        expect(buf.newest?.message).toBe('boom');
        expect(buf.newest?.name).toBe('Error');
        dispose();
    });

    it('unhandledrejection 事件入环为 unhandledrejection（reason 为 Error）', () => {
        const buf = new ErrorRingBuffer(5);
        const target = fakeTarget();
        const dispose = installErrorCaptureOn(target, buf);
        target.dispatch('unhandledrejection', { reason: new Error('rejected') });
        expect(buf.size).toBe(1);
        expect(buf.newest?.kind).toBe('unhandledrejection');
        expect(buf.newest?.message).toBe('rejected');
    });

    it('unhandledrejection 事件 reason 为字符串', () => {
        const buf = new ErrorRingBuffer(5);
        const target = fakeTarget();
        const dispose = installErrorCaptureOn(target, buf);
        target.dispatch('unhandledrejection', { reason: 'plain reject' });
        expect(buf.newest?.kind).toBe('unhandledrejection');
        expect(buf.newest?.message).toBe('plain reject');
        dispose();
    });

    it('disposer 移除监听后不再捕获', () => {
        const buf = new ErrorRingBuffer(5);
        const target = fakeTarget();
        const dispose = installErrorCaptureOn(target, buf);
        target.dispatch('error', { message: 'first' });
        dispose();
        target.dispatch('error', { message: 'second' });
        expect(buf.size).toBe(1);
        expect(buf.newest?.message).toBe('first');
    });

    it('多次 dispatch 按序进入环形缓冲', () => {
        const buf = new ErrorRingBuffer(5);
        const target = fakeTarget();
        const dispose = installErrorCaptureOn(target, buf);
        target.dispatch('error', { message: 'e1' });
        target.dispatch('unhandledrejection', { reason: new Error('r1') });
        expect(buf.toArray().map((e) => e.message)).toEqual(['e1', 'r1']);
        dispose();
    });
});

describe('installGlobalErrorCapture（默认目标，幂等）', () => {
    it('无 window 环境返回 no-op 且不抛', () => {
        // happy-dom 下 globalThis 有 addEventListener，这里只验证函数可被调用且不抛。
        const d = installGlobalErrorCapture();
        expect(typeof d).toBe('function');
        d();
    });

    it('重复调用返回同一 disposer', () => {
        const d1 = installGlobalErrorCapture();
        const d2 = installGlobalErrorCapture();
        expect(d1).toBe(d2);
        d1();
        const d3 = installGlobalErrorCapture();
        expect(d3).not.toBe(d1);
        d3();
    });
});

describe('toDiagnosticContext 序列化', () => {
    beforeEach(() => clearErrors());

    it('空缓冲返回占位符', () => {
        expect(toDiagnosticContext()).toBe('(无捕获错误)');
    });

    it('多条目从旧到新拼接，含 kind/tag', () => {
        captureError('mod', 'm1', new Error('e1'));
        captureError('mod', 'm2', undefined, 'uncaught');
        const text = toDiagnosticContext({ maxBytes: 100000 });
        expect(text).toContain('log <mod> m1');
        expect(text).toContain('uncaught <mod> m2');
        // 顺序：旧在前
        expect(text.indexOf('m1')).toBeLessThan(text.indexOf('m2'));
    });

    it('超出 maxBytes 截断头部、保留最新', () => {
        for (let i = 0; i < 20; i++) {
            captureError('mod', `m${i}`, undefined, 'log');
        }
        const text = toDiagnosticContext({ maxBytes: 40 });
        expect(text).toContain('…(已截断较早记录)');
        expect(text).toContain('m19');
        expect(text.length).toBeLessThanOrEqual(40 + '…(已截断较早记录)\n'.length);
    });
});

