            expect(chunks[0].error).toContain('HTTP 503');
            expect(chunks[0].error).toContain('Service Unavailable');
        });

        it('fetch 抛出 AbortError → 返回 done 块', async () => {
            mockConfig.endpoint = 'https://api.deepseek.com/v1/chat/completions';
