            setTimeout(() => {
                fireEvent('ai:done', {});
            }, 0);
            await iter.next();
            // 消费完毕 → finally 应清理
            const next = await iter.next();
            expect(next.done).toBe(true);
            expect(removeSpy).toHaveBeenCalled();
            removeSpy.mockRestore();
        });
    });
});

// [doc:adr-196] go-key-allows-proceed 守护测试：Go 桌面端 key 不可回读时的验证放行逻辑。
