        expect(goKeyAllowsProceed({ ok: true, message: 'ok' }, true, false)).toBe(true);
        expect(goKeyAllowsProceed({ ok: true, message: 'ok' }, false, true)).toBe(true);
    });

    it('Go 模式 + key 已配置 + 仅 missingKey 错误 → 放行', () => {
        const r = goKeyAllowsProceed(
            {
                ok: false,
                kind: 'missingKey',
                message: 'API key 未配置',
                errors: [{ kind: 'missingKey', message: 'API key 未配置' }],
            },
            true, // isGo
            true // keyConfigured
        );
        expect(r).toBe(true);
    });

    it('Go 模式 + key 已配置 + missingKey + 其他错误 → 不放行', () => {
        const r = goKeyAllowsProceed(
            {
                ok: false,
                kind: 'missingModel',
                message: '模型未选择',
                errors: [
                    { kind: 'missingKey', message: 'API key 未配置' },
                    { kind: 'missingModel', message: '模型未选择' },
                ],
            },
            true, // isGo
            true // keyConfigured
        );
        expect(r).toBe(false);
    });

    it('浏览器模式 + missingKey 错误 → 不放行（key 仍需前端提供）', () => {
        const r = goKeyAllowsProceed(
            {
                ok: false,
                kind: 'missingKey',
                message: 'API key 未配置',
                errors: [{ kind: 'missingKey', message: 'API key 未配置' }],
            },
            false, // isGo
            true // keyConfigured
        );
        expect(r).toBe(false);
    });

    it('Go 模式 + key 未配置 + missingKey 错误 → 不放行', () => {
        const r = goKeyAllowsProceed(
            {
                ok: false,
                kind: 'missingKey',
                message: 'API key 未配置',
                errors: [{ kind: 'missingKey', message: 'API key 未配置' }],
            },
            true, // isGo
            false // keyConfigured
        );
        expect(r).toBe(false);
    });

    it('Go 模式 + key 已配置 + 无 errors 数组（undefined）→ 放行（无额外错误）', () => {
        const r = goKeyAllowsProceed({ ok: false, kind: 'missingKey', message: 'x' }, true, true);
        // errors undefined → ?? [] 得空数组 → nonKey.length === 0 → true
        expect(r).toBe(true);
    });
});

// [doc:adr-196] AI 配置持久化 — 浏览器端走 IndexedDB（复用 backend/idb.ts），不再使用 Web Storage（FR-9 / AC-5）
// 桌面端（go-adapter 可用时）配置由 Go 侧持有，前端不暴露 key；本模块仅服务浏览器适配器。
// 设计要点：capabilities() 是同步签名，故用内存缓存 + 异步回源，保持同步读语义（见 loadAiConfig）。

import { idbGet, idbSet } from '../backend/idb';
import type { Store } from '../backend/idb';
import type { AiConfigProvider, AiErrorKind, AiValidationResult, AiValidationError } from './types';
export type { AiConfigProvider } from './types';

export interface AiConfig {
    provider: AiConfigProvider;
    endpoint: string;
    apiKey: string;
    model: string;
    /** [doc:adr-199 P2-3] 请求超时（毫秒）。本地 Ollama 冷启动可能 10–60s，故可配；缺省 30000。 */
    timeoutMs: number;
    /** [doc:relay] CORS 同源代理 Worker 地址。网页端远程 API 请求经此转发以绕过 CORS。
     *  空字符串表示不启用 relay。桌面端（Wails）直连 API 无需此配置。 */
    relayUrl: string;
}

/** [doc:adr-199 P2-3] 超时下限（防误设过小掐断正常请求）。 */
export const MIN_TIMEOUT_MS = 5000;
/** 超时上限（防误设导致挂死请求永不释放）。 */
export const MAX_TIMEOUT_MS = 300000;
/** 缺省超时。 */
export const DEFAULT_TIMEOUT_MS = 30000;

export interface ProviderPreset {
    endpoint: string;
    model: string;
    needsKey: boolean;
    labelKey: string;
    docUrl: string;
}

/** 服务商预设：端点、默认模型、是否需要 Key、文案 key、文档链接。 */
export const PROVIDER_PRESETS: Record<AiConfigProvider, ProviderPreset> = {
    ollama: {
        endpoint: 'http://localhost:11434/v1/chat/completions',
        model: 'llama3.2',
        needsKey: false,
        labelKey: 'ai.provider.ollama',
        docUrl: 'https://ollama.com/',
    },
    deepseek: {
        endpoint: 'https://api.deepseek.com/v1/chat/completions',
        model: 'deepseek-chat',
        needsKey: true,
        labelKey: 'ai.provider.deepseek',
        docUrl: 'https://platform.deepseek.com/api_keys',
    },
    openai: {
        endpoint: 'https://api.openai.com/v1/chat/completions',
        model: 'gpt-4o-mini',
        needsKey: true,
        labelKey: 'ai.provider.openai',
        docUrl: 'https://platform.openai.com/api-keys',
    },
    openrouter: {
        endpoint: 'https://openrouter.ai/api/v1/chat/completions',
        model: 'openai/gpt-4o-mini',
        needsKey: true,
        labelKey: 'ai.provider.openrouter',
        docUrl: 'https://openrouter.ai/keys',
    },
    custom: {
        endpoint: '',
        model: '',
        needsKey: true,
        labelKey: 'ai.provider.custom',
        docUrl: '',
    },
};

/** 网页端 CORS 同源代理 Worker 默认地址（部署时由 wrangler deploy 产出）。 */
export const DEFAULT_RELAY_URL = 'https://mikumikuar-ai-relay.mikumikuar-app.workers.dev';

/** 零 key 默认路径：本地 Ollama（大模型零 key，小模型零成本）。见 ADR-196 开放问题 Q2 裁定。 */
export const DEFAULT_AI_CONFIG: AiConfig = {
    provider: 'ollama',
    endpoint: PROVIDER_PRESETS.ollama.endpoint,
    apiKey: '',
    model: PROVIDER_PRESETS.ollama.model,
    timeoutMs: DEFAULT_TIMEOUT_MS,
    relayUrl: DEFAULT_RELAY_URL,
};

const CONFIG_STORE: Store = 'config';
const CONFIG_KEY = 'ai';

let _cache: AiConfig | null = null;

/** 同步读取：优先内存缓存；未加载时回退默认并触发异步回源（不阻塞调用方）。 */
export function loadAiConfig(): AiConfig {
    if (_cache) {
        return _cache;
    }
    void _hydrate();
    return DEFAULT_AI_CONFIG;
}

/** 补全 chat completions 路径：输入 `/v1` 自动补全为 `/v1/chat/completions`，已有完整路径则原样返回。
 *  使预设备注简短、用户少打字。 */
export function normalizeEndpoint(endpoint: string): string {
    const trimmed = endpoint.trim();
    if (!trimmed) {
        return '';
    }
    if (trimmed.endsWith('/chat/completions')) {
        return trimmed;
    }
    const base = trimmed.endsWith('/') ? trimmed.slice(0, -1) : trimmed;
    return `${base}/chat/completions`;
}

/** 保存配置：写内存缓存（同步即时生效）+ 异步落盘 IndexedDB。
 *  返回 Promise<AiConfig>，调用方可 await 以捕获持久化错误（如 QuotaExceeded）。
 *  若不 await，失败不会抛出，仅在 DEV 环境打印警告。 */
export async function saveAiConfig(partial: Partial<AiConfig>): Promise<AiConfig> {
    const merged: AiConfig = { ...(_cache ?? DEFAULT_AI_CONFIG), ...partial };
    if (merged.endpoint) {
        merged.endpoint = normalizeEndpoint(merged.endpoint);
    }
    _cache = merged;
    try {
        await idbSet(CONFIG_STORE, CONFIG_KEY, merged);
    } catch (err) {
        if (import.meta.env.DEV) {
            console.warn('[ai-config] IndexedDB 写入失败', err);
        }
        throw err;
    }
    return merged;
}

/** 主动预加载（建议 init 后台调用，使首次读取即命中缓存，避免回退默认窗口）。 */
export async function ensureAiConfigLoaded(): Promise<void> {
    if (_cache) {
        return;
    }
    await _hydrate();
}

/** [doc:adr-199 P2-3] 将超时值归一到 [MIN, MAX]；非法/缺失回落缺省。 */
export function normalizeTimeout(v: unknown): number {
    const n = typeof v === 'number' && Number.isFinite(v) ? v : DEFAULT_TIMEOUT_MS;
    return Math.min(MAX_TIMEOUT_MS, Math.max(MIN_TIMEOUT_MS, n));
}

/** 迁移旧配置：无 provider 字段时按 endpoint 推断，无法推断则回落 ollama。 */
function migrateAiConfig(stored: Partial<AiConfig>): AiConfig {
    const base = { ...DEFAULT_AI_CONFIG, ...stored };
    if (!base.provider || !PROVIDER_PRESETS[base.provider]) {
        const matched = (Object.keys(PROVIDER_PRESETS) as AiConfigProvider[])
            .filter((p) => p !== 'custom')
            .find((p) =>
                base.endpoint.includes(
                    PROVIDER_PRESETS[p].endpoint.replace('/v1/chat/completions', '')
                )
            );
        base.provider = matched ?? 'custom';
    }
    // [doc:adr-199 P2-3] 旧配置无 timeoutMs 或值非法时归一
    base.timeoutMs = normalizeTimeout(base.timeoutMs);
    return base;
}

async function _hydrate(): Promise<void> {
    // 保存当前 _cache 引用，作为并发修改的哨兵值
    // 若 saveAiConfig 在 _hydrate 等待期间修改了 _cache，完成后不应覆盖用户的新数据
    const cacheSentinel = _cache;
    try {
        const stored = await idbGet<AiConfig>(CONFIG_STORE, CONFIG_KEY);
        if (_cache !== cacheSentinel) {
            // _cache 已被 saveAiConfig 等其他操作修改，放弃本次 hydrate 结果
            return;
        }
        _cache = stored ? migrateAiConfig(stored) : DEFAULT_AI_CONFIG;
        if (_cache.endpoint) {
            _cache.endpoint = normalizeEndpoint(_cache.endpoint);
        }
    } catch {
        if (_cache === cacheSentinel) {
            // IndexedDB 不可用（隐私模式 / 非浏览器环境）时静默回退默认
            _cache = DEFAULT_AI_CONFIG;
        }
    }
}

/** 校验配置是否足够发起一次对话。全量收集所有错误，一次性返回。 */
export function validateAiConfig(config: AiConfig): AiValidationResult {
    const preset = PROVIDER_PRESETS[config.provider];
    const errors: AiValidationError[] = [];

    if (!config.endpoint.trim()) {
        errors.push({ kind: 'missingEndpoint', message: 'ai.validation.missingEndpoint' });
    }
    if (preset.needsKey && !config.apiKey.trim()) {
        errors.push({ kind: 'missingKey', message: 'ai.validation.missingKey' });
    }
    if (!config.model.trim()) {
        errors.push({ kind: 'missingModel', message: 'ai.validation.missingModel' });
    }

    if (errors.length > 0) {
        return { ok: false, kind: errors[0].kind, message: errors[0].message, errors };
    }
    return { ok: true, message: 'ai.validation.ok' };
}

/** 根据 testConnection / streamChat 的错误消息分类错误类型。 */
export function classifyAiError(
    message: string,
    corsRisk: 'none' | 'possible' | 'high'
): AiErrorKind {
    const m = message.toLowerCase();
    if (m.includes('cors') || m.includes('access-control') || m.includes('failed to fetch')) {
        return 'cors';
    }
    if (
        m.includes('401') ||
        m.includes('unauthorized') ||
        m.includes('invalid authentication') ||
        m.includes('incorrect api key')
    ) {
        return 'unauthorized';
    }
    if (
        m.includes('404') ||
        m.includes('not found') ||
        (m.includes('model') && m.includes('not'))
    ) {
        return 'notFound';
    }
    if (m.includes('429') || m.includes('rate limit') || m.includes('too many requests')) {
        return 'rateLimit';
    }
    if (
        m.includes('500') ||
        m.includes('502') ||
        m.includes('503') ||
        m.includes('504') ||
        m.includes('internal server')
    ) {
        return 'server';
    }
    if (
        m.includes('network') ||
        m.includes('dial tcp') ||
        m.includes('connection refused') ||
        m.includes('connectex') ||
        m.includes('err_connection') ||
        m.includes('etimedout')
    ) {
        return 'network';
    }
    if (
        corsRisk !== 'none' &&
        (m.includes('fetch') || m.includes('networkerror') || m.includes('typeerror'))
    ) {
        return 'cors';
    }
    return 'unknown';
}

import type {
    AiService,
    AiCapabilities,
    ChatRequest,
    ChatChunk,
    AiConnectionResult,
    AiPersistedConfig,
    AiErrorKind,
} from './types';
import { AI_ERROR_KINDS } from './types';
import { makeLazyLoader } from '../async';
import { logInfo, logWarn } from '../logger';
import type { LLMConfig } from '@bindings/mikumikuar/internal/app/models';
import type { ChatRequest as LLMChatRequest } from '@bindings/mikumikuar/internal/app/llm/models';

// 直接惰性加载 @wailsio/runtime 的 Events：Events.On 是纯静态函数（模块 import 即注册
// 全局 dispatchWailsEvent），无需实例初始化。此前经 core/runtime-bridge 的 events Proxy
// 订阅，因 WailsRuntimeBridge 惰性 _load 时序问题会静默回落到 no-op WebEvents，导致 Go
// 后端事件（ai:chunk/done/error）全部收不到、流式永久超时。go-adapter 仅在桌面 go 模式
// 加载，直接依赖 @wailsio/runtime 安全且可靠。
const _getEvents = makeLazyLoader(async () => (await import('@wailsio/runtime')).Events);

const _getB = makeLazyLoader(async () => import('@bindings/mikumikuar/internal/app/app'));

// [doc:adr-199] 首字节看门狗：streamChat 发起后若长时间无任何事件（chunk/done/error），
// 主动注入一条 error 让流收尾，避免前端按钮永久卡在 streaming、用户干等黑盒。
const _FIRST_EVENT_TIMEOUT_MS = 30000;

export class GoAiAdapter implements AiService {
    readonly kind = 'go' as const;

    private _capCache: AiCapabilities | null = null;
    private _capsPromise: Promise<void> | null = null;
    /** 仅缓存真正联网发现过的模型列表，区别于 _capCache.models（可能只是配置回显）。 */
    private _discoveredModels: string[] | null = null;

    capabilities(): AiCapabilities {
        if (this._capCache) {
            return this._capCache;
        }
        if (!this._capsPromise) {
            this._refreshCapabilities().catch(() => undefined);
        }
        return {
            available: false,
            adapter: 'go-bridge',
            streaming: true,
            models: [],
            apiKeyConfigured: false,
            corsRisk: 'none',
            endpointReachable: 'pending',
        };
    }

    refreshCapabilities(): Promise<void> {
        return this._refreshCapabilities();
    }

    private async _refreshCapabilities(): Promise<void> {
        if (this._capsPromise) {
            return this._capsPromise;
        }
        this._capsPromise = (async () => {
            try {
                const b = await _getB();
                const cfg: LLMConfig = await b.AiGetLLMConfig();
                const baseUrl = cfg.baseUrl?.trim() ?? '';
                const available = baseUrl.length > 0;
                let corsRisk: AiCapabilities['corsRisk'] = 'none';
                if (baseUrl) {
                    const isLocal = /^https?:\/\/(localhost|127\.0\.0\.1)(:|\/|$)/i.test(baseUrl);
                    if (isLocal) {
                        corsRisk = 'none';
                    } else if (/^https:\/\//i.test(baseUrl)) {
                        corsRisk = 'possible';
                    } else if (/^http:\/\//i.test(baseUrl)) {
                        corsRisk = 'high';
                    }
                }
                this._capCache = {
                    available,
                    adapter: 'go-bridge',
                    streaming: true,
                    models: cfg.model ? [cfg.model] : [],
                    apiKeyConfigured: false,
                    corsRisk,
                    endpointReachable: 'pending',
                };
            } catch (err) {
                logWarn('ai-config', 'Go _refreshCapabilities 失败:', err);
                this._capCache = {
                    available: false,
                    adapter: 'go-bridge',
                    streaming: true,
                    models: [],
                    apiKeyConfigured: false,
                    corsRisk: 'none',
                    endpointReachable: 'pending',
                };
            }
        })();
        try {
            await this._capsPromise;
        } finally {
            this._capsPromise = null;
        }
    }

    async testConnection(): Promise<AiConnectionResult> {
        const b = await _getB();
        try {
            const res = await b.AiTestLLMConnection();
            return {
                ok: res.ok,
                kind: (AI_ERROR_KINDS as readonly string[]).includes(res.kind)
                    ? (res.kind as AiErrorKind)
                    : 'unknown',
                message: res.message,
            };
        } catch (err) {
            // Wails IPC 断开/binding 未注册时给出可操作提示，而非笼统的"未知错误"
            const msg = err instanceof Error ? err.message : String(err);
            logWarn('ai-connection', 'Go AiTestLLMConnection binding 调用失败:', err);
            return {
                ok: false,
                kind: 'unknown',
                message: /connection refused|not available|binding/i.test(msg)
                    ? '桌面端 AI 桥接不可用，请重启应用；若问题持续请检查 Wails 后端日志'
                    : `桥接调用失败：${msg}`,
            };
        }
    }

    async fetchModels(): Promise<string[]> {
        // 桌面端联网发现模型：调 Go binding 真正请求 {baseUrl}/models（带 key）。
        try {
            const b = await _getB();
            const models = await b.AiFetchModels();
            if (Array.isArray(models) && models.length > 0) {
                const sorted = [...models].sort();
                // P2-3: 同步更新 _capCache.models，让 capabilities() 反映真实列表
                if (this._capCache) {
                    this._capCache = { ...this._capCache, models: sorted };
                }
                this._discoveredModels = sorted;
                return sorted;
            }
        } catch (err) {
            logWarn('ai-config', 'Go AiFetchModels 失败:', err);
        }
        // 回退到上一次真正发现的列表（非配置回显），避免把配置单模型伪装成“发现”。
        if (this._discoveredModels && this._discoveredModels.length > 0) {
            return [...this._discoveredModels];
        }
        return [];
    }

    async loadConfig(): Promise<AiPersistedConfig> {
        try {
            const b = await _getB();
            const cfg: LLMConfig = await b.AiGetLLMConfig();
            return {
                endpoint: cfg.baseUrl?.trim() ?? '',
                model: cfg.model?.trim() ?? '',
                // Go 侧为安全不回读 key 明文，仅用 aiKeyConfigured 布尔标志
                keyConfigured: cfg.aiKeyConfigured === true,
            };
        } catch {
            return { endpoint: '', model: '', keyConfigured: false };
        }
    }

    async *streamChat(req: ChatRequest): AsyncIterable<ChatChunk> {
        const b = await _getB();
        const evt = await _getEvents();

        const queue: ChatChunk[] = [];
        let done = false;
        let err: string | null = null;
        let resolveWaiter: (() => void) | null = null;
        let streamActive = true;
        // 可观测性：记录首事件到达耗时、累计事件数，便于定位"发出请求后长时间无响应"卡点。
        const t0 = Date.now();
        let firstEventSeen = false;
        let eventCount = 0;
        let watchdog: ReturnType<typeof setTimeout> | null = null;

        const markFirstEvent = (kind: string): void => {
            eventCount++;
            if (!firstEventSeen) {
                firstEventSeen = true;
                logInfo('ai-stream', `首事件到达 kind=${kind} 耗时=${Date.now() - t0}ms`);
                if (watchdog) {
                    clearTimeout(watchdog);
                    watchdog = null;
                }
            }
        };

        // @wailsio/runtime 的 On 回调收到 WailsEvent，实际数据在 ev.data（Go 端 Emit 的 map）。
        const unsubChunk = evt.On('ai:chunk', (ev) => {
            const d = ev.data as { delta?: string; reasoning?: string } | undefined;
            if (d?.delta) {
                markFirstEvent('chunk');
                queue.push({ type: 'text', content: d.delta, reasoning: d.reasoning === 'true' });
                resolveWaiter?.();
            }
        });
        const unsubDone = evt.On('ai:done', () => {
            markFirstEvent('done');
            logInfo('ai-stream', `收到 done 总耗时=${Date.now() - t0}ms 事件数=${eventCount}`);
            done = true;
            streamActive = false;
            resolveWaiter?.();
        });
        const unsubError = evt.On('ai:error', (ev) => {
            const d = ev.data as { error?: string } | undefined;
            markFirstEvent('error');
            err = d?.error ?? '未知错误';
            logWarn('ai-stream', `收到 error 事件 耗时=${Date.now() - t0}ms: ${err}`);
            done = true;
            streamActive = false;
            resolveWaiter?.();
        });
        const unsubToolCall = evt.On('ai:tool_call', (ev) => {
            const d = ev.data as
                { toolName?: string; toolArgs?: string; toolId?: string } | undefined;
            if (d?.toolName) {
                markFirstEvent('tool_call');
                queue.push({
                    type: 'tool_call',
                    toolName: d.toolName,
                    toolArgs: d.toolArgs ?? '',
                    toolId: d.toolId ?? '',
                });
                resolveWaiter?.();
            }
        });

        // 首事件看门狗：超时未收到任何事件 → 注入 error 让流收尾（防永久挂起黑盒）。
        watchdog = setTimeout(() => {
            if (!firstEventSeen && !done) {
                logWarn(
                    'ai-stream',
                    `${_FIRST_EVENT_TIMEOUT_MS}ms 内未收到任何后端事件，判定超时并收尾`
                );
                err = `等待响应超时（${Math.round(_FIRST_EVENT_TIMEOUT_MS / 1000)}s 无任何数据）`;
                done = true;
                streamActive = false;
                b.AiCancelStream().catch(() => undefined);
                resolveWaiter?.();
            }
        }, _FIRST_EVENT_TIMEOUT_MS);

        const onAbort = (): void => {
            logInfo('ai-stream', `用户中断 abort 耗时=${Date.now() - t0}ms`);
            streamActive = false;
            done = true;
            b.AiCancelStream().catch(() => undefined);
            resolveWaiter?.();
        };
        req.signal?.addEventListener('abort', onAbort);

        try {
            const tools = req.tools?.length
                ? req.tools.map((t) => ({
                      type: t.type,
                      function: {
                          name: t.function.name,
                          description: t.function.description,
                          parameters: t.function.parameters,
                      },
                  }))
                : undefined;
            const llmReq: LLMChatRequest = {
                model: req.model ?? '',
                messages: req.messages.map((m) => {
                    if (m.role === 'tool') {
                        return {
                            role: m.role,
                            content: m.content,
                            tool_call_id: m.tool_call_id,
                        };
                    }
                    if (m.role === 'assistant' && m.tool_calls) {
                        return {
                            role: m.role,
                            content: m.content,
                            tool_calls: m.tool_calls.map((tc) => ({
                                id: tc.id,
                                type: tc.type,
                                function: {
                                    name: tc.function.name,
                                    arguments: tc.function.arguments,
                                },
                            })),
                        };
                    }
                    return { role: m.role, content: m.content as string };
                }),
                temperature: req.temperature ?? 0.7,
                max_tokens: req.maxTokens ?? 2048,
                ...(tools ? { tools } : {}),
            };
            logInfo(
                'ai-stream',
                `发起 AiStreamChat model=${llmReq.model || '(默认)'} 消息数=${llmReq.messages.length} tools=${tools?.length ?? 0}`
            );
            try {
                await b.AiStreamChat(llmReq);
                logInfo(
                    'ai-stream',
                    `AiStreamChat 已提交，等待后端事件… 耗时=${Date.now() - t0}ms`
                );
            } catch (submitErr) {
                // binding 调用本身失败（IPC/序列化）：直接注入 error 收尾，不干等看门狗。
                const msg = submitErr instanceof Error ? submitErr.message : String(submitErr);
                logWarn('ai-stream', `AiStreamChat 提交失败: ${msg}`);
                err = `请求提交失败：${msg}`;
                done = true;
                streamActive = false;
                resolveWaiter?.();
            }

            while (!done || queue.length > 0) {
                if (queue.length > 0) {
                    yield queue.shift()!;
                } else if (!done) {
                    await new Promise<void>((r) => {
                        resolveWaiter = r;
                    });
                }
            }
            if (err) {
                yield { type: 'error', error: err };
            }
        } finally {
            if (watchdog) {
                clearTimeout(watchdog);
                watchdog = null;
            }
            unsubChunk();
            unsubDone();
            unsubError();
            unsubToolCall();
            req.signal?.removeEventListener('abort', onAbort);
            if (streamActive) {
                b.AiCancelStream().catch(() => undefined);
            }
        }

        yield { type: 'done' };
    }
}

export const goAiAdapter = new GoAiAdapter();

// 轻量 Markdown → DOM 渲染器（诊断助手对话专用）。
//
// 设计取舍：
// - 纯 DOM 构建（createElement + textContent），不用 innerHTML 拼字符串，从根上免疫 XSS，
//   无需引入 marked/dompurify 等重依赖与供应链面。
// - 只覆盖 LLM 回复常用的 Markdown 子集：标题(#)、加粗(**)、斜体(*/_)、行内代码(`)、
//   代码块(```)、无序列表(-/*/+)、有序列表(1.)、水平线(---)、段落与换行。
// - 不支持链接/图片/表格等（诊断场景用不到；如需再增量扩展）。

/** 行内解析：把一行文本按 `**bold** *italic* `code`` 拆成 DOM 节点数组。 */
function renderInline(text: string): Node[] {
    const nodes: Node[] = [];
    // 依次匹配：行内代码 > 加粗 > 斜体。用单一正则交替，保序处理。
    const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\*[^*]+\*)|(_[^_]+_)/g;
    let lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text)) !== null) {
        if (m.index > lastIndex) {
            nodes.push(document.createTextNode(text.slice(lastIndex, m.index)));
        }
        const token = m[0];
        if (token.startsWith('`')) {
            const code = document.createElement('code');
            code.className = 'md-code-inline';
            code.textContent = token.slice(1, -1);
            nodes.push(code);
        } else if (token.startsWith('**')) {
            const strong = document.createElement('strong');
            strong.textContent = token.slice(2, -2);
            nodes.push(strong);
        } else {
            // *italic* 或 _italic_
            const em = document.createElement('em');
            em.textContent = token.slice(1, -1);
            nodes.push(em);
        }
        lastIndex = m.index + token.length;
    }
    if (lastIndex < text.length) {
        nodes.push(document.createTextNode(text.slice(lastIndex)));
    }
    return nodes;
}

function appendInline(el: HTMLElement, text: string): void {
    for (const node of renderInline(text)) {
        el.appendChild(node);
    }
}

/**
 * 把 Markdown 文本渲染为 DOM 片段，追加进目标容器。
 * container 会被清空后重建，供流式结束时一次性定格渲染（避免逐字符重排闪烁）。
 */
export function renderMarkdownInto(container: HTMLElement, markdown: string): void {
    container.textContent = '';
    // 先做首尾空白裁剪，消除 LLM 常在正文前后附带的空行。
    const lines = markdown.replace(/\r\n/g, '\n').trim().split('\n');

    let i = 0;
    let listEl: HTMLUListElement | HTMLOListElement | null = null;

    const closeList = (): void => {
        if (listEl) {
            container.appendChild(listEl);
            listEl = null;
        }
    };

    while (i < lines.length) {
        const line = lines[i];

        // 代码块 ```
        if (line.trimStart().startsWith('```')) {
            closeList();
            const codeLines: string[] = [];
            i++;
            while (i < lines.length && !lines[i].trimStart().startsWith('```')) {
                codeLines.push(lines[i]);
                i++;
            }
            i++; // 跳过结束 ```
            const pre = document.createElement('pre');
            pre.className = 'md-code-block';
            const code = document.createElement('code');
            code.textContent = codeLines.join('\n');
            pre.appendChild(code);
            container.appendChild(pre);
            continue;
        }

        // 空行：段落分隔
        if (line.trim() === '') {
            closeList();
            i++;
            continue;
        }

        // 水平线
        if (/^\s*(---|\*\*\*|___)\s*$/.test(line)) {
            closeList();
            container.appendChild(document.createElement('hr'));
            i++;
            continue;
        }

        // 标题 #..######
        const heading = /^(#{1,6})\s+(.*)$/.exec(line);
        if (heading) {
            closeList();
            const level = heading[1].length;
            const h = document.createElement(`h${level}`);
            h.className = 'md-heading';
            appendInline(h, heading[2]);
            container.appendChild(h);
            i++;
            continue;
        }

        // 无序列表 - * +
        const ul = /^\s*[-*+]\s+(.*)$/.exec(line);
        if (ul) {
            if (!listEl || listEl.tagName !== 'UL') {
                closeList();
                listEl = document.createElement('ul');
                listEl.className = 'md-list';
            }
            const li = document.createElement('li');
            appendInline(li, ul[1]);
            listEl.appendChild(li);
            i++;
            continue;
        }

        // 有序列表 1. 2.
        const ol = /^\s*\d+\.\s+(.*)$/.exec(line);
        if (ol) {
            if (!listEl || listEl.tagName !== 'OL') {
                closeList();
                listEl = document.createElement('ol');
                listEl.className = 'md-list';
            }
            const li = document.createElement('li');
            appendInline(li, ol[1]);
            listEl.appendChild(li);
            i++;
            continue;
        }

        // 普通段落：合并连续非空、非特殊行为一个 <p>，行内以 <br> 连接。
        closeList();
        const p = document.createElement('p');
        p.className = 'md-paragraph';
        let first = true;
        while (i < lines.length) {
            const cur = lines[i];
            if (
                cur.trim() === '' ||
                cur.trimStart().startsWith('```') ||
                /^(#{1,6})\s+/.test(cur) ||
                /^\s*[-*+]\s+/.test(cur) ||
                /^\s*\d+\.\s+/.test(cur) ||
                /^\s*(---|\*\*\*|___)\s*$/.test(cur)
            ) {
                break;
            }
            if (!first) {
                p.appendChild(document.createElement('br'));
            }
            appendInline(p, cur);
            first = false;
            i++;
        }
        container.appendChild(p);
    }
    closeList();
}

// [doc:adr-196] SSE 行解析器 — 纯函数，零依赖
// 解析 OpenAI 兼容 SSE 格式：data: {...}\n\n
// 支持 delta.tool_calls 增量聚合（ADR-197 Phase 1 补完）
// 终止符：data: [DONE]

import type { ChatChunk } from './types';

interface ToolCallAcc {
    id: string;
    name: string;
    arguments: string;
}

/**
 * 从 ReadableStream<Uint8Array> 中逐行解析 SSE，yield ChatChunk。
 * 兼容 OpenAI / Ollama / 任意 OpenAI 兼容端点。
 * v2: 支持 delta.tool_calls 增量聚合，finish_reason='tool_calls' 时 emit tool_call chunks。
 */
export async function* parseSseStream(
    body: ReadableStream<Uint8Array> | null,
    signal?: AbortSignal
): AsyncGenerator<ChatChunk> {
    if (!body) {
        yield { type: 'error', error: '响应体为空' };
        return;
    }

    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    const toolAccums = new Map<number, ToolCallAcc>();

    try {
        while (true) {
            if (signal?.aborted) {
                yield { type: 'done' };
                return;
            }

            const { done, value } = await reader.read();
            if (done) {
                break;
            }

            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() ?? '';

            for (const line of lines) {
                const trimmed = line.trim();
                if (!trimmed || trimmed.startsWith(':')) {
                    continue;
                }

                if (trimmed === 'data: [DONE]') {
                    yield { type: 'done' };
                    return;
                }

                if (trimmed.startsWith('data: ')) {
                    const json = trimmed.slice(6);
                    try {
                        const parsed = JSON.parse(json);
                        const choice = parsed?.choices?.[0];
                        const delta = choice?.delta ?? {};
                        const finishReason = choice?.finish_reason;

                        // Text content
                        const content =
                            delta?.content ??
                            parsed?.choices?.[0]?.text ??
                            parsed?.response ??
                            parsed?.message?.content;
                        if (content) {
                            yield { type: 'text', content };
                        }

                        // Tool calls (delta.tool_calls[]) — accumulate by index
                        const toolCalls = delta?.tool_calls;
                        if (toolCalls && Array.isArray(toolCalls)) {
                            for (const tc of toolCalls) {
                                const idx: number = tc.index ?? 0;
                                let acc = toolAccums.get(idx);
                                if (!acc) {
                                    acc = { id: '', name: '', arguments: '' };
                                    toolAccums.set(idx, acc);
                                }
                                if (tc.id) {
                                    acc.id = tc.id;
                                }
                                if (tc.function?.name) {
                                    acc.name = tc.function.name;
                                }
                                if (tc.function?.arguments) {
                                    acc.arguments += tc.function.arguments;
                                }
                            }
                        }

                        // finish_reason='tool_calls' — flush all accumulated tool calls
                        if (finishReason === 'tool_calls') {
                            for (const [, acc] of toolAccums) {
                                yield {
                                    type: 'tool_call',
                                    toolId: acc.id,
                                    toolName: acc.name,
                                    toolArgs: acc.arguments,
                                };
                            }
                            toolAccums.clear();
                            yield { type: 'done' };
                            return;
                        }
                    } catch {
                        if (json) {
                            yield { type: 'text', content: json };
                        }
                    }
                }
            }
        }
    } catch (err) {
        toolAccums.clear();
        if (err instanceof DOMException && err.name === 'AbortError') {
            yield { type: 'done' };
            return;
        }
        yield { type: 'error', error: err instanceof Error ? err.message : String(err) };
        return;
    } finally {
        reader.releaseLock();
    }

    yield { type: 'done' };
}

