// —— 路径工具函数（消除 6 处 "split + pop + replace" 重复）——

/** 提取路径最后一段文件名（兼容 / 和 \） */
function _baseName(path: string): string {
    return path.split(/[/\\]/).pop() || path;
}

/** 去掉文件名最后一个扩展名段（如 `a.pmx` → `a`，`b.tar.gz` → `b.tar`） */
function _stripExt(name: string): string {
    return name.replace(/\.[^.]+$/, '');
}

/**
 * [doc:adr-177] 将模型 stem（可能含 `/`，如 `A/miku`）编码为 URL/键安全的单 token。
 *
 * 不同目录下同名 PMX（如 `A/miku.pmx` 与 `B/miku.pmx`）在 FSA 扫描时会产生
 * **相同裸文件名 stem**，若直接用作 `dir:<stem>:` 纹理键前缀则相互覆盖（静默错渲染）。
 * 编码后 `web://model/A%2Fmiku` 与 `web://model/B%2Fmiku` 得到互不碰撞的命名空间，
 * 纹理键 `dir:A%2Fmiku:tex/face.png` / `dir:B%2Fmiku:tex/face.png` 各自独立。
 *
 * 解析侧（_classifyPath / _resolveIdbKey / ListDirRecursive / readFileBytes）按单 token
 * 直接透传该编码串，无需解码，故与既有 bare-stem 键（`A/miku` 编码==`A/miku`）完全兼容。
 */
function _encModelStem(stem: string): string {
    return encodeURIComponent(stem);
}

// —— base64 工具（对齐 Go 侧 string ↔ bytes 转换）——

/** base64 字符串 → Uint8Array（兼容浏览器 atob） */
function _base64ToBytes(b64: string): Uint8Array {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) {
        bytes[i] = bin.charCodeAt(i);
    }
    return bytes;
}

/** Uint8Array → base64 字符串（兼容浏览器 btoa） */
function _bytesToBase64(bytes: Uint8Array): string {
    let bin = '';
    for (let i = 0; i < bytes.length; i++) {
        bin += String.fromCharCode(bytes[i]);
    }
    return btoa(bin);
}

// —— zip 条目名多编码检测（对齐 Go 端 bestDecode，adr-006）——

/**
 * [doc:adr-006] 对齐 Go 端 bestDecode（zipextract.go:428-496）：对非 UTF-8 的 zip 条目名，
 * 同时尝试 Shift-JIS / GBK / Big5 三种编码，按评分挑选（+10 无替换字符 / +3 SJIS 偏置 /
 * +2 CJK 汉字 / +1 假名·标点 / -5 U+FFFD / -1 全角半角）。
 *
 * 解决 MMD 圈 zip 条目名常用 SJIS（日文）/ GBK（中文 Windows）编码，JSZip 默认 UTF-8
 * 解码会乱码，导致 .pmx 扩展名字节被破坏、扫描期 zip 展开失败（模型嵌套识别不足）。
 */
function bestDecodeZipName(bytes: Uint8Array): string {
    const encodings = ['shift_jis', 'gbk', 'big5'] as const;
    let best = '';
    let bestScore = -Infinity;
    for (const enc of encodings) {
        let decoded: string;
        try {
            decoded = new TextDecoder(enc, { fatal: false }).decode(bytes);
        } catch {
            continue; // 浏览器不支持该编码（罕见），跳过
        }
        let score = 0;
        let ffiCount = 0;
        for (let i = 0; i < decoded.length; i++) {
            const cp = decoded.codePointAt(i)!;
            if (cp === 0xfffd) {
                ffiCount++;
                score -= 5; // 替换字符（对齐 Go 的 RuneError -5）
            } else if (cp >= 0x4e00 && cp <= 0x9fff) {
                score += 2; // CJK 统一汉字
            } else if (cp >= 0x3040 && cp <= 0x30ff) {
                score += 1; // 平假名/片假名
            } else if (cp >= 0x3000 && cp <= 0x303f) {
                score += 1; // CJK 标点
            } else if (cp >= 0xff00 && cp <= 0xffef) {
                score -= 1; // 全角/半角（疑似损坏）
            }
        }
        if (ffiCount === 0) {
            score += 10;
        } // 无替换字符（对齐 Go 的 err==nil +10）
        if (enc === 'shift_jis') {
            score += 3;
        } // SJIS 偏置（MMD 主流编码）
        if (score > bestScore) {
            bestScore = score;
            best = decoded;
        }
    }
    return best || new TextDecoder('utf-8').decode(bytes);
}

// —— ZIP 中央目录解析（替代 JSZip.loadAsync，adr-006）——
//
// 从 ZIP 原始字节中解析中央目录，提取文件名（原始字节经 bestDecodeZipName 解码）、
// 未压缩大小、目录标记等元数据。不解压任何条目数据，用于扫描阶段快速获取文件列表。
// fflateKey 模拟 fflate unzipSync 的键生成逻辑（bit 11 → UTF-8 / Latin-1），用于
// 从 unzipSync 结果中按键取回数据。
interface ZipEntryInfo {
    name: string; // 经 bestDecodeZipName 解码的文件名
    rawName: Uint8Array; // 原始文件名字节
    fflateKey: string; // 模拟 fflate unzipSync 的键（UTF-8 或 Latin-1，取决于 gpf bit 11）
    uncompressedSize: number;
    isDir: boolean;
}
// TextDecoder 单例（避免循环内反复创建）
const _latin1Decoder = new TextDecoder('iso-8859-1');
const _utf8Decoder = new TextDecoder('utf-8', { fatal: false });
function parseZipCentralDir(raw: Uint8Array): ZipEntryInfo[] {
    if (raw.length < 22) {
        return [];
    } // 最小 ZIP（空 EOCD）也需要 22 字节
    // EOCD 签名 0x06054b50，从文件末尾向前搜索（ZIP 注释长度不定）
    let eocdPos = -1;
    const limit = Math.min(raw.length, 65557); // 最大 EOCD 搜索范围 64KB + 固定头
    for (let i = raw.length - 22; i >= raw.length - limit && i >= 0; i--) {
        if (raw[i] === 0x50 && raw[i + 1] === 0x4b && raw[i + 2] === 0x05 && raw[i + 3] === 0x06) {
            eocdPos = i;
            break;
        }
    }
    if (eocdPos < 0) {
        return [];
    }

    // 解析 EOCD 字段（全部小端序）
    const eocd = new DataView(raw.buffer, raw.byteOffset + eocdPos, 22);
    const cdEntries = eocd.getUint16(10, true);
    const cdOffset = eocd.getUint32(16, true);

    const entries: ZipEntryInfo[] = [];
    let pos = cdOffset;
    for (let i = 0; i < cdEntries; i++) {
        // 边界守护：中央目录条目固定头 46 字节 + 文件名必须不越界
        if (pos + 46 > raw.length) {
            break;
        }
        // 中央目录条目签名 0x02014b50
        if (
            raw[pos] !== 0x50 ||
            raw[pos + 1] !== 0x4b ||
            raw[pos + 2] !== 0x01 ||
            raw[pos + 3] !== 0x02
        ) {
            break;
        }

        const entry = new DataView(raw.buffer, raw.byteOffset + pos, 46);
        const gpf = entry.getUint16(8, true); // general purpose bit flag
        const filenameLength = entry.getUint16(28, true);
        const extraLength = entry.getUint16(30, true);
        const commentLength = entry.getUint16(32, true);
        const uncompressedSize = entry.getUint32(24, true);

        // 文件名越界守护
        if (pos + 46 + filenameLength > raw.length) {
            break;
        }

        const rawName = raw.slice(pos + 46, pos + 46 + filenameLength);
        // [doc:adr-006] 对齐 JSZip 行为：gpf bit 11 设置时文件名为 UTF-8，直接解码；
        // 未设置时为 SJIS/GBK/Big5，走 bestDecodeZipName 评分检测。
        // fflateKey 必须与 fflate unzipSync 的键生成逻辑一致（同上 bit 11 判断）。
        const isUtf8 = (gpf & 0x800) !== 0;
        const name = isUtf8 ? _utf8Decoder.decode(rawName) : bestDecodeZipName(rawName);
        const isDir = filenameLength > 0 && rawName[filenameLength - 1] === 0x2f; // 以 '/' 结尾
        const fflateKey = isUtf8 ? _utf8Decoder.decode(rawName) : _latin1Decoder.decode(rawName);

        entries.push({ name, rawName, fflateKey, uncompressedSize, isDir });
        pos += 46 + filenameLength + extraLength + commentLength;
    }
    return entries;
}

