// ===================================================================
// addPresetChip
// ===================================================================

/**
 * 创建一个 preset-chip 按钮并追加到 container（通常是 .preset-group div）。
 * 极简工具：只管单个 chip 的创建+追加，group 容器和数据源由调用方管理。
 *
 * @param container 父容器（一般是 div.preset-group）
 * @param label     按钮文本
 * @param active    是否激活（追加 'active' class）
 * @param onClick   点击回调
 * @param opts      自更新选项（onUpdate 自定义更新逻辑）
 * @returns 创建的 button 元素（调用方可继续加内联 style 等）
 */
export function addPresetChip(
    container: HTMLElement,
    label: string,
    active: boolean,
    onClick: () => void,
    opts?: {
        onUpdate?: (btn: HTMLButtonElement) => void;
        wrap?: boolean;
        /** Iconify 图标名，前置到文本前（无则忽略） */
        icon?: string;
        /** 'danger' = 红底动作按钮；'badge' = 只读标签（不可点击）；默认 'default' */
        variant?: 'default' | 'danger' | 'badge';
        /** tooltip 文本 */
        title?: string;
        /** 上外边距（px） */
        marginTop?: number;
        /** 左外边距（px 或 'auto'） */
        marginLeft?: number | 'auto';
        /** 点击时阻止冒泡到父行（行内嵌按钮防误触） */
        stopPropagation?: boolean;
    }
): HTMLButtonElement {
    const btn = document.createElement('button');
    const variant = opts?.variant ?? 'default';
    const classes = ['preset-chip'];
    if (active) {
        classes.push('active');
    }
    if (variant === 'danger') {
        classes.push('danger');
    }
    if (variant === 'badge') {
        classes.push('badge');
    }
    if (opts?.wrap) {
        classes.push('wrap-2');
    }
    btn.className = classes.join(' ');

    if (opts?.icon) {
        const iconEl = createIconifyIcon(opts.icon);
        if (iconEl) {
            btn.appendChild(iconEl);
        }
    }
    btn.appendChild(document.createTextNode(label));

    if (opts?.title) {
        btn.title = opts.title;
    }
    if (opts?.marginTop != null) {
        btn.style.marginTop = `${opts.marginTop}px`;
    }
    if (opts?.marginLeft != null) {
        btn.style.marginLeft = opts.marginLeft === 'auto' ? 'auto' : `${opts.marginLeft}px`;
    }

    if (variant !== 'badge') {
        btn.addEventListener('click', (e) => {
            if (opts?.stopPropagation) {
                e.stopPropagation();
            }
            onClick();
        });
    }

    container.appendChild(btn);

    // === 自更新支持 ===
    if (opts?.onUpdate) {
        const update = () => opts.onUpdate!(btn);
        getCurrentRenderingContext()?.registerControl(update);
        update();
    }

    return btn;
}

/**
 * ADR-153 Phase 3: 键盘导航公共工具
 *
 * 统一 Arrow 键 + Enter/Space + Escape 列表导航。
 * 被 `menu.ts`（CSS-highlight 模型）和 `settings-diagnostic.ts`（tablist）等使用。
 *
 * ADR-153 增强（全大统一）：新增三项能力边界，使 `menu.ts` 的 `focusIndex`
 * 状态机可接入而不破坏返回手感（ArrowRight→激活、ArrowLeft→pop）：
 *   1. perKeySkip —— 按键相关的差异化跳过（↑↓ 与 →← 跳过规则可不同）
 *   2. getActiveIndex/setActiveIndex —— 焦点真相源抽象，允许外部用
 *      `.slide-focused` CSS 类而非原生 `:focus` 定位当前项
 *   3. arrowRightActivate —— ArrowRight 语义切换为激活而非平级移动
 */
import { addDisposableListener, type Disposable } from './dom';

/** 导航按键分类：垂直移动 / 水平移动，供 perKeySkip 差异化判断 */
export type NavKeyKind = 'vertical' | 'horizontal';

export interface KeyboardNavOptions {
    /** 容器内可聚焦元素的选择器，默认 '[tabindex]' */
    selector?: string;
    /** Enter/Space 激活回调，默认触发 click() */
    onEnter?: (el: HTMLElement) => void;
    /** Escape 回调 */
    onEscape?: () => void;
    /** ArrowLeft 返回回调（菜单返回用） */
    onArrowBack?: () => void;
    /** 每次箭头键移动焦点后触发（tablist 用） */
    onArrowActivate?: (el: HTMLElement) => void;
    /** 跳过选择器：焦点在此类元素内时箭头键不触发导航 */
    skipSelector?: string;
    /**
     * 按键相关的差异化跳过（优先级高于 skipSelector）。
     * 返回 true 时该按键的导航被忽略、事件透传。
     * 用于 `menu.ts`：↑↓ 仅跳 slider/tablist，→←/Enter 还要跳原生 button。
     */
    perKeySkip?: (target: HTMLElement | null, kind: NavKeyKind) => boolean;
    /** 过渡锁：为 true 时所有键盘操作被忽略 */
    transitioningGuard?: () => boolean;
    /** 是否循环 wrap（默认 true） */
    wrap?: boolean;
    /** roving tabindex：箭头移动后设置新元素 tabIndex=0、旧元素 tabIndex=-1 */
    rovingTabIndex?: boolean;
    /**
     * 焦点真相源读取：返回当前激活项索引。提供后取代默认的 `:focus` 反查，
     * 让外部（如 menu.ts）用 `.slide-focused` CSS 类维护焦点。
     */
    getActiveIndex?: (items: HTMLElement[]) => number;
    /**
     * 焦点真相源写入：移动到目标索引。提供后取代默认的 `el.focus()`，
     * 由外部负责打 `.slide-focused` 类 + scrollIntoView + focus。
     */
    setActiveIndex?: (items: HTMLElement[], nextIdx: number) => void;
    /**
     * ArrowRight 语义为「激活当前项」而非「平级向后移动」（menu.ts 层级进入）。
     * 为 true 时 ArrowRight 走 onEnter 路径；ArrowDown 仍为平级移动。
     */
    arrowRightActivate?: boolean;
    /**
     * 自定义导航项来源：提供后取代默认的 `container.querySelectorAll(selector)`。
     * 用于 menu.ts —— 其 panelItems 含纯 CSS 无法表达的过滤（如“仅含 .cs-bar 的 .cs-row”），
     * 保证焦点真相源（getActiveIndex 的索引）与 list.length 完全一致，避免 wrap 边界错位。
     */
    getItems?: () => HTMLElement[];
}

export function createKeyboardNav(
    container: HTMLElement,
    options: KeyboardNavOptions = {}
): Disposable {
    const selector = options.selector || '[tabindex]';
    const wrap = options.wrap !== false;

    const handler = (e: KeyboardEvent) => {
        if (options.transitioningGuard?.()) {
            return;
        }

        const target = e.target instanceof HTMLElement ? e.target : null;
        if (target && options.skipSelector && target.closest(options.skipSelector)) {
            return;
        }

        const items = options.getItems
            ? options.getItems()
            : Array.from(container.querySelectorAll<HTMLElement>(selector));
        if (items.length === 0) {
            return;
        }
        const list = items;

        // 焦点真相源：优先外部 getActiveIndex（如 menu.ts 的 focusIndex），
        // 否则回退原生 `:focus` 反查（tablist / fullscreen-overlay 路径不变）。
        const idx = options.getActiveIndex
            ? options.getActiveIndex(list)
            : (() => {
                  const f = container.querySelector<HTMLElement>(`${selector}:focus`);
                  return f ? list.indexOf(f) : -1;
              })();
        const activeEl = idx >= 0 && idx < list.length ? list[idx] : null;

        switch (e.key) {
            case 'ArrowDown': {
                if (options.perKeySkip?.(target, 'vertical')) {
                    return;
                }
                e.preventDefault();
                const next = wrap ? (idx + 1) % list.length : Math.min(idx + 1, list.length - 1);
                _moveFocus(list, idx, next, options);
                break;
            }
            case 'ArrowRight': {
                if (options.perKeySkip?.(target, 'horizontal')) {
                    return;
                }
                // menu.ts 语义：ArrowRight = 激活当前项（层级进入），非平级移动
                if (options.arrowRightActivate) {
                    if (activeEl) {
                        e.preventDefault();
                        if (options.onEnter) {
                            options.onEnter(activeEl);
                        } else {
                            activeEl.click();
                        }
                    }
                    break;
                }
                e.preventDefault();
                const next = wrap ? (idx + 1) % list.length : Math.min(idx + 1, list.length - 1);
                _moveFocus(list, idx, next, options);
                break;
            }
            case 'ArrowUp': {
                if (options.perKeySkip?.(target, 'vertical')) {
                    return;
                }
                e.preventDefault();
                const prev = wrap ? (idx - 1 + list.length) % list.length : Math.max(idx - 1, 0);
                _moveFocus(list, idx, prev, options);
                break;
            }
            case 'ArrowLeft': {
                if (options.perKeySkip?.(target, 'horizontal')) {
                    return;
                }
                if (options.onArrowBack) {
                    e.preventDefault();
                    options.onArrowBack();
                    break;
                }
                e.preventDefault();
                const prev = wrap ? (idx - 1 + list.length) % list.length : Math.max(idx - 1, 0);
                _moveFocus(list, idx, prev, options);
                break;
            }
            case 'Enter':
            case ' ': {
                if (options.perKeySkip?.(target, 'horizontal')) {
                    return;
                }
                if (activeEl) {
                    e.preventDefault();
                    if (options.onEnter) {
                        options.onEnter(activeEl);
                    } else {
                        activeEl.click();
                    }
                }
                break;
            }
            case 'Escape': {
                if (options.onEscape) {
                    e.preventDefault();
                    options.onEscape();
                }
                break;
            }
        }
    };

    return addDisposableListener(container, 'keydown', handler);
}

function _moveFocus(
    items: HTMLElement[],
    prevIdx: number,
    nextIdx: number,
    options: KeyboardNavOptions
): void {
    // 焦点真相源写入：外部提供 setActiveIndex 时由其接管（menu.ts 打 .slide-focused），
    // 否则走默认 roving tabindex + 原生 focus。
    if (options.setActiveIndex) {
        options.setActiveIndex(items, nextIdx);
        options.onArrowActivate?.(items[nextIdx]);
        return;
    }
    if (options.rovingTabIndex && prevIdx >= 0 && prevIdx < items.length) {
        items[prevIdx].tabIndex = -1;
    }
    items[nextIdx].focus();
    if (options.rovingTabIndex) {
        items[nextIdx].tabIndex = 0;
    }
    options.onArrowActivate?.(items[nextIdx]);
}

// [doc:architecture] ui-rows — 菜单行控件（toggle/slider/mode）
// addToggleRow / addSliderRow / addModeRow / sliderRow / toggleRow

import { createIconifyIcon } from './icons';
import { getCurrentRenderingContext } from './render-context';
import { ControlOptions } from './ui-types';
import { slideRow } from './ui-slide-row';
import { t } from './i18n/t';
import { clamp01, clampPct } from '@/core/clamp';
import { swallowError } from '@/core/async';
import { DragSliderController } from './ui-slider-controller';
import { SLIDER_QUARTER_LARGE_STEP, SLIDER_QUARTER_SMALL_STEP } from './ui-constants';

// ===================================================================
// addToggleRow
// ===================================================================

// 自增计数器，用于生成稳定的唯一 ID
let nextToggleId = 0;

export function addToggleRow(
    container: HTMLElement,
    label: string,
    value: boolean,
    onChange: (v: boolean) => void,
    icon?: string,
    opts?: ControlOptions<boolean>,
    testId?: string
): void {
    const row = document.createElement('div');
    row.className = 'toggle-row';
    if (testId) {
        row.setAttribute('data-testid', testId);
    }

    const left = document.createElement('div');
    left.className = 'toggle-left';

    if (icon) {
        const iconBox = document.createElement('span');
        iconBox.className = 'cs-icon';
        const iconEl = createIconifyIcon(icon);
        if (iconEl) {
            iconBox.appendChild(iconEl);
        } else {
            const fb = document.createElement('span');
            fb.className = 'cs-icon-fallback';
            fb.textContent = label.charAt(0) || '?';
            iconBox.appendChild(fb);
        }
        left.appendChild(iconBox);
    }

    const lbl = document.createElement('span');
    lbl.className = 'toggle-label';
    lbl.textContent = label;
    lbl.id = `toggle-${++nextToggleId}`;
    left.appendChild(lbl);

    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'toggle';
    const toggle = document.createElement('input');
    toggle.type = 'checkbox';
    toggle.checked = value;
    toggle.setAttribute('role', 'switch');
    toggle.setAttribute('aria-label', label);
    toggle.setAttribute('aria-checked', String(value));
    toggle.setAttribute('aria-labelledby', lbl.id);
    toggle.addEventListener('change', () => {
        toggle.setAttribute('aria-checked', String(toggle.checked));
        onChange(toggle.checked);
    });
    const slider = document.createElement('span');
    slider.className = 'slider';
    toggleLabel.appendChild(toggle);
    toggleLabel.appendChild(slider);
    row.appendChild(left);
    row.appendChild(toggleLabel);

    // 整行点击（除 toggle 开关外）也可切换
    row.addEventListener('click', (e) => {
        if ((e.target as HTMLElement).closest('.toggle')) {
            return;
        }
        toggle.checked = !toggle.checked;
        toggle.setAttribute('aria-checked', String(toggle.checked));
        onChange(toggle.checked);
    });

    container.appendChild(row);

    // === 自更新支持 ===
    initControl(row, opts, value, (v, cached) => {
        const b = !!v;
        if (b === cached) {
            return false;
        }
        toggle.checked = b;
        toggle.setAttribute('aria-checked', String(b));
        return true;
    });
}

// ===================================================================
// initControl — 控件自更新注册 + 立即初始化
// ===================================================================

/**
 * 封装 registerControl + immediate update 模式。
 * `apply` 返回 true 表示值已变更，用于更新缓存。
 */
export function initControl<T>(
    el: HTMLElement,
    opts: ControlOptions<T> | undefined,
    initial: T,
    apply: (v: T, cached: T) => boolean
): void {
    if (!opts) {
        return;
    }
    let cached = initial;
    const update = (): void => {
        if (opts.onUpdate) {
            opts.onUpdate(el);
            return;
        }
        if (!opts.bind) {
            return;
        }
        const v = opts.bind();
        if (apply(v, cached)) {
            cached = v;
        }
    };
    getCurrentRenderingContext()?.registerControl(update, opts.pathHint);
    update();
}

// ===================================================================
// addSliderRow
// ===================================================================

/**
 * 数字滑块行。ADR-140：内部统一由 {@link DragSliderController} 驱动
 * （拖拽 + 键盘 + 游标点击），行为与其他滑块 builder 保持一致。
 */
export function addSliderRow(
    container: HTMLElement,
    label: string,
    value: number,
    min: number,
    max: number,
    step: number,
    onChange: (v: number) => void,
    icon?: string,
    onDragEndCb?: (v: number) => void,
    opts?: ControlOptions<number>,
    testId?: string
): void {
    // 防御: 非有限数值（undefined/NaN）回落到 min ?? 0，避免 .toFixed() 崩溃导致整个面板渲染失败
    let currentValue = typeof value === 'number' && Number.isFinite(value) ? value : (min ?? 0);
    const range = max - min;

    const row = document.createElement('div');
    row.className = 'cs-row';
    if (testId) {
        row.setAttribute('data-testid', testId);
    }

    const top = document.createElement('div');
    top.className = 'cs-top';

    if (icon) {
        const iconBox = document.createElement('span');
        iconBox.className = 'cs-icon';
        const iconEl = createIconifyIcon(icon);
        if (iconEl) {
            iconBox.appendChild(iconEl);
        } else {
            const fb = document.createElement('span');
            fb.className = 'cs-icon-fallback';
            fb.textContent = label.charAt(0) || '?';
            iconBox.appendChild(fb);
        }
        top.appendChild(iconBox);
    }

    const lbl = document.createElement('span');
    lbl.className = 'cs-label';
    lbl.textContent = label;

    const val = document.createElement('span');
    val.className = 'cs-value';

    top.appendChild(lbl);
    top.appendChild(val);

    const bar = document.createElement('div');
    bar.className = 'cs-bar';
    bar.tabIndex = 0;
    bar.setAttribute('role', 'slider');
    bar.setAttribute('aria-label', label);
    bar.setAttribute('aria-valuemin', String(min));
    bar.setAttribute('aria-valuemax', String(max));

    const fill = document.createElement('div');
    fill.className = 'cs-fill';

    const thumb = document.createElement('div');
    thumb.className = 'cs-thumb';

    bar.appendChild(fill);
    bar.appendChild(thumb);

    function updateDisplay(v: number): void {
        currentValue = v;
        val.textContent = step < 1 ? v.toFixed(2) : String(Math.round(v));
        const newPct = ((v - min) / range) * 100;
        const clamped = clampPct(newPct);
        fill.style.width = clamped + '%';
        thumb.style.left = clamped + '%';
        bar.setAttribute('aria-valuenow', String(v));
    }

    updateDisplay(currentValue);

    const controller = new DragSliderController({
        value: currentValue,
        min,
        max,
        step,
        onChange: (v) => {
            updateDisplay(v);
            onChange(v);
        },
        onDragEnd: (v) => {
            onDragEndCb?.(v);
        },
    });
    controller.bind(bar);

    // cs-top 四分区域相对步进：左→右 = 减大步 → 减小步 → 加小步 → 加大步
    top.addEventListener('click', (e) => {
        e.stopPropagation();
        const rect = top.getBoundingClientRect();
        const pct = clamp01((e.clientX - rect.left) / rect.width);
        const delta =
            pct < 0.25
                ? -(range * SLIDER_QUARTER_LARGE_STEP)
                : pct < 0.5
                  ? -(range * SLIDER_QUARTER_SMALL_STEP)
                  : pct < 0.75
                    ? range * SLIDER_QUARTER_SMALL_STEP
                    : range * SLIDER_QUARTER_LARGE_STEP;
        const raw = currentValue + delta;
        const precision = step > 0 ? 1 / step : 1;
        const snapped = Math.round(raw * precision) / precision;
        const clamped = Math.max(min, Math.min(max, snapped));
        if (clamped !== currentValue) {
            currentValue = clamped;
            updateDisplay(clamped);
            onChange(clamped);
        }
    });

    row.appendChild(top);
    row.appendChild(bar);
    container.appendChild(row);

    // === 自更新支持 ===
    initControl(row, opts, value, (v, cached) => {
        if (!Number.isFinite(v) || v === cached) {
            return false;
        }
        updateDisplay(v);
        controller.setValue(v);
        return true;
    });
}

