/** 创建一个不可交互的提示行（替代手写 cs-row + opacity 0.4 + pointer-events none）。
 * 复用 cs-row / cs-label / cs-value 样式，视觉与既有行一致。 */
export function addDisabledRow(
    container: HTMLElement,
    label: string,
    value?: string,
    opts?: { testId?: string }
): HTMLElement {
    const { testId } = opts ?? {};
    const row = document.createElement('div');
