/** 创建一个内联 toggle 行（替代手写 toggle-row + toggle-label + toggle-switch）。
 * 视觉上与 addToggleRow 保持一致，但用 span 模拟而非 input checkbox，
 * 适用于不需要 aria/accessibility 完整性的菜单内联场景。 */
export function addInlineToggleRow(
    container: HTMLElement,
    label: string,
    value: boolean,
    onChange: (v: boolean) => void,
    opts?: { testId?: string }
): HTMLElement {
    const { testId } = opts ?? {};
    const row = document.createElement('div');
    row.className = 'toggle-row';
    if (testId) {
        row.setAttribute('data-testid', testId);
    }
    const lbl = document.createElement('span');
    lbl.className = 'toggle-label';
    lbl.textContent = label;
    const sw = document.createElement('span');
    sw.className = 'toggle-switch' + (value ? ' active' : '');
    sw.addEventListener('click', () => {
        const v = !sw.classList.contains('active');
        sw.classList.toggle('active', v);
        onChange(v);
    });
    row.appendChild(lbl);
    row.appendChild(sw);
    container.appendChild(row);
    return row;
}

// ===================================================================
// addBoneSelectRow — 骨骼下拉选择行（分组 + 搜索 + IK 标记）
// 替代 addModeRow 在骨骼列表上的误用与各面板内联 select 重复（ADR-122 P3）
// ===================================================================

/** [doc:adr-122 P3] 已知 IK 骨骼名集合（IK 目标骨 + 链骨） */
const IK_BONE_NAMES = new Set([
    '左足IK',
    '右足IK',
    '左腕IK',
    '右腕IK',
    '左足首',
    '右足首',
    '左ひざ',
    '右ひざ',
    '左ひじ',
    '右ひじ',
]);

/** [doc:adr-122 P3] 判断骨骼是否为 IK 相关骨骼 */
export function isIkBone(boneName: string): boolean {
    return IK_BONE_NAMES.has(boneName) || boneName.endsWith('IK');
}

/** 已知 MMD 骨骼分组（按日文标准名匹配前缀；遍历顺序决定归属优先级） */
const KNOWN_BONE_GROUPS: Record<string, string[]> = {
    'センター/腰部': ['センター', 'グルーブ', '腰'],
    '上半身': ['上半身', '上半身2', '胸', '首', '頭'],
    '下半身': [
        '下半身',
        '左足',
        '右足',
        '左ひざ',
        '右ひざ',
        '左足首',
        '右足首',
        '左足IK',
        '右足IK',
    ],
    '左腕': ['左肩', '左腕', '左ひじ', '左手首'],
    '右腕': ['右肩', '右腕', '右ひじ', '右手首'],
    '左手': ['左親指', '左人指', '左中指', '左薬指', '左小指'],
    '右手': ['右親指', '右人指', '右中指', '右薬指', '右小指'],
};

/** 按类别分组骨骼名，未匹配的归入「その他」。空组被剔除。 */
export function buildBoneGroups(boneNames: readonly string[]): [string, string[]][] {
    const groups: Map<string, string[]> = new Map();
    for (const key of Object.keys(KNOWN_BONE_GROUPS)) {
        groups.set(key, []);
    }
    groups.set('その他', []);
    for (const name of boneNames) {
        let placed = false;
        for (const [groupName, prefixes] of Object.entries(KNOWN_BONE_GROUPS)) {
            if (prefixes.some((p) => name === p || name.startsWith(p))) {
                groups.get(groupName)!.push(name);
                placed = true;
                break;
            }
        }
        if (!placed) {
            groups.get('その他')!.push(name);
        }
    }
    const result: [string, string[]][] = [];
    for (const [groupName, boneList] of groups) {
        if (boneList.length > 0) {
            boneList.sort();
            result.push([groupName, boneList]);
        }
    }
    return result;
}

export interface BoneSelectOptions {
    /** 搜索框 placeholder，默认 t('motion.boneOverride.search') */
    searchPlaceholder?: string;
    testId?: string;
}

/**
 * 创建骨骼选择行：label + 搜索框 + 分组下拉（含 IK 标记）。
 * 替代 addModeRow 在上百骨骼上的误用，统一相机骨骼锁定 / 高级骨骼覆盖两处入口。
 * 返回 select 元素，便于调用方按需同步 value。
 */
export function addBoneSelectRow(
    container: HTMLElement,
    label: string,
    boneNames: readonly string[],
    currentName: string,
    onChange: (name: string) => void,
    opts?: BoneSelectOptions
): HTMLSelectElement {
    const wrapper = document.createElement('div');
    wrapper.className = 'bone-select-row';
    if (opts?.testId) {
        wrapper.setAttribute('data-testid', opts.testId);
    }

    if (label) {
        const lbl = document.createElement('div');
        lbl.className = 'cs-label-sm';
        lbl.textContent = label;
        wrapper.appendChild(lbl);
    }

    const boneSearch = document.createElement('input');
    boneSearch.type = 'text';
    boneSearch.className = 'full-input';
    boneSearch.placeholder = opts?.searchPlaceholder ?? t('motion.boneOverride.search');
    wrapper.appendChild(boneSearch);

    const boneSelect = document.createElement('select');
    boneSelect.className = 'setting-select';

    const groups = buildBoneGroups(boneNames);
    for (const [groupLabel, names] of groups) {
        const optGroup = document.createElement('optgroup');
        optGroup.label = groupLabel;
        for (const bn of names) {
            const opt = document.createElement('option');
            opt.value = bn;
            // [doc:adr-122 P3] IK 骨骼附加标记
            opt.textContent = isIkBone(bn) ? `${bn} ${t('motion.ikTag')}` : bn;
            optGroup.appendChild(opt);
        }
        boneSelect.appendChild(optGroup);
    }
    boneSelect.value = currentName;
    boneSelect.addEventListener('change', () => {
        onChange(boneSelect.value);
    });
    // [doc:adr-116 P4] 搜索过滤：原生 select 不支持搜索，附加过滤输入框
    boneSearch.addEventListener('input', () => {
        const q = boneSearch.value.trim().toLowerCase();
        for (const g of Array.from(boneSelect.querySelectorAll('optgroup'))) {
            let visible = 0;
            for (const opt of Array.from(g.querySelectorAll('option'))) {
                const hit = !q || (opt.textContent ?? '').toLowerCase().includes(q);
                (opt as HTMLElement).style.display = hit ? '' : 'none';
                if (hit) {
                    visible++;
                }
            }
            (g as HTMLElement).style.display = visible > 0 ? '' : 'none';
        }
    });
    wrapper.appendChild(boneSelect);
    container.appendChild(wrapper);
    return boneSelect;
}

// [doc:architecture] slideRow — 菜单行组件
// 带图标+标签+箭头+可选 sublabel/tag/headerToggle + actionBtn + variant 的通用菜单行

import { createIconifyIcon } from './icons';
import { createHeaderToggle, type HeaderToggleConfig } from './ui-header-toggle';

export type { HeaderToggleConfig };

export interface TrailingAction {
    /** 图标：含 ':' 视为 iconify 名（如 'lucide:settings-2'）渲染为 SVG；否则作为字面字符（如 '▶'）。 */
    icon: string;
    title?: string;
    danger?: boolean;
    onClick: (e: MouseEvent) => void;
}

/**
 * 统一尾部第二动作按钮工厂——供 slideRow 与 menu.ts createRow 共用，
 * 确保两条渲染路径的第二按钮观感与行为一致（22px .slide-add-btn；iconify 名渲染 SVG，
 * 否则 textContent；点击 stopPropagation 防冒泡触发整行 onClick）。
 */
/**
 * 动作按钮内部构造器——供 createTrailingBtn / createLeadingBtn 共用，
 * 消除两份 ~90% 相同的函数体（仅 class 名不同：右侧 22px 盒装 / 左侧 21px 透明指示）。
 */
function buildActionBtn(act: TrailingAction, cls: string): HTMLElement {
    const btn = document.createElement('span');
    btn.className = cls + (act.danger ? ' slide-act-danger' : '');
    if (act.icon.includes(':')) {
        const iconEl = createIconifyIcon(act.icon);
        if (iconEl) {
            btn.appendChild(iconEl);
        } else {
            btn.textContent = act.icon;
        }
    } else {
        btn.textContent = act.icon;
    }
    btn.title = act.title || '';
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        act.onClick(e);
    });
    return btn;
}

/**
 * 统一尾部第二动作按钮工厂——供 slideRow 与 menu.ts createRow 共用，
 * 确保两条渲染路径的第二按钮观感与行为一致（22px .slide-add-btn；iconify 名渲染 SVG，
 * 否则 textContent；点击 stopPropagation 防冒泡触发整行 onClick）。
 */
export function createTrailingBtn(act: TrailingAction): HTMLElement {
    return buildActionBtn(act, 'slide-add-btn');
}

/**
 * 统一左侧行为区按钮工厂——镜像 createTrailingBtn，但渲染为 21px 透明可点击
 * `.slide-lead-btn`（复用 .slide-icon 尺寸，非 22px 盒装），保持指示图标（如 radio）
 * 视觉一致；点击 stopPropagation 防冒泡触发整行 onClick。
 */
export function createLeadingBtn(act: TrailingAction): HTMLElement {
    return buildActionBtn(act, 'slide-lead-btn');
}

export interface SlideRowExtra {
    /** label 颜色变体：danger(红), accent(主题色) */
    variant?: 'default' | 'danger' | 'accent';
    /** 统一尾部行为区：传入则在行最右侧渲染为可点击图标，并【不】渲染装饰性 `>`。
     *  用于「+ 加载」「▶ 播放」「✕ 删除」等第二动作；与 hasArrow 互斥，
     *  从构造上杜绝「文件行既渲染 + 又渲染 >」的误渲染。 */
    trailing?: TrailingAction;
    /** 统一左侧行为区：传入则左侧图标（如 radio 指示）被渲染为可点击按钮，
     *  点击 stopPropagation 后触发该动作（如切焦点），与整行 onClick 解耦。
     *  视觉复用 .slide-icon 尺寸（非 22px 盒装），保持指示图标一致性。 */
    leading?: TrailingAction;
    /** 自定义右侧 label（key-value 布局用） */
    rightLabel?: string;
    /** 动态图标工厂函数——替代 icon 字符串参数，每次渲染调用 */
    iconFactory?: () => HTMLElement;
    /** key-value 字段行专用：为 true 时不渲染左侧图标占位，避免 21px 空白。addFieldRow 默认开启 */
    hideIcon?: boolean;
    /** sublabel 内联在 label 后（而非右对齐），适合需要 text-overflow 的场景 */
    inlineSub?: boolean;
    /** label 允许双行显示（用于长文件名等场景） */
    wrapLabel?: boolean;
    /**
     * 稳定测试钩子：建议传声明式节点的稳定 id（非可见文本），e2e 用
     * `getByTestId` 定位，避免依赖文本/位置导致重构即红。仅作测试属性，
     * 生产行为不受影响。
     */
    testId?: string;
}

export function slideRow(
    container: HTMLElement,
    icon: string,
    label: string,
    hasArrow: boolean,
    onClick: () => void,
    sublabel?: string,
    tag?: string,
    focused?: boolean,
    headerToggle?: HeaderToggleConfig,
    extra?: SlideRowExtra
): HTMLElement {
    const row = document.createElement('div');

    // 稳定测试钩子：覆盖 headerToggle 与普通行两条分支（共用同一 row）。
    if (extra?.testId) {
        row.setAttribute('data-testid', extra.testId);
    }

    if (headerToggle) {
        // 使用 addCollapsible 的 header 样式：图标 + label + toggle + 箭头
        row.className = 'collapsible-header';
        row.tabIndex = 0;
        row.role = 'button';

        const iconSpan = document.createElement('span');
        iconSpan.className = 'collapsible-icon';
        const iconEl = createIconifyIcon(icon);
        if (iconEl) {
            iconSpan.appendChild(iconEl);
        } else {
            const fb = document.createElement('span');
            fb.className = 'cs-icon-fallback';
            fb.textContent = label.charAt(0) || '?';
            iconSpan.appendChild(fb);
        }
        row.appendChild(iconSpan);

        const labelSpan = document.createElement('span');
        labelSpan.className = 'collapsible-label';
        labelSpan.textContent = label;
        row.appendChild(labelSpan);

        if (sublabel) {
            const sub = document.createElement('span');
            sub.className = 'slide-sublabel';
            sub.textContent = sublabel;
            row.appendChild(sub);
        }

        // Toggle
        const toggle = createHeaderToggle({
            value: headerToggle.value,
            onChange: (v) => headerToggle.onChange(v),
            bind: headerToggle.bind,
            disabled: headerToggle.disabled,
            onDisabledClick: headerToggle.onDisabledClick,
        });
        row.appendChild(toggle);

        // Arrow
        if (hasArrow) {
            const arrowSpan = document.createElement('span');
            arrowSpan.className = 'collapsible-arrow';
            arrowSpan.textContent = '▾';
            row.appendChild(arrowSpan);
        }

        row.addEventListener('click', () => {
            if (window.getSelection()?.toString()) {
                return;
            }
            onClick();
        });
    } else {
        // 原始 slide-item 样式（无 toggle）
        const variant = extra?.variant ?? 'default';
        row.className = 'slide-item' + (focused ? ' slide-focused' : '');
        row.tabIndex = 0;
        row.role = 'button';

        // === 统一左侧行为区：leading 优先于纯展示 .slide-icon（互斥）===
        // leading 存在时，左侧图标被渲染为可点击按钮（保持 radio 指示视觉），
        // 点击 stopPropagation 后触发该动作（如切焦点），与整行 onClick 解耦。
        if (extra?.leading) {
            row.appendChild(createLeadingBtn(extra.leading));
        } else if (!extra?.hideIcon) {
            const iconSpan = document.createElement('span');
            iconSpan.className = 'slide-icon';
            if (extra?.iconFactory) {
                const el = extra.iconFactory();
                if (el) {
                    iconSpan.appendChild(el);
                }
            } else {
                const iconEl = createIconifyIcon(icon);
                if (iconEl) {
                    iconSpan.appendChild(iconEl);
                } else {
                    const fb = document.createElement('span');
                    fb.className = 'cs-icon-fallback';
                    fb.textContent = label.charAt(0) || '?';
                    iconSpan.appendChild(fb);
                }
            }
            row.appendChild(iconSpan);
        }

        // 右侧 label（key-value 布局）
        if (extra?.rightLabel !== undefined) {
            // 左侧 label（字段名）
            const leftSpan = document.createElement('span');
            leftSpan.className = 'slide-label field-label';
            leftSpan.textContent = label;
            row.appendChild(leftSpan);
            // 右侧 label（字段值）
            const rightSpan = document.createElement('span');
            rightSpan.className = 'field-value';
            rightSpan.textContent = extra.rightLabel;
            row.appendChild(rightSpan);
        } else {
            const labelSpan = document.createElement('span');
            let labelCls = 'slide-label';
            if (variant === 'danger') {
                labelCls += ' danger-text';
            } else if (variant === 'accent') {
                labelCls += ' accent-text';
            }
            if (extra?.wrapLabel) {
                labelCls += ' wrap-2';
            }
            labelSpan.className = labelCls;
            labelSpan.textContent = label;
            row.appendChild(labelSpan);
        }

        if (sublabel) {
            const sub = document.createElement('span');
            sub.className = 'slide-sublabel' + (extra?.inlineSub ? ' slide-sublabel-inline' : '');
            sub.textContent = sublabel;
            row.appendChild(sub);
        }

        // === 统一尾部行为区：trailing 优先于装饰性 `>`（互斥，避免误渲染 `>`）===
        if (extra?.trailing) {
            row.appendChild(createTrailingBtn(extra.trailing));
        } else if (hasArrow) {
            const arrowSpan = document.createElement('span');
            arrowSpan.className = 'slide-arrow';
            arrowSpan.textContent = '>';
            row.appendChild(arrowSpan);
        }

        row.addEventListener('click', () => {
            if (window.getSelection()?.toString()) {
                return;
            }
            onClick();
        });
    }

    container.appendChild(row);
    return row;
}

// diagnostic-chat.ts — 纯 UI 渲染函数（无业务协调逻辑）
import { t } from '../core/i18n/t';
import { getLang } from '../core/i18n/locale';
import { renderMarkdownInto } from '../core/ai/markdown';
import { buildToolCatalogText } from '../core/ai/action-catalog';
import type { ChatMessage, ChatChunk } from '../core/ai/types';
import { diagState } from './diagnostic-state';
import { speakLines, cancelSpeech, isSpeechSupported } from '../core/ai/dialogue-speech';
import { parseDialogueLines, type DialogueLine } from '../core/ai/character-bible';
import {
    getActiveBible,
    buildDialogueSystemPrompt,
    listBibles,
    setActiveBible,
} from '../core/ai/dialogue-session';
import { renderPendingAction, renderControlHint } from './diagnostic-control';
import type { MenuNode } from './menu-schema';

/** 添加助手消息 */
export function addAssistantMessage(text: string): void {
    diagState.messages.push({ role: 'assistant', content: text });
}

/** 全量重绘对话区 */
export function renderChat(): void {
    if (!diagState.chatContainer) {
        return;
    }
    diagState.chatContainer.innerHTML = '';

    // 预处理：tool_call_id → 结果文本，供助手消息渲染时反查
    const toolResults = new Map<string, string>();
    for (const msg of diagState.messages) {
        if (msg.role === 'tool') {
            toolResults.set(msg.tool_call_id, msg.content);
        }
    }

    for (const msg of diagState.messages) {
        // ── tool 结果：作为紧凑指示器渲染（不再跳过） ──
        if (msg.role === 'tool') {
            const row = document.createElement('div');
            row.className = 'diag-chat-row chat-row--tool';
            const label = document.createElement('strong');
            label.textContent = t('ai.chat.tool');
            label.className = 'diag-chat-label';
            row.appendChild(label);
            const content = document.createElement('div');
            content.className = 'diag-chat-content diag-tool-result';
            const details = document.createElement('details');
            const summary = document.createElement('summary');
            summary.textContent = t('ai.chat.toolResult');
            summary.className = 'diag-tool-summary';
            details.appendChild(summary);
            const body = document.createElement('div');
            body.className = 'diag-tool-result-body';
            body.textContent =
                msg.content.length > 200 ? msg.content.slice(0, 200) + '…' : msg.content;
            details.appendChild(body);
            content.appendChild(details);
            row.appendChild(content);
            diagState.chatContainer.appendChild(row);
            continue;
        }

        // ── 助手消息（可能含 tool_calls） ──
        const hasToolCalls =
            msg.role === 'assistant' &&
            'tool_calls' in msg &&
            Array.isArray(msg.tool_calls) &&
            msg.tool_calls!.length > 0;
        const textContent = typeof msg.content === 'string' ? msg.content : '';

        // 纯文本助手消息（无 tool_calls）：正常渲染
        // 含 tool_calls 但无文本：只渲染工具调用区
        // 含 tool_calls 且有文本：文本 + 工具调用区
        if (!hasToolCalls && !textContent) {
            continue;
        }

        const row = document.createElement('div');
        row.className = `diag-chat-row chat-row--${msg.role}`;
        const label = document.createElement('strong');
        label.textContent = t(msg.role === 'user' ? 'ai.chat.you' : 'ai.chat.assistant');
        label.className = 'diag-chat-label';
        row.appendChild(label);
        const content = document.createElement('div');
        content.className = 'diag-chat-content';

        // 渲染文本内容
        if (textContent) {
            renderMarkdownInto(content, textContent);
        }

        // 渲染工具调用折叠区
        if (hasToolCalls) {
            const toolDetails = document.createElement('details');
            toolDetails.className = 'diag-tool-calls';
            const toolSummary = document.createElement('summary');
            toolSummary.className = 'diag-tool-summary';
            toolSummary.textContent = t('ai.chat.toolCalls', { count: msg.tool_calls!.length });
            toolDetails.appendChild(toolSummary);
            for (const tc of msg.tool_calls!) {
                const tcDiv = document.createElement('div');
                tcDiv.className = 'diag-tool-call-item';
                const nameSpan = document.createElement('span');
                nameSpan.className = 'diag-tool-call-name';
                nameSpan.textContent = tc.function.name;
                tcDiv.appendChild(nameSpan);
                // 尝试解析参数做简要展示
                try {
                    const args = JSON.parse(tc.function.arguments);
                    const argText = Object.entries(args)
                        .map(
                            ([k, v]) =>
                                `${k}: ${typeof v === 'string' && v.length > 40 ? v.slice(0, 40) + '…' : v}`
                        )
                        .join(', ');
                    if (argText) {
                        const argSpan = document.createElement('span');
                        argSpan.className = 'diag-tool-call-args';
                        argSpan.textContent = `(${argText})`;
                        tcDiv.appendChild(argSpan);
                    }
                } catch {
                    /* 参数解析失败则跳过 */
                }
                // 对应的工具结果状态
                const result = toolResults.get(tc.id);
                if (result !== undefined) {
                    const status = document.createElement('span');
                    status.className = 'diag-tool-call-status';
                    try {
                        const parsed = JSON.parse(result);
                        status.textContent = parsed.success ? '✓' : '✗';
                        status.title = typeof parsed.message === 'string' ? parsed.message : result;
                    } catch {
                        status.textContent = '✓';
                        status.title = result;
                    }
                    tcDiv.appendChild(status);
                }
                toolDetails.appendChild(tcDiv);
            }
            content.appendChild(toolDetails);
        }

        row.appendChild(content);
        diagState.chatContainer.appendChild(row);
    }
    diagState.chatContainer.scrollTop = diagState.chatContainer.scrollHeight;
}

/** 显示"思考中"占位气泡 */
export function showPendingBubble(): void {
    if (!diagState.chatContainer) {
        return;
    }
    if (diagState.chatContainer.querySelector('.chat-row--streaming')) {
        return;
    }
    const row = document.createElement('div');
    row.className = 'diag-chat-row chat-row--streaming chat-row--assistant';
    row.dataset.pending = 'true';
    const label = document.createElement('strong');
    label.textContent = t('ai.chat.assistant');
    label.className = 'diag-chat-label';
    row.appendChild(label);
    const content = document.createElement('div');
    content.textContent = t('ai.chat.thinking');
    content.className = 'diag-chat-content diag-chat-pending';
    row.appendChild(content);
    diagState.chatContainer.appendChild(row);
    diagState.chatContainer.scrollTop = diagState.chatContainer.scrollHeight;
}

/** 流式追加 chunk 到当前 streaming row */
export function renderStreamingChunk(chunk: ChatChunk): void {
    if (!diagState.chatContainer) {
        return;
    }
    if (chunk.type !== 'text' || !chunk.content) {
        return;
    }
    let lastRow = diagState.chatContainer.lastElementChild as HTMLElement | null;
    if (!lastRow || !lastRow.classList.contains('chat-row--streaming')) {
        const row = document.createElement('div');
        row.className = 'diag-chat-row chat-row--streaming chat-row--assistant';
        const label = document.createElement('strong');
        label.textContent = t('ai.chat.assistant');
        label.className = 'diag-chat-label';
        row.appendChild(label);
        const content = document.createElement('div');
        content.textContent = '';
        content.className = 'diag-chat-content';
        row.appendChild(content);
        diagState.chatContainer.appendChild(row);
        lastRow = row;
    } else if (lastRow.dataset.pending === 'true') {
        delete lastRow.dataset.pending;
        const pendingContent = lastRow.querySelector('.diag-chat-pending') as HTMLElement | null;
        if (pendingContent) {
            pendingContent.textContent = '';
            pendingContent.classList.remove('diag-chat-pending');
        }
    }
    if (chunk.reasoning) {
        let details = lastRow.querySelector('.diag-reasoning') as HTMLDetailsElement | null;
        if (!details) {
            details = document.createElement('details');
            details.className = 'diag-reasoning';
            details.open = true;
            const summary = document.createElement('summary');
            summary.textContent = t('ai.chat.reasoning');
            details.appendChild(summary);
            const body = document.createElement('div');
            body.className = 'diag-reasoning-body';
            details.appendChild(body);
            const contentDiv = lastRow.querySelector('.diag-chat-content');
            lastRow.insertBefore(details, contentDiv);
        }
        const body = details.querySelector('.diag-reasoning-body') as HTMLElement;
        if (body) {
            body.textContent += chunk.content;
        }
    } else {
        const contentDiv = lastRow.querySelector('.diag-chat-content') as HTMLElement | null;
        if (contentDiv) {
            const fullText = (contentDiv.dataset.fullText ?? '') + chunk.content;
            contentDiv.dataset.fullText = fullText;
            contentDiv.innerHTML = '';
            renderMarkdownInto(contentDiv, fullText);
        }
    }
    diagState.chatContainer.scrollTop = diagState.chatContainer.scrollHeight;
}

/** 定格 streaming row（移除 streaming class + Markdown 渲染） */
export function finalizeStreamRow(fullText: string): void {
    if (diagState.chatContainer && fullText) {
        const streamingRow = diagState.chatContainer.querySelector('.chat-row--streaming');
        if (streamingRow) {
            streamingRow.classList.remove('chat-row--streaming');
            const contentDiv = streamingRow.querySelector(
                '.diag-chat-content'
            ) as HTMLElement | null;
            if (contentDiv) {
                renderMarkdownInto(contentDiv, fullText);
            }
            diagState.chatContainer.scrollTop = diagState.chatContainer.scrollHeight;
        } else {
            renderChat();
        }
    } else {
        renderChat();
    }
}

/** 流式完成收尾（非 dialogue 模式） */
export function finalizeStream(fullText: string, afterFinalize: () => void): void {
    if (fullText) {
        diagState.messages.push({ role: 'assistant', content: fullText });
    }
    diagState.isStreaming = false;
    diagState.abortController = null;
    if (diagState.dialogueMode && fullText) {
        const lines = parseDialogueLines(fullText);
        renderChat();
        renderDialogueCards(lines);
        if (diagState.speakEnabled) {
            speakLines(lines, speechLang());
        }
    } else {
        finalizeStreamRow(fullText);
    }
    afterFinalize();
}

function speechLang(): string {
    switch (getLang()) {
        case 'ja':
            return 'ja-JP';
        case 'ko':
            return 'ko-KR';
        case 'en':
            return 'en-US';
        case 'zh-TW':
            return 'zh-TW';
        default:
            return 'zh-CN';
    }
}

/** 渲染情绪卡片（台词模式） */
export function renderDialogueCards(lines: DialogueLine[]): void {
    if (!diagState.chatContainer || lines.length === 0) {
        return;
    }
    const wrap = document.createElement('div');
    wrap.className = 'diag-dialogue-cards';
    for (const { line, emotion } of lines) {
        const card = document.createElement('div');
        card.className = `diag-dialogue-card diag-emotion--${emotion}`;
        const tag = document.createElement('span');
        tag.className = 'diag-dialogue-emotion';
        tag.textContent = t('ai.dialogue.emotion.' + emotion);
        card.appendChild(tag);
        const body = document.createElement('div');
        body.className = 'diag-dialogue-line';
        body.textContent = line;
        card.appendChild(body);
        wrap.appendChild(card);
    }
    diagState.chatContainer.appendChild(wrap);
    diagState.chatContainer.scrollTop = diagState.chatContainer.scrollHeight;
}

/** 历史截断 */
export function pruneHistory(messages: ChatMessage[], maxPairs = 10): ChatMessage[] {
    const systemMsg = messages[0]?.role === 'system' ? messages[0] : null;
    const body = systemMsg ? messages.slice(1) : messages;
    if (body.length <= maxPairs * 2) {
        return messages;
    }
    const keepFromIdx = body.length - maxPairs * 2;
    let start = keepFromIdx;
    while (start > 0 && body[start]?.role === 'tool') {
        start--;
    }
    if (start > 0 && body[start]?.role === 'assistant') {
        const asst = body[start] as Extract<ChatMessage, { role: 'assistant' }>;
        if (asst.tool_calls) {
            while (start > 0 && body[start - 1]?.role === 'tool') {
                start--;
            }
        }
    }
    const pruned = body.slice(start);
    return systemMsg ? [systemMsg, ...pruned] : pruned;
}

/** 构造 system message */
export function buildSystemMessage(): ChatMessage {
    if (diagState.dialogueMode) {
        return { role: 'system', content: buildDialogueSystemPrompt(getActiveBible()) };
    }
    const catalog = buildToolCatalogText();
    return {
        role: 'system',
        content: [t('ai.system.control'), catalog, t('ai.system.controlFormat')].join('\n\n'),
    };
}

/** 更新朗读开关 UI（不支持时隐藏） */
export function updateSpeakToggle(): void {
    if (!diagState.speakToggleBtn) {
        return;
    }
    if (!isSpeechSupported() && diagState.dialogueMode) {
        diagState.speakToggleBtn.style.display = 'none';
        return;
    }
    diagState.speakToggleBtn.style.display = diagState.dialogueMode ? '' : 'none';
    diagState.speakToggleBtn.textContent = diagState.speakEnabled
        ? t('ai.dialogue.speakOn')
        : t('ai.dialogue.speakOff');
    diagState.speakToggleBtn.setAttribute('aria-checked', String(diagState.speakEnabled));
    diagState.speakToggleBtn.setAttribute('aria-label', t('ai.dialogue.speakToggle'));
}

/** 更新发送/停止按钮 */
export function updateSendButton(): void {
    const sendBtn = document.getElementById('diag-send-btn') as HTMLButtonElement | null;
    if (!sendBtn) {
        return;
    }
    if (diagState.isStreaming) {
        sendBtn.innerHTML = '\u25A0';
        sendBtn.setAttribute('aria-label', t('ai.chat.stop'));
        sendBtn.disabled = false;
    } else {
        sendBtn.innerHTML = '\u25B6';
        sendBtn.setAttribute('aria-label', t('ai.chat.send'));
        sendBtn.disabled = diagState.pendingAction !== null || !diagState.aiResolved;
    }
}

/** 构建 chat schema（纯 DOM 构建） */
export function buildChatSchema(): MenuNode[] {
    return [
        {
            id: 'diagnostic:chat',
            kind: 'custom',
            renderCustom: (c) => {
                diagState.chatContainer = document.createElement('div');
                diagState.chatContainer.setAttribute('aria-live', 'polite');
                diagState.chatContainer.setAttribute('aria-relevant', 'additions');
                diagState.chatContainer.className = 'diag-chat-box';
                c.appendChild(diagState.chatContainer);

                const inputRow = document.createElement('div');
                inputRow.className = 'diag-input-row';
                diagState.inputEl = document.createElement('textarea');
                diagState.inputEl.placeholder = t('ai.chat.placeholder');
                diagState.inputEl.setAttribute('aria-label', t('ai.chat.placeholder'));
                diagState.inputEl.className = 'diag-textarea';
                diagState.inputEl.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        diagState.callbacks.sendMessage?.();
                    }
                });
                inputRow.appendChild(diagState.inputEl);
                c.appendChild(inputRow);

                const btnRow = document.createElement('div');
                btnRow.className = 'diag-btn-row';

                const sendBtn = document.createElement('button');
                sendBtn.id = 'diag-send-btn';
                sendBtn.className = 'preset-chip diag-btn-icon';
                sendBtn.setAttribute('aria-label', t('ai.chat.send'));
                sendBtn.innerHTML = '\u25B6';
                btnRow.appendChild(sendBtn);

                const clearBtn = document.createElement('button');
                clearBtn.id = 'diag-clear-btn';
                clearBtn.className = 'preset-chip diag-btn-icon';
                clearBtn.setAttribute('aria-label', t('ai.chat.clear'));
                clearBtn.innerHTML = '\u2715';
                btnRow.appendChild(clearBtn);

                const spacer = document.createElement('div');
                spacer.className = 'diag-btn-spacer';
                btnRow.appendChild(spacer);

                const dialogueToggle = document.createElement('button');
                dialogueToggle.id = 'diag-dialogue-toggle';
                dialogueToggle.className = 'preset-chip diag-btn-icon';
                dialogueToggle.setAttribute('aria-pressed', 'false');
                dialogueToggle.setAttribute('aria-label', t('ai.mode.dialogue'));
                dialogueToggle.innerHTML = '\uD83D\uDCAC';
                btnRow.appendChild(dialogueToggle);

                const roleSelect = document.createElement('select');
                roleSelect.className = 'diag-role-select';
                roleSelect.style.display = 'none';
                roleSelect.setAttribute('aria-label', t('ai.dialogue.roleSelect'));
                for (const bible of listBibles()) {
                    const opt = document.createElement('option');
                    opt.value = bible.id;
                    opt.textContent = bible.name;
                    if (bible.id === getActiveBible().id) {
                        opt.selected = true;
                    }
                    roleSelect.appendChild(opt);
                }
                roleSelect.addEventListener('change', () => setActiveBible(roleSelect.value));
                btnRow.appendChild(roleSelect);

                dialogueToggle.addEventListener('click', () => {
                    diagState.dialogueMode = !diagState.dialogueMode;
                    roleSelect.style.display = diagState.dialogueMode ? '' : 'none';
                    dialogueToggle.setAttribute('aria-pressed', String(diagState.dialogueMode));
                    if (diagState.dialogueMode) {
                        diagState.callbacks.ensureActionsRegistered?.();
                    } else {
                        cancelSpeech();
                    }
                    updateSpeakToggle();
                    if (diagState.pendingContainer) {
                        diagState.pendingContainer.style.display = diagState.dialogueMode
                            ? 'none'
                            : '';
                        if (!diagState.dialogueMode) {
                            if (diagState.pendingAction) {
                                renderPendingAction();
                            } else {
                                renderControlHint();
                            }
                        }
                    }
                    diagState.callbacks.updateControlsEnabled?.();
                });

                diagState.speakToggleBtn = document.createElement('button');
                diagState.speakToggleBtn.id = 'diag-speak-toggle';
                diagState.speakToggleBtn.className = 'preset-chip diag-btn-icon';
                diagState.speakToggleBtn.setAttribute('role', 'switch');
                diagState.speakToggleBtn.innerHTML = '\uD83D\uDD0A';
                diagState.speakToggleBtn.addEventListener('click', () => {
                    diagState.speakEnabled = !diagState.speakEnabled;
                    if (!diagState.speakEnabled) {
                        cancelSpeech();
                    }
                    updateSpeakToggle();
                });
                btnRow.appendChild(diagState.speakToggleBtn);
                updateSpeakToggle();

                c.appendChild(btnRow);

                diagState.pendingContainer = document.createElement('div');
                diagState.pendingContainer.className = 'diag-pending-area';
                diagState.pendingContainer.style.display = 'none';
                diagState.pendingContainer.setAttribute('data-testid', 'ai:control:pending-action');
                c.appendChild(diagState.pendingContainer);

                renderChat();
                updateSendButton();
            },
        },
    ];
}

// Core
import { t } from '../core/i18n/t';
import { logWarn } from '../core/logger';
import { DebouncedTimer } from '../core/async';
import { captureError } from '../core/ai/error-buffer';
import {
    loadAiConfig,
    saveAiConfig,
    ensureAiConfigLoaded,
    PROVIDER_PRESETS,
    validateAiConfig,
    normalizeEndpoint,
    DEFAULT_RELAY_URL,
    type AiConfig,
    type AiConfigProvider,
} from '../core/ai/config-store';
import { resolveAi } from '../core/ai';
import type { AiErrorKind } from '../core/ai/types';

// Local
import { diagState } from './diagnostic-state';
import type { MenuNode } from './menu-schema';

export function goKeyAllowsProceed(validation: ReturnType<typeof validateAiConfig>): boolean {
    if (validation.ok) {
        return true;
    }
    if (diagState.ai?.kind !== 'go') {
        return false;
    }
    if (!diagState.goKeyConfigured) {
        return false;
    }
    // go 模式 key 不可回读但已配置：允许 missingKey 通过
    if (validation.kind === 'missingKey') {
        return true;
    }
    return false;
}

async function ensureTestModel(): Promise<void> {
    if (diagState.localConfig.model.trim()) {
        return;
    }
    if (diagState.fetchedModels.length === 0) {
        await refreshModelList();
    }
    if (diagState.fetchedModels.length > 0) {
        diagState.localConfig.model = diagState.fetchedModels[0];
        if (diagState.configModel) {
            diagState.configModel.value = diagState.fetchedModels[0];
        }
        await doSaveConfig();
    }
}

function inferProvider(endpoint: string): AiConfigProvider {
    if (!endpoint) {
        return 'custom';
    }
    let hostname: string;
    try {
        hostname = new URL(endpoint).hostname;
    } catch {
        return 'custom';
    }
    const matched = (Object.keys(PROVIDER_PRESETS) as AiConfigProvider[])
        .filter((p) => p !== 'custom')
        .find((p) => {
            try {
                return new URL(PROVIDER_PRESETS[p].endpoint).hostname === hostname;
            } catch {
                return false;
            }
        });
    return matched ?? 'custom';
}

export async function loadInitialConfig(): Promise<void> {
    await diagState.saveChain;
    await ensureAiConfigLoaded();
    diagState.localConfig = { ...loadAiConfig() };
    await resolveAi();
    if (diagState.ai?.loadConfig) {
        try {
            const persisted = await diagState.ai.loadConfig();
            if (persisted.endpoint || persisted.model) {
                diagState.localConfig = {
                    ...diagState.localConfig,
                    provider: inferProvider(persisted.endpoint),
                    endpoint: persisted.endpoint,
                    model: persisted.model,
                    apiKey: persisted.apiKey ?? diagState.localConfig.apiKey,
                    relayUrl: persisted.relayUrl ?? diagState.localConfig.relayUrl,
                };
            }
            if (diagState.ai.kind === 'go' && persisted.keyConfigured && !persisted.apiKey) {
                diagState.goKeyConfigured = true;
            }
        } catch {
            /* keep defaults */
        }
    }
}

export async function refreshCaps(): Promise<void> {
    if (diagState.refreshingCaps || !diagState.ai) {
        return;
    }
    diagState.refreshingCaps = true;
    try {
        await diagState.ai.refreshCapabilities?.();
        diagState.caps = diagState.ai.capabilities();
        refreshConfigUI();
    } finally {
        diagState.refreshingCaps = false;
    }
}

function refreshConfigUI(): void {
    updateCorsWarning();
    updateApiKeyVisibility();
    if (diagState.caps === null) {
        setStatusBadge('initializing');
    } else {
        updateStatusBadge();
        scheduleAutoTest();
    }
}

function scheduleAutoTest(): void {
    if (!diagState.aiResolved || diagState.testing) {
        return;
    }
    if (!diagState.autoTestTimer) {
        diagState.autoTestTimer = new DebouncedTimer();
    }
    void refreshModelList();
    diagState.autoTestTimer.schedule(() => void runAutoTest(), 600);
}

async function runAutoTest(): Promise<void> {
    if (!diagState.ai || diagState.testing || diagState.autoTesting) {
        return;
    }
    await ensureTestModel();
    const validation = validateAiConfig(diagState.localConfig);
    if (!validation.ok && !goKeyAllowsProceed(validation)) {
        return;
    }
    diagState.autoTesting = true;
    setStatusBadge('testing');
    try {
        const result = await diagState.ai.testConnection();
        if (result.ok) {
            diagState.lastConnectionOk = true;
            diagState.lastConnectionKind = null;
            renderAdvice(undefined);
        } else {
            diagState.lastConnectionOk = false;
            diagState.lastConnectionKind = result.kind;
            captureError('ai-connection', result.message, undefined);
            renderAdvice(result.kind);
        }
    } catch (err) {
        diagState.lastConnectionOk = false;
        diagState.lastConnectionKind = 'unknown';
        captureError('ai-connection', err instanceof Error ? err.message : String(err), err);
        renderAdvice('unknown');
    } finally {
        diagState.autoTesting = false;
        updateStatusBadge();
    }
}

function updateApiKeyVisibility(): void {
    if (!diagState.configApiKey) {
        return;
    }
    const row = diagState.configApiKey.closest('.diag-field-row') as HTMLElement | null;
    if (!row) {
        return;
    }
    const needsKey = PROVIDER_PRESETS[diagState.localConfig.provider].needsKey;
    row.style.display = needsKey ? '' : 'none';
}

function updateCorsWarning(): void {
    if (!diagState.corsWarningEl || !diagState.relayStatusEl) {
        return;
    }
    const caps = diagState.caps;
    const cfg = diagState.localConfig;
    if (!caps) {
        diagState.corsWarningEl.style.display = 'none';
        diagState.relayStatusEl.textContent = '';
        return;
    }

    // [doc:relay] 若 relay 已配置且网页端+远程端点，显示 relay 状态，隐藏 CORS 警告
    const isRemote = !/^https?:\/\/(localhost|127\.0\.0\.1)(:|\/|$)/i.test(cfg.endpoint);
    const relayConfigured = !!(cfg.relayUrl && isRemote);

    if (relayConfigured) {
        diagState.corsWarningEl.style.display = 'none';
        diagState.relayStatusEl.textContent = t('ai.config.relayActive', { url: cfg.relayUrl });
        diagState.relayStatusEl.className = 'diag-hint diag-hint--ok';
    } else if (caps.corsRisk !== 'none') {
        diagState.corsWarningEl.style.display = '';
        diagState.relayStatusEl.textContent = t('ai.config.relayNotConfigured');
        diagState.relayStatusEl.className = 'diag-hint';
    } else {
        diagState.corsWarningEl.style.display = 'none';
        diagState.relayStatusEl.textContent = '';
    }
}

export function persistConfig(partial: Partial<AiConfig>): void {
    diagState.localConfig = { ...diagState.localConfig, ...partial };
    void doSaveConfig();
}

async function doSaveConfig(): Promise<void> {
    const snapshot: AiConfig = { ...diagState.localConfig };
    const kind = diagState.ai?.kind;
    diagState.saveChain = diagState.saveChain.then(async () => {
        try {
            if (kind === 'go') {
                const normalizedEndpoint = normalizeEndpoint(snapshot.endpoint);
                const b = await import('@bindings/mikumikuar/internal/app/app');
                await b.AiSetLLMConfig({
                    baseUrl: normalizedEndpoint,
                    model: snapshot.model,
                    aiKey: snapshot.apiKey,
                });
                await saveAiConfig({ ...snapshot, endpoint: normalizedEndpoint, apiKey: '' });
            } else {
                await saveAiConfig(snapshot);
            }
        } catch (err) {
            console.warn('[ai-config] 持久化失败', err);
            throw err; // 重新抛出，让调用方（如保存按钮）能够捕获并反馈给用户
        }
    });
    return diagState.saveChain;
}

export function applyProvider(provider: AiConfigProvider): void {
    const preset = PROVIDER_PRESETS[provider];
    diagState.localConfig.provider = provider;
    diagState.localConfig.endpoint = preset.endpoint;
    diagState.localConfig.model = preset.model;
    if (diagState.configEndpoint) {
        diagState.configEndpoint.value = preset.endpoint;
    }
    if (diagState.configModel) {
        diagState.configModel.value = preset.model;
    }
    updateProviderButtons(provider);
    updateDocLink(provider);
    if (diagState.configModelDatalist) {
        diagState.configModelDatalist.innerHTML = '';
    }
    diagState.fetchedModels = [];
    void (async () => {
        await doSaveConfig();
        void refreshCaps();
        void refreshModelList();
    })();
}

function updateProviderButtons(active: AiConfigProvider): void {
    for (const btn of diagState.activeProviderButtons) {
        const provider = btn.dataset.provider as AiConfigProvider;
        btn.className = 'preset-chip' + (provider === active ? ' active' : '');
    }
}

function updateDocLink(provider: AiConfigProvider): void {
    if (!diagState.activeDocLink) {
        return;
    }
    const preset = PROVIDER_PRESETS[provider];
    if (preset.docUrl) {
        diagState.activeDocLink.href = preset.docUrl;
        diagState.activeDocLink.textContent = t('ai.config.doc', { provider: t(preset.labelKey) });
        diagState.activeDocLink.style.display = '';
    } else {
        diagState.activeDocLink.style.display = 'none';
    }
}

export async function refreshModelList(): Promise<void> {
    if (!diagState.ai) {
        return;
    }
    try {
        const models = (await diagState.ai.fetchModels?.()) ?? [];
        diagState.fetchedModels = models;
        populateModelDatalist(models);
        if (models.length > 0 && diagState.configModel) {
            populateModelChips(models, diagState.configModel);
            if (diagState.modelListEl) {
                diagState.modelListEl.style.display = '';
            }
        }
        const btn = document.getElementById('diag-model-refresh-btn');
        if (btn) {
            btn.setAttribute(
                'title',
                models.length > 0
                    ? t('ai.config.modelsFound', { n: String(models.length) })
                    : t('ai.config.modelsNone')
            );
        }
    } catch (err) {
        logWarn('ai-config', 'fetchModels failed:', err);
        const btn = document.getElementById('diag-model-refresh-btn');
        if (btn) {
            btn.setAttribute('title', t('ai.config.modelsNone'));
        }
    }
}

function populateModelDatalist(models: string[]): void {
    if (!diagState.configModelDatalist) {
        return;
    }
    diagState.configModelDatalist.innerHTML = '';
    for (const m of models) {
        const opt = document.createElement('option');
        opt.value = m;
        diagState.configModelDatalist.appendChild(opt);
    }
}

function populateModelChips(models: string[], inputEl: HTMLInputElement): void {
    if (!diagState.modelListEl) {
        return;
    }
    diagState.modelListEl.innerHTML = '';
    for (const m of models) {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.textContent = m;
        chip.className = 'preset-chip';
        chip.addEventListener('click', () => {
            diagState.localConfig.model = m;
            inputEl.value = m;
            persistConfig({ model: m });
            if (diagState.modelListEl) {
                diagState.modelListEl.style.display = 'none';
            }
        });
        diagState.modelListEl.appendChild(chip);
    }
}

export function updateStatusBadge(): void {
    if (!diagState.statusBadgeEl || !diagState.statusTextEl) {
        return;
    }
    const validation = validateAiConfig(diagState.localConfig);
    if (!validation.ok && !goKeyAllowsProceed(validation) && validation.kind) {
        setStatusBadge(validation.kind);
        renderAdvice(validation.kind);
        return;
    }
    if (diagState.lastConnectionOk === true) {
        setStatusBadge('connected');
        renderAdvice(undefined);
    } else if (diagState.lastConnectionOk === false) {
        const kind = diagState.lastConnectionKind ?? 'unknown';
        setStatusBadge(kind);
        renderAdvice(kind);
    } else {
        setStatusBadge(diagState.caps?.available ? 'disconnected' : 'missingEndpoint');
        renderAdvice(undefined);
    }
}

function setStatusBadge(
    state: AiErrorKind | 'connected' | 'disconnected' | 'testing' | 'error' | 'initializing'
): void {
    if (!diagState.statusBadgeEl || !diagState.statusTextEl) {
        return;
    }
    diagState.statusBadgeEl.className = 'diag-status-badge diag-status-badge--' + state;
    diagState.statusTextEl.textContent = t(`ai.status.${state}`);
}

function focusInput(el: HTMLInputElement | null): void {
    if (!el) {
        return;
    }
    el.closest('.diag-field-row')?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    el.focus();
}

function renderAdvice(kind?: AiErrorKind): void {
    if (!diagState.adviceEl) {
        return;
    }
    if (!kind) {
        diagState.adviceEl.style.display = 'none';
        diagState.adviceEl.innerHTML = '';
        return;
    }
    diagState.adviceEl.className = 'diag-advice diag-advice--' + kind;
    diagState.adviceEl.innerHTML = '';
    const textSpan = document.createElement('span');
    textSpan.textContent = t(`ai.errorAdvice.${kind}`);
    diagState.adviceEl.appendChild(textSpan);
    const actions = document.createElement('div');
    actions.className = 'diag-advice-actions';
    if (kind === 'missingEndpoint' || kind === 'notFound') {
        const btn = document.createElement('button');
        btn.className = 'preset-chip';
        btn.textContent = t('ai.config.endpoint');
        btn.addEventListener('click', () => focusInput(diagState.configEndpoint));
        actions.appendChild(btn);
    }
    if (kind === 'missingKey' || kind === 'unauthorized') {
        const btn = document.createElement('button');
        btn.className = 'preset-chip';
        btn.textContent = t('ai.config.apiKey');
        btn.addEventListener('click', () => focusInput(diagState.configApiKey));
        actions.appendChild(btn);
    }
    if (kind === 'missingModel') {
        const btn = document.createElement('button');
        btn.className = 'preset-chip';
        btn.textContent = t('ai.config.model');
        btn.addEventListener('click', () => focusInput(diagState.configModel));
        actions.appendChild(btn);
    }
    if (actions.children.length > 0) {
        diagState.adviceEl.appendChild(actions);
    }
    diagState.adviceEl.style.display = 'block';
}

async function flushAndSave(): Promise<{ ok: boolean; error?: string }> {
    if (diagState.configEndpoint) {
        diagState.localConfig.endpoint = diagState.configEndpoint.value;
    }
    if (diagState.configModel) {
        diagState.localConfig.model = diagState.configModel.value;
    }
    if (diagState.configApiKey) {
        diagState.localConfig.apiKey = diagState.configApiKey.value;
    }
    try {
        await doSaveConfig();
        void refreshCaps();
        return { ok: true };
    } catch (err) {
        return { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
}

export function buildConfigSchema(): MenuNode[] {
    return [
        {
            id: 'diagnostic:config',
            kind: 'custom',
            renderCustom: (c) => {
                const loadingEl = document.createElement('div');
                loadingEl.className = 'setting-hint';
                loadingEl.textContent = '\u231B ' + t('ai.config.loading');
                c.appendChild(loadingEl);
                void (async () => {
                    try {
                        await loadInitialConfig();
                    } catch (err) {
                        console.warn('[ai-config] loadInitialConfig failed', err);
                    } finally {
                        loadingEl.remove();
                    }
                    renderConfigCard(c);
                })();
            },
        },
    ];
}

function renderConfigCard(c: HTMLElement): void {
    diagState.activeProviderButtons = [];
    diagState.activeDocLink = null;

    const statusBadge = document.createElement('div');
    statusBadge.className = 'diag-status-badge diag-status-badge--disconnected';
    const statusText = document.createElement('span');
    statusText.textContent = t('ai.status.disconnected');
    statusBadge.appendChild(statusText);
    c.appendChild(statusBadge);
    diagState.statusBadgeEl = statusBadge;
    diagState.statusTextEl = statusText;

    const adviceEl = document.createElement('div');
    adviceEl.className = 'diag-advice';
    adviceEl.style.display = 'none';
    adviceEl.setAttribute('role', 'status');
    c.appendChild(adviceEl);
    diagState.adviceEl = adviceEl;

    const hintEl = document.createElement('div');
    hintEl.className = 'setting-hint';
    hintEl.textContent = t('ai.config.providerHint');
    c.appendChild(hintEl);

    const providerRow = document.createElement('div');
    providerRow.className = 'diag-provider-row';
    const providers: AiConfigProvider[] = ['deepseek', 'openai', 'openrouter', 'custom', 'ollama'];
    for (const provider of providers) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = t(PROVIDER_PRESETS[provider].labelKey);
        btn.className =
            'preset-chip' + (provider === diagState.localConfig.provider ? ' active' : '');
        btn.dataset.provider = provider;
        btn.addEventListener('click', () => applyProvider(provider));
        providerRow.appendChild(btn);
        diagState.activeProviderButtons.push(btn);
    }
    const docLink = document.createElement('a');
    docLink.target = '_blank';
    docLink.className = 'diag-link';
    docLink.setAttribute('aria-label', t('ai.config.doc', { provider: '' }));
    providerRow.appendChild(docLink);
    diagState.activeDocLink = docLink;
    c.appendChild(providerRow);

    diagState.corsWarningEl = document.createElement('div');
    diagState.corsWarningEl.textContent = t('ai.config.corsWarning');
    diagState.corsWarningEl.className = 'diag-warning';
    diagState.corsWarningEl.setAttribute('role', 'alert');
    c.appendChild(diagState.corsWarningEl);

    diagState.relayStatusEl = document.createElement('div');
    diagState.relayStatusEl.className = 'diag-hint';
    c.appendChild(diagState.relayStatusEl);

    const createField = (
        label: string,
        type: string,
        value: string,
        onChange: (val: string) => void,
        fieldKey?: keyof AiConfig
    ): { row: HTMLDivElement; input: HTMLInputElement } => {
        const row = document.createElement('div');
        row.className = 'diag-field-row';
        const lbl = document.createElement('div');
        lbl.textContent = label;
        lbl.className = 'diag-field-label';
        row.appendChild(lbl);
        const input = document.createElement('input');
        input.type = type;
        input.value = value;
        input.className = 'diag-input';
        input.addEventListener('input', () => onChange(input.value));
        input.addEventListener('blur', () => {
            persistConfig(fieldKey ? { [fieldKey]: input.value } : diagState.localConfig);
        });
        row.appendChild(input);
        return { row, input };
    };

    const endpointGroup = createField(
        t('ai.config.endpoint'),
        'text',
        diagState.localConfig.endpoint,
        (v) => {
            diagState.localConfig.endpoint = v;
        },
        'endpoint'
    );
    c.appendChild(endpointGroup.row);
    diagState.configEndpoint = endpointGroup.input;

    const apiKeyGroup = createField(
        t('ai.config.apiKey'),
        'password',
        diagState.localConfig.apiKey,
        (v) => {
            diagState.localConfig.apiKey = v;
        },
        'apiKey'
    );
    c.appendChild(apiKeyGroup.row);
    diagState.configApiKey = apiKeyGroup.input;

    if (diagState.ai?.kind === 'go' && diagState.goKeyConfigured && diagState.configApiKey) {
        diagState.configApiKey.placeholder = t('ai.config.keyConfigured');
    }

    const modelRow = document.createElement('div');
    modelRow.className = 'diag-field-row';
    const modelLabel = document.createElement('div');
    modelLabel.textContent = t('ai.config.model');
    modelLabel.className = 'diag-field-label';
    modelRow.appendChild(modelLabel);
    const modelInput = document.createElement('input');
    modelInput.type = 'text';
    modelInput.className = 'diag-input';
    modelInput.value = diagState.localConfig.model;
    modelInput.setAttribute('list', 'diag-model-list');
    modelInput.setAttribute('aria-label', t('ai.config.model'));
    modelInput.addEventListener('input', () => {
        diagState.localConfig.model = modelInput.value;
        if (diagState.modelListEl) {
            diagState.modelListEl.style.display = 'none';
        }
    });
    modelInput.addEventListener('blur', () => persistConfig({ model: modelInput.value }));
    modelRow.appendChild(modelInput);

    const modelBtnRow = document.createElement('div');
    modelBtnRow.className = 'diag-hint-row';

    const modelRefresh = document.createElement('button');
    modelRefresh.id = 'diag-model-refresh-btn';
    modelRefresh.textContent = t('ai.config.refreshModels');
    modelRefresh.className = 'preset-chip';
    modelRefresh.setAttribute('title', t('ai.config.refreshModels'));
    modelRefresh.setAttribute('aria-label', t('ai.config.refreshModels'));
    modelRefresh.style.padding = '2px 10px';
    modelRefresh.style.fontSize = 'var(--font-ui-sm)';
    modelBtnRow.appendChild(modelRefresh);

    const modelToggleBtn = document.createElement('button');
    modelToggleBtn.textContent = '\u25BC';
    modelToggleBtn.className = 'preset-chip';
    modelToggleBtn.setAttribute('title', t('ai.config.showModels'));
    modelToggleBtn.setAttribute('aria-label', t('ai.config.showModels'));
    modelToggleBtn.style.padding = '2px 10px';
    modelToggleBtn.style.fontSize = 'var(--font-ui-sm)';
    modelToggleBtn.addEventListener('click', () => {
        if (diagState.modelListEl && diagState.modelListEl.style.display !== 'none') {
            diagState.modelListEl.style.display = 'none';
        } else if (diagState.modelListEl && diagState.modelListEl.children.length > 0) {
            diagState.modelListEl.style.display = '';
        } else {
            modelRefresh.click();
        }
    });
    modelBtnRow.appendChild(modelToggleBtn);
    modelRow.appendChild(modelBtnRow);

    const modelDatalist = document.createElement('datalist');
    modelDatalist.id = 'diag-model-list';
    modelRow.appendChild(modelDatalist);
    c.appendChild(modelRow);

    const modelListWrap = document.createElement('div');
    modelListWrap.className = 'diag-model-chips';
    modelListWrap.style.display = 'none';
    c.appendChild(modelListWrap);
    diagState.configModel = modelInput;
    diagState.configModelDatalist = modelDatalist;
    diagState.modelListEl = modelListWrap;

    const testRow = document.createElement('div');
    testRow.className = 'diag-hint-row';

    const saveBtn = document.createElement('button');
    saveBtn.textContent = t('ai.config.save');
    saveBtn.className = 'preset-chip';
    saveBtn.setAttribute('aria-label', t('ai.config.save'));
    testRow.appendChild(saveBtn);

    const testBtn = document.createElement('button');
    testBtn.id = 'diag-test-btn';
    testBtn.textContent = t('ai.config.test');
    testBtn.className = 'preset-chip';
    testBtn.setAttribute('aria-label', t('ai.config.test'));
    testRow.appendChild(testBtn);

    const statusEl = document.createElement('span');
    statusEl.className = 'diag-status';
    testRow.appendChild(statusEl);
    c.appendChild(testRow);

    // Wire up model refresh click (event handler set by entry point via data attributes)
    modelRefresh.addEventListener('click', async () => {
        if (modelRefresh.dataset.refreshing === 'true' || !diagState.ai) {
            return;
        }
        modelRefresh.dataset.refreshing = 'true';
        modelRefresh.disabled = true;
        modelRefresh.textContent = '\u2026';
        try {
            await flushAndSave();
            const models = (await diagState.ai.fetchModels?.()) ?? [];
            diagState.fetchedModels = models;
            populateModelDatalist(models);
            if (models.length > 0 && !diagState.localConfig.model) {
                diagState.localConfig.model = models[0];
                modelInput.value = models[0];
            }
            modelRefresh.setAttribute(
                'title',
                models.length > 0
                    ? t('ai.config.modelsFound', { n: String(models.length) })
                    : t('ai.config.modelsNone')
            );
            if (models.length > 0) {
                populateModelChips(models, modelInput);
                modelListWrap.style.display = '';
            }
        } catch (err) {
            console.warn('[ai-config] 发现模型失败', err);
            modelRefresh.setAttribute('title', t('ai.config.modelsNone'));
        } finally {
            delete modelRefresh.dataset.refreshing;
            modelRefresh.disabled = false;
            modelRefresh.textContent = t('ai.config.refreshModels');
        }
    });

    let saving = false;
    saveBtn.addEventListener('click', async () => {
        if (saving) {
            return;
        }
        saving = true;
        saveBtn.disabled = true;
        statusEl.textContent = t('ai.config.saving');
        statusEl.style.color = 'var(--text-muted)';
        const res = await flushAndSave();
        statusEl.textContent = res.ok
            ? t('ai.config.saved')
            : `${t('ai.config.saveFailed')}: ${res.error ?? ''}`;
        statusEl.style.color = res.ok ? 'var(--success)' : 'var(--danger)';
        if (!res.ok) {
            captureError('ai-config', res.error ?? 'save failed', undefined);
        }
        saving = false;
        saveBtn.disabled = false;
    });

    testBtn.addEventListener('click', () => void testConnection(statusEl));

    updateDocLink(diagState.localConfig.provider);
    refreshConfigUI();
}

async function testConnection(statusEl: HTMLElement): Promise<void> {
    if (diagState.testing || diagState.autoTesting) {
        return;
    }
    diagState.testing = true;
    if (!diagState.ai) {
        statusEl.textContent = t('ai.config.notResolved');
        statusEl.style.color = 'var(--warn)';
        diagState.lastConnectionOk = false;
        updateStatusBadge();
        diagState.testing = false;
        return;
    }
    await ensureTestModel();
    await flushAndSave();
    const validation = validateAiConfig(diagState.localConfig);
    if (!validation.ok && !goKeyAllowsProceed(validation)) {
        const errMsg = validation.errors
            ? validation.errors.map((e) => t(e.message)).join('; ')
            : t(validation.message);
        statusEl.textContent = errMsg;
        statusEl.style.color = 'var(--warn)';
        captureError('ai-config', errMsg, undefined);
        if (validation.kind) {
            setStatusBadge(validation.kind);
            renderAdvice(validation.kind);
        }
        diagState.lastConnectionOk = false;
        diagState.testing = false;
        return;
    }
    statusEl.textContent = t('ai.config.testing');
    statusEl.style.color = 'var(--text-muted)';
    setStatusBadge('testing');
    diagState.lastConnectionOk = null;
    const isLocalOllama =
        /localhost|127\.0\.0\.1/i.test(diagState.localConfig.endpoint) &&
        diagState.localConfig.provider === 'ollama';
    try {
        const result = await diagState.ai.testConnection();
        if (result.ok) {
            statusEl.textContent = t('ai.config.connected');
            statusEl.style.color = 'var(--success)';
            diagState.lastConnectionOk = true;
            diagState.lastConnectionKind = null;
            renderAdvice(undefined);
        } else {
            const msg = isLocalOllama
                ? t('ai.errorAdvice.ollamaNotInstalled') + ' ' + result.message
                : result.message;
            statusEl.textContent = msg;
            statusEl.style.color = 'var(--danger)';
            captureError('ai-connection', result.message, undefined);
            diagState.lastConnectionKind = result.kind;
            setStatusBadge(result.kind);
            renderAdvice(result.kind);
            diagState.lastConnectionOk = false;
        }
    } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        const display = isLocalOllama ? t('ai.errorAdvice.ollamaNotInstalled') + ' ' + msg : msg;
        statusEl.textContent = display;
        statusEl.style.color = 'var(--danger)';
        captureError('ai-connection', msg, err);
        diagState.lastConnectionKind = 'unknown';
        setStatusBadge('unknown');
        renderAdvice('unknown');
        diagState.lastConnectionOk = false;
    } finally {
        diagState.testing = false;
    }
    updateStatusBadge();
}

// [doc:architecture] Env Ground Level — 地面功能面板
// 从 env-feature-levels.ts 拆分

import { envState } from '../core/config';
