                        visibleWhen: () => envState.groundOverlay === 'checker',
                    },
                ],
            },
        ];
        disposes.push(renderMenu(overlaySchema, c));

        // ===== 地形（schema 驱动）=====
        const terrainSchema: MenuNode[] = [
            {
                id: 'env:ground:terrain',
                kind: 'folder',
                label: 'env.terrain',
                icon: 'lucide:mountain',
                defaultOpen: false,
                headerToggle: {
                    bind: 'env.groundType',
                    get: (v) => v === 'terrain',
                    set: (on) => (on ? 'terrain' : 'flat'),
                },
                children: [
                    {
                        id: 'env:ground:terrain-height',
                        kind: 'slider',
                        label: 'env.terrainHeight',
                        control: {
                            bind: 'env.groundTerrainHeight',
                            min: 0,
                            max: 15,
                            step: 0.1,
                        },
                        icon: 'lucide:mountain',
                    },
                    {
                        id: 'env:ground:terrain-scale',
                        kind: 'slider',
                        label: 'env.terrainScale',
                        control: {
                            bind: 'env.groundTerrainScale',
                            min: 0.01,
                            max: 5,
                            step: 0.05,
                        },
                        icon: 'lucide:ruler',
                    },
                    {
                        id: 'env:ground:terrain-seed',
                        kind: 'slider',
                        label: 'env.terrainSeed',
                        control: {
                            bind: 'env.groundTerrainSeed',
                            min: 0,
                            max: 9999,
                            step: 1,
                        },
                        icon: 'lucide:hash',
                    },
                    {
                        id: 'env:ground:terrain-octaves',
                        kind: 'slider',
                        label: 'env.terrainOctaves',
                        control: {
                            bind: 'env.groundTerrainOctaves',
                            min: 1,
                            max: 8,
                            step: 1,
                        },
