            },
        ];
        disposes.push(renderMenu(enhanceSchema, c));

        // ===== 材质与反射（ADR-114 合并，消除「反射」vs「PBR」边界模糊）=====
        const mergedSchema: MenuNode[] = [
            {
                id: 'env:ground:material',
                kind: 'folder',
                label: 'env.groundMaterial',
                icon: 'lucide:sparkles',
                defaultOpen: false,
                headerToggle: { bind: 'env.groundPbrEnabled' },
                children: [
                    // ── PBR 参数（PBR 开启时显示）──
                    {
                        id: 'env:ground:metallic',
                        kind: 'slider',
                        label: 'env.metallic',
                        control: { bind: 'env.groundMetallic', min: 0, max: 1, step: 0.05 },
                        icon: 'lucide:circle-dot',
                        visibleWhen: () => envState.groundPbrEnabled,
                    },
                    {
                        id: 'env:ground:roughness',
                        kind: 'slider',
                        label: 'env.roughness',
                        control: { bind: 'env.groundRoughness', min: 0, max: 1, step: 0.05 },
                        icon: 'lucide:grid-2x2',
                        visibleWhen: () => envState.groundPbrEnabled,
                    },
                    {
                        id: 'env:ground:reflection-blur',
                        kind: 'slider',
                        label: 'env.reflectionBlur',
                        control: {
                            bind: 'env.groundReflectionBlur',
                            min: 0,
                            max: 1,
                            step: 0.05,
                        },
                        icon: 'lucide:droplets',
                        visibleWhen: () => envState.groundPbrEnabled,
                    },
                    {
                        id: 'env:ground:reflection-distort',
                        kind: 'slider',
                        label: 'env.reflectionDistort',
                        control: {
                            bind: 'env.groundReflectionDistort',
                            min: 0,
                            max: 1,
                            step: 0.05,
                        },
                        icon: 'lucide:waves',
                        visibleWhen: () => envState.groundPbrEnabled,
                    },
                    // ── 反射（始终显示）──
                    {
                        id: 'env:ground:reflect-blend',
                        kind: 'slider',
                        label: 'env.groundReflectBlend',
                        control: {
                            bind: 'env.groundReflectionBlend',
                            min: 0,
                            max: 1,
                            step: 0.05,
                        },
                        icon: 'lucide:blend',
                    },
                    {
                        id: 'env:ground:normal-strength',
                        kind: 'slider',
                        label: 'env.groundNormalStrength',
                        control: {
                            bind: 'env.groundNormalStrength',
                            min: 0,
                            max: 2,
                            step: 0.05,
                        },
                        icon: 'lucide:layers',
                    },
                    // ── 地形专属（terrain 模式）──
                    {
                        id: 'env:ground:elevation-coloring',
                        kind: 'toggle',
                        label: 'env.groundElevationColoringEnabled',
                        control: { bind: 'env.groundElevationColoringEnabled' },
                        icon: 'lucide:mountain-snow',
                        visibleWhen: () => envState.groundType === 'terrain',
                    },
                ],
            },
        ];
        disposes.push(renderMenu(mergedSchema, c));

        return () => {
            for (const d of disposes) {
                d();
            }
        };
    });
}

// [doc:architecture] Env Water Level — 水面功能面板
// 从 env-feature-levels.ts 拆分

import { envState } from '../core/config';
import type { PopupLevel } from '../core/config';
import { buildPresetChipGroup } from '../core/ui-helpers';
import { setEnvState } from '../scene/scene';
import { t } from '../core/i18n/t';
import {
    WATER_PRESETS,
    applyWaterPresetToCurrent,
    buildWaterPresetEnvState,
    disposeWater,
    createWater,
} from '../scene/env/env-water';
import { renderMenu } from './render-menu';
import type { MenuNode } from './menu-schema';
import { buildLevel } from './env-level-helpers';
import { getEnvMenu } from './env-menu-state';

/** 预设 key → i18n key 映射 */
const WATER_PRESET_I18N: Record<string, string> = {
    calm: 'env.presetCalm',
    ripple: 'env.presetRipple',
    ocean: 'env.presetOcean',
    storm: 'env.presetStorm',
    tropical: 'env.presetTropical',
};

export function buildWaterLevel(): PopupLevel {
    return buildLevel(
        t('env.water'),
        (c) => {
            // ===== 水面预设（顶部 chips，一键应用）=====
            const waterSchema: MenuNode[] = [
                {
                    id: 'env:water:presets',
                    kind: 'custom',
                    renderCustom: (cc) => {
                        buildPresetChipGroup(
                            cc,
                            Object.entries(WATER_PRESETS).map(([key, wp]) => ({
                                label: t(WATER_PRESET_I18N[key] ?? wp.label),
                                onClick: () => {
                                    setEnvState({
                                        ...buildWaterPresetEnvState(wp),
                                        waterEnabled: true,
                                    });
                                    applyWaterPresetToCurrent(wp);
                                    getEnvMenu()?.reRender();
                                },
                            }))
                        );
                    },
                },
                {
                    id: 'env:water:basic',
                    kind: 'folder',
                    label: 'env.basicParams',
                    icon: 'lucide:sliders',
                    defaultOpen: true,
                    children: [
                        {
                            id: 'env:water:level',
                            kind: 'slider',
                            label: 'env.height',
                            control: { bind: 'env.waterLevel', min: -10, max: 30, step: 0.1 },
                            icon: 'lucide:arrow-up',
                        },
                        {
                            id: 'env:water:anim-speed',
                            kind: 'slider',
                            label: 'env.animSpeed',
                            control: {
                                bind: 'env.waterAnimSpeed',
                                min: 0.1,
                                max: 5,
                                step: 0.1,
