// ======== Model Detail Fullscreen ========

function openModelDetailFullscreen(id: string): void {
    const inst = modelManager.get(id);
    if (!inst) {
        return;
    }

    // 外层闭包持有当前 Tab 的 dispose，供 onBack 在全屏关闭时级联释放
    let activeDispose: (() => void) | null = null;

    openFullscreen({
        title: t('model-detail.modelDetail'),
        onBack: () => {
            if (activeDispose) {
                activeDispose();
                activeDispose = null;
            }
        },
        renderContent: (container) => {
            container.style.display = 'flex';
            container.style.flexDirection = 'column';
            container.style.gap = '12px';

            const tabs = document.createElement('div');
            tabs.className = 'type-row model-detail-tabs';

            const content = document.createElement('div');
            content.className = 'model-detail-tab-content';
            content.style.flex = '1';
            content.style.overflowY = 'auto';
            content.style.minHeight = '0';

            const renderTab = (tab: 'info' | 'bones'): void => {
                if (activeDispose) {
                    activeDispose();
                    activeDispose = null;
                }
                content.innerHTML = '';
                const schema =
                    tab === 'info' ? buildModelInfoSchema(id) : buildBoneHierarchySchema(id);
                activeDispose = renderMenu(schema, content);
            };

            const createTabButton = (tab: 'info' | 'bones', label: string): HTMLButtonElement => {
                const btn = document.createElement('button');
                btn.className = 'model-detail-tab-btn mode-btn';
                btn.type = 'button';
                btn.textContent = label;
                btn.addEventListener('click', () => {
                    const active = tabs.querySelector('.model-detail-tab-btn.active');
                    active?.classList.remove('active');
                    btn.classList.add('active');
                    renderTab(tab);
                });
                return btn;
            };

            const infoBtn = createTabButton('info', t('model-detail.basicInfo'));
            const boneBtn = createTabButton('bones', t('model-detail.boneHierarchy'));
            tabs.appendChild(infoBtn);
            tabs.appendChild(boneBtn);

            container.appendChild(tabs);
            container.appendChild(content);

            infoBtn.classList.add('active');
            renderTab('info');
        },
    });
}

// ======== Model Info ========

function buildModelInfoSchema(id: string): MenuNode[] {
    const inst = modelManager.get(id);
    if (!inst) {
        return [] satisfies MenuNode[];
    }
    const metaKey = inst.libraryPath ?? inst.filePath;
    return [
        {
            id: 'model-info:root',
            kind: 'custom',
            renderCustom: (container) => {
                container.classList.remove('render-card');
                // [fix:meta-key] zip 内模型 inst.filePath 为解压临时路径 ≠ 库 file_path，
                // 而 modelMetaCache 以库绝对路径为 key（library-actions.ts 写入）。
                // 改用 inst.libraryPath（库引用路径）优先，缺失时回退 filePath，对齐写侧 key。
                const meta = metaKey ? (modelMetaCache.get(metaKey) ?? null) : null;
                // 异步加载 comment（若缓存 miss）
                if (metaKey && !modelMetaCache.has(metaKey)) {
                    GetModelMetaBatch([metaKey])
                        .then((batch) => {
                            // 优先用 batch 返回的数据，否则回退查已有缓存（可能被 loadActor 先写入）
                            const commentText =
                                batch?.[metaKey]?.comment ||
                                modelMetaCache.get(metaKey)?.comment ||
                                '';
                            if (batch?.[metaKey] || commentText) {
                                const merged = new Map(modelMetaCache);
                                if (batch?.[metaKey]) {
                                    merged.set(metaKey, batch[metaKey]);
                                }
                                setModelMetaCache(merged);
                            }
                            // 无论是否有新数据，都更新已渲染的 comment card
                            const el = container.querySelector('[data-comment-card]');
                            if (el) {
                                const labelEl = el.querySelector('.info-card-label');
                                const valEl = el.querySelector('.info-card-value');
                                if (labelEl) {
                                    labelEl.textContent = t('model-detail.fComment');
                                }
                                if (valEl) {
                                    valEl.textContent =
                                        commentText || t('model-detail.fCommentEmpty');
                                    (valEl as HTMLElement).style.whiteSpace = 'pre-wrap';
                                }
                            }
                        })
                        .catch((err) => logWarn('model-detail', 'GetModelMetaBatch:', err));
                }
                let vertCount = 0,
                    faceCount = 0;
                for (const m of inst.meshes ?? []) {
                    vertCount += m.getTotalVertices() || 0;
                    faceCount += m.getTotalIndices() || 0;
                }
                const boneCount = inst.mmdModel?.runtimeBones?.length ?? null;
                const morphCount = inst.mmdModel?.morph?.morphs?.length ?? null;
                // [audit-fix] 材质数必须以 PMX 材质列表为准：MMD 模型通常仅 1 个 Babylon 网格，
                // 而 MmdMesh.materials 才是真实材质数组（IMmdModel 不暴露 materials 字段）。
                // 直接对网格材质计数；mesh.material 单值时按 1 计。
                const matCount = (inst.meshes ?? []).reduce((n, m) => {
                    const mm = m as unknown as { materials?: readonly unknown[] };
                    return n + (mm.materials?.length ?? (m.material ? 1 : 0));
                }, 0);
                const fileName = inst.filePath.split(/[/\\]/).pop() || inst.filePath;
                // comment 状态：undef=无缓存(加载中), ''=后端返回空, string=内容
                const metaStatus =
                    metaKey && !modelMetaCache.has(metaKey)
                        ? 'loading'
                        : meta?.comment
                          ? 'ok'
                          : 'empty';
                const comment = meta?.comment ?? '';
                const commentLabel =
                    metaStatus === 'loading'
                        ? t('model-detail.fCommentLoading')
                        : t('model-detail.fComment');
                const commentValue =
                    metaStatus === 'loading'
                        ? t('model-detail.loading')
                        : comment || t('model-detail.fCommentEmpty');
                const fields: Array<{
                    label: string;
                    value: string;
                    wide?: boolean;
                    sub?: string;
                }> = [
                    {
                        label: t('model-detail.fName'),
                        value: inst.name,
                        wide: true,
                        sub: `${t('model-detail.fFile')}: ${fileName}`,
                    },
                    {
                        label: t('model-detail.fType'),
                        value:
                            inst.kind === 'actor'
                                ? t('model-detail.actorModel')
                                : t('model-detail.stageModel'),
                    },
                    {
                        label: t('model-detail.fMotion'),
                        value: inst.vmdName || t('model-detail.none'),
                    },
                    { label: t('model-detail.fVerts'), value: vertCount.toLocaleString() },
                    { label: t('model-detail.fFaces'), value: (faceCount / 3).toLocaleString() },
                    { label: t('model-detail.fMaterials'), value: String(matCount) },
                    {
                        label: t('model-detail.fBones'),
                        value:
                            boneCount !== null ? boneCount.toLocaleString() : t('model-detail.na'),
                    },
                    {
                        label: t('model-detail.fMorphs'),
                        value:
                            morphCount !== null
                                ? morphCount.toLocaleString()
                                : t('model-detail.na'),
                    },
                    {
                        label: commentLabel,
                        value: commentValue,
                        wide: true,
                    },
                ];
                cardContainer(container, (c) => {
                    const grid = addInfoGrid(c);
                    for (const f of fields) {
                        const cardEl = addInfoCard(
                            grid,
                            f.label,
                            f.value,
                            f.wide ? { wide: true, sub: f.sub } : f.sub ? { sub: f.sub } : undefined
                        );
                        // 为 comment 卡片标记 data-comment-card 供异步更新
                        if (
                            f.label === t('model-detail.fComment') ||
                            f.label === t('model-detail.fCommentLoading')
                        ) {
                            cardEl.setAttribute('data-comment-card', '');
                            const valEl = cardEl.querySelector('.info-card-value');
                            if (valEl) {
                                (valEl as HTMLElement).style.whiteSpace = 'pre-wrap';
                            }
                        }
                    }
                });
            },
        },
    ] satisfies MenuNode[];
}

