    stopVMD,
    getMatState,
    applyMatState,
    MaterialCategoryParams,
} from '../scene/scene';
import {
    GetModelPresets,
    SaveModelPresetToLibAuto,
    LoadModelPresetFromLib,
    DeleteModelPreset,
} from '../core/wails-bindings';
import { getBaseName, normPath } from '../core/path';
