/**
 * proc-motion-autodance.ts
 * 程序化舞蹈 VMD 生成 — 主入口
 *
 * 架构（ADR-XXX Phase 2 重构）：
 * - proc-motion-autodance-bones.ts  │ 骨骼帧生成 + 三角函数预计算
 * - proc-motion-autodance-emotion.ts│ 情绪引擎：morph 评分 + 帧生成
 * - proc-motion-autodance.ts  ← 本文件 │ 主入口 + 插值覆写 + VMD 组装
 */
import { buildVmd, INTERP_EASE_IN_OUT, INTERP_EASE_OUT, INTERP_SHARP } from './vmd-writer';
import {
    FPS,
    MAX_FRAMES,
    PROC_VMD_NAME_AUTODANCE,
    type ProcMotionState,
} from './proc-motion-shared';

import {
    buildTrigCache,
    resolveBones,
    genCenterBone,
    genUpperBone,
    genUpper2Bone,
    genWaistBone,
    genArmBones,
    genGrooveBone,
    genShoulderBones,
    genAllParentBone,
    genWristBones,
    genFootIkBones,
    genElbowBones,
    applyInterp,
    applyInterpOverride,
} from './proc-motion-autodance-bones';

import { generateEmotionMorphs } from './proc-motion-autodance-emotion';

/**
 * 生成 AutoDance VMD
 *
 * @param state       程序化运动状态（含开关/强度/速度）
 * @param bpm         节拍 BPM（clamp 60–200）
 * @param morphNames  可用的 morph 名称列表
 * @param boneNames   可用的骨骼名称列表
 */
export function generateAutoDanceVmd(
    state: ProcMotionState,
    bpm: number,
    morphNames: readonly string[] = [],
    boneNames: readonly string[] = []
): ArrayBuffer {
    // ========================================================================
    // 1. 参数计算
    // ========================================================================
    const safeSpeed = Math.max(0.1, Math.min(10, state.speed));
    const clampedBpm = Math.max(60, Math.min(200, bpm));
    const beatFrames = Math.min(MAX_FRAMES, Math.round(((60 / clampedBpm) * FPS) / safeSpeed));
    const loopFrames = beatFrames * 8;
    const intensity = state.intensity;

    // ========================================================================
    // 2. 骨骼解析
    // ========================================================================
    const resolution = resolveBones([...boneNames]);

    // ========================================================================
    // 3. 三角函数预计算
    // ========================================================================
    const cache = buildTrigCache(loopFrames, beatFrames);

    // ========================================================================
    // 4. 骨骼帧生成
    // ========================================================================
    const bones = [
        ...(resolution.centerBone && state.boneToggles.center
            ? genCenterBone(resolution.centerBone, state, cache, intensity)
            : []),
        ...(resolution.upperBone && state.boneToggles.upper
            ? genUpperBone(resolution.upperBone, state, cache, intensity)
            : []),
        ...(resolution.upper2Bone && state.boneToggles.upper2
            ? genUpper2Bone(resolution.upper2Bone, state, cache, intensity)
            : []),
        ...(resolution.waistBone && state.boneToggles.waist
            ? genWaistBone(resolution.waistBone, state, cache, intensity)
            : []),
        ...(resolution.larmBone && resolution.rarmBone && state.boneToggles.arm
            ? genArmBones(resolution.larmBone, resolution.rarmBone, state, cache, intensity)
            : []),
        ...(state.boneToggles.arm
            ? genElbowBones(resolution.elbowLBone, resolution.elbowRBone, state, cache, intensity)
            : []),
        ...(resolution.grooveBone && state.boneToggles.groove
            ? genGrooveBone(resolution.grooveBone, state, cache, intensity)
            : []),
        ...(resolution.shoulderLBone && resolution.shoulderRBone && state.boneToggles.shoulder
            ? genShoulderBones(
                  resolution.shoulderLBone,
                  resolution.shoulderRBone,
                  state,
                  cache,
                  intensity
              )
            : []),
        ...(resolution.allParentBone && state.boneToggles.allParent
            ? genAllParentBone(resolution.allParentBone, state, cache, intensity)
            : []),
        ...(resolution.wristLBone && resolution.wristRBone && state.boneToggles.wrist
            ? genWristBones(resolution.wristLBone, resolution.wristRBone, state, cache, intensity)
            : []),
        ...(state.boneToggles.footIk && resolution.legIkLBone && resolution.legIkRBone
            ? genFootIkBones(resolution.legIkLBone, resolution.legIkRBone, state, cache, intensity)
            : []),
    ];

    // ========================================================================
    // 5. 插值类型
    // ========================================================================
    let overrideInterp:
        typeof INTERP_SHARP | typeof INTERP_EASE_IN_OUT | typeof INTERP_EASE_OUT | null = null;
    if (state.interpOverride === 'sharp') {
        overrideInterp = INTERP_SHARP;
    } else if (state.interpOverride === 'ease-in-out') {
        overrideInterp = INTERP_EASE_IN_OUT;
    } else if (state.interpOverride === 'ease-out') {
        overrideInterp = INTERP_EASE_OUT;
    }

    if (overrideInterp) {
        applyInterpOverride(bones, overrideInterp);
    } else {
        applyInterp(bones, resolution);
    }

    // ========================================================================
    // 6. 情绪 morph（独立模块）
    // ========================================================================
    const morphs = state.boneToggles.emotion
        ? generateEmotionMorphs(morphNames, beatFrames, loopFrames, intensity).morphs
        : [];

    // ========================================================================
    // 7. 组装 VMD
    // ========================================================================
    return buildVmd(bones, morphs, PROC_VMD_NAME_AUTODANCE);
}

// 保持向后兼容的导出（供 proc-motion-bridge.ts 等调用方使用）

import { buildVmd, type BoneKeyFrame, type MorphKeyFrame, INTERP_EASE_IN_OUT } from './vmd-writer';
import {
    BONE_SHOULDER_L_CANDIDATES,
    BONE_SHOULDER_R_CANDIDATES,
    BONE_LARM_CANDIDATES,
    BONE_RARM_CANDIDATES,
    BONE_WRIST_L_CANDIDATES,
    BONE_WRIST_R_CANDIDATES,
    BONE_LEG_IK_L_CANDIDATES,
    BONE_LEG_IK_R_CANDIDATES,
    BONE_CENTER_CANDIDATES,
    BONE_UPPER2_CANDIDATES,
    BONE_WAIST_CANDIDATES,
    BONE_ALLPARENT_CANDIDATES,
    MAX_FRAMES,
    matchBone,
    clamp1,
    quatW,
    closingFrame,
    PROC_VMD_NAME_IDLE,
    type ProcMotionState,
} from './proc-motion-shared';

export function generateIdleVmd(state: ProcMotionState, boneNames: string[] = []): ArrayBuffer {
    const safeSpeed = Math.max(0.1, Math.min(10, state.speed));
    const loopFrames = Math.min(MAX_FRAMES, Math.round(120 / safeSpeed));
    const intensity = state.intensity;
    const bones: BoneKeyFrame[] = [];
    const morphs: MorphKeyFrame[] = [];

    const shoulderLBone = matchBone(boneNames, BONE_SHOULDER_L_CANDIDATES);
    const shoulderRBone = matchBone(boneNames, BONE_SHOULDER_R_CANDIDATES);
    const larmBone = matchBone(boneNames, BONE_LARM_CANDIDATES);
    const rarmBone = matchBone(boneNames, BONE_RARM_CANDIDATES);
    const wristLBone = matchBone(boneNames, BONE_WRIST_L_CANDIDATES);
    const wristRBone = matchBone(boneNames, BONE_WRIST_R_CANDIDATES);

    // ── 足 IK ──
    const legIkLBone = matchBone(boneNames, BONE_LEG_IK_L_CANDIDATES);
    const legIkRBone = matchBone(boneNames, BONE_LEG_IK_R_CANDIDATES);

    // ── 躯干微晃（center/upper2/waist/allParent）─ 从感知层迁回程序化 idle ──
    const centerBone = matchBone(boneNames, BONE_CENTER_CANDIDATES);
    const upper2Bone = matchBone(boneNames, BONE_UPPER2_CANDIDATES);
    const waistBone = matchBone(boneNames, BONE_WAIST_CANDIDATES);
    const allParentBone = matchBone(boneNames, BONE_ALLPARENT_CANDIDATES);

    // 重心微动振幅（从感知层原值缩减 50%，避免过晃）
    const swayAmp = {
        centerRz: 0.025, // center 左右摆（原 0.05）
        centerRx: 0.01, // center 前后倾（原 0.02）
        centerBobY: 0.015, // center 上下浮动（原 0.03）
        upper2Rx: 0.008, // 上半身2 前后倾（原 0.015）
        waistRz: 0.008, // 腰 左右摆（原 0.015）
        allParentRx: 0.003, // 全ての親 微倾（原 0.005）
        allParentRz: 0.003, // 全ての親 微摆（原 0.005）
    };

    if (centerBone) {
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const slowPhase = phase * 0.5;
            const bobY = Math.sin(phase) * swayAmp.centerBobY * intensity;
            const rz = Math.sin(slowPhase) * swayAmp.centerRz * intensity;
            const rx = Math.sin(phase * 0.37 + 0.5) * swayAmp.centerRx * intensity;
            const w = quatW(rx, 0, rz);
            bones.push({
                name: centerBone,
                frame: f,
                position: [0, bobY, 0],
                rotation: [rx, 0, rz, w],
            });
        }
        bones.push(closingFrame(centerBone, loopFrames));
    }

    if (upper2Bone) {
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const rx = Math.sin(phase * 0.7 + 0.3) * swayAmp.upper2Rx * intensity;
            const w = quatW(rx, 0, 0);
            bones.push({
                name: upper2Bone,
                frame: f,
                position: [0, 0, 0],
                rotation: [rx, 0, 0, w],
            });
        }
        bones.push(closingFrame(upper2Bone, loopFrames));
    }

    if (waistBone) {
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const rz = Math.sin(phase + 0.5) * swayAmp.waistRz * intensity;
            const w = quatW(0, 0, rz);
            bones.push({
                name: waistBone,
                frame: f,
                position: [0, 0, 0],
                rotation: [0, 0, rz, w],
            });
        }
        bones.push(closingFrame(waistBone, loopFrames));
    }

    if (allParentBone) {
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const rx = Math.sin(phase * 0.2 + 1.1) * swayAmp.allParentRx * intensity;
            const rz = Math.sin(phase * 0.3 + 2.3) * swayAmp.allParentRz * intensity;
            const w = quatW(rx, 0, rz);
            bones.push({
                name: allParentBone,
                frame: f,
                position: [0, 0, 0],
                rotation: [rx, 0, rz, w],
            });
        }
        bones.push(closingFrame(allParentBone, loopFrames));
    }

    if (larmBone || rarmBone) {
        const armAmp = 0.04 * intensity;
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const rz = clamp1(Math.sin(phase + 1.5) * armAmp);
            const w = quatW(0, 0, rz);
            if (larmBone) {
                bones.push({
                    name: larmBone,
                    frame: f,
                    position: [0, 0, 0],
                    rotation: [0, 0, rz, w],
                });
            }
            if (rarmBone) {
                bones.push({
                    name: rarmBone,
                    frame: f,
                    position: [0, 0, 0],
                    rotation: [0, 0, -rz, w],
                });
            }
        }
        if (larmBone) {
            bones.push(closingFrame(larmBone, loopFrames));
        }
        if (rarmBone) {
            bones.push(closingFrame(rarmBone, loopFrames));
        }
    }

    if (shoulderLBone || shoulderRBone) {
        const shoulderAmp = 0.015 * intensity;
        const rotAmp = 0.01 * intensity;
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const breath = Math.sin(phase + 0.3);
            const yOffset = breath * shoulderAmp;
            const rz = clamp1(Math.sin(phase + 0.1) * rotAmp);
            const w = quatW(0, 0, rz);
            if (shoulderLBone) {
                bones.push({
                    name: shoulderLBone,
                    frame: f,
                    position: [0, yOffset, 0],
                    rotation: [0, 0, rz, w],
                });
            }
            if (shoulderRBone) {
                const rOffset = Math.sin(phase + 0.5) * shoulderAmp;
                const rrz = clamp1(Math.sin(phase + 0.4) * rotAmp);
                const rw = quatW(0, 0, rrz);
                bones.push({
                    name: shoulderRBone,
                    frame: f,
                    position: [0, rOffset, 0],
                    rotation: [0, 0, rrz, rw],
                });
            }
        }
        if (shoulderLBone) {
            bones.push(closingFrame(shoulderLBone, loopFrames));
        }
        if (shoulderRBone) {
            bones.push(closingFrame(shoulderRBone, loopFrames));
        }
    }

    if (wristLBone || wristRBone) {
        const wristAmp = 0.015 * intensity;
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            const rx = clamp1(Math.sin(phase + 0.8) * wristAmp);
            const w = quatW(rx, 0, 0);
            if (wristLBone) {
                bones.push({
                    name: wristLBone,
                    frame: f,
                    position: [0, 0, 0],
                    rotation: [rx, 0, 0, w],
                });
            }
            if (wristRBone) {
                const rxR = clamp1(Math.sin(phase + 1.1) * wristAmp);
                const wR = quatW(rxR, 0, 0);
                bones.push({
                    name: wristRBone,
                    frame: f,
                    position: [0, 0, 0],
                    rotation: [rxR, 0, 0, wR],
                });
            }
        }
        if (wristLBone) {
            bones.push(closingFrame(wristLBone, loopFrames));
        }
        if (wristRBone) {
            bones.push(closingFrame(wristRBone, loopFrames));
        }
    }

    // ── 足 IK 微动（呼吸起伏 + 重心微摆）──
    if (legIkLBone || legIkRBone) {
        const legIkAmp = 0.012 * intensity; // Y 轴起伏振幅
        const legSwayAmp = 0.005 * intensity; // Z 轴微摆
        for (let f = 0; f < loopFrames; f += 4) {
            const phase = (f / loopFrames) * Math.PI * 2;
            // 用较慢的呼吸相位，与 center 的上下浮动错位制造自然感
            const breathPhase = phase * 0.5;
            const ly = Math.sin(breathPhase + 0.5) * legIkAmp;
            const ry = Math.sin(breathPhase + 0.8) * legIkAmp;
            // 微小 Z 轴摆幅，模拟重心交换
            const lz = Math.sin(breathPhase) * legSwayAmp;
            const rz = Math.sin(breathPhase + Math.PI) * legSwayAmp;
            if (legIkLBone) {
                bones.push({
                    name: legIkLBone,
                    frame: f,
                    position: [0, ly, lz],
                    rotation: [0, 0, 0, 1],
                });
            }
            if (legIkRBone) {
                bones.push({
                    name: legIkRBone,
                    frame: f,
                    position: [0, ry, rz],
                    rotation: [0, 0, 0, 1],
                });
            }
        }
        if (legIkLBone) {
            bones.push(closingFrame(legIkLBone, loopFrames));
        }
        if (legIkRBone) {
            bones.push(closingFrame(legIkRBone, loopFrames));
        }
    }

    for (const b of bones) {
        b.interp = INTERP_EASE_IN_OUT;
    }
    return buildVmd(bones, morphs, PROC_VMD_NAME_IDLE);
}

// [doc:architecture] Outfit Overlay — FBX 布料叠加层加载/骨骼重定向/生命周期
// 职责: 从 MD 导出的 FBX 加载叠加 mesh，绑定到 PMX skeleton，管理隐藏/恢复

import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { Bone } from '@babylonjs/core/Bones/bone';
import { Skeleton } from '@babylonjs/core/Bones/skeleton';
import { ImportMeshAsync } from '@babylonjs/core/Loading/sceneLoader';
import type { Scene } from '@babylonjs/core/scene';

import { type ModelInstance } from '../core/config';
import { readFileBytes } from '../core/wails-bindings';
import { normPath } from '@/core/path';
import { logWarn } from '../core/logger';
import { safeCallVoid } from '../core/safe-call';

// Skeleton retargeting
// ============================================================

/**
 * 将 FBX skeleton 的 bone 按 name 匹配到 PMX runtimeBones，
 * 重建 bone weight index 映射，使 FBX mesh 跟随 PMX 骨骼动画。
 *
 * @returns true = 成功重定向，false = 匹配率过低，应降级为静态叠加
 */
function retargetSkeleton(inst: ModelInstance, fbxMeshes: Mesh[]): boolean {
    const pmxModel = inst.mmdModel;
    if (!pmxModel) {
        return false;
    }
    // 找到第一个有 skeleton 的 FBX mesh
    const skinned = fbxMeshes.find((m) => m.skeleton != null);
    if (!skinned || !skinned.skeleton) {
        return false;
    }
    const fbxSkeleton = skinned.skeleton;

    // 建立 FBX bone name → PMX runtimeBone 索引的映射
    const pmxRuntimeBones = pmxModel.runtimeBones;
    const pmxBoneNameToIdx = new Map<string, number>();
    for (let i = 0; i < pmxRuntimeBones.length; i++) {
        pmxBoneNameToIdx.set(pmxRuntimeBones[i].name, i);
    }

    // 匹配 FBX bones 到 PMX bones
    const fbxToPmxBoneIdx = new Map<number, number>(); // fbx bone index → pmx bone index
    let matchCount = 0;
    for (let i = 0; i < fbxSkeleton.bones.length; i++) {
        const fbxBone = fbxSkeleton.bones[i];
        const pmxIdx = pmxBoneNameToIdx.get(fbxBone.name);
        if (pmxIdx !== undefined) {
            fbxToPmxBoneIdx.set(i, pmxIdx);
            matchCount++;
        }
    }

    const matchRate = matchCount / fbxSkeleton.bones.length;
    if (matchRate < 0.5) {
        logWarn(
            'outfit-overlay',
            `Skeleton retarget failed: only ${matchCount}/${fbxSkeleton.bones.length} bones matched (${Math.round(matchRate * 100)}%)`
        );
        return false;
    }

    console.info(
        `[outfit-overlay] Skeleton retarget: ${matchCount}/${fbxSkeleton.bones.length} bones matched (${Math.round(matchRate * 100)}%)`
    );

    // 预计算：每个 FBX bone 的有效 PMX 索引
    // 自身已匹配 → 用自身；否则向上回溯父骨骼链寻找第一个已匹配祖先；都无 → null（权重清空）
    const boneToIndex = new Map<Bone, number>();
    for (let i = 0; i < fbxSkeleton.bones.length; i++) {
        boneToIndex.set(fbxSkeleton.bones[i], i);
    }
    const effectivePmxIdx: (number | null)[] = new Array(fbxSkeleton.bones.length).fill(null);
    for (let i = 0; i < fbxSkeleton.bones.length; i++) {
        let curBone: Bone | null = fbxSkeleton.bones[i];
        let resolved: number | null = null;
        while (curBone) {
            const ci = boneToIndex.get(curBone);
            if (ci !== undefined) {
                const pmx = fbxToPmxBoneIdx.get(ci);
                if (pmx !== undefined) {
                    resolved = pmx;
                    break;
                }
            }
            curBone = curBone.getParent();
        }
        effectivePmxIdx[i] = resolved;
    }

    // 获取 PMX 的 Babylon.js skeleton（从 rootMesh metadata 获取）
    const rootMeta = inst.rootMesh.metadata as { skeleton?: Skeleton } | undefined;
    const pmxSkeleton = rootMeta?.skeleton;
    if (!pmxSkeleton) {
        logWarn('outfit-overlay', 'PMX model has no skeleton in metadata');
        return false;
    }

    // 对每个 skinned mesh：重建 bone weight index 映射
    for (const mesh of fbxMeshes) {
        if (!mesh.skeleton) {
            continue;
        }

        // 获取 mesh 的 bone weight buffer
        const matricesWeights = mesh.getVerticesData('matricesWeights');
        const matricesIndices = mesh.getVerticesData('matricesIndices');
        if (!matricesWeights || !matricesIndices) {
            continue;
        }

        // 重建 matricesIndices：FBX bone index → PMX bone index（含父链回退）
        // 无匹配祖先的权重槽置 0 并重归一化，避免误映射到根骨骼导致严重变形
        const newIndices = new Float32Array(matricesIndices.length);
        const newWeights = new Float32Array(matricesWeights); // 复制原权重，仅供 dropped 槽重归一化
        const vertexCount = matricesIndices.length / 4;
        let _remapped = 0;
        let unmatched = 0;
        let meshDropped = false;
        for (let v = 0; v < vertexCount; v++) {
            const base = v * 4;
            let anyDropped = false;
            for (let s = 0; s < 4; s++) {
                const slot = base + s;
                const fbxIdx = matricesIndices[slot];
                const eff = effectivePmxIdx[fbxIdx];
                if (eff !== null) {
                    newIndices[slot] = eff;
                    _remapped++;
                } else {
                    // 无匹配祖先：该权重槽失效，置 0 并将骨骼指向占位（权重为 0 不影响形变）
                    newIndices[slot] = 0;
                    newWeights[slot] = 0;
                    anyDropped = true;
                    unmatched++;
                }
            }
            if (anyDropped) {
                meshDropped = true;
                let totalW = 0;
                for (let s = 0; s < 4; s++) {
                    totalW += newWeights[base + s];
                }
                if (totalW > 1e-5) {
                    const inv = 1 / totalW;
                    for (let s = 0; s < 4; s++) {
                        newWeights[base + s] *= inv;
                    }
                }
            }
        }
        if (unmatched > 0) {
            logWarn(
                'outfit-overlay',
                `${unmatched}/${matricesIndices.length} bone weights unmatched on mesh "${mesh.name}", mapped to parent chain / zeroed (no longer root bone)`
            );
        }

        // 更新 vertex buffer
        mesh.setVerticesData('matricesIndices', newIndices);
        if (meshDropped) {
            mesh.setVerticesData('matricesWeights', newWeights);
        }

        // 切换 skeleton 引用
        mesh.skeleton = pmxSkeleton;
    }

    // 释放 FBX 原 skeleton：仅当确认没有 mesh 仍引用它时（防止悬空指针）
    const stillReferenced = fbxMeshes.some((m) => m.skeleton === fbxSkeleton);
    if (!stillReferenced) {
        try {
            fbxSkeleton.dispose();
        } catch {
            /* cleanup, ignore errors */
        }
    } else {
        logWarn(
            'outfit-overlay',
            'FBX skeleton still referenced by a mesh; skip dispose to avoid dangling pointer'
        );
    }

    return true;
}

// ============================================================
// Load overlay
// ============================================================

/**
 * 加载 FBX overlay 并尝试绑定到模型 skeleton。
 * @param inst 模型实例
 * @param meshFile FBX 相对路径（相对模型目录）
 * @param scene Babylon scene
 * @returns { meshes, retargetOk } — meshes 为加载的 mesh 列表（失败为空数组），retargetOk 表示骨骼重定向是否成功
 */
export async function loadOverlay(
    inst: ModelInstance,
    meshFile: string,
    scene: Scene
): Promise<{ meshes: Mesh[]; retargetOk: boolean }> {
    // meshFile 必须是相对路径（相对模型目录），拒绝绝对路径与路径穿越
    if (
        /^[A-Za-z]:[\\/]/.test(meshFile) ||
        meshFile.startsWith('/') ||
        meshFile.startsWith('\\\\')
    ) {
        console.error(
            `[outfit-overlay] meshFile must be a relative path (got "${meshFile}"). Use a path relative to the model directory, e.g. "subdir/dress.fbx"`
        );
        return { meshes: [], retargetOk: false };
    }
    // 防御纵深：拒绝 `..` 路径穿越（Go 侧 IsolateModelDir 已兜底，TS 侧提前拒绝便于诊断）
    if (/(^|\/)\.\.(\/|$)/.test(normPath(meshFile))) {
        console.error(
            `[outfit-overlay] meshFile must not contain parent directory traversal (got "${meshFile}")`
        );
        return { meshes: [], retargetOk: false };
    }
    // [doc:adr-057] meshFile 是相对模型目录的路径（可能含子目录）
    const normalizedMeshFile = normPath(meshFile);
    const fullPath = inst.modelDir + '/' + normalizedMeshFile;
    console.info(`[outfit-overlay] Loading FBX overlay: ${meshFile}`);

    let meshes: Mesh[] = [];
    try {
        const fbxBytes = await readFileBytes(fullPath);
        if (!fbxBytes) {
            logWarn('outfit-overlay', 'Failed to read FBX file:', fullPath);
            return { meshes: [], retargetOk: false };
        }
        const result = await ImportMeshAsync(fbxBytes, scene);
        meshes = result.meshes.filter((m): m is Mesh => m instanceof Mesh);

        if (meshes.length === 0) {
            logWarn('outfit-overlay', 'FBX loaded but no meshes found');
            // 清理已加载到 scene 的 mesh（虽然 filter 为空，但 ImportMeshAsync 可能添加了非 Mesh 资源）
            for (const m of result.meshes) {
                try {
                    m.dispose();
                } catch {
                    /* cleanup, ignore errors */
                }
            }
            return { meshes: [], retargetOk: false };
        }

        // 尝试骨骼重定向
        let skeletonOk = false;
        if (inst.mmdModel) {
            skeletonOk = retargetSkeleton(inst, meshes);
        }

        if (!skeletonOk) {
            // Fail-Fast: 骨骼重定向失败，直接抛错
            for (const m of meshes) {
                try {
                    m.dispose();
                } catch {
                    /* cleanup, ignore errors */
                }
            }
            throw new Error('outfit-overlay: 骨骼重定向匹配率过低，无法叠加');
        }

        // 标记为 overlay（避免被 outfit 纹理替换逻辑处理）
        for (const m of meshes) {
            m.metadata = { ...(m.metadata ?? {}), outfitOverlay: true };
        }

        inst._overlayMeshes = meshes;
        return { meshes, retargetOk: skeletonOk };
    } catch (err) {
        console.error('[outfit-overlay] Failed to load FBX overlay:', err);
        // 确保已加载的 mesh 被清理（meshes 在 try 块外声明，catch 可访问）
        for (const m of meshes) {
            try {
                m.dispose();
            } catch {
                /* cleanup, ignore errors */
            }
        }
        return { meshes: [], retargetOk: false };
    }
}

// ============================================================
// Material hide/restore
// ============================================================

/**
 * 隐藏指定材质名的 PMX mesh（保存原始可见性用于恢复）。
 */
export function hideMaterials(inst: ModelInstance, materialNames: string[]): void {
    if (!materialNames || materialNames.length === 0) {
        return;
    }

    const nameSet = new Set(materialNames.map((n) => n.toLowerCase()));

    if (!inst._origMaterialVisibility) {
        inst._origMaterialVisibility = new Map();
    }

    for (let i = 0; i < inst.meshes.length; i++) {
        const mesh = inst.meshes[i];
        const mat = mesh.material;
        if (!mat) {
            continue;
        }

        // 按材质名匹配
        if (nameSet.has(mat.name.toLowerCase())) {
            // 只在第一次保存原始可见性
            if (!inst._origMaterialVisibility.has(i)) {
                inst._origMaterialVisibility.set(i, mesh.isEnabled());
            }
            mesh.setEnabled(false);
        }
    }
}

/**
 * 恢复被 hideMaterials 隐藏的 PMX mesh 可见性。
 */
export function restoreMaterials(inst: ModelInstance): void {
    if (!inst._origMaterialVisibility) {
        return;
    }

    for (const [idx, wasVisible] of inst._origMaterialVisibility) {
        if (idx < inst.meshes.length) {
            inst.meshes[idx].setEnabled(wasVisible);
        }
    }
    inst._origMaterialVisibility = undefined;
}

// ============================================================
// Dispose
// ============================================================

/**
 * 释放 overlay mesh 并清理引用。
 */
export function disposeOverlay(inst: ModelInstance): void {
    if (!inst._overlayMeshes) {
        return;
    }

    // 获取 PMX skeleton 用于比较（避免误释放共享 skeleton）
    const rootMeta = inst.rootMesh.metadata as { skeleton?: Skeleton } | undefined;
    const pmxSkeleton = rootMeta?.skeleton;

    const disposedSkeletons = new Set<Skeleton>();
    for (const mesh of inst._overlayMeshes) {
        safeCallVoid('outfit-overlay', 'mesh dispose failed', () => {
            // 如果 mesh 有独立 skeleton（未重定向成功），先释放
            const meshSkeleton = mesh.skeleton;
            mesh.skeleton = null; // 清空引用，避免 mesh.dispose() 内部访问已释放的 skeleton
            if (
                meshSkeleton &&
                meshSkeleton !== pmxSkeleton &&
                !disposedSkeletons.has(meshSkeleton)
            ) {
                disposedSkeletons.add(meshSkeleton);
                meshSkeleton.dispose();
            }
            mesh.dispose();
        });
    }
    inst._overlayMeshes = undefined;
}

// [doc:architecture] Outfit — 换装系统核心逻辑（load/apply/reset + 自动发现）

import { observe } from '@/core/observer-handle';

import { Texture } from '@babylonjs/core/Materials/Textures/texture';
import { StandardMaterial } from '@babylonjs/core/Materials/standardMaterial';
import { LoadOutfitFile, ListSubDirs, readFileBytes, FileExists } from '../core/wails-bindings';
import {
    modelRegistry,
    OutfitFile,
    OutfitVariant,
    OutfitSlot,
    ModelInstance,
} from '../core/config';
import { showInfoToast } from '../core/toast';
import type { Scene } from '@babylonjs/core/scene';
import { getBaseName, normPath, getDirPath } from '@/core/path';
import { delay, LoadingGuard } from '@/core/async';
import { logWarn, logInfo } from '@/core/logger';
import { col3FromTriple } from '@/core/color-helpers';
import { _catOf } from '../scene/manager/material';
import { triggerAutoSave } from '../core/config';
import { loadOverlay, hideMaterials, restoreMaterials, disposeOverlay } from './outfit-overlay';
import type { MmdStandardMaterial } from '../core/types';
import { t } from '../core/i18n/t';

/** 恢复默认变体的标识名（非 outfits.json 中定义的变体名） */
const RESET_VARIANT = '默认';

// [adr-104] Scene 引用注入：由 scene.ts 初始化后调用 setSceneRef() 注入，
// 破除 outfit → scene → scene-serialize → outfit 的循环依赖（原靠动态 import 解耦，
// 有运行时开销且难测试）。保留动态 import 作为未注入时的兜底兼容路径。
let _sceneRef: Scene | null = null;
let _sceneLoading: Promise<Scene> | null = null;

/** 由 scene.ts 在场景初始化完成后注入当前 scene 实例 */
export function setSceneRef(scene: Scene): void {
    _sceneRef = scene;
}

async function _getScene(): Promise<Scene> {
    if (_sceneRef) {
        return _sceneRef;
    }
    if (!_sceneLoading) {
        _sceneLoading = (async () => {
            const mod = await import('../scene/scene');
            _sceneRef = mod.scene;
            _sceneLoading = null;
            return _sceneRef;
        })().catch((err) => {
            _sceneLoading = null;
            throw err;
        });
    }
    return _sceneLoading;
}

type TextureSlotKey =
    'diffuseTexture' | 'toonTexture' | 'sphereTexture' | 'bumpTexture' | 'emissiveTexture';

type OutfitTextureSlot = 'diffuse' | 'toon' | 'spa' | 'normal' | 'emissive';

interface _SlotMapping {
    matName: string;
    slot: string;
    basename: string;
}

function _isSharedTexture(basename: string): boolean {
    const lower = basename.toLowerCase();
    if (lower.startsWith('shared_toon_texture_')) {
        return true;
    }
    return false;
}

function _collectSlotMappings(inst: ModelInstance): _SlotMapping[] {
    const result: _SlotMapping[] = [];
    const seen = new Set<string>();
    for (const mesh of inst.meshes) {
        const sm = mesh.material as StandardMaterial;
        if (!sm) {
            continue;
        }
        const matName = sm.name;
        const mmdSm = sm as MmdStandardMaterial;
        for (const [slot, tex] of [
            ['diffuse', sm.diffuseTexture],
            ['toon', mmdSm.toonTexture],
            ['spa', mmdSm.sphereTexture],
            ['normal', sm.bumpTexture],
            ['emissive', sm.emissiveTexture],
        ] as const) {
            if (!tex) {
                continue;
            }
            const url = (tex as Texture).name || (tex as Texture).url || '';
            const base = getBaseName(url.split('?')[0]) || '';
            if (!base) {
                continue;
            }
            if (_isSharedTexture(base)) {
                continue;
            }
            const key = matName + '|' + slot + '|' + base;
            if (seen.has(key)) {
                continue;
            }
            seen.add(key);
            result.push({ matName, slot, basename: base });
        }
    }
    return result;
}

// _encodePath 已改为复用 normPath（@/core/utils）

export async function loadOutfits(id: string, signal?: AbortSignal): Promise<OutfitFile | null> {
    if (!_loadingOutfitsGuard.tryEnter(id)) {
        return null;
    }

    // [adr-105] AbortSignal：允许外部取消；内部 AbortController 合并外部 signal
    let abortCtrl: AbortController | undefined;
    let effectiveSignal: AbortSignal;
    if (signal) {
        effectiveSignal = signal;
    } else {
        abortCtrl = new AbortController();
        effectiveSignal = abortCtrl.signal;
    }

    try {
        const inst = modelRegistry.get(id);
        if (!inst) {
            return null;
        }
        if (!inst.filePath) {
            return null;
        }

        // [adr-105] 每个 await 点前检查取消状态
        if (effectiveSignal.aborted) {
            return null;
        }

        try {
            const json = await LoadOutfitFile(inst.filePath);
            if (json) {
                const outfit: OutfitFile = JSON.parse(json);
                if (outfit.version && Array.isArray(outfit.variants)) {
                    inst.outfitFile = outfit;
                    return outfit;
                }
            }
        } catch {
            /* expected failure when outfit file is invalid */
        }

        if (effectiveSignal.aborted) {
            return null;
        }

        try {
            const mappings = _collectSlotMappings(inst);
            if (mappings.length === 0) {
                inst.outfitFile = undefined;
                return null;
            }
            const modelDir = getDirPath(inst.filePath);
            const subdirs = await ListSubDirs(modelDir);
            if (!subdirs || subdirs.length === 0) {
                inst.outfitFile = undefined;
                return null;
            }

            if (effectiveSignal.aborted) {
                return null;
            }

            interface _Probe {
                subdir: string;
                matName: string;
                slot: string;
                relPath: string;
                fullPath: string;
            }
            const seenPath = new Set<string>();
            const probes: _Probe[] = [];
            for (const subdir of subdirs) {
                for (const m of mappings) {
                    const relPath = subdir + '/' + m.basename;
                    const fullPath = modelDir + '/' + normPath(relPath);
                    if (seenPath.has(fullPath)) {
                        continue;
                    }
                    seenPath.add(fullPath);
                    probes.push({ subdir, matName: m.matName, slot: m.slot, relPath, fullPath });
                }
            }
            const headCache = new Map<string, boolean>();
            // 并发限制：避免对大量子目录同时发起数百个 HEAD 请求
            const HEAD_CONCURRENCY = 6;
            const semaphore = { count: 0 };
            const withLimit = async <T>(fn: () => Promise<T>): Promise<T> => {
                while (semaphore.count >= HEAD_CONCURRENCY) {
                    await delay(10);
                    if (effectiveSignal.aborted) {
                        break;
                    }
                }
                semaphore.count++;
                try {
                    return await fn();
                } finally {
                    semaphore.count--;
                }
            };
            const results = await Promise.all(
                subdirs.map(async (subdir): Promise<OutfitVariant | null> => {
                    if (effectiveSignal.aborted) {
                        return null;
                    }
                    const byMaterial: Record<string, OutfitSlot> = {};
                    let hasAny = false;
                    const subdirProbes = probes.filter((p) => p.subdir === subdir);
                    await Promise.all(
                        subdirProbes.map(async (p) => {
                            if (effectiveSignal.aborted) {
                                return;
                            }
                            let ok: boolean;
                            if (headCache.has(p.fullPath)) {
                                ok = headCache.get(p.fullPath)!;
                            } else {
                                ok = await withLimit(async () => {
                                    try {
                                        return await FileExists(p.fullPath);
                                    } catch {
                                        return false;
                                    }
                                });
                                headCache.set(p.fullPath, ok);
                            }
                            if (!ok) {
                                return;
                            }
                            if (!byMaterial[p.matName]) {
                                byMaterial[p.matName] = {};
                            }
                            (byMaterial[p.matName] as Record<string, string>)[p.slot] = p.relPath;
                            hasAny = true;
                        })
                    );
                    return hasAny ? { name: subdir, byMaterial } : null;
                })
            );
            const variantList: OutfitVariant[] = results.filter(Boolean) as OutfitVariant[];
            if (variantList.length === 0) {
                inst.outfitFile = undefined;
                return null;
            }
            const outfit: OutfitFile = { version: 1, variants: variantList };
            inst.outfitFile = outfit;
            return outfit;
        } catch {
            inst.outfitFile = undefined;
            return null;
        }
    } finally {
        abortCtrl?.abort(); // 清理内部 AbortController
        _loadingOutfitsGuard.leave(id);
    }
}

async function _applySlot(
    sm: StandardMaterial,
    slot: TextureSlotKey,
    newPath: string | null,
    origTex: Texture | null,
    modelDir: string
): Promise<void> {
    const mmdSm = sm as MmdStandardMaterial & Record<TextureSlotKey, Texture | null>;
    const cur = mmdSm[slot];
    if (newPath) {
        const scene = await _getScene();
        // ReadFileBytes → base64 → Blob URL（替换 HTTP 中转）
        const bytes = await readFileBytes(modelDir + '/' + normPath(newPath));
        if (!bytes) {
            logWarn('outfit', '_applySlot: failed to read texture', newPath);
            return;
        }
        const ext = newPath.split('.').pop()?.toLowerCase() || 'png';
        const mimeMap: Record<string, string> = {
            png: 'image/png',
            jpg: 'image/jpeg',
            jpeg: 'image/jpeg',
            bmp: 'image/bmp',
            tga: 'image/x-tga',
            dds: 'image/vnd-ms.dds',
            spa: 'image/png',
            sph: 'image/png',
        };
        const blob = new Blob([bytes.buffer as ArrayBuffer], {
            type: mimeMap[ext] || 'application/octet-stream',
        });
        const url = URL.createObjectURL(blob);
        let loaded = false;
        let disposed = false;
        // onError 仅能通过构造函数选项注册（Texture 类无 onError 属性）；
        // 用 resolveLoad 桥接，使构造期回调能在 Promise 内 resolve。
        let resolveLoad: () => void = () => {};
        const newTex = new Texture(url, scene, {
            onError: () => {
                if (!loaded && !disposed) {
                    disposed = true;
                    newTex.dispose();
                    URL.revokeObjectURL(url);
                }
                resolveLoad();
            },
        });
        await new Promise<void>((resolve) => {
            resolveLoad = resolve;
            if (newTex.isReady()) {
                loaded = true;
                resolve();
                return;
            }
            const loadH = observe(newTex.onLoadObservable, () => {
                loadH.dispose();
                loaded = true;
                resolve();
            });
            setTimeout(() => {
                loadH.dispose();
                resolve(); // 超时：loaded 保持 false
            }, 5000);
        });
        if (loaded) {
            if (cur && cur !== origTex) {
                cur.dispose();
            }
            mmdSm[slot] = newTex;
            URL.revokeObjectURL(url);
        } else {
            let done = false;
            const trySwap = (): void => {
                if (done) {
                    return;
                }
                done = true;
                if (disposed) {
                    return; // 已因加载失败被清理
                }
                if (mmdSm[slot] === cur) {
                    if (cur && cur !== origTex) {
                        cur.dispose();
                    }
                    mmdSm[slot] = newTex;
                    URL.revokeObjectURL(url);
                } else {
                    newTex.dispose();
                    URL.revokeObjectURL(url); // 修复：丢弃过期贴图时回收 blob URL
                }
            };
            if (newTex.isReady()) {
                trySwap();
            } else {
                // 兜底 observer 等待迟到的加载完成；但若贴图永不加载（既不 load 也不 error），
                // observer + newTex + blobURL 会永不释放，故再加一次超时清理。
                const handle = observe(newTex.onLoadObservable, () => {
                    handle.dispose();
                    trySwap();
                });
                setTimeout(() => {
                    if (done) {
                        return;
                    }
                    done = true;
                    handle.dispose();
                    if (!disposed) {
                        newTex.dispose();
                        URL.revokeObjectURL(url);
                    }
                }, 5000);
            }
        }
    } else {
        if (origTex) {
            if (cur && cur !== origTex) {
                cur.dispose();
            }
            mmdSm[slot] = origTex;
        }
    }
}

/** 三级回退：byMaterial → byCategory → all，泛型访问器 */
function _resolveVariant<T>(
    variant: OutfitVariant | undefined,
    smName: string,
    cat: string,
    access: (slot: OutfitSlot | undefined) => T | undefined
): T | undefined {
    if (!variant) {
        return undefined;
    }
    return (
        access(variant.byMaterial?.[smName]) ??
        access(variant.byCategory?.[cat]) ??
        access(variant.all)
    );
}

/** 按 slot key 回退纹理路径 */
function _getSlotFor(
    variant: OutfitVariant | undefined,
    smName: string,
    cat: string,
    slotKey: OutfitTextureSlot
): string | null {
    return (
        _resolveVariant(
            variant,
            smName,
            cat,
            (slot) => slot?.[slotKey as keyof OutfitSlot] as string | undefined
        ) ?? null
    );
}

/** 按材质/分类/全局回退参数块 */
function _getParamsFor(
    variant: OutfitVariant | undefined,
    smName: string,
    cat: string
): OutfitSlot['params'] | undefined {
    return _resolveVariant(variant, smName, cat, (s) => s?.params);
}

/** 按材质/分类/全局回退 tint */
function _getTintFor(
    variant: OutfitVariant | undefined,
    smName: string,
    cat: string
): [number, number, number] | undefined {
    return _resolveVariant(variant, smName, cat, (s) => s?.tint);
}

function _applyOutfitParams(
    sm: StandardMaterial,
    params: OutfitSlot['params'],
    orig: {
        diffuseR: number;
        diffuseG: number;
        diffuseB: number;
        specularR: number;
        specularG: number;
        specularB: number;
        specularPower: number;
        ambientR: number;
        ambientG: number;
        ambientB: number;
    }
): void {
    if (!params) {
        return;
    }
    if (params.diffuseMul !== undefined) {
        sm.diffuseColor.set(
            orig.diffuseR * params.diffuseMul,
            orig.diffuseG * params.diffuseMul,
            orig.diffuseB * params.diffuseMul
        );
    }
    if (params.specularMul !== undefined) {
        sm.specularColor.set(
            orig.specularR * params.specularMul,
            orig.specularG * params.specularMul,
            orig.specularB * params.specularMul
        );
    }
    if (params.shininess !== undefined) {
        sm.specularPower = params.shininess;
    }
    if (params.ambientMul !== undefined) {
        sm.ambientColor.set(
            orig.ambientR * params.ambientMul,
            orig.ambientG * params.ambientMul,
            orig.ambientB * params.ambientMul
        );
    }
}

function _applyOutfitTint(sm: StandardMaterial, tint: [number, number, number]): void {
    sm.diffuseColor.multiplyInPlace(col3FromTriple(tint));
}

function _captureOrigParams(inst: ModelInstance): void {
    if (inst._origParams) {
        return;
    }
    inst._origParams = new Map();
    for (let mi = 0; mi < inst.meshes.length; mi++) {
        const sm = inst.meshes[mi].material as StandardMaterial;
        if (!sm) {
            continue;
        }
        inst._origParams.set(mi, {
            diffuseR: sm.diffuseColor.r,
            diffuseG: sm.diffuseColor.g,
            diffuseB: sm.diffuseColor.b,
            specularR: sm.specularColor.r,
            specularG: sm.specularColor.g,
            specularB: sm.specularColor.b,
            specularPower: sm.specularPower,
            ambientR: sm.ambientColor.r,
            ambientG: sm.ambientColor.g,
            ambientB: sm.ambientColor.b,
        });
    }
}

// 并发锁：防止同一模型的变体应用并发执行导致竞态
const _applyingVariantGuard = new LoadingGuard();

// R3 去重：防止对同一模型并发执行 loadOutfits 导致重复请求
const _loadingOutfitsGuard = new LoadingGuard();

// 并发队列：快速切换变体时记录最新一次请求（last-wins），待当前应用完成后再执行，
// 避免直接 return 导致用户点击的切换被静默丢弃
const _pendingVariant = new Map<string, string>();

export async function applyOutfitVariant(id: string, variantName: string): Promise<void> {
    if (_applyingVariantGuard.isLoading(id)) {
        _pendingVariant.set(id, variantName);
        return;
    }
    _applyingVariantGuard.tryEnter(id);
    try {
        let target = variantName;
        for (;;) {
            await _applyOutfitVariantCore(id, target);
            const next = _pendingVariant.get(id);
            if (next === undefined) {
                break;
            }
            _pendingVariant.delete(id);
            target = next;
        }
    } finally {
        _applyingVariantGuard.leave(id);
    }
}

async function _applyOutfitVariantCore(id: string, variantName: string): Promise<void> {
    const inst = modelRegistry.get(id);
    if (!inst) {
        return;
    }
    if (!inst.outfitFile) {
        return;
    }
    const variant =
        variantName === RESET_VARIANT
            ? undefined
            : inst.outfitFile.variants.find((v) => v.name === variantName);
    if (!variant && variantName !== RESET_VARIANT) {
        return;
    }

    if (!inst._origTextures) {
        inst._origTextures = new Map();
        for (let mi = 0; mi < inst.meshes.length; mi++) {
            const sm = inst.meshes[mi].material as StandardMaterial;
            if (!sm) {
                continue;
            }
            const mmdSm = sm as MmdStandardMaterial;
            inst._origTextures.set(mi, {
                diffuse: sm.diffuseTexture as Texture | null,
                toon: mmdSm.toonTexture,
                spa: mmdSm.sphereTexture,
                normal: sm.bumpTexture as Texture | null,
                emissive: sm.emissiveTexture as Texture | null,
            });
        }
    }
    _captureOrigParams(inst);

    const promises: Promise<void>[] = [];

    // overlay 处理（与纹理替换并行）：清理旧 overlay → 加载新 overlay → 隐藏 PMX 布料
    // token 守卫：防止快速切换变体时，旧 loadOverlay 完成后覆盖新状态导致孤儿 mesh 泄漏
    const token = Symbol('overlay');
    inst._overlayLoadToken = token;
    promises.push(
        (async () => {
            if (inst._overlayMeshes) {
                disposeOverlay(inst);
                restoreMaterials(inst);
            }
            if (variant?.meshFile) {
                const { meshes, retargetOk } = await loadOverlay(
                    inst,
                    variant.meshFile,
                    await _getScene()
                );
                // token 过期：说明此期间已切换到其他变体，丢弃本次结果
                if (inst._overlayLoadToken !== token) {
                    logInfo('outfit', 'overlay load stale (token mismatch), discarding');
                    for (const m of meshes) {
                        try {
                            m.dispose();
                        } catch {
                            /* cleanup, ignore errors */
                        }
                    }
                    return;
                }
                // 仅在 overlay 成功加载且骨骼重定向成功时隐藏 PMX 布料；
                // retarget 失败（静态降级）时保留原布料，避免穿模
                if (meshes.length > 0 && retargetOk && variant.hideMaterials) {
                    hideMaterials(inst, variant.hideMaterials);
                } else if (meshes.length > 0 && !retargetOk && variant.hideMaterials) {
                    logWarn(
                        'outfit',
                        'FBX overlay retarget failed, keeping PMX materials to avoid穿模'
                    );
                }
            }
        })()
    );

    for (let mi = 0; mi < inst.meshes.length; mi++) {
        const sm = inst.meshes[mi].material as StandardMaterial;
        if (!sm) {
            continue;
        }
        const origTex = inst._origTextures.get(mi);
        if (!origTex) {
            continue;
        }
        const origParams = inst._origParams.get(mi)!;
        const cat = _catOf(sm);

        promises.push(
            _applySlot(
                sm,
                'diffuseTexture',
                _getSlotFor(variant, sm.name, cat, 'diffuse'),
                origTex.diffuse,
                inst.modelDir
            )
        );
        promises.push(
            _applySlot(
                sm,
                'toonTexture',
                _getSlotFor(variant, sm.name, cat, 'toon'),
                origTex.toon,
                inst.modelDir
            )
        );
        promises.push(
            _applySlot(
                sm,
                'sphereTexture',
                _getSlotFor(variant, sm.name, cat, 'spa'),
                origTex.spa,
                inst.modelDir
            )
        );
        promises.push(
            _applySlot(
                sm,
                'bumpTexture',
                _getSlotFor(variant, sm.name, cat, 'normal'),
                origTex.normal,
                inst.modelDir
            )
        );
        promises.push(
            _applySlot(
                sm,
                'emissiveTexture',
                _getSlotFor(variant, sm.name, cat, 'emissive'),
                origTex.emissive,
                inst.modelDir
            )
        );

        const slotParams = _getParamsFor(variant, sm.name, cat);
        if (slotParams) {
            _applyOutfitParams(sm, slotParams, origParams);
        }

        const tint = _getTintFor(variant, sm.name, cat);
        if (tint) {
            _applyOutfitTint(sm, tint);
        }
    }

    await Promise.all(promises);
    inst.activeVariant = variantName;
    showInfoToast(t('outfit.switched', { name: variantName }));
    triggerAutoSave();
}

export async function resetOutfit(id: string): Promise<void> {
    const inst = modelRegistry.get(id);
    if (!inst) {
        return;
    }
    const promises: Promise<void>[] = [];
    if (inst._origTextures) {
        for (let mi = 0; mi < inst.meshes.length; mi++) {
            const sm = inst.meshes[mi].material as StandardMaterial;
            if (!sm) {
                continue;
            }
            const orig = inst._origTextures.get(mi);
            if (!orig) {
                continue;
            }
            promises.push(_applySlot(sm, 'diffuseTexture', null, orig.diffuse, inst.modelDir));
            promises.push(_applySlot(sm, 'toonTexture', null, orig.toon, inst.modelDir));
            promises.push(_applySlot(sm, 'sphereTexture', null, orig.spa, inst.modelDir));
            promises.push(_applySlot(sm, 'bumpTexture', null, orig.normal, inst.modelDir));
            promises.push(_applySlot(sm, 'emissiveTexture', null, orig.emissive, inst.modelDir));
        }
    }
    await Promise.all(promises);
    if (inst._origParams) {
        for (let mi = 0; mi < inst.meshes.length; mi++) {
            const sm = inst.meshes[mi].material as StandardMaterial;
            if (!sm) {
                continue;
            }
            const p = inst._origParams.get(mi);
            if (!p) {
                continue;
            }
            sm.diffuseColor.set(p.diffuseR, p.diffuseG, p.diffuseB);
            sm.specularColor.set(p.specularR, p.specularG, p.specularB);
            sm.specularPower = p.specularPower;
            sm.ambientColor.set(p.ambientR, p.ambientG, p.ambientB);
        }
    }
    // 清理 overlay mesh 并恢复被隐藏的 PMX 材质
    // token 失效，使进行中的 loadOverlay 完成后丢弃结果
    inst._overlayLoadToken = undefined;
    disposeOverlay(inst);
    restoreMaterials(inst);

    inst.activeVariant = undefined;
    inst.outfitFile = undefined;
    inst._origTextures = undefined;
    inst._origParams = undefined;
    triggerAutoSave();
}

// [doc:architecture] AR Camera — 摄像头视频透传与模型叠加
// 规范文档: docs/adr/adr-055-ar-camera-mode.md
// 职责: 管理摄像头视频流, 提供 start/stop/switchFacing 接口, 维护 <video> 元素
// 渲染合成策略: 透明 canvas + CSS <video> 底层 (S2 方案, 性能最优)

import { dom } from '@/core/config';
import { feedbackInfo, feedbackStatus } from '@/core/feedback';
import { t } from '@/core/i18n/t';
import { getCachedCapabilities } from '@/core/backend';
import { logWarn } from '@/core/logger';
import { canvasToBase64 } from '@/core/image';

// ======== Types ========
export type CameraFacing = 'user' | 'environment';

declare global {
    interface Window {
        // Callback the Android bridge invokes with the CAMERA permission result
        // after requestCameraPermission() (see ensureAndroidCameraPermission).
        __onArcCameraPermission?: (granted: boolean) => void;
    }
}

interface ARCameraState {
    active: boolean;
    facing: CameraFacing;
    streamId: string | null;
}

// ======== Internal State ========
let _active = false;
let _facing: CameraFacing = 'user';
let _stream: MediaStream | null = null;
let _videoEl: HTMLVideoElement | null = null;
const _originalClearColor: { r: number; g: number; b: number; a: number } | null = null;
let _mirrorOverridden = false; // 用户是否手动设置过镜像
type ARModeChangeListener = (active: boolean) => void;
const _listeners: ARModeChangeListener[] = [];

// 代数令牌：每次发起/终止 AR 都会自增，用于作废在途的异步 getUserMedia。
// 典型竞态：进入 AR 时 getUserMedia 弹窗未关闭，用户已切走——stopARCamera 会 bump
// 此令牌，pending 的 startARCamera 在 await 后检测到 myGen !== _arGen 即丢弃流并 return false，
// 避免"幽灵 AR"（isARActive()===true 但已离开 AR 模式）。
let _arGen = 0;
// 防重入：避免并发双 getUserMedia 泄漏摄像头流。
let _starting = false;

function _notifyARModeChange(active: boolean): void {
    for (const fn of _listeners) {
        try {
            fn(active);
        } catch (e) {
            console.error('[ar-camera] listener error:', e);
        }
    }
}

// ======== Video Element ========
function getVideoEl(): HTMLVideoElement {
    if (_videoEl) {
        return _videoEl;
    }
    let el = document.getElementById('arVideo') as HTMLVideoElement | null;
    if (!el) {
        el = document.createElement('video');
        el.id = 'arVideo';
        el.autoplay = true;
        el.playsInline = true;
        el.muted = true;
        el.setAttribute('aria-hidden', 'true');
        const canvas = dom.canvas;
        if (canvas.parentElement) {
            canvas.parentElement.insertBefore(el, canvas);
        } else {
            document.body.appendChild(el);
        }
    }
    _videoEl = el;
    return el;
}

// ======== Public API ========
export function isARActive(): boolean {
    return _active;
}

export function getARFacing(): CameraFacing {
    return _facing;
}

/**
 * 启动 AR 摄像头并显示视频背景。
 * @param facing 前置(user)或后置(environment)
 * @returns 是否成功启动
 */
export async function startARCamera(facing: CameraFacing = 'user'): Promise<boolean> {
    // 串行化：已有启动在途时直接返回当前状态，避免并发双 getUserMedia 泄漏流。
    if (_starting) {
        return _active;
    }
    _starting = true;
    // 占用一个代数；随后任意 stopARCamera 或新的 startARCamera 都会使本代数失效。
    const myGen = ++_arGen;

    if (_active && _facing === facing && _stream) {
        _starting = false;
        return true;
    }

    // 停止旧流（内联停止，不 bump 代数——我们马上会用新流替换它）。
    if (_stream) {
        const old = _stream;
        _stream = null;
        old.getTracks().forEach((tr) => tr.stop());
        if (_videoEl) {
            _videoEl.srcObject = null;
        }
        _active = false;
        _hideVideo();
    }

    const video = getVideoEl();
    _facing = facing;

    // 环境不支持（如 Wails/WebView2 未声明 media 能力）：navigator.mediaDevices 可能为 undefined。
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        _active = false;
        _hideVideo();
        feedbackStatus('scene.ar.cameraUnavailable', undefined, false);
        _starting = false;
        return false;
    }

    // Android WebView：进入 AR 前必须持有 CAMERA 运行时权限，否则 getUserMedia
    // 会被 WebChromeClient 静默拒绝（NotAllowedError）。这里在按钮点击链路里显式
    // 判断授权状态——已授权则继续，未授权则弹系统授权框并等待用户决策。
    if (
        getCachedCapabilities().arScope === 'android-app' &&
        !(await ensureAndroidCameraPermission())
    ) {
        _active = false;
        _hideVideo();
        feedbackStatus('scene.ar.cameraDenied', undefined, false);
        _starting = false;
        return false;
    }

    try {
        const constraints: MediaStreamConstraints = {
            video: {
                facingMode: facing,
                width: { ideal: 1280 },
                height: { ideal: 720 },
            } as MediaTrackConstraints,
            audio: false,
        };

        _stream = await navigator.mediaDevices.getUserMedia(constraints);

        // 关键：await 之后校验代数是否仍有效（期间可能已被 stopARCamera 或新切换作废）。
        if (myGen !== _arGen) {
            _stream.getTracks().forEach((tr) => tr.stop());
            _stream = null;
            _active = false;
            _hideVideo();
            _starting = false;
            return false;
        }

        video.srcObject = _stream;
        await video.play();

        _applyVideoMirror();
        _active = true;
        _showVideo();

        feedbackInfo('scene.ar.enabled', undefined);
        _notifyARModeChange(true);
        _starting = false;
        return true;
    } catch (err) {
        logWarn('AR', 'startARCamera failed:', err);
        if (_stream) {
            _stream.getTracks().forEach((tr) => tr.stop());
            _stream = null;
        }
        _active = false;
        _hideVideo();
        feedbackStatus('scene.ar.cameraDenied', undefined, false);
        _starting = false;
        return false;
    }
}

/** 停止 AR 摄像头，释放资源并隐藏视频背景。 */
export function stopARCamera(): void {
    // 作废任何在途的 startARCamera（其 await 后会检测到代数失效并丢弃流）。
    _arGen++;
    if (_stream) {
        const tracks = _stream.getTracks();
        for (const track of tracks) {
            track.stop();
        }
        _stream = null;
    }
    if (_videoEl) {
        _videoEl.srcObject = null;
    }
    _active = false;
    _hideVideo();
    _notifyARModeChange(false);
}

/** 切换前后摄像头。 */
export async function switchARCameraFacing(): Promise<boolean> {
    const nextFacing: CameraFacing = _facing === 'user' ? 'environment' : 'user';
    const ok = await startARCamera(nextFacing);
    if (ok) {
        feedbackInfo(
            nextFacing === 'user' ? 'scene.ar.switchedUser' : 'scene.ar.switchedEnv',
            undefined
        );
    }
    return ok;
}

/** 设置是否镜像显示（前置默认镜像，后置默认不镜像）。用户手动调用后标记为 overridden，切换摄像头时保持用户设置。 */
export function setARMirror(mirrored: boolean): void {
    _mirrorOverridden = true;
    const el = getVideoEl();
    el.style.transform = mirrored ? 'scaleX(-1)' : 'scaleX(1)';
}

/** 当前是否镜像显示。 */
export function isARMirrored(): boolean {
    const el = getVideoEl();
    return el.style.transform === 'scaleX(-1)';
}

/**
 * 截取 AR 合成画面（视频底 + 3D 模型层）。
 * 异步版：用 toBlob 替代 toDataURL，将 PNG/JPEG 编码移至后台线程，
 * 避免低端 Android 机同步编码 OOM（ADR-017 A2-04）。
 * @param format 图片格式，默认 image/png
 * @param quality 质量 0~1，默认 0.9
 * @returns base64 字符串（不含 data:image/xxx;base64, 前缀）
 */
export function captureARScreenshot(
    format: string = 'image/png',
    quality: number = 0.9
): Promise<string> {
    return canvasToBase64(dom.canvas, format, quality).then((fallbackBase64) => {
        if (!_active || !_videoEl) {
            return fallbackBase64;
        }
        const video = _videoEl;
        const out = document.createElement('canvas');
        out.width = dom.canvas.width;
        out.height = dom.canvas.height;
        const ctx = out.getContext('2d');
        if (!ctx) {
            return fallbackBase64;
        }

        const vw = video.videoWidth || dom.canvas.width;
        const vh = video.videoHeight || dom.canvas.height;
        const cw = dom.canvas.width;
        const ch = dom.canvas.height;

        const vRatio = vw / vh;
        const cRatio = cw / ch;

        let sx = 0,
            sy = 0,
            sw = vw,
            sh = vh;
        if (vRatio > cRatio) {
            sw = vh * cRatio;
            sx = (vw - sw) / 2;
        } else {
            sh = vw / cRatio;
            sy = (vh - sh) / 2;
        }

        try {
            ctx.drawImage(video, sx, sy, sw, sh, 0, 0, cw, ch);
        } catch (e) {
            logWarn('AR', 'drawImage video failed:', e);
        }

        ctx.drawImage(dom.canvas, 0, 0, cw, ch);
        return canvasToBase64(out, format, quality);
    });
}

// ======== Internal Helpers ========
/**
 * 在 Android 上确保 CAMERA 运行时权限已授予，再允许 getUserMedia。
 * - 非 Android / 无桥接：直接 resolve(true)，走桌面自身逻辑。
 * - 已授权：立即 resolve(true)。
 * - 未授权：调用 Java 侧 requestCameraPermission() 弹出系统授权框，
 *   并以 window.__onArcCameraPermission(granted) 回调返回用户决策。
 */
function ensureAndroidCameraPermission(): Promise<boolean> {
    const w = window.wails;
    if (!w || typeof w.hasCameraPermission !== 'function') {
        return Promise.resolve(true);
    }
    if (w.hasCameraPermission()) {
        return Promise.resolve(true);
    }
    return new Promise<boolean>((resolve) => {
        const prev = window.__onArcCameraPermission;
        window.__onArcCameraPermission = (granted: boolean) => {
            window.__onArcCameraPermission = prev;
            resolve(granted);
        };
        w.requestCameraPermission!();
    });
}

function _showVideo(): void {
    const video = getVideoEl();
    video.style.display = 'block';
}

function _hideVideo(): void {
    if (_videoEl) {
        _videoEl.style.display = 'none';
    }
}

function _applyVideoMirror(): void {
    if (_mirrorOverridden) {
        return; // 用户手动设置过，保持用户设置
    }
    const video = getVideoEl();
    if (_facing === 'user') {
        video.style.transform = 'scaleX(-1)';
    } else {
        video.style.transform = 'none';
    }
}

// [doc:architecture] WebXR Probe — ADR-072 P1 支持度探针
// 职责: 探测当前环境的 WebXR immersive-ar 能力，输出兼容性矩阵
// 决策前提: 探针结果决定 WebXR 路线(ADR-072)是否可行，不可行则转原生 ARCore(ADR-073)

import { logWarn } from '@/core/logger';
import { translateGoError } from '@/core/i18n/goerr';

// ======== Types ========

export interface WebXRProbeResult {
    /** navigator.xr 是否存在 */
    xrAvailable: boolean;
    /** immersive-ar session 是否支持 */
    immersiveAR: boolean;
    /** hit-test 特性是否可用 */
    hitTest: boolean;
    /** plane-detection 特性是否可用 */
    planeDetection: boolean;
    /** light-estimation 特性是否可用 */
    lightEstimation: boolean;
    /** anchors 特性是否可用 */
    anchors: boolean;
    /** 用户代理字符串（用于兼容性矩阵） */
    userAgent: string;
    /** 平台标识 */
    platform: string;
    /** 是否为 Android WebView */
    isAndroidWebView: boolean;
    /** 是否为桌面 WebView2 */
    isDesktopWebView2: boolean;
    /** WebView 包名（Android 侧探针回传） */
    webViewPackage?: string;
    /** WebView 版本（Android 侧探针回传） */
    webViewVersion?: string;
    /** 探测时间戳 */
    timestamp: number;
    /** 综合结论 */
    verdict: 'full' | 'partial' | 'none';
    /** 人类可读的结论描述 */
    summary: string;
}

/** Java 侧探针回传的原始数据 */
interface AndroidProbeResult {
    webViewPackage: string;
    webViewVersion: string;
    xrExists: boolean;
    xrIsSessionSupported: boolean;
    userAgent: string;
    error?: string;
}

// ======== Internal ========

let _cachedResult: WebXRProbeResult | null = null;

// Android 侧探针回调注册
declare global {
    interface Window {
        __onWebXRProbeResult?: (json: string) => void;
    }
}

/**
 * 调用 Java 侧 probeWebXRSupport()，等待回调结果。
 * 仅在 Android WebView 环境有效。
 */
function probeAndroidWebView(): Promise<AndroidProbeResult | null> {
    const w = window.wails;
    if (!w || typeof w.probeWebXRSupport !== 'function') {
        return Promise.resolve(null);
    }
    return new Promise<AndroidProbeResult | null>((resolve) => {
        const timeout = setTimeout(() => {
            window.__onWebXRProbeResult = undefined;
            resolve(null);
        }, 5000); // 5s 超时

        window.__onWebXRProbeResult = (json: string) => {
            clearTimeout(timeout);
            window.__onWebXRProbeResult = undefined;
            try {
                resolve(JSON.parse(json) as AndroidProbeResult);
            } catch {
                resolve(null);
            }
        };
        w.probeWebXRSupport!();
    });
}

/**
 * 检测 navigator.xr 是否支持指定 session mode。
 * 若 navigator.xr 不存在或 isSessionSupported 抛异常，返回 false。
 */
async function checkSessionSupported(mode: XRSessionMode): Promise<boolean> {
    if (!navigator.xr) {
        return false;
    }
    try {
        return await navigator.xr.isSessionSupported(mode);
    } catch (e) {
        logWarn('webxr-probe', `isSessionSupported(${mode}) failed:`, e);
        return false;
    }
}

/**
 * 尝试请求一个短暂的 immersive-ar session 来验证特性可用性。
 * 注意：这会实际触发 AR session（摄像头权限弹窗），仅在用户主动触发时调用。
 *
 * @param features 要验证的 optional features 列表
 * @returns 实际被授予的 features 列表
 */
async function probeFeaturesBySession(
    features: string[]
): Promise<{ granted: string[]; error: string | null }> {
    if (!navigator.xr) {
        return { granted: [], error: 'navigator.xr not available' };
    }
    try {
        const session = await navigator.xr.requestSession('immersive-ar', {
            requiredFeatures: ['local-floor'],
            optionalFeatures: features,
        });
        // Session 创建成功——检查实际启用了哪些特性
        const granted: string[] = [];
        // WebXR spec: session.enabledFeatures 可能不存在于所有实现
        const enabled = (session as unknown as { enabledFeatures?: string[] }).enabledFeatures;
        if (Array.isArray(enabled)) {
            for (const f of features) {
                if (enabled.includes(f)) {
                    granted.push(f);
                }
            }
        } else {
            // 回退：session 创建成功即认为 requiredFeatures 可用
            // optionalFeatures 无法确认，标记为 'unknown'
            granted.push(...features.map((f) => `${f}(unconfirmed)`));
        }
        await session.end();
        return { granted, error: null };
    } catch (e) {
        const msg = translateGoError(e);
        return { granted: [], error: msg };
    }
}

// ======== Platform Detection ========

function detectPlatform(): {
    isAndroidWebView: boolean;
    isDesktopWebView2: boolean;
    platform: string;
} {
    const ua = navigator.userAgent;
    const isAndroid = /Android/i.test(ua);
    // Android WebView 的 UA 包含 "wv" 标记或 Version/x.x（Chrome 无此标记）
    const isWebView = /\bwv\b/.test(ua) || (/Version\/[\d.]+/.test(ua) && /Chrome/.test(ua));
    // Wails 桌面端 WebView2 UA 包含 "Edg/" (Edge Chromium)
    const isWebView2 = /Edg\//.test(ua) && !isAndroid;
    // Wails 注入标识
    const hasWails = typeof window.wails !== 'undefined';

    let platform = 'unknown';
    if (isAndroid && isWebView) {
        platform = 'android-webview';
    } else if (isAndroid) {
        platform = 'android-chrome';
    } else if (isWebView2 || (hasWails && !isAndroid)) {
        platform = 'desktop-webview2';
    } else {
        platform = 'desktop-browser';
    }

    return {
        isAndroidWebView: isAndroid && isWebView,
        isDesktopWebView2: isWebView2 || (hasWails && !isAndroid),
        platform,
    };
}

// ======== Public API ========

/**
 * 执行 WebXR 支持度探针（非侵入式，不请求 session）。
 * 结果会被缓存，重复调用返回同一结果。
 * 在 Android WebView 环境下会同时调用 Java 侧探针获取 WebView 包信息。
 */
export async function probeWebXR(): Promise<WebXRProbeResult> {
    if (_cachedResult) {
        return _cachedResult;
    }

    const { isAndroidWebView, isDesktopWebView2, platform } = detectPlatform();
    const xrAvailable = typeof navigator.xr !== 'undefined';

    let immersiveAR = false;
    if (xrAvailable) {
        immersiveAR = await checkSessionSupported('immersive-ar');
    }

    // Android 侧探针：获取 WebView 包名/版本 + Java 侧 navigator.xr 评估
    let webViewPackage: string | undefined;
    let webViewVersion: string | undefined;
    if (isAndroidWebView) {
        const androidResult = await probeAndroidWebView();
        if (androidResult) {
            webViewPackage = androidResult.webViewPackage;
            webViewVersion = androidResult.webViewVersion;
            // Java 侧的结果可能比 JS 侧更准确（同一 WebView 上下文）
            if (androidResult.xrExists && !xrAvailable) {
                // 理论上不应发生，但以防万一
                logWarn('webxr-probe', 'Java-side reports xr exists but JS-side disagrees');
            }
            if (androidResult.xrIsSessionSupported && !immersiveAR) {
                immersiveAR = true;
            }
        }
    }

    // 非侵入式探针无法确认具体 features（需实际创建 session），
    // 这里仅根据 immersive-ar 支持度做初步判断。
    // 完整特性验证需调用 probeWebXRFeatures()（会触发权限弹窗）。
    const hitTest = false;
    const planeDetection = false;
    const lightEstimation = false;
    const anchors = false;

    // 综合结论
    let verdict: 'full' | 'partial' | 'none';
    let summary: string;

    if (!xrAvailable && !immersiveAR) {
        verdict = 'none';
        if (isDesktopWebView2) {
            summary = 'WebView2 无 XR 后端 → 永久降级 passthrough（ADR-072 §1.3 已确认）';
        } else if (isAndroidWebView) {
            const pkgInfo = webViewPackage
                ? ` [WebView: ${webViewPackage} v${webViewVersion}]`
                : '';
            summary =
                `Android WebView 未暴露 navigator.xr → WebXR 默认禁用${pkgInfo}，` +
                '需评估启用机制（flag / WebViewCompat / ROM）';
        } else {
            summary = 'navigator.xr 不存在 → 浏览器不支持 WebXR';
        }
    } else if (!immersiveAR) {
        verdict = 'none';
        summary =
            'navigator.xr 存在但 immersive-ar 不受支持 → ' + '可能仅支持 immersive-vr 或 inline';
    } else {
        // immersive-ar 支持，但具体 features 未验证
        verdict = 'partial';
        summary =
            'immersive-ar 受支持 ✓ — hit-test / plane-detection 等特性需进一步验证' +
            '（调用 probeWebXRFeatures 会触发 AR session + 摄像头权限）';
    }

    _cachedResult = {
        xrAvailable: xrAvailable || immersiveAR, // Java 侧可能确认 xr 存在
        immersiveAR,
        hitTest,
        planeDetection,
        lightEstimation,
        anchors,
        userAgent: navigator.userAgent,
        platform,
        isAndroidWebView,
        isDesktopWebView2,
        webViewPackage,
        webViewVersion,
        timestamp: Date.now(),
        verdict,
        summary,
    };

    return _cachedResult;
}

/**
 * 深度探针：实际创建 immersive-ar session 验证特性可用性。
 * ⚠️ 会触发摄像头权限弹窗，仅在用户主动点击「深度探针」时调用。
 */
export async function probeWebXRFeatures(): Promise<WebXRProbeResult> {
    const base = await probeWebXR();

    if (!base.immersiveAR) {
        // 无法创建 session，直接返回基础结果
        return base;
    }

    const featuresToProbe = ['hit-test', 'plane-detection', 'light-estimation', 'anchors'];
    const { granted, error } = await probeFeaturesBySession(featuresToProbe);

    if (error) {
        // Session 创建失败（权限拒绝等）
        _cachedResult = {
            ...base,
            verdict: 'partial',
            summary: `immersive-ar 支持但 session 创建失败: ${error}`,
        };
        return _cachedResult;
    }

    const has = (f: string) => granted.some((g) => g.startsWith(f));

    const hitTest = has('hit-test');
    const planeDetection = has('plane-detection');
    const lightEstimation = has('light-estimation');
    const anchors = has('anchors');

    // 至少 hit-test 可用才算 'full'
    const verdict: 'full' | 'partial' | 'none' = hitTest ? 'full' : 'partial';
    const parts: string[] = [];
    if (hitTest) {
        parts.push('hit-test ✓');
    }
    if (planeDetection) {
        parts.push('plane-detection ✓');
    }
    if (lightEstimation) {
        parts.push('light-estimation ✓');
    }
    if (anchors) {
        parts.push('anchors ✓');
    }
    const missing = featuresToProbe.filter((f) => !has(f));
    if (missing.length > 0) {
        parts.push(`缺失: ${missing.join(', ')}`);
    }

    _cachedResult = {
        ...base,
        hitTest,
        planeDetection,
        lightEstimation,
        anchors,
        verdict,
        summary: `特性验证: ${parts.join(' | ')}`,
    };

    return _cachedResult;
}

/** 清除缓存的探针结果（用于重新探测）。 */
function resetProbeCache(): void {
    _cachedResult = null;
}

/**
 * 格式化探针结果为人类可读的多行文本（用于 UI 展示或复制到剪贴板）。
 */
export function formatProbeReport(r: WebXRProbeResult): string {
    const lines: string[] = [
        '═══ WebXR 兼容性探针报告 ═══',
        `平台: ${r.platform}`,
        `时间: ${new Date(r.timestamp).toLocaleString()}`,
    ];
    if (r.webViewPackage) {
        lines.push(`WebView: ${r.webViewPackage} v${r.webViewVersion}`);
    }
    lines.push(
        '',
        `navigator.xr: ${r.xrAvailable ? '✓ 存在' : '✗ 不存在'}`,
        `immersive-ar: ${r.immersiveAR ? '✓ 支持' : '✗ 不支持'}`,
        `hit-test: ${r.hitTest ? '✓' : r.immersiveAR ? '? (未验证)' : '✗'}`,
        `plane-detection: ${r.planeDetection ? '✓' : r.immersiveAR ? '? (未验证)' : '✗'}`,
        `light-estimation: ${r.lightEstimation ? '✓' : r.immersiveAR ? '? (未验证)' : '✗'}`,
        `anchors: ${r.anchors ? '✓' : r.immersiveAR ? '? (未验证)' : '✗'}`,
        '',
        `结论: ${r.verdict === 'full' ? '🟢 WebXR 路线可行' : r.verdict === 'partial' ? '🟡 部分支持，需降级共存' : '🔴 不可行，转 ADR-073 原生路线'}`,
        r.summary,
        '',
        `UA: ${r.userAgent}`
    );
    return lines.join('\n');
}

