const WEATHER_TYPES = ['sakura', 'rain', 'snow', 'leaves'];

/** 天气类型的盒发射器方向参数 */
const WEATHER_BOX_DIRS: Record<
    string,
    { dir1: [number, number, number]; dir2: [number, number, number] }
> = {
    sakura: { dir1: [-0.5, -0.2, -0.5], dir2: [0.5, 0.2, 0.5] },
    rain: { dir1: [-0.1, -1, -0.1], dir2: [0.1, -1, 0.1] },
    snow: { dir1: [-0.5, -0.3, -0.5], dir2: [0.5, -0.3, 0.5] },
    leaves: { dir1: [-0.8, -0.3, -0.8], dir2: [0.8, 0.3, 0.8] },
};

function _applyParticleConfig(ps: ParticleSystem, cfg: ParticleConfig, type: string): void {
    ps.blendMode = cfg.blendMode;
    ps.emitRate = cfg.emitRate;
    ps.gravity = new Vector3(...cfg.gravity);
    ps.minLifeTime = cfg.minLifeTime;
    ps.maxLifeTime = cfg.maxLifeTime;
    ps.minEmitPower = cfg.minEmitPower;
    ps.maxEmitPower = cfg.maxEmitPower;
    ps.minSize = cfg.minSize;
    ps.maxSize = cfg.maxSize;
    if (cfg.angularSpeed) {
        ps.minAngularSpeed = cfg.angularSpeed[0];
        ps.maxAngularSpeed = cfg.angularSpeed[1];
    }
    if (cfg.emitter) {
        if (cfg.emitter.kind === 'sphere') {
            ps.createSphereEmitter(cfg.emitter.radius);
        }
    } else if (WEATHER_TYPES.includes(type)) {
        // 天气类型使用盒发射器
        const dirs = WEATHER_BOX_DIRS[type];
        if (dirs) {
            ps.createBoxEmitter(
                new Vector3(...dirs.dir1),
                new Vector3(...dirs.dir2),
                new Vector3(-WEATHER_BOX_XZ_HALF, 0, -WEATHER_BOX_XZ_HALF),
                new Vector3(WEATHER_BOX_XZ_HALF, WEATHER_BOX_Y_RANGE, WEATHER_BOX_XZ_HALF)
            );
        }
    }
    for (const [t, c1, c2] of cfg.colors) {
        ps.addColorGradient(t, c1, c2);
    }
}

/** 计算粒子发射器 Y 坐标（天气类型在世界地面以上，局部效果按类型偏移） */
function _getEmitterY(type: string, groundY: number): number {
    if (WEATHER_TYPES.includes(type)) {
        return groundY + WEATHER_HEIGHT_ABOVE_GROUND;
    }
    if (type === 'fireflies') {
        return groundY + FIREFLY_HEIGHT_OFFSET;
    }
    if (type === 'fireworks') {
        return groundY + FIREWORK_HEIGHT_OFFSET;
    }
    return groundY;
}

export function createParticleEmitter(type: EnvState['particleType'], windEnabled: boolean): void {
    ensureEnvUpdateObserver();
    if (_envSys.particles.system && _currentParticleType === type) {
        return;
    }
    // [doc:adr-160] 粒子类型切换时同步湿身效果
    const prevType = _currentParticleType;
    if (_envSys.particles.system) {
        // keepWetness=true：内部重建不清湿身，湿身由紧随其后的类型判断逻辑处理
        disposeParticles(true);
    }
    _currentParticleType = type;
    // 湿身效果：进入/退出雨天时切换
    if (isWeatherType(type) && type === 'rain' && !isWeatherType(prevType)) {
        applyWetnessToAllModels();
    } else if (isWeatherType(prevType) && !isWeatherType(type)) {
        removeWetnessFromAllModels();
    }
    if (type === 'none') {
        return;
    }

    const scene = getScene();
    const cfg = PARTICLE_CONFIGS[type];
    if (!cfg) {
        logWarn('env', `unknown particle type: ${type}`);
        return;
    }

    const ps = new ParticleSystem('envParticles', 15000, scene);
    ps.particleTexture = makeParticleTexture(type, envState.particleCustomTexture || undefined);
    _prevCustomTexKey = envState.particleCustomTexture
        ? `_custom_${envState.particleCustomTexture}`
        : null;
    ps.updateSpeed = 0.01;
    ps.emitter = new Vector3(0, 0, 0);

    _applyParticleConfig(ps, cfg, type);

    // 雨的纹理是竖线条，用 STRETCHED billboard 沿速度方向拉伸，避免风吹时纹理方向与实际轨迹错位
    if (type === 'rain') {
        ps.billboardMode = ParticleSystem.BILLBOARDMODE_STRETCHED;
    }

    _baseEmitRate = ps.emitRate;
    _baseMinSize = ps.minSize;
    _baseMaxSize = ps.maxSize;
    _baseMinEmitPower = ps.minEmitPower;
    _baseMaxEmitPower = ps.maxEmitPower;
    _initialDir1 = ps.direction1.clone();
    _initialDir2 = ps.direction2.clone();

    // 应用 multiplier（用户设置 + 质量档位）
    _particleQualityMultiplier = resolveParticleQualityMultiplier(
        envState.particleQuality ?? 'high'
    );
    ps.emitRate = Math.max(0, ps.emitRate * envState.particleEmitRate * _particleQualityMultiplier);
    if (envState.particleSize !== 1) {
        ps.minSize *= envState.particleSize;
        ps.maxSize *= envState.particleSize;
    }
    if (envState.particleSpeed !== 1) {
        ps.minEmitPower *= envState.particleSpeed;
        ps.maxEmitPower *= envState.particleSpeed;
    }
    if (windEnabled) {
        applyWindToParticles(ps);
    }

    // 每帧跟随相机（XZ 跟随，Y 按类型策略定位）
    _envSys.particles.followObserver = observe(scene.onBeforeRenderObservable, () => {
        const cam = scene.activeCamera;
        if (!cam) {
            return;
        }
        const e = ps.emitter;
        if (!(e instanceof Vector3)) {
            return;
        }
        const groundY = envState.groundLevel ?? 0;
        e.x = cam.position.x;
        e.z = cam.position.z;
        e.y = _getEmitterY(type, groundY);
    });

    _envSys.particles.system = ps;
    ps.start();

    if (WEATHER_TYPES.includes(type)) {
        startCollisionDetection(ps, type);
    }
    syncSplashState();
    if (type === 'fireworks') {
        scheduleNextFireworkBurst();
    }
}

export function disposeParticles(keepWetness = false): void {
    _collisionObserver = safeDispose(_collisionObserver);
    _envSys.particles.followObserver = safeDispose(_envSys.particles.followObserver);
    _envSys.particles.system = safeDispose(_envSys.particles.system);
    disposeSplash(); // 粒子销毁时同步销毁溅射
    stopFireworkBursts(); // 烟花 burst 清理
    // 释放粒子纹理缓存（防止 GPU 资源泄漏）
    for (const tex of _particleTextures.values()) {
        tex.dispose();
    }
    _particleTextures.clear();
    _initialDir1 = null;
    _initialDir2 = null;
    _baseGravity = null;
    _baseEmitRate = 0;
    _baseMinSize = 0;
    _baseMaxSize = 0;
    _baseMinEmitPower = 0;
    _baseMaxEmitPower = 0;
    _prevCustomTexKey = null;
    // 彻底停止粒子（type→none / particleEnabled=false / 场景销毁）时移除湿身，防止状态泄漏；
    // 内部类型切换重建（keepWetness=true）不清，交由 createParticleEmitter 类型判断处理
    if (!keepWetness) {
        removeWetnessFromAllModels();
    }
    // 不重置 _currentParticleType，以便 particleEnabled 自动恢复时知道上次类型
}

/** 获取当前粒子类型（用于 particleEnabled 自动启停） */
export function getCurrentParticleType(): EnvState['particleType'] {
    return _currentParticleType;
}

// ======== Splash System (方案B: GPU渲染 + CPU幽灵粒子碰撞联动) ========

/** 判断当前粒子类型是否支持溅射（仅天气类型 rain/snow 有溅射） */
function isWeatherType(type: EnvState['particleType']): boolean {
    return type === 'rain' || type === 'snow';
}

/** 初始化 splash burst 对象池（预创建 N 个小型 GPUParticleSystem） */
function initSplashBurstPool(): void {
    if (_splashPoolReady) {
        return;
    }
    const scene = getScene();
    for (let i = 0; i < SPLASH_POOL_SIZE; i++) {
        const ps = new GPUParticleSystem(`splashBurst_${i}`, { capacity: 30 }, scene);
        ps.particleTexture = makeParticleTexture('splash');
        ps.emitRate = 0; // 待命状态，不持续发射
        ps.emitter = new Vector3(0, 0, 0);
        ps.minLifeTime = 0.3;
        ps.maxLifeTime = 0.8;
        ps.minSize = 0.04;
        ps.maxSize = 0.12;
        ps.minEmitPower = 3;
        ps.maxEmitPower = 6;
        ps.gravity = new Vector3(0, -12, 0);
        ps.blendMode = ParticleSystem.BLENDMODE_STANDARD;
        ps.direction1 = new Vector3(-1.5, 2, -1.5);
        ps.direction2 = new Vector3(1.5, 4, 1.5);
        ps.addColorGradient(0, new Color4(0.8, 0.9, 1, 0.9), new Color4(0.9, 0.95, 1, 0.95));
        ps.addColorGradient(1, new Color4(0.8, 0.9, 1, 0), new Color4(0.9, 0.95, 1, 0));
        ps.updateSpeed = 0.01;
        ps.start();
        _splashBurstPool.push({ system: ps, busy: false, releaseTimer: null });
    }
    _splashPoolReady = true;
}

/** 在精确位置触发一次 splash burst（幽灵粒子触地时调用） */
function spawnSplashAt(x: number, y: number, z: number): void {
    // 取一个空闲 burst
    let burst: SplashBurst | undefined;
    for (let i = 0; i < _splashBurstPool.length; i++) {
        if (!_splashBurstPool[i].busy) {
            burst = _splashBurstPool[i];
            break;
        }
    }
    if (!burst) {
        return;
    } // 池满，跳过这次溅射

    burst.busy = true;
    const e = burst.system.emitter;
    if (e instanceof Vector3) {
        e.set(x, y + 0.05, z); // 略微抬高避免 Z-fighting
    }

    // 短暂高密度发射
    burst.system.emitRate = 300;
    setTimeout(() => {
        burst!.system.emitRate = 0;
    }, 50);

    // 0.8s 后释放回池
    if (burst.releaseTimer) {
        clearTimeout(burst.releaseTimer);
    }
    burst.releaseTimer = setTimeout(() => {
        burst!.busy = false;
        burst!.releaseTimer = null;
    }, 800);
}

/** 碰撞检测地面高度空间网格缓存 — 每帧清空，按需填充，避免重复调用 getGroundHeightAt */
const _gridCellSize = 10;
const _groundHeightCache = new Map<number, number>();

function _gridCellKey(x: number, z: number): number {
    const cx = Math.floor(x / _gridCellSize);
    const cz = Math.floor(z / _gridCellSize);
    // 用 16 位交错编码（Morton-like）合成单 key，避免字符串 GC
    return (cx << 16) | (cz & 0xffff);
}

/** 启动碰撞检测 — 每帧遍历 CPU 粒子数组，检测地面碰撞 */
function startCollisionDetection(ps: ParticleSystem, type: EnvState['particleType']): void {
    const scene = getScene();
    _collisionObserver = safeDispose(_collisionObserver);

    const splashProb = type === 'rain' ? 0.15 : type === 'snow' ? 0.3 : 0.4;
    const frameSkip = type === 'rain' ? 4 : 2;
    let frameIdx = 0;

    _collisionObserver = observe(scene.onBeforeRenderObservable, () => {
        const particles = ps.particles;
        if (!particles || particles.length === 0) {
            return;
        }

        // 每帧清空缓存，避免旧帧数据残留
        _groundHeightCache.clear();

        const startIdx = frameIdx;
        for (let i = startIdx; i < particles.length; i += frameSkip) {
            const p = particles[i];
            if (p.direction.y >= 0) {
                continue;
            }

            // 空间网格缓存：同网格内粒子共享 ground height 查询结果
            const key = _gridCellKey(p.position.x, p.position.z);
            let gh = _groundHeightCache.get(key);
            if (gh === undefined) {
                gh = getGroundHeightAt(p.position.x, p.position.z);
                _groundHeightCache.set(key, gh);
            }

            const deathY = envState.waterEnabled ? Math.max(gh, envState.waterLevel) : gh;
            if (p.position.y <= deathY) {
                p.age = p.lifeTime;
                if (envState.waterEnabled && envState.waterLevel >= gh) {
                    // 水面涟漪
                    addRipple(
                        new Vector3(p.position.x, envState.waterLevel, p.position.z),
                        0.5,
                        0.35,
                        6,
                        1
                    );
                } else {
                    // 地面涟漪 + splash（雨滴/落叶触地）
                    addGroundRipple(
                        new Vector3(p.position.x, gh, p.position.z),
                        2, // 半径略小于水面，地面涟漪扩散范围小
                        0.25, // 强度适中
                        1.5, // 速度
                        1.5 // 寿命1.5秒
                    );
                    if (envState.particleSplashEnabled && Math.random() < splashProb) {
                        spawnSplashAt(p.position.x, gh, p.position.z);
                    }
                }
            }
        }
        frameIdx = (frameIdx + 1) % frameSkip;
    });
}

/** 销毁 splash burst 池 */
export function disposeSplash(): void {
    // 销毁 burst 池
    for (const b of _splashBurstPool) {
        if (b.releaseTimer) {
            clearTimeout(b.releaseTimer);
        }
        b.system.dispose();
    }
    _splashBurstPool = [];
    _splashPoolReady = false;
    // 清理旧 observer（兼容遗留 _envSys.splash.observer）
    if (_envSys.splash.observer) {
        _envSys.splash.observer.dispose();
        _envSys.splash.observer = null;
    }
}

/** 溅射开关切换（由 env-impl 检测 particleSplashEnabled 变化时调用） */
export function syncSplashState(): void {
    const shouldShow =
        envState.particleSplashEnabled &&
        isWeatherType(_currentParticleType) &&
        envState.particleEnabled;
    if (shouldShow && !_splashPoolReady) {
        initSplashBurstPool();
    } else if (!shouldShow && _splashPoolReady) {
        disposeSplash();
    }
}

// ======== Firework Multi-Burst System ========
interface FireworkBurstInstance {
    system: GPUParticleSystem;
    cleanupTimer: ReturnType<typeof setTimeout>;
}
let _fireworkBursts: FireworkBurstInstance[] = [];
let _fireworkScheduler: ReturnType<typeof setTimeout> | null = null;

function spawnFireworkBurst(): void {
    const scene = getScene();
    const cam = scene.activeCamera;
    if (!cam) {
        return;
    }

    const groundY = envState.groundLevel ?? 0;
    // 在相机附近随机位置爆散
    const pos = new Vector3(
        cam.position.x + (Math.random() - 0.5) * 30,
        groundY + FIREWORK_HEIGHT_OFFSET + (Math.random() - 0.5) * 4,
        cam.position.z + (Math.random() - 0.5) * 30
    );

    const burst = new GPUParticleSystem(
        `firework_${_fireworkBursts.length}_${Date.now()}`,
        { capacity: 200 },
        scene
    );
    burst.particleTexture = makeParticleTexture('fireworks');
    burst.emitter = pos;
    // 瞬时高密度爆发：emitRate=2000，50ms 内出约 100 粒子，之后停发
    burst.emitRate = 2000;
    setTimeout(() => {
        burst.emitRate = 0;
    }, 50);

    burst.minLifeTime = 0.4;
    burst.maxLifeTime = 1.0;
    burst.minEmitPower = 4;
    burst.maxEmitPower = 10;
    burst.gravity = new Vector3(0, -2, 0);
    burst.blendMode = ParticleSystem.BLENDMODE_ADD;
    burst.createSphereEmitter(0.2);

    // 每发随机色相
    const hue = Math.random();
    const r = 0.5 + Math.cos(hue * Math.PI * 2) * 0.5;
    const g = 0.5 + Math.cos((hue + 1 / 3) * Math.PI * 2) * 0.5;
    const b = 0.5 + Math.cos((hue + 2 / 3) * Math.PI * 2) * 0.5;

    burst.addColorGradient(0, new Color4(r, g, b, 1), new Color4(r, g, b, 1));
    burst.addColorGradient(
        0.4,
        new Color4(r, g, b, 0.8),
        new Color4(r * 0.8, g * 0.8, b * 0.8, 0.6)
    );
    burst.addColorGradient(
        1,
        new Color4(r * 0.3, g * 0.3, b * 0.3, 0),
        new Color4(r * 0.2, g * 0.2, b * 0.2, 0)
    );

    // 尺寸：爆炸膨胀后缩小
    burst.minSize = 0.05;
    burst.maxSize = 0.1;
    burst.addSizeGradient(0, 0.02, 0.04);
    burst.addSizeGradient(0.3, 0.2, 0.35);
    burst.addSizeGradient(1, 0.04, 0.08);

    burst.start();

    const cleanupTimer = setTimeout(() => {
        burst.dispose();
        _fireworkBursts = _fireworkBursts.filter((b) => b.system !== burst);
    }, 3000);

    _fireworkBursts.push({ system: burst, cleanupTimer });
}

function scheduleNextFireworkBurst(): void {
    const delay = 1200 + Math.random() * 1800; // 1.2~3s 间隔
    _fireworkScheduler = setTimeout(() => {
        if (_currentParticleType !== 'fireworks') {
            return;
        }
        if (!envState.particleEnabled) {
            return;
        }
        spawnFireworkBurst();
        scheduleNextFireworkBurst();
    }, delay);
}

function stopFireworkBursts(): void {
    if (_fireworkScheduler !== null) {
        clearTimeout(_fireworkScheduler);
        _fireworkScheduler = null;
    }
    for (const b of _fireworkBursts) {
        clearTimeout(b.cleanupTimer);
        b.system.dispose();
    }
    _fireworkBursts = [];
}

// ======== Wind System ========
// 双重风场：
//   1) 发射瞬间初速度带风偏（direction1/2 + wind × 0.2）
//   2) 飞行中持续风加速度（gravity = baseGravity + wind × 1.0）——物理正确，所有活跃粒子响应
// 单独只改 direction 是"假风"：粒子出生后只受 gravity，风停即无横向力，轨迹是直线平移。
// gravity 叠加后：风速变化实时响应，轨迹是真实弧线，风停后立即恢复竖直下落。
export function applyWindToParticles(ps: ParticleSystem): void {
    if (!_initialDir1 || !_initialDir2) {
        return;
    }
    // 惰性初始化：HMR/冷启动后粒子已存在时，从现有系统读取基础重力（避免 createParticleEmitter 早返回不执行赋值）
    if (!_baseGravity) {
        _baseGravity = ps.gravity.clone();
    }
    const wind = getWindVector();
    // 1. 发射瞬间初速度风偏（系数 0.2，避免与 gravity 叠加首帧过冲）
    const emitWind = wind.scale(0.2);
    ps.direction1 = _initialDir1.clone().add(emitWind);
    ps.direction2 = _initialDir2.clone().add(emitWind);
    // 2. 飞行中持续风加速度（系数 1.0，等价于把风场视为持续作用的重力分量）
    ps.gravity.copyFrom(_baseGravity).addInPlace(wind);
}

// 运行时动态更新风力（由 ensureEnvUpdateObserver 每帧调用）
export function updateParticleWind(): void {
    if (_envSys.particles.system) {
        applyWindToParticles(_envSys.particles.system);
    }
}

/** 运行时更新粒子参数（密度/大小/速度），响应滑条变化 */
export function updateParticleParams(): void {
    const ps = _envSys.particles.system;
    if (!ps) {
        return;
    }
    ps.emitRate = Math.max(
        0,
        _baseEmitRate * envState.particleEmitRate * _particleQualityMultiplier
    );
    ps.minSize = _baseMinSize * envState.particleSize;
    ps.maxSize = _baseMaxSize * envState.particleSize;
    ps.minEmitPower = _baseMinEmitPower * envState.particleSpeed;
    ps.maxEmitPower = _baseMaxEmitPower * envState.particleSpeed;
}

/** 运行时更新粒子纹理（响应自定义纹理变化） */
let _prevCustomTexKey: string | null = null;
export function updateParticleTexture(): void {
    const ps = _envSys.particles.system;
    if (!ps || !_currentParticleType || _currentParticleType === 'none') {
        return;
    }
    const url = envState.particleCustomTexture || undefined;
    const newKey = url ? `_custom_${url}` : null;
    // 切换前 dispose 上一个自定义纹理（释放 GPU 资源）
    if (_prevCustomTexKey && _prevCustomTexKey !== newKey) {
        const old = _particleTextures.get(_prevCustomTexKey);
        if (old) {
            old.dispose();
            _particleTextures.delete(_prevCustomTexKey);
        }
    }
    ps.particleTexture = makeParticleTexture(_currentParticleType, url);
    _prevCustomTexKey = newKey;
}

// ======== [ADR-138] env-dispatcher 回调注册 ========
const _PARTICLE_KEYS = getEnvKeys('particle');

registerEnvCallback((changed, state) => {
    if (!changed || [...changed].some((k) => _PARTICLE_KEYS.includes(k))) {
        // particleQuality-only change: light update, no full rebuild
        if (changed && changed.size === 1 && changed.has('particleQuality')) {
            _particleQualityMultiplier = resolveParticleQualityMultiplier(
                state.particleQuality ?? 'high'
            );
            updateParticleParams();
            return;
        }
        if (state.particleEnabled && state.particleType && state.particleType !== 'none') {
            createParticleEmitter(state.particleType, state.windEnabled);
        } else {
            disposeParticles();
        }
    }
});

// env-reflection.ts — 反射子系统统一入口（ADR-151）
//
// 参考天空子系统（env-sky.ts）的 applySky 模式：
//   - 统一入口 applyReflection(state)
//   - 模式互斥（或 hybrid 分层混合）
//   - 全量清理确保旧资源纯净
//   - reflectionTexture 所有权声明 + save/restore
//
// 关键设计决策（审查后调整）：
//   1. reflectionMode（新增字段）控制反射模式，reflectionQuality 保持原有语义（Planar 分辨率）
//   2. 互斥粒度为"材质槽位级"而非"系统级"：SSR + Planar 可共存，Probe 不写地面/水面材质
//   3. save/restore 在绑定前逐个保存，新模型加载时自动补绑

import { ReflectionProbe } from '@babylonjs/core/Probes/reflectionProbe';
import { Scene } from '@babylonjs/core/scene';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { BaseTexture } from '@babylonjs/core/Materials/Textures/baseTexture';
import type { Color3 } from '@babylonjs/core/Maths/math.color';
import { observe, type ObserverHandle } from '@/core/observer-handle';
import { safeDispose } from '@/core/dispose-helpers';
import { logWarn } from '@/core/logger';
import type { EnvState } from '@/core/config';
import { envState } from '@/core/config';
import { getScene } from './_shared/env-context';
import { registerEnvCallback } from './_bridge/env-dispatcher';
import { getEnvKeys } from '@/core/env-state-schema';
import { setSSRFromReflection, isSSRActive } from '../render/renderer';

// ======== 类型定义 ========

export type ReflectionMode = 'none' | 'planar' | 'ssr' | 'probe' | 'hybrid';

export type ResolvedReflectionMode = ReflectionMode;

/** 合法反射模式白名单：用于防御旧版持久化存档残留的非法枚举值（如 ADR-151 修订前 schema 曾含 'auto'） */
const VALID_REFLECTION_MODES: readonly ResolvedReflectionMode[] = [
    'none',
    'planar',
    'ssr',
    'probe',
    'hybrid',
];

// ======== 质量等级参数预设 ========

interface ReflectionQualityPreset {
    ssr: { step: number; strength: number; thickness: number } | null;
    probe: { resolution: number; strength: number } | null;
}

const QUALITY_PRESETS: Record<string, ReflectionQualityPreset> = {
    off: {
        ssr: null,
        probe: null,
    },
    low: {
        ssr: null,
        probe: { resolution: 256, strength: 0.3 },
    },
    medium: {
        ssr: null,
        probe: { resolution: 256, strength: 0.5 },
    },
    high: {
        ssr: { step: 16, strength: 0.7, thickness: 0.5 },
        probe: { resolution: 256, strength: 0.3 },
    },
};

// ======== 模块状态 ========

let _reflectionProbe: ReflectionProbe | null = null;
let _probeRefreshObserver: ObserverHandle | null = null;
let _lastProbeRefresh = 0;
let _currentMode: ResolvedReflectionMode = 'none';

/** AR 模式激活时挂起全部反射（纯派生覆盖，退出 AR 后恢复用户 reflectionMode） */
let _arSuspended = false;

/** Probe 创建失败标记：GPU 资源不足等场景下不再无限重试 */
let _probeCreateFailed = false;

/** Probe 自动刷新的最低 FPS 守卫：帧率低于此值时跳过本次刷新，避免 cubemap 渲染造成帧 spike */
const PROBE_REFRESH_MIN_FPS = 24;

/** 上次 Probe renderList 重建时的场景网格数量（增量优化：仅数量变化时重建） */
let _lastProbeMeshCount = 0;
/**
 * P3-fix: 上次 Probe renderList 重建时的网格 uniqueId 签名。
 * 仅数量变化不足以捕获"换装/替换模型"场景（mesh 数不变但内容变化），
 * 用 uniqueId 排序后拼接的签名做脏标记，内容变化时也触发重建。
 */
let _lastProbeMeshSignature = '';

/**
 * 保存材质原始 reflectionTexture 的映射（material.uniqueId → 原始纹理）。
 * Probe 绑定前逐个保存，退出时逐个恢复，消除悬空指针。
 */
const _savedReflectionTextures = new Map<number, BaseTexture | null>();
/** 保存材质原始 reflectionColor（与 _savedReflectionTextures 对称，P4 修复） */
const _savedReflectionColors = new Map<number, Color3 | null>();

/**
 * 已绑定 Probe 的材质映射（uniqueId → 材质引用）。
 * dispose 时直接遍历值恢复，避免网格被移出场景（模型卸载）后
 * 遍历 scene.meshes 漏掉其材质导致悬空指针。
 */
const _probeBoundMaterials = new Map<number, MaterialWithReflection>();

/** Probe 当前强度（hybrid 模式下按 _getHybridProbeFactor 衰减） */
let _probeStrength = 1;

/** Hybrid 模式下 Probe 强度衰减系数：按 reflectionQuality 分级，低画质更依赖 SSR */
function _getHybridProbeFactor(state: EnvState): number {
    const quality = state.reflectionQuality ?? 'high';
    switch (quality) {
        case 'low':
            return 0.3;
        case 'medium':
            return 0.4;
        case 'high':
            return 0.5;
        default:
            return 0.5;
    }
}

// ======== 模式推导 ========

export function resolveReflectionMode(state: EnvState): ResolvedReflectionMode {
    // AR 场景无背景平面，角色倒影/环境反射无意义且浪费 GPU：纯派生覆盖为 'none'
    if (_arSuspended) {
        return 'none';
    }
    const mode = state.reflectionMode;
    // 防御旧版持久化存档残留的非法枚举（如 ADR-151 修订前 schema 曾含 'auto'），
    // 避免落入 applyReflection 的 switch 无匹配分支导致零反射静默 no-op。
    if (!mode || !VALID_REFLECTION_MODES.includes(mode)) {
        return 'planar';
    }
    return mode;
}

/**
 * AR 模式联动：挂起/恢复反射子系统。
 * 由 ar-scene.ts 的 setARMode 在 AR 激活成功时挂起、退出时恢复。
 * 采用派生覆盖（不改写用户 reflectionMode），避免状态泄漏与回滚遗漏。
 */
export function setReflectionARSuspended(suspended: boolean): void {
    if (_arSuspended === suspended) {
        return;
    }
    _arSuspended = suspended;
    // 立即重算反射（envState 为当前态），使进入/退出 AR 反射即时开关。
    // scene 未初始化（模块加载期/测试环境）时 applyReflection 会抛，安全跳过：
    // 派生标志 _arSuspended 已更新，待下次反射状态变化重算时生效。
    try {
        applyReflection(envState);
    } catch (err) {
        logWarn(
            'env-reflection',
            'setReflectionARSuspended: applyReflection 跳过（scene 未就绪）:',
            err
        );
    }
}

/**
 * 获取当前质量等级对应的参数预设。
 */
export function getQualityPreset(state: EnvState): ReflectionQualityPreset {
    const quality = state.reflectionQuality ?? 'off';
    return QUALITY_PRESETS[quality] ?? QUALITY_PRESETS['off'];
}

/**
 * ADR-151: 平面反射质量全局覆盖（供 env-ground / env-water 的 getQuality 检查）。
 * - reflectionMode='none'  → 强制 'off'（关闭全部反射，含平面反射）
 * - reflectionMode='planar' → 固定 'low'（控制平面倒影成本）
 * - 其他模式且 reflectionQuality='off' → 'low'（保底，避免已选反射模式却零倒影）
 * - 其他模式且 reflectionQuality≠'off' → null（平面倒影遵循用户 reflectionQuality 设置）
 * 纯函数于 state，与 dispatcher 回调执行顺序无关，保证任意时序下结论一致。
 */
export function getPlanarQualityOverride(state: EnvState): 'off' | 'low' | null {
    const mode = resolveReflectionMode(state);
    if (mode === 'none') {
        return 'off';
    }
    // planar 模式固定 low（控制平面倒影成本）；
    // ssr/probe/hybrid 模式下 reflectionQuality='off' 仅关 SSR/Probe 层，
    // 不应连带关闭地面/水面平面倒影（尤其 hybrid=最高画质预期）。
    if (mode === 'planar') {
        return 'low';
    }
    const quality = state.reflectionQuality ?? 'off';
    if (quality === 'off') {
        return 'low';
    }
    return null;
}

// ======== 所有权管理 ========

interface MaterialWithReflection {
    uniqueId: number;
    reflectionTexture: BaseTexture | null;
    reflectionColor?: Color3 | null;
    isDisposed?: boolean;
}

/**
 * 保存材质原始 reflectionTexture（绑定前调用）。
 * 仅首次保存，避免 Probe 的 cubeTexture 被当作"原始值"误存。
 */
function _saveOriginalTexture(mat: MaterialWithReflection): void {
    if (!_savedReflectionTextures.has(mat.uniqueId)) {
        _savedReflectionTextures.set(mat.uniqueId, mat.reflectionTexture);
        // P4 修复：克隆原始 reflectionColor，避免后续 .set() 原地修改污染保存值
        _savedReflectionColors.set(
            mat.uniqueId,
            mat.reflectionColor ? mat.reflectionColor.clone() : null
        );
    }
}

/**
 * 恢复材质原始 reflectionTexture（Probe 退出时调用）。
 * 校验材质是否仍存活，已 dispose 的材质跳过并清理映射。
 */
function _restoreOriginalTexture(mat: MaterialWithReflection): void {
    if (mat.isDisposed) {
        _savedReflectionTextures.delete(mat.uniqueId);
        _probeBoundMaterials.delete(mat.uniqueId);
        return;
    }
    const saved = _savedReflectionTextures.get(mat.uniqueId);
    mat.reflectionTexture = saved ?? null;
    _savedReflectionTextures.delete(mat.uniqueId);

    // P4 修复：同步还原 reflectionColor，消除 Probe 退出后残留强度色
    const savedColor = _savedReflectionColors.get(mat.uniqueId);
    if (mat.reflectionColor) {
        if (savedColor) {
            mat.reflectionColor.copyFrom(savedColor);
        } else {
            mat.reflectionColor.set(1, 1, 1);
        }
    }
    _savedReflectionColors.delete(mat.uniqueId);

    _probeBoundMaterials.delete(mat.uniqueId);
}

// ======== Probe 管理 ========

/**
 * 创建 ReflectionProbe 并绑定到场景环境网格。
 * @param resolution cubemap 分辨率（默认 256）
 */
function _createProbe(scene: Scene, resolution = 256): void {
    if (_reflectionProbe || _probeCreateFailed) {
        return;
    }
    try {
        _reflectionProbe = new ReflectionProbe('envProbe', resolution, scene);
        _reflectionProbe.renderList = scene.meshes.filter(
            (m) =>
                m.name.includes('sky') ||
                m.name.includes('env') ||
                m.name.includes('ground') ||
                m.name.includes('water')
        );
        _reflectionProbe.refreshRate = 0; // 静态环境，仅渲染一次
        _lastProbeMeshCount = scene.meshes.length; // 记录初始网格数量
    } catch (err) {
        logWarn('env-reflection', 'ReflectionProbe 创建失败（本次会话不再重试）:', err);
        _reflectionProbe = null;
        _probeCreateFailed = true;
        return;
    }

    // 自动刷新 observer：每 10 秒检查环境变化
    _lastProbeRefresh = performance.now();
    _probeRefreshObserver = observe(scene.onBeforeRenderObservable, () => {
        if (!_reflectionProbe || !scene || scene.isDisposed) {
            return;
        }
        const now = performance.now();
        if (now - _lastProbeRefresh < 10000) {
            return;
        }
        // FPS 守卫：帧率过低时跳过本次刷新，避免 cubemap 渲染造成帧 spike
        if (scene.getEngine().getFps() < PROBE_REFRESH_MIN_FPS) {
            return;
        }
        _lastProbeRefresh = now;
        try {
            // P3-fix: 用 uniqueId 签名替代纯数量比较，捕获换装/替换模型时的内容变化
            const currentMeshCount = scene.meshes.length;
            const currentSignature = scene.meshes
                .map((m) => m.uniqueId)
                .sort((a, b) => a - b)
                .join(',');
            if (currentSignature !== _lastProbeMeshSignature) {
                _lastProbeMeshSignature = currentSignature;
                _lastProbeMeshCount = currentMeshCount;
                _reflectionProbe!.renderList = scene.meshes.filter(
                    (m) =>
                        m.name.includes('sky') ||
                        m.name.includes('env') ||
                        m.name.includes('ground') ||
                        m.name.includes('water')
                );
            }
            _reflectionProbe!.cubeTexture.render();
        } catch (err) {
            logWarn('env-reflection', 'ReflectionProbe 自动刷新失败:', err);
        }
    });
}

/**
 * 将 Probe cubemap 绑定到指定网格的材质（含 save 原始纹理）。
 * 仅绑定模型网格（排除 env 前缀的环境网格，避免与 PlanarReflection 槽位冲突）。
 */
export function bindProbeToMeshes(meshes: AbstractMesh[]): void {
    if (!_reflectionProbe) {
        return;
    }
    const rt = _reflectionProbe.cubeTexture;
    if (!rt) {
        return;
    }
    for (const mesh of meshes) {
        // 排除环境网格（地面/水面/天空），它们的 reflectionTexture 由 PlanarReflection 管理
        // （'env' 前缀已覆盖 envGround/envWater/envSkySphere 等，无需冗余判断）
        if (mesh.name.startsWith('env')) {
            continue;
        }
        try {
            const m = mesh.material as unknown as MaterialWithReflection | null;
            if (m && !m.isDisposed && 'reflectionTexture' in m) {
                _saveOriginalTexture(m);
                m.reflectionTexture = rt;
                _probeBoundMaterials.set(m.uniqueId, m);
                // 设置反射强度
                if ('reflectionColor' in m) {
                    const intensity = _probeStrength;
                    (
                        m as unknown as {
                            reflectionColor: { set: (r: number, g: number, b: number) => void };
                        }
                    ).reflectionColor.set(intensity, intensity, intensity);
                }
            }
        } catch (err) {
            // 单个网格绑定失败（如 MultiMaterial 等特殊结构）不中断其他网格
            logWarn('env-reflection', `Probe 绑定网格 ${mesh.name} 失败:`, err);
        }
    }
}

/**
 * 从所有已绑定材质恢复原始 reflectionTexture，然后销毁 Probe。
 */
function _disposeProbe(_scene: Scene): void {
    if (!_reflectionProbe) {
        return;
    }

    // 恢复所有已绑定材质的原始纹理。
    // 直接遍历材质引用映射（而非 scene.meshes），确保已被移出场景的
    // 网格（模型卸载）其材质也能被正确恢复，消除悬空指针。
    for (const m of _probeBoundMaterials.values()) {
        _restoreOriginalTexture(m);
    }
    _probeBoundMaterials.clear();
    _savedReflectionTextures.clear();
    _savedReflectionColors.clear();

    // 释放 observer + probe
    _probeRefreshObserver = safeDispose(_probeRefreshObserver);
    _reflectionProbe = safeDispose(_reflectionProbe);
    _lastProbeRefresh = 0;
}

// ======== SSR 控制（委托 renderer.ts） ========

/**
 * 通过 renderer.setRenderState 控制 SSR 管线。
 * SSR pipeline 对象仍在 renderer.ts 维护（渲染管线资源），控制权由本模块行使。
 */
function _applySSR(params: {
    enabled: boolean;
    step?: number;
    strength?: number;
    thickness?: number;
}): void {
    setSSRFromReflection(params);
}

// ======== 统一入口 ========

/**
 * 反射子系统统一入口。参考 applySky 模式：
 * 1. 推导模式
 * 2. 模式切换时全量清理旧资源
 * 3. 按模式激活对应子系统
 */
export function applyReflection(state: EnvState): void {
    const scene = getScene();
    if (!scene || scene.isDisposed) {
        return;
    }

    const mode = resolveReflectionMode(state);
    const preset = getQualityPreset(state);

    // 模式未变化 → 仅更新参数（避免无谓重建）
    if (mode === _currentMode && mode !== 'none') {
        if ((mode === 'probe' || mode === 'hybrid') && _reflectionProbe) {
            const factor = mode === 'hybrid' ? _getHybridProbeFactor(state) : 1.0;
            _updateProbeStrength(preset, factor);
        }
        // 同步更新 SSR 参数（仅在 SSR 当前激活时，尊重用户手动关闭）
        if ((mode === 'ssr' || mode === 'hybrid') && isSSRActive()) {
            _applySSR({
                enabled: true,
                step: preset.ssr?.step ?? 16,
                strength: preset.ssr?.strength ?? 0.7,
                thickness: preset.ssr?.thickness ?? 0.5,
            });
        }
        return;
    }

    // 模式切换：全量清理旧状态
    if (mode !== _currentMode) {
        _disableCurrentMode(scene);
    }

    _currentMode = mode;

    switch (mode) {
        case 'none':
            // 全关（已在 _disableCurrentMode 中处理）
            break;

        case 'probe':
            _enableProbe(scene, preset, mode);
            break;

        case 'ssr':
            _enableSSR(preset);
            break;

        case 'planar':
            // PlanarReflection 仍由 env-ground / env-water 各自管理（SSR 与 Probe 已关闭）。
            // 最低质量保证通过 getPlanarQualityOverride 在二者 getQuality 内完成
            // （reflectionMode='planar' 时拔高到至少 low）。
            break;

        case 'hybrid':
            _enableHybrid(scene, preset, state);
            break;
    }
}

/**
 * 关闭当前激活的反射模式，释放资源。
 */
function _disableCurrentMode(scene: Scene): void {
    // 关闭 Probe
    if (_reflectionProbe) {
        _disposeProbe(scene);
    }
    // 关闭 SSR
    if (_currentMode === 'ssr' || _currentMode === 'hybrid') {
        _applySSR({ enabled: false });
    }
}

/**
 * 启用 Probe 模式。
 */
function _enableProbe(
    scene: Scene,
    preset: ReflectionQualityPreset,
    _mode: ResolvedReflectionMode
): void {
    const resolution = preset.probe?.resolution ?? 256;
    _probeStrength = preset.probe?.strength ?? 0.5;
    _createProbe(scene, resolution);
    if (_reflectionProbe) {
        // 绑定到场景中已有的模型网格
        bindProbeToMeshes(scene.meshes);
    }
}

/**
 * 启用 SSR 模式。
 */
function _enableSSR(preset: ReflectionQualityPreset): void {
    _applySSR({
        enabled: true,
        step: preset.ssr?.step ?? 16,
        strength: preset.ssr?.strength ?? 0.7,
        thickness: preset.ssr?.thickness ?? 0.5,
    });
}

/**
 * 启用 hybrid 模式：SSR + Probe 分层混合。
 * Probe 提供基础环境反射底色（强度按 reflectionQuality 分级衰减），SSR 提供动态细节叠加。
 */
function _enableHybrid(scene: Scene, preset: ReflectionQualityPreset, state: EnvState): void {
    // Probe 层：强度衰减避免与 SSR 叠加过亮
    const resolution = preset.probe?.resolution ?? 256;
    _probeStrength = (preset.probe?.strength ?? 0.3) * _getHybridProbeFactor(state);
    _createProbe(scene, resolution);
    if (_reflectionProbe) {
        bindProbeToMeshes(scene.meshes);
    }

    // SSR 层：独立渲染动态反射细节
    _applySSR({
        enabled: true,
        step: preset.ssr?.step ?? 16,
        strength: preset.ssr?.strength ?? 0.7,
        thickness: preset.ssr?.thickness ?? 0.5,
    });
}

/**
 * 更新 Probe 强度（模式未变但参数变化时调用）。
 */
function _updateProbeStrength(preset: ReflectionQualityPreset, factor: number): void {
    const baseStrength = preset.probe?.strength ?? 0.5;
    const newStrength = baseStrength * factor;
    if (Math.abs(newStrength - _probeStrength) < 0.01) {
        return;
    }
    _probeStrength = newStrength;
    // 更新已绑定材质的反射强度（直接遍历材质引用映射，跳过已 dispose 的）
    for (const m of _probeBoundMaterials.values()) {
        if (!m.isDisposed && 'reflectionColor' in m) {
            (
                m as unknown as {
                    reflectionColor: { set: (r: number, g: number, b: number) => void };
                }
            ).reflectionColor.set(_probeStrength, _probeStrength, _probeStrength);
        }
    }
}

// ======== 公共 API ========

/**
 * 模型加载后调用：将 Probe 绑定到新模型的网格。
 * 替代旧 renderer.ts 的 bindReflectionProbeToModel。
 */
export function onModelMeshesReady(meshes: AbstractMesh[]): void {
    if (_reflectionProbe && (_currentMode === 'probe' || _currentMode === 'hybrid')) {
        bindProbeToMeshes(meshes);
    }
}

/**
 * 释放反射子系统全部资源（场景销毁时调用）。
 */
export function disposeReflection(): void {
    const scene = getScene();
    if (scene) {
        _disableCurrentMode(scene);
    } else {
        // scene 已不可用，直接清理引用
        _probeRefreshObserver = safeDispose(_probeRefreshObserver);
        _reflectionProbe = safeDispose(_reflectionProbe);
    }
    _currentMode = 'none';
    _probeStrength = 1;
    _probeCreateFailed = false;
    _savedReflectionTextures.clear();
    _savedReflectionColors.clear();
    _probeBoundMaterials.clear();
}

// ======== env-dispatcher 回调注册 ========

const _REFLECTION_KEYS = getEnvKeys('reflection');

registerEnvCallback((changed, state) => {
    if (!changed || [...changed].some((k) => _REFLECTION_KEYS.includes(k))) {
        applyReflection(state);
    }
});

// env-sky.ts — 天空子系统（程序化渐变 / CubeTexture / color 模式）
// 从 env-impl.ts 拆分而来，导入共享依赖通过 env-impl.ts barrel。

import {
    Scene,
    Color3,
    Color4,
    Texture,
    DynamicTexture,
    StandardMaterial,
    Constants,
    Mesh,
    MeshBuilder,
    CubeTexture,
    RawCubeTexture,
} from '@babylonjs/core';
import { EnvState, envState } from '@/core/config';
import { col3FromTriple } from '@/core/color-helpers';
import { logWarn } from '@/core/logger';
import { _envSys, getScene, resolveStaticAsset } from './_shared/env-context';
import { ensureEnvUpdateObserver } from './env';
import { _disposeSunDisc } from '../render/lighting';
import { observe, type ObserverHandle } from '@/core/observer-handle';
import { safeDispose } from '@/core/dispose-helpers';

// ======== Module state ========
let _lastProceduralSkyKey = '';
let _lastSkyCubePath: string | null = null; // cube 路径缓存，避免旋转/强度微调时重复从磁盘加载
let _skyFollowHandle: ObserverHandle | null = null;
let _proceduralEnvTexture: RawCubeTexture | null = null;

/** 天空渐变 canvas 尺寸 */
const SKY_TEX_SIZE = 512;

// ======== 星空贴图异步加载缓存 ========
let _texStarsImg: HTMLImageElement | null = null;
let _texStarsImgUrl: string | null = null;
let _texStarsGeneration = 0;

export function clearStarsTexCache() {
    _texStarsImg = null;
    _texStarsImgUrl = null;
    _texStarsGeneration = 0;
}

/** 异步加载星空贴图（带 generation 守卫）。 */
function _ensureStarsTextureImage(url: string, onReady: (img: HTMLImageElement) => void): void {
    if (_texStarsImg && _texStarsImgUrl === url && _texStarsImg.complete) {
        onReady(_texStarsImg);
        return;
    }
    if (_texStarsImgUrl !== url) {
        _texStarsImg = null;
        _texStarsImgUrl = url;
    }
    const generation = ++_texStarsGeneration;
    const img = new Image();
    img.onload = () => {
        if (generation !== _texStarsGeneration) {
            return;
        }
        _texStarsImg = img;
        onReady(img);
    };
    img.onerror = () => {
        if (generation !== _texStarsGeneration) {
            return;
        }
        logWarn('stars', 'texture load failed:', url);
    };
    img.src = url;
}

// ======== Sky Gradient Drawing ========

function drawSkyGradient(
    ctx: CanvasRenderingContext2D,
    top: Color3,
    mid: Color3,
    bot: Color3,
    brightness: number,
    sunAngle: number,
    starsEnabled: boolean,
    starsTextureImg?: HTMLImageElement | null
): void {
    const W = SKY_TEX_SIZE,
        H = SKY_TEX_SIZE;
    ctx.clearRect(0, 0, W, H);

    const grad = ctx.createLinearGradient(0, 0, 0, H);
    const scale = (c: Color3) =>
        `rgb(${(c.r * brightness * 255) | 0},${(c.g * brightness * 255) | 0},${(c.b * brightness * 255) | 0})`;
    // 渐变方向：canvas 顶 → 天顶(top)，canvas 底 → 天底(bot)
    // BACKSIDE 球体映射：canvas top = 天顶，canvas bottom = 地平/脚下
    grad.addColorStop(0, scale(top));
    grad.addColorStop(0.55, scale(mid));
    grad.addColorStop(0.85, scale(bot));
    grad.addColorStop(1, scale(bot));
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    if (starsEnabled) {
        const starAlpha = sunAngle > 10 ? 0 : sunAngle < -5 ? 1 : (10 - sunAngle) / 15;
        if (starAlpha > 0.01) {
            if (starsTextureImg) {
                ctx.save();
                ctx.globalAlpha = starAlpha;
                ctx.drawImage(starsTextureImg, 0, 0, W, H);
                ctx.restore();
            } else {
                const starSeed = 12345;
                const hash = (i: number) => {
                    let h = (i * 2654435761 + starSeed) | 0;
                    h ^= h >>> 13;
                    return (h & 0x7fffffff) / 0x7fffffff;
                };
                // 星星画在 canvas 上半 → 映射到球体可见天空半球
                const starCount = Math.round(400 + starAlpha * 200);
                for (let i = 0; i < starCount; i++) {
                    const sx = hash(i * 3) * W;
                    const sy = hash(i * 3 + 1) * H * 0.55;
                    const sr = 0.8 + hash(i * 3 + 2) * 2.2;
                    const sa = starAlpha * (0.4 + hash(i + 1000) * 0.6);
                    const twinkle = 0.7 + hash(i + 2000) * 0.3;
                    const r = (220 + hash(i + 3000) * 35) | 0;
                    const g = (210 + hash(i + 4000) * 45) | 0;
                    const b = (200 + hash(i + 5000) * 55) | 0;
                    const alpha = sa * twinkle;
                    // 辉光晕圈（较大星星才有）
                    if (sr > 1.5) {
                        ctx.fillStyle = `rgba(${r},${g},${b},${(alpha * 0.12).toFixed(3)})`;
                        ctx.beginPath();
                        ctx.arc(sx, sy, sr * 3, 0, Math.PI * 2);
                        ctx.fill();
                    }
                    // 星体
                    ctx.fillStyle = `rgba(${r},${g},${b},${alpha.toFixed(2)})`;
                    ctx.beginPath();
                    ctx.arc(sx, sy, sr, 0, Math.PI * 2);
                    ctx.fill();
                }
            }
        }
    }
}

// ======== DynamicTexture Management ========

function updateSkyDynamicTexture(state: EnvState): DynamicTexture {
    const scene = getScene();
    const envBrightness = state.globalBrightness ?? 1;
    const effectiveSkyBrightness = state.skyBrightness * envBrightness;
    let tex = _envSys.sky.skyDynamicTex;
    if (!tex) {
        tex = new DynamicTexture(
            'skyGradient',
            { width: SKY_TEX_SIZE, height: SKY_TEX_SIZE },
            scene,
            false
        );
        tex.wrapU = Constants.TEXTURE_CLAMP_ADDRESSMODE;
        tex.wrapV = Constants.TEXTURE_CLAMP_ADDRESSMODE;
        tex.hasAlpha = false;
        _envSys.sky.skyDynamicTex = tex;
    }
    const ctx = tex.getContext() as CanvasRenderingContext2D;

    let starsImg: HTMLImageElement | null = null;
    if (
        state.starsTexture &&
        _texStarsImg &&
        _texStarsImgUrl === state.starsTexture &&
        _texStarsImg.complete
    ) {
        starsImg = _texStarsImg;
    }

    drawSkyGradient(
        ctx,
        col3FromTriple(state.skyColorTop),
        col3FromTriple(state.skyColorMid),
        col3FromTriple(state.skyColorBot),
        effectiveSkyBrightness,
        state.sunAngle,
        state.starsEnabled,
        starsImg
    );
    tex.update();

    if (state.starsTexture && !starsImg) {
        const url = resolveStaticAsset(state.starsTexture);
        _ensureStarsTextureImage(url, (img) => {
            const cur = _envSys.sky.skyDynamicTex;
            if (!cur) {
                return;
            }
            const curCtx = cur.getContext() as CanvasRenderingContext2D | null;
            if (!curCtx) {
                return;
            }
            drawSkyGradient(
                curCtx,
                col3FromTriple(state.skyColorTop),
                col3FromTriple(state.skyColorMid),
                col3FromTriple(state.skyColorBot),
                effectiveSkyBrightness,
                state.sunAngle,
                state.starsEnabled,
                img
            );
            cur.update();
        });
    }

    return tex;
}

// ======== Procedural Sky ========

function createProceduralSky(state: EnvState): void {
    const scene = getScene();
    const cam = scene.activeCamera;
    const farZ = cam?.maxZ ?? 10000;
    const diameter = Math.min(20000, Math.max(2000, farZ * 1.8));
    const sphere = MeshBuilder.CreateSphere(
        'envSkySphere',
        { diameter, segments: 32, sideOrientation: Mesh.BACKSIDE },
        scene
    );
    sphere.isPickable = false;
    // 先于体积云（Group -1）渲染，填背景但不写深度，避免挡住云的 alpha 合成
    sphere.renderingGroupId = -2;

    const mat = new StandardMaterial('envSkyMat', scene);
    mat.emissiveTexture = updateSkyDynamicTexture(state);
    mat.disableLighting = true;
    mat.backFaceCulling = false;
    mat.disableDepthWrite = true;

    sphere.material = mat;
    _envSys.sky.skyMesh = sphere;

    // 跟随相机，与云层同心（同 center），确保深度测试正确。
    // Y 也跟随：天空盒是钉在眼球上的无限远背景，仅跟 X/Z 时相机抬升/远离
    // 会越过有限球壳边界，露出 clearColor 灰底（俯视天顶 / 转身）。
    _skyFollowHandle = observe(scene.onBeforeRenderObservable, () => {
        const cam = scene.activeCamera;
        if (!cam) {
            return;
        }
        sphere.position.x = cam.position.x;
        sphere.position.y = cam.position.y;
        sphere.position.z = cam.position.z;
    });

    scene.clearColor = new Color4(0, 0, 0, 1);

    // 为 PBR 材质创建简单环境贴图（IBL）
    createProceduralEnvTexture(state, scene);

    const envBrightness = state.globalBrightness ?? 1;
    const effectiveSkyBrightness = state.skyBrightness * envBrightness;
    // 过渡区量化 sunAngle 使 skyKey 在星星 alpha 连续变化时正确失效
    const starsPhase = state.starsEnabled
        ? state.sunAngle > 10
            ? 'h'
            : state.sunAngle < -5
              ? 'l'
              : `t${Math.round(state.sunAngle)}`
        : '';
    _lastProceduralSkyKey = `${state.skyColorTop}|${state.skyColorMid}|${state.skyColorBot}|${effectiveSkyBrightness}|${state.starsEnabled}|${state.starsTexture}|${starsPhase}`;
}

/** 为 PBR 材质创建简单环境立方体贴图（基于天空渐变颜色） */
function createProceduralEnvTexture(state: EnvState, scene: Scene): void {
    // 释放旧贴图
    if (_proceduralEnvTexture) {
        _proceduralEnvTexture.dispose();
        _proceduralEnvTexture = null;
    }

    const size = 32; // 小尺寸足够，环境贴图不需要高分辨率
    const topColor = col3FromTriple(state.skyColorTop);
    const midColor = col3FromTriple(state.skyColorMid);
    const botColor = col3FromTriple(state.skyColorBot);
    const brightness = state.skyBrightness * (state.globalBrightness ?? 1);

    // 创建 6 个面的像素数据（简单渐变：上=顶色，中=中色，下=底色）
    const faces: Uint8Array[] = [];
    for (let face = 0; face < 6; face++) {
        const data = new Uint8Array(size * size * 4);
        for (let y = 0; y < size; y++) {
            // 根据 y 位置插值颜色
            const t = y / size;
            let r: number, g: number, b: number;
            if (t < 0.5) {
                // 上半：顶色 → 中色
                const lt = t * 2;
                r = (topColor.r * (1 - lt) + midColor.r * lt) * brightness;
                g = (topColor.g * (1 - lt) + midColor.g * lt) * brightness;
                b = (topColor.b * (1 - lt) + midColor.b * lt) * brightness;
            } else {
                // 下半：中色 → 底色
                const lt = (t - 0.5) * 2;
                r = (midColor.r * (1 - lt) + botColor.r * lt) * brightness;
                g = (midColor.g * (1 - lt) + botColor.g * lt) * brightness;
                b = (midColor.b * (1 - lt) + botColor.b * lt) * brightness;
            }
            for (let x = 0; x < size; x++) {
                const idx = (y * size + x) * 4;
                data[idx] = Math.min(255, r * 255);
                data[idx + 1] = Math.min(255, g * 255);
                data[idx + 2] = Math.min(255, b * 255);
                data[idx + 3] = 255;
            }
        }
        faces.push(data);
    }

    // 创建 RawCubeTexture
    _proceduralEnvTexture = new RawCubeTexture(scene, faces, size);
    scene.environmentTexture = _proceduralEnvTexture;
}

// ======== CubeTexture Sky ========

function loadSkyCube(path: string, rotationY: number, intensity: number): void {
    const scene = getScene();
    const ext = path.split('.').pop().toLowerCase();
    const supported = ['hdr', 'dds', 'exr'];
    if (!supported.includes(ext ?? '')) {
        logWarn('sky', `unsupported format .${ext}, falling back to procedural`);
        disposeSky();
        createProceduralSky(envState);
        return;
    }

    const cubeTex = new CubeTexture(
        path,
        scene,
        null,
        false,
        null,
        null,
        (message?: string, exception?: unknown) => {
            logWarn('sky', `loadSkyCube failed: ${message}`, exception);
            disposeSky();
            createProceduralSky(envState);
        }
    );
    cubeTex.rotationY = rotationY;
    scene.environmentTexture = cubeTex;
    scene.environmentIntensity = intensity;
    scene.clearColor = new Color4(0, 0, 0, 1);
    _envSys.sky.skyCubeTexture = cubeTex;
    _lastSkyCubePath = path; // 缓存成功加载的路径，供 applySky 判定是否需重载

    const cam = scene.activeCamera;
    const farZ = cam?.maxZ ?? 10000;
    const diameter = Math.min(20000, Math.max(2000, farZ * 1.8));
    const sphere = MeshBuilder.CreateSphere(
        'envSkyDome',
        { diameter, segments: 32, sideOrientation: Mesh.BACKSIDE },
        scene
    );
    sphere.isPickable = false;
    // 先于体积云（Group -1）渲染，填背景但不写深度，避免挡住云的 alpha 合成
    sphere.renderingGroupId = -2;
    const mat = new StandardMaterial('envSkyDomeMat', scene);
    mat.reflectionTexture = cubeTex;
    mat.reflectionTexture.coordinatesMode = Texture.SKYBOX_MODE;
    mat.diffuseColor = new Color3(0, 0, 0);
    mat.specularColor = new Color3(0, 0, 0);
    mat.disableLighting = true;
    mat.disableDepthWrite = true;
    sphere.material = mat;
    _envSys.sky.skyMesh = sphere;

    // 跟随相机，与云层同心（同 center），确保深度测试正确。
    // Y 同步跟随（见 procedural 分支说明），避免高空/远离原点时露灰底。
    _skyFollowHandle = observe(scene.onBeforeRenderObservable, () => {
        const cam = scene.activeCamera;
        if (!cam) {
            return;
        }
        sphere.position.x = cam.position.x;
        sphere.position.y = cam.position.y;
        sphere.position.z = cam.position.z;
    });
}

// ======== Public API ========

export function disposeSky(): void {
    const scene = getScene();
    // 移除相机跟随观察者，避免泄漏
    _skyFollowHandle = safeDispose(_skyFollowHandle);
    if (_envSys.sky.skyMesh) {
        _envSys.sky.skyMesh.material?.dispose();
        _envSys.sky.skyMesh = safeDispose(_envSys.sky.skyMesh);
    }
    if (_envSys.sky.skyCubeTexture) {
        scene.environmentTexture = null;
        _envSys.sky.skyCubeTexture = safeDispose(_envSys.sky.skyCubeTexture);
    }
    if (_envSys.sky.skyDynamicTex) {
        _envSys.sky.skyDynamicTex = safeDispose(_envSys.sky.skyDynamicTex);
    }
    // 释放程序化环境贴图
    if (_proceduralEnvTexture) {
        scene.environmentTexture = null;
        _proceduralEnvTexture.dispose();
        _proceduralEnvTexture = null;
    }
    _lastProceduralSkyKey = '';
    _lastSkyCubePath = null;
    _disposeSunDisc();
}

export function applySky(state: EnvState): void {
    const scene = getScene();
    ensureEnvUpdateObserver();
    if (state.skyMode === 'color') {
        disposeSky();
        scene.clearColor = new Color4(
            state.skyColorTop[0],
            state.skyColorTop[1],
            state.skyColorTop[2],
            1
        );
        return;
    }

    const mesh = _envSys.sky.skyMesh;

    if (state.skyMode === 'procedural') {
        if (!mesh || !mesh.material) {
            disposeSky();
            createProceduralSky(state);
            return;
        }
        if (mesh.material && mesh.material.getClassName() === 'StandardMaterial') {
            const mat = mesh.material as StandardMaterial;

            const envBrightness = state.globalBrightness ?? 1;
            const effectiveSkyBrightness = state.skyBrightness * envBrightness;
            // 过渡区量化 sunAngle 使 skyKey 在星星 alpha 连续变化时正确失效
            const starsPhase = state.starsEnabled
                ? state.sunAngle > 10
                    ? 'h'
                    : state.sunAngle < -5
                      ? 'l'
                      : `t${Math.round(state.sunAngle)}`
                : '';
            const skyKey = `${state.skyColorTop}|${state.skyColorMid}|${state.skyColorBot}|${effectiveSkyBrightness}|${state.starsEnabled}|${state.starsTexture}|${starsPhase}`;
            if (skyKey === _lastProceduralSkyKey && _envSys.sky.skyDynamicTex) {
                return;
            }
            _lastProceduralSkyKey = skyKey;

            if (_envSys.sky.skyCubeTexture || mat.reflectionTexture) {
                if (_envSys.sky.skyCubeTexture) {
                    scene.environmentTexture = null;
                    _envSys.sky.skyCubeTexture.dispose();
                    _envSys.sky.skyCubeTexture = null;
                }
                mat.reflectionTexture = null;
            }

            mat.emissiveTexture = updateSkyDynamicTexture(state);
            // 同步更新程序化 IBL，使 PBR 材质反射颜色与天空一致
            createProceduralEnvTexture(state, scene);
            return;
        }
        disposeSky();
        createProceduralSky(state);
        return;
    }

    if (state.skyTexture) {
        const intensity = state.iblIntensity * (state.globalBrightness ?? 1);
        // 路径未变：仅更新静态旋转与 IBL 强度，避免重复从磁盘加载 CubeTexture
        // （旋转滑块拖动 / 强度微调场景 —— 修复此前每次 sky key 变更都整图重载的隐患）
        if (
            _lastSkyCubePath === state.skyTexture &&
            _envSys.sky.skyCubeTexture &&
            _envSys.sky.skyMesh
        ) {
            (_envSys.sky.skyCubeTexture as CubeTexture).rotationY = state.skyRotationY;
            getScene().environmentIntensity = intensity;
            return;
        }
        disposeSky();
        loadSkyCube(state.skyTexture, state.skyRotationY, intensity);
    } else {
        disposeSky();
    }
}

import { Scene } from '@babylonjs/core/scene';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { ColorCurves } from '@babylonjs/core/Materials/colorCurves';
import { Vector3, Matrix, Vector2 } from '@babylonjs/core/Maths/math.vector';
import { Texture } from '@babylonjs/core/Materials/Textures/texture';
import { DynamicTexture } from '@babylonjs/core/Materials/Textures/dynamicTexture';
import { observe, type ObserverHandle } from '@/core/observer-handle';
import { safeDispose } from '@/core/dispose-helpers';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { MeshBuilder } from '@babylonjs/core/Meshes/meshBuilder';
import { ShaderMaterial } from '@babylonjs/core/Materials/shaderMaterial';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import { DefaultRenderingPipeline } from '@babylonjs/core/PostProcesses/RenderPipeline/Pipelines/defaultRenderingPipeline';

import { Plane } from '@babylonjs/core/Maths/math.plane';

// P3-fix: 水面镜像反射平面复用，避免每帧 new Plane 造成的 GC 压力
const _waterMirrorPlane = new Plane(0, 1, 0, 0);
import { EnvState, envState } from '@/core/config';
import { col3FromTriple } from '@/core/color-helpers';
import { _envSys, getScene, effectiveGroundSize } from './_shared/env-context';
import { PlanarReflection, registerReflectionSurface } from './planar-reflection';
import { getPlanarQualityOverride } from './env-reflection';
import { createCanvasTexture } from './_shared/env-texture';
import { causticsController } from './env-caustics';
import { valueNoise } from '@/core/math/hash-noise';
import { registerEnvCallback, registerEnvDtTickCallback } from './_bridge/env-dispatcher';
import { getEnvKeys } from '@/core/env-state-schema';
import { clamp01 } from '@/core/clamp';
import { logWarn } from '@/core/logger';

import WATER_VERT_SRC from './shaders/water.vert.glsl?raw';
import WATER_FRAG_SRC from './shaders/water.frag.glsl?raw';

// ======== 常量定义 ========
const WATER_BASE_SIZE = 60; // 水面基准尺寸（世界单位），通过缩放调整最终大小
const LOD_HIGH_DISTANCE = 30; // LOD 切换距离（近）
const LOD_LOW_DISTANCE = 80; // LOD 切换距离（远）
const UNDERWATER_TRANSITION_SPEED = 0.8; // 水下过渡速度（秒）

// 波方向偏移（Gerstner 波 4 层）— 四风归一后加宽偏移，制造交叉浪
const WAVE_DIR_OFFSETS: [number, number, number, number] = [0, 0.6, -0.4, 1.2];
// 涟漪参数
const RIPPLE_MIN_RADIUS = 0.1;
const RIPPLE_MIN_SPEED = 0.1;
const RIPPLE_INFINITY_LIFE = 9999;
// deltaTime 钳制上限（秒），防止切后台返回时跳变
const DT_CLAMP_MAX = 0.1;
// 水下后处理色调：蓝绿色相（colorCurves 色相旋转滤镜，保亮度，替代原 FOGMODE_EXP2 雾）
const UNDERWATER_TINT_HUE = 200;

// ======== 水下状态（供 Env Update Observer 和 disposeWater 使用）========
// 私有化 + getter 导出，消除导出可变绑定（审核 P2-4）
let _underwaterActive = false;
let _underwaterSavedDirIntensity = 1;
let _underwaterSavedHemiIntensity = 0.6;
let _underwaterTransitionProgress = 0;
let _underwaterTarget = false;

/** 相机是否处于水下（雾效接管中）。 */
export function isUnderwaterActive(): boolean {
    return _underwaterActive;
}

// ======== 波方向计算（风向联动）========
/**
 * 根据风向计算 4 层 Gerstner 波的 vec2 方向数组。
 * 主方向与风向对齐，其余 3 层以微小偏移分散，保持波浪自然丰富度。
 * 风向为零或无效时回退到默认的均匀分布方向。
 */
export function computeWaveDirs(windDir: [number, number, number]): number[] {
    // Float32Array → number[] 因为 Babylon setArray2 需要 number[]
    const arr: number[] = new Array(8).fill(0); // 4 × vec2
    if (!windDir || (windDir[0] === 0 && windDir[2] === 0)) {
        // 零风向时回退到默认方向（Z+），避免运行时 throw 导致水面崩溃
        logWarn('env-water', '零风向，回退到默认方向 [0,0,1]');
        windDir = [0, 0, 1];
    }
    // 从 windDirection 计算风向角（XZ 平面）
    const angle = Math.atan2(windDir[0], windDir[2]);
    // 4 个波方向：主方向对齐风向，其余偏移以保持波面复杂度
    const offsets = WAVE_DIR_OFFSETS;
    for (let i = 0; i < 4; i++) {
        const a = angle + offsets[i];
        arr[i * 2] = Math.sin(a);
        arr[i * 2 + 1] = Math.cos(a);
    }
    return arr;
}

// === LOD 水面：记录所有 LOD 子网格（兄弟根网格），用于同步缩放/位置和手动可见性控制 ===
let _waterLODs: Mesh[] = [];
let _activeWaterLOD = -1; // 手动 LOD 当前层级：-1=未初始化, 0=high, 1=mid, 2=low
let _waterPhase = 0; // 累计波相位，避免调节波速时相位跳变
let _waterWaveSpeed = 1; // 当前波速，供每帧相位累加使用

// Gerstner 波参数（与 water.vert.glsl 中 WAVE_SPEED/WAVE_FREQ 保持一致）
// ADR-115 P5: 层 0/1 频率下调（0.15/0.2 → 0.07/0.11），拉长波长制造连绵涌浪
// ADR-115 二轮增强: WAVE_SPEED 在 uDispersionEnabled=1 时被 ω=sqrt(g·k) 覆盖（见 vert shader）
const _GERSTNER_WAVE_FREQ = [0.07, 0.11, 0.25, 0.3] as const;
const _GERSTNER_WAVE_SPEED = [0.7, 0.9, 0.5, 1.2] as const;

/**
 * ADR-115 P2: 动态计算细节法线滚动速度倍率。
 * 基于 Gerstner 波相位的瞬时速度（WAVE_SPEED/WAVE_FREQ）同步法线纹理 UV 滚动，
 * 保证大波高时法线滚动快、小波高时滚动慢，与顶点波形运动一致。
 * @param waveSpeedMultiplier 当前波速倍率（来自 state.waterAnimSpeed，默认 1.0）
 * @returns [speed1, speed2] 大/小尺度法线层的滚动倍率（正值沿风向）
 */
function computeDetailNormalSpeeds(waveSpeedMultiplier = 1): [number, number] {
    // 第 0 层（大波组代表层）：speed/freq，决定大尺度法线滚动基准
    const baseSpeed = _GERSTNER_WAVE_SPEED[0] / _GERSTNER_WAVE_FREQ[0]; // ≈ 10（P5 后）
    // 大尺度层：与主波同速；小尺度层：稍慢（反向交错感）
    const speed1 = baseSpeed * waveSpeedMultiplier; // 沿风向滚动
    const speed2 = baseSpeed * waveSpeedMultiplier * 0.55; // 反向，0.55:1 比例（两层不重复）
    return [speed1, speed2];
}
let _waterUpdateObserver: ObserverHandle | null = null;
let _waterScene: Scene | null = null;

// === 平面反射（统一平面反射引擎，ADR-092）===
// 水面用 screenSpace 模式：RenderTargetTexture + 镜像相机（_worldMatrix 镜像矩阵）+ ShaderMaterial 屏空采样。
// 互斥可恢复：启用地面反射时本引擎自动停用，地面关闭后由协调器触发重建（关地即开水）。
const waterReflection = new PlanarReflection({
    name: 'water',
    mode: 'screenSpace',
    resolutionMap: { high: 2048, medium: 1024, low: 512, off: 0 },
    getQuality: (s) => {
        // ADR-151: reflectionMode 全局覆盖（none→强关、planar→拔高到至少 low）
        const override = getPlanarQualityOverride(s);
        if (override === 'off') {
            return 'off';
        }
        let q: string;
        // reflectionQuality 显式指定（含 'off'）直接返回；仅当值不在合法列表时 fallback
        if (['high', 'medium', 'low', 'off'].includes(s.reflectionQuality)) {
            q = s.reflectionQuality;
        } else {
            const map: Record<string, string> = { high: 'high', medium: 'medium', low: 'low' };
            q = map[s.qualityProfile] ?? 'off';
        }
        if (override === 'low' && q === 'off') {
            return 'low';
        }
        return q;
    },
    getBlend: (s) => s.planarReflectionBlend ?? 0.5,
    getSurfaceLevel: (s) => s.waterLevel,
    getMirrorCameraMatrix: (s, scene) => {
        const cam = scene.activeCamera;
        if (!cam) {
            return null;
        }
        // P3-fix: 真正复用 Plane 对象，每帧仅更新 d 参数，避免 GC 压力
        _waterMirrorPlane.normal.set(0, 1, 0);
        _waterMirrorPlane.d = -s.waterLevel;
        return Matrix.Reflection(_waterMirrorPlane).multiply(cam.getWorldMatrix());
    },
    predicate: (mesh, level) =>
        !mesh.name.startsWith('envWater') &&
        mesh.isEnabled() &&
        mesh.getBoundingInfo().boundingBox.maximumWorld.y >= level,
    getMaterial: () => _envSys.water.material as ShaderMaterial | null,
    mount: (rt) => {
        const mat = _envSys.water.material as ShaderMaterial | null;
        if (mat) {
            if (rt) {
                mat.setTexture('reflectionTexture', rt as Texture);
            } else {
                // ADR-### P1: setTexture(name, null) 在 Babylon 中直接赋值 _textures[name]=null，
                // 导致 isReady() for…in 遍历时 null.isReady() 崩溃。改用 removeTexture 彻底删除 key。
                (mat as ShaderMaterial).removeTexture('reflectionTexture');
            }
        }
    },
    setBlend: (b) => {
        const mat = _envSys.water.material as ShaderMaterial | null;
        if (mat) {
            mat.setFloat('planarReflectionBlend', b);
        }
    },
    skipWhenUnderwater: true,
    onDisable: () => {
        // 停用时保留 RT（blend=0 时隐藏反射但不销毁 RT），避免 blend 从 0→正数时闪烁
        // 仅在 quality 真正变为 off 时才销毁 RT（由 disable() 处理）
    },
});
registerReflectionSurface('water', waterReflection, () =>
    waterReflection.update(envState, getScene())
);

// ======== 涟漪系统（Interaction Ripples）========
// 最大 slot 数（与 shader 循环上限 1024 对齐）；有效使用数由 envState.waterRippleSlots 控制
const MAX_RIPPLES = 1024;
interface RippleSource {
    position: Vector3;
    radius: number;
    strength: number;
    speed: number;
    life: number;
    maxLife: number;
}
let _ripples: RippleSource[] = [];

// ======== 水下灯光衰减（微降，保留亮度；色调由后处理 colorCurves 负责）========
const UNDERWATER_DIR_INTENSITY_SCALE = 0.8;
const UNDERWATER_HEMI_INTENSITY_SCALE = 0.9;

/** slot 数由水效面板控制，确保每秒碰撞率 × rippleLife 可填满启用 slot */
function _maxSlots(): number {
    return Math.min(MAX_RIPPLES, Math.max(16, Math.round(envState.waterRippleSlots ?? 256)));
}

export function addRipple(pos: Vector3, radius = 5, strength = 0.5, speed = 2, maxLife = 3): void {
    const maxSlots = _maxSlots();
    // 1. 找已死亡的 slot（直接复用）
    for (let i = 0; i < _ripples.length; i++) {
        if (_ripples[i].life <= 0) {
            _fillSlot(i, pos, radius, strength, speed, maxLife);
            return;
        }
    }
    // 2. 未满 → push 新 slot
    if (_ripples.length < maxSlots) {
        const idx = _ripples.length;
        _ripples.push({
            position: new Vector3(0, 0, 0),
            radius: 0,
            strength: 0,
            speed: 0,
            life: 0,
            maxLife: 0,
        });
        _fillSlot(idx, pos, radius, strength, speed, maxLife);
        return;
    }
    // 3. 全活 → 替换寿命最短的（等效缩短其动画，适应高密度场景）
    let oldest = 0;
    for (let i = 1; i < _ripples.length; i++) {
        if (_ripples[i].life < _ripples[oldest].life) {
            oldest = i;
        }
    }
    _fillSlot(oldest, pos, radius, strength, speed, maxLife);
}

function _fillSlot(
    idx: number,
    pos: Vector3,
    radius: number,
    strength: number,
    speed: number,
    maxLife: number
): void {
    const r = _ripples[idx];
    r.position.copyFrom(pos);
    r.radius = Math.max(RIPPLE_MIN_RADIUS, radius);
    r.strength = clamp01(strength);
    r.speed = Math.max(RIPPLE_MIN_SPEED, speed);
    r.life = maxLife > 0 ? maxLife : RIPPLE_INFINITY_LIFE;
    r.maxLife = maxLife;
}

export function clearRipples(): void {
    _ripples = [];
}

// ======== 地面涟漪系统（Ground Ripples）========
// 与水面涟漪结构相同，但渲染到地面材质的 bumpTexture（法线扰动）
// 由 env-particles 在粒子落地时触发，模拟雨滴/落叶触地效果
const GROUND_RIPPLE_SIZE = 256; // 地面涟漪纹理尺寸
const GROUND_RIPPLE_MAX = 64; // 最大同时活跃数
let _groundRipples: RippleSource[] = [];
let _groundRippleTex: DynamicTexture | null = null;
let _groundRippleScene: Scene | null = null;
let _groundRippleDirty = false;

// 地面几何提供者（由 env-ground 注入，避免 env-water→env-ground 循环依赖）。
// 用于将涟漪世界坐标映射到地面 mesh 的 UV 空间。默认原点居中、尺寸 60。
let _groundGeomProvider: () => { centerX: number; centerZ: number; size: number } = () => ({
    centerX: 0,
    centerZ: 0,
    size: 60,
});

/** 注入地面几何提供者（env-ground 在模块初始化时调用一次） */
export function setGroundGeometryProvider(
    provider: () => { centerX: number; centerZ: number; size: number }
): void {
    _groundGeomProvider = provider;
}

/** 添加地面涟漪（粒子落地时调用） */
export function addGroundRipple(
    pos: Vector3,
    radius = 3,
    strength = 0.3,
    speed = 1.5,
    maxLife = 2
): void {
    // 复用死亡 slot
    for (let i = 0; i < _groundRipples.length; i++) {
        if (_groundRipples[i].life <= 0) {
            _fillGroundRippleSlot(i, pos, radius, strength, speed, maxLife);
            return;
        }
    }
    // 未满 → push
    if (_groundRipples.length < GROUND_RIPPLE_MAX) {
        const idx = _groundRipples.length;
        _groundRipples.push({
            position: new Vector3(0, 0, 0),
            radius: 0,
            strength: 0,
            speed: 0,
            life: 0,
            maxLife: 0,
        });
        _fillGroundRippleSlot(idx, pos, radius, strength, speed, maxLife);
        return;
    }
    // 全活 → 替换寿命最短的
    let oldest = 0;
    for (let i = 1; i < _groundRipples.length; i++) {
        if (_groundRipples[i].life < _groundRipples[oldest].life) {
            oldest = i;
        }
    }
    _fillGroundRippleSlot(oldest, pos, radius, strength, speed, maxLife);
}

function _fillGroundRippleSlot(
    idx: number,
    pos: Vector3,
    radius: number,
    strength: number,
    speed: number,
    maxLife: number
): void {
    const r = _groundRipples[idx];
    r.position.copyFrom(pos);
    r.radius = Math.max(0.5, radius);
    r.strength = clamp01(strength);
    r.speed = Math.max(0.5, speed);
    r.life = maxLife > 0 ? maxLife : 3;
    r.maxLife = maxLife;
    _groundRippleDirty = true;
}

export function clearGroundRipples(): void {
    _groundRipples = [];
    _groundRippleDirty = true;
}

/** 释放地面涟漪纹理与状态（由 disposeWater / disposeGround 调用，防止 GPU 纹理泄漏） */
export function disposeGroundRipples(): void {
    _groundRippleTex = safeDispose(_groundRippleTex);
    _groundRippleScene = null;
    _groundRipples = [];
    _groundRippleDirty = false;
}

/** 获取地面涟漪纹理（供 env-ground 设置到 bumpTexture） */
export function getGroundRippleTexture(scene: Scene): Texture | null {
    if (!_groundRippleTex || _groundRippleScene !== scene) {
        // 场景变更时释放旧纹理
        if (_groundRippleTex && _groundRippleScene !== scene) {
            _groundRippleTex.dispose();
        }
        _groundRippleScene = scene;
        const tex = new DynamicTexture(
            'groundRippleTex',
            { width: GROUND_RIPPLE_SIZE, height: GROUND_RIPPLE_SIZE },
            scene,
            false
        );
        tex.name = 'groundRippleTex';
        _groundRippleTex = tex;
        _groundRippleDirty = true;
    }
    return _groundRippleTex;
}

/** 是否有活跃的地面涟漪（供 env-ground 判断是否需要叠加 ripple 法线纹理） */
export function hasActiveGroundRipples(): boolean {
    return _groundRipples.length > 0;
}

/** 每帧更新地面涟漪纹理（由 env-ground 的 update observer 驱动） */
export function updateGroundRipples(dt: number): void {
    if (_groundRipples.length === 0) {
        return;
    }

    // 更新生命
    let anyAlive = false;
    for (const r of _groundRipples) {
        if (r.life <= 0) {
            continue;
        }
        r.life -= dt;
        anyAlive = true;
    }
    if (!anyAlive) {
        _groundRipples = [];
        return;
    }

    if (!_groundRippleDirty && _groundRipples.every((r) => r.life <= 0)) {
        return;
    }
    _groundRippleDirty = false;

    // 绘制涟漪法线扰动到 DynamicTexture 的 canvas
    const rippleTex = _groundRippleTex;
    if (!rippleTex) {
        return;
    }
    const ctx = rippleTex.getContext();
    if (!ctx) {
        return;
    }

    const S = GROUND_RIPPLE_SIZE;
    ctx.clearRect(0, 0, S, S);
    // 默认法线朝上 (128,128,255) = 无扰动
    ctx.fillStyle = 'rgb(128,128,255)';
    ctx.fillRect(0, 0, S, S);

    // 地面 mesh 几何：将涟漪世界坐标映射到纹理 UV（原点/尺寸由 env-ground 注入）
    const geom = _groundGeomProvider();
    const safeSize = geom.size || 60;
    const halfSize = safeSize / 2;
    // 世界单位 → 像素比例（用于半径换算，使涟漪大小与地面尺度一致）
    const worldToPixel = S / safeSize;

    for (const r of _groundRipples) {
        if (r.life <= 0) {
            continue;
        }
        const lifeRatio = r.life / (r.maxLife || 1);
        const alpha = Math.max(0, lifeRatio);
        const currentRadius = r.radius * (1 + (1 - lifeRatio) * 0.5);
        const pixelRadius = Math.max(2, currentRadius * worldToPixel);

        // 世界坐标 → UV → 像素中心。地面 mesh 中心对应纹理中心。
        const u = (r.position.x - geom.centerX) / geom.size + 0.5;
        const v = (r.position.z - geom.centerZ) / geom.size + 0.5;
        // 落在地面范围外的涟漪跳过绘制（含半径外扩容差）
        if (
            r.position.x < geom.centerX - halfSize - currentRadius ||
            r.position.x > geom.centerX + halfSize + currentRadius ||
            r.position.z < geom.centerZ - halfSize - currentRadius ||
            r.position.z > geom.centerZ + halfSize + currentRadius
        ) {
            continue;
        }
        const px = u * S;
        const py = v * S;

        // 径向渐变法线扰动：中心法线偏转最大，向外衰减
        const grad = ctx.createRadialGradient(px, py, 0, px, py, pixelRadius);
        // 涟漪中心：法线偏转（r=偏红, g=偏绿, b=255）
        const rStrength = r.strength * alpha;
        grad.addColorStop(0, `rgb(${128 + rStrength * 80}, ${128}, 255)`);
        grad.addColorStop(0.5, `rgb(128, ${128 + rStrength * 60}, 255)`);
        grad.addColorStop(1, 'rgb(128,128,255)');
        ctx.fillStyle = grad;
        ctx.fillRect(px - pixelRadius, py - pixelRadius, pixelRadius * 2, pixelRadius * 2);
    }

    // 更新 texture
    if (_groundRippleTex) {
        _groundRippleTex.update();
    }
}

// ======== 焦散系统已迁移至 env-caustics.ts controller（共享给水底地面）========

// ADR-115 P1: 高频法线细节纹理（程序化生成，单例，不随水色变化）
// P1 增强：1024×1024 + 6 层 octave + 波峰锐化 → 高光密度 + 锐度提升
let _detailNormalTexture: Texture | null = null;
let _detailNormalScene: Scene | null = null;
const DETAIL_NORMAL_TEX_SIZE = 1024;

// ======== ADR-115 P1: 程序化法线细节纹理 ========
function regenerateDetailNormalTexture(scene: Scene): void {
    const S = DETAIL_NORMAL_TEX_SIZE;
    const draw = (ctx: CanvasRenderingContext2D, s: number) => {
        const imgData = ctx.createImageData(s, s);
        const data = imgData.data;
        const heights = new Float32Array(s * s);

        // P1 增强：6 层 octave（原来 4 层）→ 高频细节更密集，波光更多
        for (let y = 0; y < s; y++) {
            for (let x = 0; x < s; x++) {
                let h = 0,
                    amp = 1,
                    freq = 1;
                for (let oct = 0; oct < 6; oct++) {
                    h += valueNoise((x * freq) / s, (y * freq) / s) * amp;
                    amp *= 0.5;
                    freq *= 2;
                }
                // P1 增强：幂函数锐化（原来线性），波峰更尖，高光更亮
                h = Math.pow(h, 0.8);
                heights[y * s + x] = h;
            }
        }

        // 中心差分求法线，编码到 RGB
        for (let y = 0; y < s; y++) {
            for (let x = 0; x < s; x++) {
                const xl = heights[y * s + ((x - 1 + s) % s)];
                const xr = heights[y * s + ((x + 1) % s)];
                const yl = heights[((y - 1 + s) % s) * s + x];
                const yr = heights[((y + 1) % s) * s + x];
                const nx = (xl - xr) * 0.5;
                const ny = (yl - yr) * 0.5;
                const nz = 1.0;
                const len = Math.sqrt(nx * nx + ny * ny + nz * nz);
                const i = (y * s + x) * 4;
                data[i] = Math.floor(((nx / len) * 0.5 + 0.5) * 255);
                data[i + 1] = Math.floor(((ny / len) * 0.5 + 0.5) * 255);
                data[i + 2] = Math.floor(((nz / len) * 0.5 + 0.5) * 255);
                data[i + 3] = 255;
            }
        }
        ctx.putImageData(imgData, 0, 0);
    };

    _detailNormalTexture = safeDispose(_detailNormalTexture);
    _detailNormalTexture = createCanvasTexture({
        size: S,
        draw,
        scene,
        name: 'waterDetailNormal',
        wrap: 'wrap',
    });
    _detailNormalScene = scene;
}

function ensureDetailNormalTexture(scene: Scene): Texture {
    if (_detailNormalTexture && _detailNormalScene === scene) {
        return _detailNormalTexture;
    }
    regenerateDetailNormalTexture(scene);
    return _detailNormalTexture!;
}

// ======== Water System ========

/**
 * 水下雾状态：自定义 ShaderMaterial 不参与 Babylon 的 scene.fog，
 * 因此由 underwaterFogController 在穿越水面时把水下雾参数推给水面，
 * 让水面与地面/角色用同一套雾（同起始距离 + 同雾色），视觉统一。
 * enabled=0 时水面不做水下雾混合（出水/陆地）。
 */
let _underwaterFog = {
    enabled: 0,
    color: new Color3(0.35, 0.58, 0.72),
    start: 40,
    end: 500,
};

// 复用的焦散 UV 偏移向量（每帧由 causticsController 推进的纹理 uOffset/vOffset 注入，避免每帧分配）
const _causticOffset = new Vector2(0, 0);

/** 由水下雾控制器同步水下雾参数到水面材质（含材质重建后的恢复由 _syncWaterUniforms 负责）。 */
export function setUnderwaterFog(
    enabled: boolean,
    color: Color3,
    start: number,
    end: number
): void {
    _underwaterFog = { enabled: enabled ? 1 : 0, color: color.clone(), start, end };
    const mat = _envSys.water.material as ShaderMaterial | null;
    if (mat) {
        mat.setFloat('uUnderwater', _underwaterFog.enabled);
        mat.setColor3('uUnderwaterFogColor', _underwaterFog.color);
        mat.setFloat('uUnderwaterFogStart', start);
        mat.setFloat('uUnderwaterFogEnd', end);
    }
}

/**
 * 同步水面材质的全部 uniform 参数（非破坏性，不销毁/重建材质）。
 * 由 createWater 在惰性路径和首次创建后调用。
 */
function _syncWaterUniforms(state: EnvState, scene: Scene): void {
    const mat = _envSys.water.material as ShaderMaterial | null;
    const mesh = _envSys.water.mesh;
    if (!mat || !mesh) {
        return;
    }

    // ——— 基础参数 ———
    mat.setFloat('waveHeight', state.waterWaveHeight);
    // ADR-115 P4 + ADR-211 Part3：大波受 bigWaveEnabled 门控，关闭时送 0 振幅（水面趋于平静镜面）
    mat.setFloat(
        'bigWaveHeight',
        (state.bigWaveEnabled ?? true) ? (state.bigWaveHeight ?? 1.0) : 0
    );
    // ADR-115 P4 + 功能开关试点：小波受 smallWaveEnabled 门控，关闭时送 0 振幅（水面呈纯净反射面）
    mat.setFloat(
        'smallWaveHeight',
        (state.smallWaveEnabled ?? true) ? (state.smallWaveHeight ?? 1.0) : 0
    );
    _waterWaveSpeed = (state.waterAnimSpeed ?? 1) * 1.0;
    // wavePhase 由 _waterUpdateCallback 每帧统一写入，此处无需重复赋值
    // ADR-115 二轮增强：色散关系开关（0=旧硬编码 ω 零回归，1=物理色散 ω=sqrt(g·k)）
    mat.setFloat('uDispersionEnabled', state.waterDispersionEnabled ? 1 : 0);
    mat.setColor3('waterColor', col3FromTriple(state.waterColor));
    mat.setFloat('waterTransparency', state.waterTransparency);
    mat.setFloat('waterLevel', state.waterLevel);
    mat.setInt('uWaterFlip', state.waterFlipEnabled ? 1 : 0);

    const hasEnv = !!scene.environmentTexture;
    // envIntensity 随日照微缩放（与 per-frame 同公式）：高底线保留夕阳暖色
    const _initDl = scene.getLightByName('dir') as DirectionalLight | null;
    const _initSunI = _initDl ? _initDl.intensity : 0.4;
    mat.setFloat('envIntensity', hasEnv ? Math.max(0.6, Math.min(1, _initSunI * 0.4 + 0.6)) : 0);
    if (hasEnv && scene.environmentTexture) {
        mat.setTexture('envTexture', scene.environmentTexture);
    }

    // ——— 灯光 ———
    const dirLight = scene.getLightByName('dir') as DirectionalLight | null;
    if (dirLight) {
        mat.setVector3('lightDir', dirLight.direction);
        mat.setColor3('lightColor', dirLight.diffuse);
        mat.setFloat('lightIntensity', dirLight.intensity);
    } else {
        mat.setVector3('lightDir', new Vector3(-0.5, -1, -0.5));
        mat.setColor3('lightColor', new Color3(1, 1, 1));
        mat.setFloat('lightIntensity', 0.5);
    }
    mat.setFloat('ambientIntensity', 0.3);

    // ——— 焦散（共享 env-caustics controller 唯一实例，UV 滚动由 controller 推）——
    const causticTex = causticsController.getTexture(scene);
    mat.setTexture('uCausticTex', causticTex);
    // ADR-211 Part3：焦散受 causticEnabled 门控，关闭时送 0 强度（水底无光斑）
    mat.setFloat('uCausticIntensity', (state.causticEnabled ?? true) ? state.causticIntensity : 0);
    // 焦散 UV 偏移（联动 causticScrollX/Y，经 causticsController 推 uOffset/vOffset）
    mat.setVector2('uCausticOffset', _causticOffset.set(causticTex.uOffset, causticTex.vOffset));

    // ——— ADR-115 P1: 高频法线扰动层 + Sun Glitter（波浪联动）——

    const detailNormalTex = ensureDetailNormalTexture(scene);
    mat.setTexture('uDetailNormalTex', detailNormalTex);
    mat.setFloat('uDetailNormalStrength', state.waterNormalStrength);
    // 波纹方格尺度：tile 周期 = 1/tiling 世界单位
    // tiling1=3.0 → 细尺度波纹单元 ≈0.33 单位（60 单位水面重复 180 次）
    // tiling2=6.0 → 高频微纹单元 ≈0.17 单位（重复 360 次）；两层保持 2:1 比例
    // 原 0.5/1.5 单元过大（2/0.67 单位），高频扰动不可见
    mat.setFloat('uDetailNormalTiling1', 3.0);
    mat.setFloat('uDetailNormalTiling2', 6.0);
    // P2 修复：删除 dead code，改为动态计算速度（与 Gerstner 波相位同步）
    const waveAnimSpeed = state.waterAnimSpeed ?? 1;
    const [speed1, speed2] = computeDetailNormalSpeeds(waveAnimSpeed);
    mat.setFloat('uDetailNormalSpeed1', speed1);
    mat.setFloat('uDetailNormalSpeed2', speed2);
    mat.setFloat('uGlintStrength', state.waterGlintStrength);
    mat.setFloat('uGlintPower', 96);
    mat.setFloat('uGlintScale', 80.0);
    mat.setFloat('uGlintSpeed', 2.0);

    // ——— ADR-115 P5: 低频滚动法线层（大尺度滚动光带）——
    mat.setFloat('uLowFreqNormalTiling', 0.04);
    mat.setFloat('uLowFreqNormalStrength', state.lowFreqNormalStrength ?? 0.15);
    mat.setFloat('uLowFreqNormalSpeed', 0.05);

    // ——— ADR-115 P3: 地平线淡出 + 天空-水面颜色联动 ———
    // 天空基准色：优先 skyColorBot，fallback waterFogColor
    const skyBot = state.skyColorBot ?? state.waterFogColor;
    mat.setVector3('uSkyBlendColor', new Vector3(skyBot[0], skyBot[1], skyBot[2]));
    mat.setFloat('uSkyColorBlend', state.waterSkyColorBlend ?? 0);
    // 地平线淡出距离按生效地面尺寸自动计算（无限地面时同步推到 2000，与地面延伸对齐）
    const ws = effectiveGroundSize(state.groundSize, state.groundInfiniteEnabled ?? false);
    mat.setFloat('uHorizonFade', state.waterHorizonFade ?? 0);
    mat.setFloat('uHorizonStart', ws * 0.7);
    mat.setFloat('uHorizonEnd', ws * 0.95);
    // 地平线融合色：优先 skyColorBot，fallback waterFogColor
    mat.setVector3('uHorizonColor', new Vector3(skyBot[0], skyBot[1], skyBot[2]));

    // ——— 高级参数（从 EnvState 读取，持久化）———
    mat.setFloat('fresnelBias', state.fresnelBias);
    mat.setFloat('fresnelPower', state.fresnelPower);
    mat.setFloat('diffuseStrength', state.diffuseStrength);
    mat.setFloat('ambientStrength', state.ambientStrength);
    mat.setFloat('rippleNormalStrength', state.rippleNormalStrength);
    mat.setFloat('rippleGlintStrength', state.rippleGlintStrength);
    mat.setVector3(
        'causticColor1',
        new Vector3(state.causticColor1[0], state.causticColor1[1], state.causticColor1[2])
    );
    mat.setVector3(
        'causticColor2',
        new Vector3(state.causticColor2[0], state.causticColor2[1], state.causticColor2[2])
    );
    mat.setFloat('fresnelAlphaInfluence', state.fresnelAlphaInfluence);

    // ——— 泡沫系统（foamEnabled=false 零回归：foamIntensity 送 0，mix 因子为 0）———
    const foamOn = state.foamEnabled ?? false;
    mat.setFloat('foamThreshold', state.foamThreshold);
    mat.setFloat('foamIntensity', foamOn ? state.foamIntensity : 0);
    mat.setFloat('foamOpacity', state.foamOpacity);
    mat.setFloat('foamTransitionRange', state.foamTransitionRange);
    mat.setColor3('foamColor', col3FromTriple(state.foamColor));
    mat.setFloat('uFoamNoiseStrength', foamOn ? state.foamNoiseStrength : 0);

    mat.setColor3('waterFogColor', col3FromTriple(state.waterFogColor));
    mat.setFloat('waterFogStart', state.waterFogStart);
    mat.setFloat('waterFogEnd', state.waterFogEnd);
    mat.setFloat('waterFogOpacityInfluence', state.waterFogOpacityInfluence);

    // ——— 水下雾（与 scene.fog 同源；ShaderMaterial 不参与 Babylon fog，需手动注入）———
    // 入水时由 underwaterFogController 调 setUnderwaterFog 改写 _underwaterFog；
    // 此处每帧/重建时兜底写入，保证材质重建后水下雾参数不丢失。
    mat.setFloat('uUnderwater', _underwaterFog.enabled);
    mat.setColor3('uUnderwaterFogColor', _underwaterFog.color);
    mat.setFloat('uUnderwaterFogStart', _underwaterFog.start);
    mat.setFloat('uUnderwaterFogEnd', _underwaterFog.end);

    // ——— 波方向（风向联动）———
    const windDirs = computeWaveDirs(state.windDirection);
    mat.setArray2('uWindDir', windDirs);
    // 风速调制波幅度（0 级风时 0.3 倍平静海面，10 级风时 1.8 倍汹涌涌浪）
    // windEnabled 守卫：对齐其他三系统（粒子/Bullet/云）行为，风关则浪静（wind-physics-fix P2）
    const effectiveWindSpeed = state.windEnabled ? state.windSpeed : 0;
    mat.setFloat('uWindSpeed', effectiveWindSpeed);
    // 细节法线滚动方向：取 Gerstner 主波（第一波）风向
    mat.setVector3('uDetailWindDir', new Vector3(windDirs[0], windDirs[1], 0));

    // ——— 涟漪数组（初始化为空）———
    mat.setArray4('uRipplePosRad', new Array(MAX_RIPPLES * 4).fill(0));
    mat.setArray4('uRippleStrSpdLife', new Array(MAX_RIPPLES * 4).fill(0));
    mat.setInt('uRippleCount', 0);

    // ——— 平面反射（ADR-062）———
    mat.setFloat('planarReflectionBlend', state.planarReflectionBlend ?? 0.5);
}

// ══════════════════════════════════════════════════════════════
// 平面反射（ADR-062 P1）：委托统一平面反射引擎（ADR-092）
// ══════════════════════════════════════════════════════════════

/** 初始化/更新水面平面反射：委托给统一引擎（创建 RT、镜像相机、挂载、互斥）。 */
function _setupMirrorRT(scene: Scene, state: EnvState): void {
    waterReflection.update(state, scene);
}

/**
 * 更新水面网格的位置和缩放（非破坏性）。所有 LOD 层同步变换。
 */
function _updateWaterMesh(state: EnvState): void {
    const scale = Math.max(
        1,
        effectiveGroundSize(state.groundSize, state.groundInfiniteEnabled ?? false) /
            WATER_BASE_SIZE
    );
    const rotX = state.waterFlipEnabled ? Math.PI : 0;
    const meshes: Mesh[] = [];
    if (_envSys.water.mesh) {
        meshes.push(_envSys.water.mesh);
    }
    meshes.push(..._waterLODs);
    for (const m of meshes) {
        m.position.y = state.waterLevel;
        m.scaling = new Vector3(scale, 1, scale);
        m.rotation.x = rotX;
    }
}

/**
 * 按相机到水面的距离选择 LOD 层级（纯函数，便于单测）。
 * 0=近景高精度, 1=中景, 2=远景低精度。
 */
export function selectWaterLOD(distance: number): 0 | 1 | 2 {
    if (distance > LOD_LOW_DISTANCE) {
        return 2;
    }
    if (distance > LOD_HIGH_DISTANCE) {
        return 1;
    }
    return 0;
}

/**
 * 按相机到水面的距离手动切换 LOD 可见性（仅 0/1/2 三层中恰好一层 enabled），
 * 规避 Babylon addLODLevel 的父子/兄弟重复渲染问题。仅当层级变化时才 setEnabled。
 */
export function _applyWaterLOD(scene: Scene): void {
    const high = _envSys.water.mesh;
    if (!high || _waterLODs.length < 2) {
        return;
    }
    const cam = scene.activeCamera;
    if (!cam) {
        return;
    }
    const dist = Vector3.Distance(cam.globalPosition, high.getAbsolutePosition());
    const level = selectWaterLOD(dist);
    if (level === _activeWaterLOD) {
        return;
    }
    _activeWaterLOD = level;
    high.setEnabled(level === 0);
    _waterLODs[0].setEnabled(level === 1);
    _waterLODs[1].setEnabled(level === 2);
}

