    ],
};

const PHYSICS_CAT_PATTERNS: [PhysicsCategory, RegExp][] = Object.entries(PHYSICS_CAT_RULES).map(
    ([cat, keywords]) => [cat as PhysicsCategory, new RegExp(keywords.join('|'), 'i')]
);

function _classifyBonePhysics(name: string): PhysicsCategory | null {
    const l = name.toLowerCase();
    for (const [cat, re] of PHYSICS_CAT_PATTERNS) {
        if (re.test(l)) {
            return cat;
        }
    }
    return null;
}

function _buildRigidBodyCatMap(mmdModel: RuntimeModel): Map<number, PhysicsCategory> {
    const bones = mmdModel.runtimeBones;
    const map = new Map<number, PhysicsCategory>();
    for (let i = 0; i < bones.length; i++) {
        const bone = bones[i];
        if (bone.rigidBodyIndices.length === 0) {
            continue;
        }
        const cat = _classifyBonePhysics(bone.name);
        if (!cat) {
            continue;
        }
        for (const rbi of bone.rigidBodyIndices) {
            map.set(rbi, cat);
        }
    }
    return map;
}

/** Apply the current visibility, opacity, and wireframe state to meshes. */
function syncModelVisibility(inst: ModelInstance): void {
    for (const m of inst.meshes) {
        m.setEnabled(inst.visible);
        if (m.material) {
            m.material.alpha = inst.opacity;
            if (m.material instanceof StandardMaterial) {
                m.material.wireframe = inst.wireframe;
            }
        }
    }
}

/** Apply the current scaling and rotation state to the root mesh. */
function syncModelTransform(inst: ModelInstance): void {
    if (inst.meshes.length > 0) {
        const root = inst.meshes[0];
        root.scaling.setAll(inst.scaling);
        root.rotation.set(inst.rotation[0], inst.rotation[1], inst.rotation[2]);
    }
}

// ======== Formation Types ========

export type FormationType = 'line' | 'v-shape' | 'circle' | 'grid' | 'diagonal' | 'arc';

const FORMATION_LABELS: Record<FormationType, string> = {
    'line': '一字排列',
    'v-shape': 'V 字阵型',
    'circle': '圆形阵型',
    'grid': '网格阵型',
    'diagonal': '对角排列',
    'arc': '弧形排列',
};

export function getFormationLabels(): Record<FormationType, string> {
    return { ...FORMATION_LABELS };
}

function _computeFormationPos(
    type: FormationType,
    index: number,
    total: number,
    spacing: number
): [number, number, number] {
    const cx = 0,
        cz = 0;
    switch (type) {
        case 'line': {
            const x = (index - (total - 1) / 2) * spacing;
            return [cx + x, 0, cz];
        }
        case 'v-shape': {
            const half = Math.floor(total / 2);
            const row = Math.abs(index - half);
            const x = (index - half) * spacing * 0.6;
            const z = row * spacing * 0.8;
            return [cx + x, 0, cz + z];
        }
        case 'circle': {
            const radius = Math.max(spacing, (total * spacing) / (2 * Math.PI));
            const angle = (index / total) * Math.PI * 2 - Math.PI / 2;
            const x = cx + Math.cos(angle) * radius;
            const z = cz + Math.sin(angle) * radius;
            return [x, 0, z];
        }
        case 'grid': {
            const cols = Math.ceil(Math.sqrt(total));
            const row = Math.floor(index / cols);
            const col = index % cols;
            const x = (col - (cols - 1) / 2) * spacing;
            const z = row * spacing;
            return [cx + x, 0, cz + z];
        }
        case 'diagonal': {
            const x = (index - (total - 1) / 2) * spacing * 0.7;
            const z = index * spacing * 0.5;
            return [cx + x, 0, cz + z];
        }
        case 'arc': {
            const radius = Math.max(spacing * 2, total * spacing * 0.8);
            const spread = Math.min(Math.PI * 0.8, (total - 1) * 0.4);
            const angle = -spread / 2 + (index / Math.max(1, total - 1)) * spread;
            const x = cx + Math.sin(angle) * radius;
            const z = cz + (1 - Math.cos(angle)) * radius * 0.3;
            return [x, 0, z];
        }
    }
}

// ======== ModelManager Class ========

export class ModelManager {
    // --- State ---
    readonly modelRegistry = new Map<string, ModelInstance>();
    /** Delegates to config's focusedModelId for cross-module consistency. */
    get focusedModelId(): string | null {
        return configFocusedId;
    }
    private set _focusedModelId(v: string | null) {
        setFocusedModelId(v);
    }

    private _initialRigidBodyStates = new Map<string, Uint8Array>();
    private _physicsCatState = new Map<string, Map<string, boolean>>();
    private _boneOverlayMap = new Map<
        string,
        {
            lineSystem: Mesh;
            joints: Mesh[];
            /** 覆盖着色线段（每对骨骼一条，根据覆盖状态显示/隐藏/着色） */
            overrideLines: LinesMesh[];
            update: () => void;
            dirty: boolean;
            markDirty: () => void;
        }
    >();
    /** 骨骼覆盖着色材质（懒加载，四种类型共享所有模型） */
    private _ovMaterials: Record<OverrideType | 'default', StandardMaterial> | null = null;
    private _boneUpdateObserver: ObserverHandle | null = null;

    /** Currently active formation type, or null if custom/manual arrangement. */
    private _activeFormation: FormationType | null = null;
    /** Currently active formation spacing (default 3). */
    private _activeFormationSpacing: number = 3;

    /** Cleanup callback invoked by removeModel for external per-model state. */
    onRemoveModel: ((id: string) => void) | null = null;
    /** Callback invoked when a model receives focus (e.g. to activate gaze tracking). */
    onModelFocused: ((id: string) => void | Promise<void>) | null = null;

    constructor(
        private scene: Scene,
        private triggerAutoSave: () => void,
        private autoFrame: (center: Vector3, extent: number) => void
    ) {}

    // ======== Registry ========

    /** Get a model by ID. Returns undefined if not found. */
    get(id: string): ModelInstance | undefined {
        return this.modelRegistry.get(id);
    }

    /** Get all registered models as an array. */
    getAll(): ModelInstance[] {
        return Array.from(this.modelRegistry.values());
    }

    /** Get the number of registered models. */
    get size(): number {
        return this.modelRegistry.size;
    }

    /** Register a new model instance. */
    register(inst: ModelInstance): void {
        this.modelRegistry.set(inst.id, inst);
        applyWetnessToInst(inst);
    }

    /** Store initial rigid body state for physics toggle restoration. */
    storeRigidBodyState(id: string, states: Uint8Array): void {
        this._initialRigidBodyStates.set(id, new Uint8Array(states));
    }

    // ======== Convenience getters ========

    /** Get the currently focused ModelInstance, or undefined. */
    focused(): ModelInstance | undefined {
        return configFocusedId ? this.modelRegistry.get(configFocusedId) : undefined;
    }

    /** Get the currently focused runtime model (RuntimeModel), or null. */
    focusedMmdModel(): RuntimeModel | null {
        if (!configFocusedId) {
            return null;
        }
        const inst = this.modelRegistry.get(configFocusedId);
        return inst?.mmdModel ?? null;
    }

    /** Find a model by file path. Returns the first match or undefined. */
    findByFilePath(filePath: string): ModelInstance | undefined {
        for (const inst of this.modelRegistry.values()) {
            if (inst.filePath === filePath) {
                return inst;
            }
        }
        return undefined;
    }

    // ======== Model Lifecycle ========

    /** Remove a model and clean up all associated state. */
    remove(id: string): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }

        // [doc:adr-215] 级联卸载附属子模型（先子后父，递归）
        this.detachChildModels(id);

        disposeOverlay(inst);
        restoreMaterials(inst);

        // ⚠️ onRemoveModel（mmdRuntime.destroyMmdModel）必须在网格释放之前调用！
        // destroyMmdModel 需要 skeleton 尚存才能从运行时中解除 observable 链接，
        // 否则下一帧渲染循环中 mmdWasmModel.skeleton 为 null 会抛 TypeError。
        // onRemoveModel 也必须在 modelRegistry.delete 之前调用，
        // 因为外部回调需要通过 modelRegistry.get(id) 获取模型实例。
        this.onRemoveModel?.(id);

        // [fix:gpu-texture-leak] 显式释放材质及其纹理（mesh.dispose 只释放几何体，不释放材质）。
        // restoreMaterials 已将原始材质恢复到 mesh 上，此处统一 dispose 防止 GPU 纹理泄漏。
        // 用 Set 去重：多个 mesh 可能共享同一材质实例。
        const disposedMats = new Set<import('@babylonjs/core/Materials/material').Material>();
        for (const m of inst.meshes) {
            if (m instanceof Mesh && m.material && !disposedMats.has(m.material)) {
                disposedMats.add(m.material);
                m.material.dispose(false, true); // disposeTextures=true 级联释放贴图
            }
        }

        for (const m of inst.meshes) {
            if (m instanceof Mesh) {
                m.dispose();
            }
        }
        inst._origTextures = undefined;
        inst.outfitFile = undefined;

        this.modelRegistry.delete(id);
        this._initialRigidBodyStates.delete(id);
        this._physicsCatState.delete(id);
        this._boneOverlayMap.delete(id);
        this.destroyBoneOverlay(id);

        disposeModelMaterialState(id);

        // Update focus
        if (configFocusedId === id) {
            setFocusedModelId(
                this.modelRegistry.size > 0 ? this.modelRegistry.keys().next().value : null
            );
        }
        if (configFocusedId) {
            this.focus(configFocusedId);
        }
    }

    /** Remove the currently focused model. */
    removeFocused(): void {
        if (!configFocusedId) {
            return;
        }
        this.remove(configFocusedId);
    }

    /** Focus a model by ID: set focus + auto-frame camera.
     *  @param frameCamera 是否自动取景（相机对准模型）。false 时仅切换焦点（不移动相机）。
     *                     由 uiState.autoCenterModel 控制（undefined 视为 true）。 */
    focus(id: string, frameCamera = true): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            setFocusedModelId(null);
            return;
        }
        setFocusedModelId(id);

        // 焦点切换后自动激活默认视线追踪，使眼球 / 头部跟随当前焦点模型
        if (this.onModelFocused) {
            swallowError(Promise.resolve(this.onModelFocused(id)));
        }

        if (frameCamera) {
            const min = new Vector3(Infinity, Infinity, Infinity);
            const max = new Vector3(-Infinity, -Infinity, -Infinity);
            let hasVisibleMesh = false;
            for (const m of inst.meshes) {
                if (!m.isVisible) {
                    continue;
                }
                hasVisibleMesh = true;
                m.computeWorldMatrix(true);
                const bb = m.getBoundingInfo().boundingBox;
                min.minimizeInPlace(bb.minimumWorld);
                max.maximizeInPlace(bb.maximumWorld);
            }
            if (hasVisibleMesh) {
                const center = min.add(max).scale(0.5);
                const size = max.subtract(min);
                const extent = Math.max(size.x, size.y, size.z);
                this.autoFrame(center, extent);
            }
        }

        this.triggerAutoSave();
    }

    /** Arrange all models in a horizontal row. Clears the active formation. */
    arrange(): void {
        this._activeFormation = null;
        const models = Array.from(this.modelRegistry.values());
        const spacing = 3;
        models.forEach((inst, i) => {
            const offsetX = (i - (models.length - 1) / 2) * spacing;
            if (inst.meshes.length > 0) {
                inst.meshes[0].position.x = offsetX;
            }
        });
        this.triggerAutoSave();
    }

    /** Return the currently active formation type, or null if manually arranged. */
    getActiveFormation(): FormationType | null {
        return this._activeFormation;
    }

    /** Return the currently active formation spacing (default 3). */
    getActiveFormationSpacing(): number {
        return this._activeFormationSpacing;
    }

    /** Apply a formation preset to all models. */
    setFormation(type: FormationType, spacing?: number): void {
        this._activeFormation = type;
        this._activeFormationSpacing = spacing ?? 3;
        const models = Array.from(this.modelRegistry.values());
        const n = models.length;
        if (n === 0) {
            return;
        }
        const s = this._activeFormationSpacing;
        for (let i = 0; i < n; i++) {
            const inst = models[i];
            if (inst.meshes.length === 0) {
                continue;
            }
            const pos = _computeFormationPos(type, i, n, s);
            inst.meshes[0].position.set(pos[0], pos[1], pos[2]);
        }
        this.triggerAutoSave();
    }

    // ======== Property Setters ========

    setVisibility(id: string, visible: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.visible = visible;
        syncModelVisibility(inst);
        this.triggerAutoSave();
    }

    setOpacity(id: string, opacity: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.opacity = clamp01(opacity);
        syncModelVisibility(inst);
        this.triggerAutoSave();
    }

    setWireframe(id: string, wireframe: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.wireframe = wireframe;
        syncModelVisibility(inst);
        this.triggerAutoSave();
    }

    setBoneLinesVis(id: string, show: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.showBoneLines = show;
        const hasAny = show || inst.showBoneJoints;
        const hadOverlay = this._boneOverlayMap.has(id);
        if (hasAny && !hadOverlay) {
            this.createBoneOverlay(id);
        } else if (!hasAny && hadOverlay) {
            this.destroyBoneOverlay(id);
        } else if (hadOverlay) {
            const entry = this._boneOverlayMap.get(id)!;
            entry.lineSystem.setEnabled(show);
            entry.markDirty();
        }
        this.triggerAutoSave();
    }

    setBoneJointsVis(id: string, show: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.showBoneJoints = show;
        const hasAny = show || inst.showBoneLines;
        const hadOverlay = this._boneOverlayMap.has(id);
        if (hasAny && !hadOverlay) {
            this.createBoneOverlay(id);
        } else if (!hasAny && hadOverlay) {
            this.destroyBoneOverlay(id);
        } else if (hadOverlay) {
            const entry = this._boneOverlayMap.get(id)!;
            for (const j of entry.joints) {
                j.setEnabled(show);
            }
            entry.markDirty();
        }
        this.triggerAutoSave();
    }

    setPhysics(id: string, enabled: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.physicsEnabled = enabled;
        const mmdModel = inst.mmdModel;
        if (mmdModel) {
            const states = mmdModel.rigidBodyStates;
            if (states) {
                if (enabled) {
                    const init = this._initialRigidBodyStates.get(id) || new Uint8Array(0);
                    if (init.length === states.length) {
                        states.set(init);
                    } else {
                        states.fill(1);
                    }
                } else {
                    states.fill(0);
                }
            }
        }
        this.triggerAutoSave();
    }

    setScaling(id: string, scaling: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        if (!Number.isFinite(scaling)) {
            logWarn('model-manager', 'setScaling: 无效值', scaling);
            return;
        }
        inst.scaling = Math.max(0.01, scaling);
        syncModelTransform(inst);
        this.triggerAutoSave();
    }

    setRotationY(id: string, rotationY: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.rotationY = rotationY;
        inst.rotation[1] = rotationY;
        syncModelTransform(inst);
        this.triggerAutoSave();
    }

    /** [doc:adr-126] 全自由度旋转：以欧拉角（弧度）设置模型 root 三轴旋转。 */
    setRotation(id: string, rotation: Vector3): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.rotation[0] = rotation.x;
        inst.rotation[1] = rotation.y;
        inst.rotation[2] = rotation.z;
        inst.rotationY = rotation.y;
        syncModelTransform(inst);
        this.triggerAutoSave();
    }

    /** [doc:adr-126] 读取模型 root 当前三轴旋转（欧拉角，弧度）。 */
    getRotation(id: string): Vector3 | null {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return null;
        }
        return new Vector3(inst.rotation[0], inst.rotation[1], inst.rotation[2]);
    }

    setPosition(id: string, x: number, y: number, z: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) {
            logWarn('model-manager', 'setPosition: 无效坐标', { x, y, z });
            return;
        }
        if (inst.meshes.length > 0) {
            inst.meshes[0].position.set(x, y, z);
        }
        this.triggerAutoSave();
    }

    getPosition(id: string): [number, number, number] {
        const inst = this.modelRegistry.get(id);
        if (!inst || inst.meshes.length === 0) {
            return [0, 0, 0];
        }
        const p = inst.meshes[0].position;
        return [p.x, p.y, p.z];
    }

    /** [doc:adr-049] 以球面坐标（方位角/仰角/距离）定位模型，等价于围绕原点旋转。 */
    setOrbit(id: string, azimuth: number, elevation: number, distance: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        // 边界保护：钳制到合法值域（绝不产生 NaN / 退化），损坏场景文件反序列化也能安全定位。
        const invalid =
            !Number.isFinite(azimuth) ||
            !Number.isFinite(elevation) ||
            !Number.isFinite(distance) ||
            distance <= 0 ||
            elevation < -90 ||
            elevation > 90;
        const o = normalizeOrbit(azimuth, elevation, distance);
        if (invalid) {
            logWarn('model-manager', 'setOrbit: 输入越界已钳制', {
                azimuth,
                elevation,
                distance,
                result: o,
            });
        }
        inst.positionMode = 'orbit';
        inst.orbitAzimuth = o.azimuth;
        inst.orbitElevation = o.elevation;
        inst.orbitDistance = o.distance;
        const [x, y, z] = orbitToCartesian(o.azimuth, o.elevation, o.distance);
        if (inst.meshes.length > 0) {
            inst.meshes[0].position.set(x, y, z);
        }
        this.triggerAutoSave();
    }

    /** [doc:adr-049] 读取模型当前球面坐标。orbit 模式下返回存储值，否则从当前笛卡尔位置反推。 */
    getOrbit(id: string): { azimuth: number; elevation: number; distance: number } | null {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return null;
        }
        if (
            inst.positionMode === 'orbit' &&
            inst.orbitAzimuth !== undefined &&
            inst.orbitElevation !== undefined &&
            inst.orbitDistance !== undefined
        ) {
            return {
                azimuth: inst.orbitAzimuth,
                elevation: inst.orbitElevation,
                distance: inst.orbitDistance,
            };
        }
        const [x, y, z] = this.getPosition(id);
        return cartesianToOrbit(x, y, z);
    }

    /** [doc:adr-049] 切换坐标模式。切到 orbit 时从当前笛卡尔位置反推球面参数（无跳变）；切回 cartesian 保留当前位置。 */
    setPositionMode(id: string, mode: 'cartesian' | 'orbit'): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        if (mode === 'orbit') {
            const [x, y, z] = this.getPosition(id);
            const o = cartesianToOrbit(x, y, z);
            inst.orbitAzimuth = o.azimuth;
            inst.orbitElevation = o.elevation;
            inst.orbitDistance = o.distance;
        } else {
            // cartesian 模式：确保 mesh 位置与实例当前位置一致（orbit 模式已写入）
            const [x, y, z] = this.getPosition(id);
            if (inst.meshes.length > 0) {
                inst.meshes[0].position.set(x, y, z);
            }
        }
        inst.positionMode = mode;
        this.triggerAutoSave();
    }

    /** [doc:adr-049] 读取模型当前坐标模式（默认 'cartesian'）。 */
    getPositionMode(id: string): 'cartesian' | 'orbit' {
        const inst = this.modelRegistry.get(id);
        return inst?.positionMode ?? 'cartesian';
    }

    resetTransform(id: string): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.visible = true;
        inst.opacity = 1.0;
        inst.wireframe = false;
        inst.scaling = 1.0;
        inst.rotationY = 0;
        inst.rotation = [0, 0, 0];
        if (inst.meshes.length > 0) {
            inst.meshes[0].position.set(0, 0, 0);
        }
        syncModelVisibility(inst);
        syncModelTransform(inst);
        this.triggerAutoSave();
    }

    /** Stop VMD animation on a model and clean up associated state. */
    /** 清空模型的 VMD 数据（vmdData/vmdName/vmdPath/animationDuration）。
     *  注意：此方法不暂停动画或修改播放状态——暂停由上层 `stopVMD` 编排。 */
    clearVmdData(id: string): void {
        const inst = this.modelRegistry.get(id);
        if (!inst) {
            return;
        }
        inst.vmdData = null;
        inst.vmdName = '';
        inst.vmdPath = null;
        inst.animationDuration = 0;
        inst.vmdLayers = [];
        this.triggerAutoSave();
    }

    // ======== Physics Categories ========

    getPhysicsCategories(id: string): PhysicsCategory[] {
        const inst = this.modelRegistry.get(id);
        if (!inst.mmdModel) {
            return [];
        }
        const map = _buildRigidBodyCatMap(inst.mmdModel);
        const set = new Set(map.values());
        return [...set];
    }

    getPhysicsCatState(id: string): Record<string, boolean> | null {
        const state = this._physicsCatState.get(id);
        if (!state || state.size === 0) {
            return null;
        }
        const result: Record<string, boolean> = {};
        for (const [cat, enabled] of state) {
            result[cat] = enabled;
        }
        return result;
    }

    isPhysicsCategoryEnabled(id: string, cat: string): boolean {
        return this._physicsCatState.get(id)?.get(cat) ?? true;
    }

    setPhysicsCategory(id: string, cat: string, enabled: boolean): void {
        const inst = this.modelRegistry.get(id);
        if (!inst || !inst.mmdModel) {
            return;
        }
        // 若启用子类别但总开关未开，自动开启总开关防止 UI 状态不一致
        if (enabled && !inst.physicsEnabled) {
            this.setPhysics(id, true);
        }
        const states = inst.mmdModel.rigidBodyStates;
        if (!states) {
            return;
        }
        const catMap = _buildRigidBodyCatMap(inst.mmdModel);
        const init = this._initialRigidBodyStates.get(id);
        for (const [rbi, c] of catMap) {
            if (c !== cat || rbi >= states.length) {
                continue;
            }
            states[rbi] = enabled ? (init ? init[rbi] : 1) : 0;
        }
        let physMap = this._physicsCatState.get(id);
        if (!physMap) {
            physMap = new Map();
            this._physicsCatState.set(id, physMap);
        }
        physMap.set(cat, enabled);
        this.triggerAutoSave();
    }

    // ======== Morphs ========

    getMorphs(id: string): Array<{ name: string; type: number }> {
        const inst = this.modelRegistry.get(id);
        if (!inst || !inst.mmdModel || !inst.mmdModel.morph || !inst.mmdModel.morph.morphs) {
            return [];
        }
        return inst.mmdModel.morph.morphs.map((m) => ({ name: m.name, type: m.type }));
    }

    setMorphWeight(id: string, morphName: string, weight: number): void {
        const inst = this.modelRegistry.get(id);
        if (!inst || !inst.mmdModel || !inst.mmdModel.morph) {
            return;
        }
        inst.mmdModel.morph.setMorphWeight(morphName, weight);
    }

    getMorphWeight(id: string, morphName: string): number {
        const inst = this.modelRegistry.get(id);
        if (!inst || !inst.mmdModel || !inst.mmdModel.morph) {
            return 0;
        }
        return inst.mmdModel.morph.getMorphWeight(morphName);
    }

    resetMorphs(id: string): void {
        const inst = this.modelRegistry.get(id);
        if (!inst || !inst.mmdModel || !inst.mmdModel.morph) {
            return;
        }
        inst.mmdModel.morph.resetMorphWeights();
        this.triggerAutoSave();
    }

    // ======== Skeletal Bone Overlay ========

    private createBoneOverlay(id: string): void {
        const inst = this.modelRegistry.get(id);
        if (!inst.mmdModel) {
            return;
        }
        if (this._boneOverlayMap.has(id)) {
            return;
        }
        const bones = inst.mmdModel.runtimeBones;
        if (!bones || bones.length === 0) {
            return;
        }

        const lines: Vector3[][] = [];
        const tmp = new Vector3();
        const joints: Mesh[] = [];
        const jointData: { mesh: Mesh; boneIndex: number; boneName: string }[] = [];
        const lineData: { childIndex: number; parentIndex: number }[] = [];

        // 懒加载覆盖着色材质
        if (!this._ovMaterials) {
            this._ovMaterials = {
                default: new StandardMaterial('bone_ov_default', this.scene),
                rotation: new StandardMaterial('bone_ov_rotation', this.scene),
                position: new StandardMaterial('bone_ov_position', this.scene),
                both: new StandardMaterial('bone_ov_both', this.scene),
            };
            this._ovMaterials.default.diffuseColor = new Color3(1, 1, 1);
            this._ovMaterials.rotation.diffuseColor = new Color3(1, 0.2, 0.2); // 红 — 旋转覆盖
            this._ovMaterials.position.diffuseColor = new Color3(0.2, 0.5, 1); // 蓝 — 位置覆盖
            this._ovMaterials.both.diffuseColor = new Color3(1, 0.3, 1); // 紫 — 旋转 + 位置
        }
        const ovMat = this._ovMaterials;

        for (let i = 0; i < bones.length; i++) {
            const bone = bones[i];
            const parent = bone.parentBone;
            if (!parent) {
                continue;
            }

            // 找到父骨骼的索引
            const parentIndex = bones.indexOf(parent);
            if (parentIndex === -1) {
                continue;
            }

            // Joint sphere at bone position
            bone.getWorldTranslationToRef(tmp);
            const pos = tmp.clone();
            const sphere = MeshBuilder.CreateSphere(
                'bone_joint',
                { diameter: 1.5, segments: 8 },
                this.scene
            );
            sphere.position.copyFrom(pos);
            sphere.setEnabled(false);
            joints.push(sphere);
            jointData.push({ mesh: sphere, boneIndex: i, boneName: bone.name });

            // Bone line from parent to child
            const parentPos = new Vector3();
            parent.getWorldTranslationToRef(parentPos);
            lines.push([parentPos.clone(), pos.clone()]);
            lineData.push({ childIndex: i, parentIndex });
        }

        // Create overlay: line system + sphere meshes
        // updatable: true 必填，否则 updateVerticesData 不写入 GPU buffer，骨骼线无法跟随骨骼运动
        const lineSystem = MeshBuilder.CreateLineSystem(
            'bone_overlay_lines',
            { lines, updatable: true },
            this.scene
        );
        lineSystem.color = new Color3(1, 1, 1);
        lineSystem.isPickable = false;
        lineSystem.setEnabled(inst.showBoneLines);

        // [doc:bone-override] 覆盖着色线段：为每对骨骼创建独立 LinesMesh，
        // 根据覆盖状态显示/隐藏/着色。白色 lineSystem 不可逐段着色，需独立 mesh。
        const overrideLines: LinesMesh[] = [];
        for (let i = 0; i < lineData.length; i++) {
            const ovLine = MeshBuilder.CreateLines(
                'bone_ov_line',
                {
                    points: [Vector3.Zero(), Vector3.Zero()],
                    updatable: true,
                },
                this.scene
            );
            ovLine.isPickable = false;
            ovLine.setEnabled(false);
            overrideLines.push(ovLine);
        }

        let dirty = true;
        const markDirty = () => {
            dirty = true;
        };

        const updateFn = () => {
            if (!dirty) {
                return;
            }
            dirty = false;

            if (inst.showBoneLines && lineSystem.isEnabled()) {
                const positions = lineSystem.getVerticesData('position');
                if (positions) {
                    for (let i = 0; i < lineData.length; i++) {
                        const ld = lineData[i];
                        const childBone = bones[ld.childIndex];
                        const parentBone = bones[ld.parentIndex];

                        if (childBone && parentBone) {
                            parentBone.getWorldTranslationToRef(tmp);
                            positions[i * 6] = tmp.x;
                            positions[i * 6 + 1] = tmp.y;
                            positions[i * 6 + 2] = tmp.z;

                            childBone.getWorldTranslationToRef(tmp);
                            positions[i * 6 + 3] = tmp.x;
                            positions[i * 6 + 4] = tmp.y;
                            positions[i * 6 + 5] = tmp.z;
                        }
                    }
                    lineSystem.updateVerticesData('position', positions);
                }

                // [doc:bone-override] 覆盖线段着色
                const ovLineColors: Record<
                    NonNullable<ReturnType<typeof getOverrideType>>,
                    Color3
                > = {
                    rotation: new Color3(1, 0.3, 0.3), // 红
                    position: new Color3(0.3, 0.5, 1), // 蓝
                    both: new Color3(1, 0.3, 1), // 紫
                };
                for (let i = 0; i < lineData.length; i++) {
                    const ld = lineData[i];
                    const childBone = bones[ld.childIndex];
                    const parentBone = bones[ld.parentIndex];
                    if (!childBone || !parentBone) {
                        overrideLines[i].setEnabled(false);
                        continue;
                    }
                    const childOv = getOverrideType(childBone.name, id);
                    const parentOv = getOverrideType(parentBone.name, id);
                    const ovType = childOv ?? parentOv;
                    if (!ovType) {
                        overrideLines[i].setEnabled(false);
                        continue;
                    }
                    const ovLine = overrideLines[i];
                    const ovPositions = ovLine.getVerticesData('position');
                    if (ovPositions) {
                        parentBone.getWorldTranslationToRef(tmp);
                        ovPositions[0] = tmp.x;
                        ovPositions[1] = tmp.y;
                        ovPositions[2] = tmp.z;
                        childBone.getWorldTranslationToRef(tmp);
                        ovPositions[3] = tmp.x;
                        ovPositions[4] = tmp.y;
                        ovPositions[5] = tmp.z;
                        ovLine.updateVerticesData('position', ovPositions);
                    }
                    ovLine.color = ovLineColors[ovType];
                    ovLine.setEnabled(true);
                }
            }

            if (!inst.showBoneJoints) {
                return;
            }
            for (const jd of jointData) {
                const bone = bones[jd.boneIndex];
                if (!bone) {
                    jd.mesh.setEnabled(false);
                    continue;
                }
                bone.getWorldTranslationToRef(tmp);
                jd.mesh.position.copyFrom(tmp);
                jd.mesh.setEnabled(true);

                // [doc:bone-override] 覆盖状态着色
                const ovType = getOverrideType(jd.boneName, id);
                jd.mesh.material = ovType ? ovMat[ovType] : ovMat.default;
            }
        };

        // 不合并 sphere meshes：
        // Mesh.MergeMeshes(disposeSource=true) 会 dispose 原始 sphere，
        // 而合并后 overlay 的顶点数据无法逐 bone 更新 —— 关节球一旦创建就固化在初始位置。
        // 改为保留独立 sphere mesh，每帧由 updateFn 直接修改 mesh.position 跟随骨骼世界坐标。
        for (const j of joints) {
            j.isPickable = false;
            j.setEnabled(inst.showBoneJoints);
        }

        this._boneOverlayMap.set(id, {
            lineSystem,
            joints,
            overrideLines,
            update: updateFn,
            dirty: true,
            markDirty,
        });
        this.ensureBoneUpdateObserver();
    }

    private destroyBoneOverlay(id: string): void {
        const entry = this._boneOverlayMap.get(id);
        if (entry) {
            entry.lineSystem.dispose();
            for (const j of entry.joints) {
                j.dispose();
            }
            for (const ol of entry.overrideLines) {
                ol.dispose();
            }
            this._boneOverlayMap.delete(id);
        }
    }

    private ensureBoneUpdateObserver(): void {
        if (this._boneUpdateObserver) {
            return;
        }
        this._boneUpdateObserver = observe(this.scene.onBeforeRenderObservable, () => {
            const toDelete: string[] = [];
            for (const [id, entry] of this._boneOverlayMap) {
                const inst = this.modelRegistry.get(id);
                // 模型已 dispose（mmdModel 非 null 但 mesh 已释放）时跳过更新并延迟清理，避免访问已销毁骨骼
                if (
                    !inst ||
                    !inst.mmdModel ||
                    inst.mmdModel.mesh?.isDisposed() ||
                    (!inst.showBoneLines && !inst.showBoneJoints)
                ) {
                    entry.lineSystem.dispose();
                    for (const j of entry.joints) {
                        j.dispose();
                    }
                    for (const ol of entry.overrideLines) {
                        ol.dispose();
                    }
                    toDelete.push(id);
                    continue;
                }
                // WASM 物理恒启用，叠加层可见即每帧更新
                entry.markDirty();
                entry.update();
            }
            for (const id of toDelete) {
                this._boneOverlayMap.delete(id);
            }
        });
    }

    /** Clean up all observers. Called on shutdown. */
    dispose(): void {
        if (this._boneUpdateObserver) {
            this._boneUpdateObserver.dispose();
            this._boneUpdateObserver = null;
        }
        // Dispose all bone overlay resources (lineSystem + joints + overrideLines)
        for (const [, entry] of this._boneOverlayMap) {
            entry.lineSystem.dispose();
            for (const j of entry.joints) {
                j.dispose();
            }
            for (const ol of entry.overrideLines) {
                ol.dispose();
            }
        }
        this._boneOverlayMap.clear();
        // Dispose override coloring materials
        if (this._ovMaterials) {
            this._ovMaterials.default.dispose();
            this._ovMaterials.rotation.dispose();
            this._ovMaterials.position.dispose();
            this._ovMaterials.both.dispose();
            this._ovMaterials = null;
        }
        // Dispose all remaining outfit overlays
        for (const [, inst] of this.modelRegistry) {
            disposeOverlay(inst);
            restoreMaterials(inst);
        }
    }

    // ======== [doc:adr-215] 模型附属关系管理 ========

    /**
     * DAG 校验：从 startId 沿 parentId 链向上追溯，是否能到达 targetId。
     * 用于判断「把 child 附属到 parent」是否成环——若 parent 的祖先链中已含 child
     * （即 child 是 parent 的祖先），则新建 child←parent 会成环。
     */
    private _hasAncestor(startId: string, targetId: string): boolean {
        const visited = new Set<string>();
        let currentId: string | undefined = startId;
        while (currentId) {
            if (currentId === targetId) {
                return true;
            }
            if (visited.has(currentId)) {
                return false;
            }
            visited.add(currentId);
            currentId = this.modelRegistry.get(currentId)?.parentId;
        }
        return false;
    }

    /**
     * 将子模型（角色配件）附属到父模型的指定骨骼上。
     * 含 DAG 校验、单父限制、骨骼名 guard。
     * @returns 是否成功
     */
    attachModelToBone(
        childId: string,
        parentId: string,
        boneName: string,
        offset: [number, number, number] = [0, 0, 0],
        rotation: [number, number, number] = [0, 0, 0]
    ): boolean {
        const childInst = this.modelRegistry.get(childId);
        if (!childInst) {
            logWarn('model-manager', 'attachModelToBone: child not found:', childId);
            return false;
        }
        const parentInst = this.modelRegistry.get(parentId);
        if (!parentInst?.mmdModel) {
            logWarn(
                'model-manager',
                'attachModelToBone: parent not found or no mmd runtime:',
                parentId
            );
            return false;
        }

        // DAG 校验：防止成环。
        // 从 parent 沿 parentId 链向上追溯，若能到达 child，说明 child 是 parent 的祖先，
        // 建立 child←parent 会成环（child 自身旧 parentId 指向别处不影响此追溯）。
        // 反向也需检查：若 child 沿 parentId 链向上能到达 parent，说明 child 已为 parent 后代，
        // 直接建立 child←parent 也会成环。但排除 child 已直接附属到此 parent 的情况（重挂载）。
        const childIsDescendant =
            childInst.parentId !== undefined &&
            childInst.parentId !== parentId &&
            this._hasAncestor(childInst.parentId, parentId);
        if (childId === parentId || this._hasAncestor(parentId, childId) || childIsDescendant) {
            logWarn('model-manager', 'attachModelToBone: would create cycle');
            feedbackStatus('scene.accessory.cycleDetected', undefined, false);
            return false;
        }

        // 骨骼名 guard
        const rb = parentInst.mmdModel.runtimeBones.find((b) => b.name === boneName);
        if (!rb) {
            logWarn('model-manager', 'attachModelToBone: bone not found:', boneName);
            feedbackStatus('scene.accessory.boneNotFound', undefined, false, { bone: boneName });
            return false;
        }

        const linkedBone = (
            rb as unknown as { linkedBone?: import('@babylonjs/core/Bones/bone').Bone }
        ).linkedBone;
        if (!linkedBone) {
            logWarn('model-manager', 'attachModelToBone: bone has no linkedBone:', boneName);
            return false;
        }

        // 记录附属关系
        childInst.parentId = parentId;
        childInst.attachedBone = boneName;
        childInst.attachedOffset = offset;
        childInst.attachedRotation = rotation;

        const target = childInst.rootMesh;
        target.position.set(offset[0], offset[1], offset[2]);
        const rotQ = Quaternion.FromEulerAngles(
            (rotation[0] * Math.PI) / 180,
            (rotation[1] * Math.PI) / 180,
            (rotation[2] * Math.PI) / 180
        );
        target.rotationQuaternion = rotQ;
        target.attachToBone(linkedBone, parentInst.rootMesh);

        showInfoToast(t('scene.accessory.attached', { name: childInst.name, bone: boneName }));
        this.triggerAutoSave();
        return true;
    }

    /**
     * 解除子模型的骨骼附属，回到场景坐标模式。
     * 保留在 modelRegistry 中，可独立操作或重新挂载。
     */
    detachModelFromBone(childId: string): void {
        const childInst = this.modelRegistry.get(childId);
        if (!childInst) {
            return;
        }

        const target = childInst.rootMesh;
        const worldMat = target.getWorldMatrix().clone();
        target.detachFromBone();

        childInst.parentId = undefined;
        childInst.attachedBone = undefined;
        childInst.attachedOffset = undefined;
        childInst.attachedRotation = undefined;

        target.position = worldMat.getTranslation();
        target.rotationQuaternion = Quaternion.FromRotationMatrix(worldMat.getRotationMatrix());

        showInfoToast(t('scene.accessory.detached', { name: childInst.name }));
        this.triggerAutoSave();
    }

    /**
     * 重新挂载所有附属模型（场景恢复时调用）。
     * 遍历 modelRegistry 中所有 parentId !== undefined 的实例。
     */
    reattachAllAttachments(): void {
        for (const [childId, inst] of this.modelRegistry) {
            if (inst.parentId && inst.attachedBone) {
                const target = inst.rootMesh;
                try {
                    target.detachFromBone();
                } catch {
                    /* cleanup */
                }
                this.attachModelToBone(
                    childId,
                    inst.parentId,
                    inst.attachedBone,
                    inst.attachedOffset ?? [0, 0, 0],
                    inst.attachedRotation ?? [0, 0, 0]
                );
            }
        }
    }

    /**
     * 卸载父模型时，级联卸载其附属子模型。
     * 遍历 modelRegistry 中所有 parentId === parentId 的实例并移除。
     */
    detachChildModels(parentId: string): void {
        const childIds = [...this.modelRegistry]
            .filter(([, inst]) => inst.parentId === parentId)
            .map(([id]) => id);
        for (const cid of childIds) {
            this.remove(cid);
        }
    }
}

// thumbnail-capture.ts — 模型/动作缩略图离屏渲染（RenderTargetTexture），pmx 与 motion 共用
//
// 架构说明：model-loader 已静态 import vmd-loader（加载动作），若 vmd-loader 再静态
// import model-loader 会形成循环依赖。故将 RT 渲染逻辑独立成本模块：
//   - model-loader 通过 captureThumbnail 复用 renderInstanceThumbnail（封装 pmx 特有 key 计算）
//   - vmd-loader 通过动态 import 调用 renderInstanceThumbnail（规避静态循环）
// 本模块内部仅动态 import '../scene' 取 Scene 实例，不反向引入 model-loader / vmd-loader。

import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { RenderTargetTexture } from '@babylonjs/core/Materials/Textures/renderTargetTexture';
import { FreeCamera } from '@babylonjs/core/Cameras/freeCamera';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Matrix } from '@babylonjs/core/Maths/math.vector';
import { Color4 } from '@babylonjs/core/Maths/math.color';
import type { Scene } from '@babylonjs/core/scene';
import { SaveThumbnail } from '@/core/wails-bindings';
import { thumbnailCache, setThumbnailCache, type ModelInstance } from '@/core/config';
import { uiState } from '@/core/state';
import { isStageLike } from '@/core/path';
import { canvasToBase64 } from '@/core/image';
import { logWarn } from '@/core/logger';
import { type RuntimeModel } from '@/core/types';
import { buildThumbnailKey } from './thumbnail-key';

// 缩略图渲染所需的最小实例形状。
// 仅消费三个字段：rootMesh（渲染根节点）、kind（宽高比判定）、mmdModel?（物理冻结，可选）。
// 用 TransformNode 而非 Mesh：道具的渲染根是其父级容器（TransformNode），
// 以便多网格道具的全部子网格入镜；模型 rootMesh 为 Mesh（TransformNode 子类）同样兼容。
export interface ThumbnailSource {
    rootMesh: TransformNode;
    kind: string;
    mmdModel?: RuntimeModel;
}

// ======== 并发互斥：promise 链确保同一时刻只有一个缩略图渲染 ========
// renderInstanceThumbnail 共享 RT + framebuffer + 物理冻结状态，
// 并发调用会导致 WebGL 状态冲突或截图内容错乱。
let _thumbMutex: Promise<unknown> = Promise.resolve();

// [doc:adr-dep-graph] thumbDataUrl 已迁移到 @/core/image，直接引用该零依赖叶
/**
 * 用离屏 RenderTargetTexture 渲染指定模型实例的「当前骨骼姿态」并保存为缩略图。
 *
 * 调用方负责先把场景/动画定位到目标帧（例如动作第 0 帧）再调用——本函数只截当前姿态，
 * 不推进动画时间轴。始终创建独立缩略图相机，基于包围盒聚焦上半身（凸显服饰特征）。
 */
export async function renderInstanceThumbnail(
    scene: Scene,
    inst: ModelInstance,
    key: string
): Promise<void> {
    // 串行化：排队等待上一个缩略图渲染完成，避免并发操作 RT/framebuffer/物理状态
    const prev = _thumbMutex;
    let release!: () => void;
    _thumbMutex = new Promise<void>((r) => {
        release = r;
    });
    await prev;
    try {
        await _renderThumbnailImpl(scene, inst, key);
    } finally {
        release();
    }
}

async function _renderThumbnailImpl(
    scene: Scene,
    inst: ThumbnailSource,
    key: string
): Promise<void> {
    if (!inst || !inst.rootMesh) {
        return;
    }
    const engine = scene.getEngine();
    // 缩略图分辨率复用用户设置（默认 512，可选 1024/2048/4096）
    const thumbMax = uiState.thumbnailResolution ?? 512;
    // 角色竖屏 2:3，舞台横屏 16:9，thumbMax 为长边像素数
    const isStage = isStageLike(inst.kind);
    const THUMB_ASPECT = isStage ? 16 / 9 : 2 / 3;
    // 缓存 key 追加分辨率和比例，确保不同分辨率的缩略图被视为独立条目。
    // 格式：原 key::resolution::aspect（如 filePath::512::2/3）
    const cacheKey = buildThumbnailKey({ baseKey: key, isStage, resolution: thumbMax });

    const rtW = isStage ? thumbMax : Math.max(1, Math.round(thumbMax * THUMB_ASPECT));
    const rtH = isStage ? Math.max(1, Math.round(thumbMax / THUMB_ASPECT)) : thumbMax;

    const rt = new RenderTargetTexture('thumbRT', { width: rtW, height: rtH }, scene, false);
    rt.clearColor = new Color4(0, 0, 0, 0);

    // 缩略图相机 FOV 独立常量（0.8 = 中等广角，与主相机默认值一致但解耦）。
    // 不读 activeCamera.fov：避免「调 0.8 无效 → AI 跨界改主相机」死循环，
    // 也避免用户调主相机 FOV 时缩略图意外畸变。缩略图应稳定可预测。
    const THUMB_FOV = 0.8;

    const thumbCam = new FreeCamera('thumbCam', Vector3.Zero(), scene);
    thumbCam.minZ = 0.1;
    thumbCam.maxZ = 5000;
    thumbCam.fov = THUMB_FOV;

    // [fix:thumbnail-aspect] 手动构建投影矩阵并冻结，绕过引擎 aspect 计算。
    // 问题：RTT 渲染时，相机投影矩阵可能在 framebuffer 绑定前计算，导致 aspect 用主画布尺寸
    // 而非 RT 尺寸（主画布 16:9，RT 2:3）→ 水平视野过宽 → 角色被水平压扁。
    // 修复：用 RT 的 aspect (rtW/rtH) 手动构建 PerspectiveFovLH 投影矩阵并冻结，
    //       确保渲染时使用正确的宽高比。
    const projMatrix = new Matrix();
    Matrix.PerspectiveFovLHToRef(
        THUMB_FOV,
        rtW / rtH,
        thumbCam.minZ,
        thumbCam.maxZ,
        projMatrix,
        true // isVerticalFovFixed = true（fov 是垂直视野）
    );
    thumbCam.freezeProjectionMatrix(projMatrix);

    if (inst.kind === 'stage' && scene.activeCamera) {
        // 舞台：直接沿用主相机的 position + target。
        // 舞台场景常含天空盒/远景背景板（千米级 bb），按包围盒推算距离必然失效。
        // 场景在 (0,0,0) 加载，主相机聚焦设计已针对核心区域，缩略图直接复用即可。
        thumbCam.position.copyFrom(scene.activeCamera.position);
        // activeCamera 类型是 Camera 基类，getTarget 只在 TargetCamera 上。
        // 用 position + forward 方向 × 10 推算 target，兼容所有相机类型。
        const fwd = scene.activeCamera.getDirection(Vector3.Forward());
        thumbCam.setTarget(thumbCam.position.add(fwd.scale(10)));
    } else {
        // 角色（或无主相机的退化场景）：基于包围盒聚焦上半身，凸显服饰特征。
        const bb = inst.rootMesh.getHierarchyBoundingVectors(true);
        const fullHeight = bb.max.y - bb.min.y;
        const centerX = (bb.max.x + bb.min.x) * 0.5;
        const centerZ = (bb.max.z + bb.min.z) * 0.5;
        const extent = bb.max.subtract(bb.min);

        // 焦点：全身 60% 高度（胸部），能看到面部+上半身服饰
        const focusCenterY = bb.min.y + fullHeight * 0.55;
        const focusHeight = fullHeight * 0.65;
        const focusWidth = extent.x * 0.55;

        // 距离系数 0.75 与主相机 autoFrame（extent * 0.75 + 2）同源，行为可预测。
        const dist =
            (Math.max(focusHeight, focusWidth / THUMB_ASPECT) * 0.75) /
            (2 * Math.tan(THUMB_FOV / 2));

        // 相机朝向：复用主相机方向，或默认 -Z（MMD 正面）
        let dirX = 0,
            dirY = 0,
            dirZ = -1;
        if (scene.activeCamera) {
            const fwd = scene.activeCamera.getDirection(Vector3.Forward());
            dirX = fwd.x;
            dirY = fwd.y;
            dirZ = fwd.z;
        }
        // 沿朝向反方向放置相机（dir 是相机看向目标的方向，相机在 target - dir*dist）
        thumbCam.position.set(
            centerX - dirX * dist,
            focusCenterY - dirY * dist,
            centerZ - dirZ * dist
        );
        thumbCam.setTarget(new Vector3(centerX, focusCenterY, centerZ));
    }
    rt.activeCamera = thumbCam;

    const renderList: Mesh[] = [];
    inst.rootMesh.getChildMeshes().forEach((m) => {
        if (m.isVisible) {
            renderList.push(m as Mesh);
        }
    });
    if (inst.rootMesh instanceof Mesh && inst.rootMesh.isVisible) {
        renderList.push(inst.rootMesh);
    }
    rt.renderList = renderList;

    // 渲染前临时冻结物理：WASM Bullet 物理在 onBeforeRenderObservable 中推进，
    // 若在物理已更新帧截取缩略图，刚体位置变化导致骨骼跟随 → 裙子/头发等物理刚体
    // 处于「飞行中」姿态（ADR-XXX 缩略图物理干扰）。
    // 做法与 model-manager.ts:setPhysics 相同：保存 → 填 0（禁用）→ 渲染 → 恢复。
    const mmdModel = inst.mmdModel;
    const states = mmdModel?.rigidBodyStates;
    const savedStates = states ? new Uint8Array(states) : null;

    try {
        if (states) {
            states.fill(0);
        }

        rt.render();

        // readPixels 读取的是「当前绑定的 framebuffer」。
        // rt.render() 结束会 unBindFramebuffer 回到默认 backbuffer，
        // 必须重新绑定 RTT 自身的 framebuffer 才能读到离屏渲染结果（否则截到的是主场景）。
        engine.bindFramebuffer(rt.renderTarget!);
        try {
            const pixels = await engine.readPixels(0, 0, rtW, rtH, true);
            const canvas = document.createElement('canvas');
            canvas.width = rtW;
            canvas.height = rtH;
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                return;
            }

            const imageData = ctx.createImageData(rtW, rtH);
            // readPixels 返回 Uint8Array（0–255 字节），已是最终像素值，直接拷贝即可。
            const arr = pixels as Uint8Array;
            // WebGL framebuffer 原点在左下角，readPixels 行序「底→顶」；
            // canvas putImageData 原点左上，需逐行上下翻转，否则缩略图上下颠倒（倒立）。
            const rowBytes = rtW * 4;
            const flipped = new Uint8Array(arr.length);
            for (let y = 0; y < rtH; y++) {
                try {
                    flipped.set(
                        arr.subarray(y * rowBytes, y * rowBytes + rowBytes),
                        (rtH - 1 - y) * rowBytes
                    );
                } catch {
                    // readPixels 返回的 buffer 可能被 detach（WebGL 竞态），跳过此行不崩
                    continue;
                }
            }
            imageData.data.set(flipped);
            ctx.putImageData(imageData, 0, 0);

            // 复用截图格式/质量设置（PNG 无损，JPEG/WebP 受 quality 控制）
            // [fix:thumbnail-async] 用 toBlob 异步编码替代同步 toDataURL，
            // 将 PNG/JPEG 编码移至后台线程，避免阻塞主线程 0.5–2s（加载时跌帧元凶）。
            const fmt = uiState.screenshotFormat ?? 'image/png';
            const q = uiState.screenshotQuality ?? 0.9;
            const base64 = await canvasToBase64(canvas, fmt, q);

            try {
                await SaveThumbnail(cacheKey, base64);
                const updated = new Map(thumbnailCache);
                updated.set(cacheKey, base64);
                setThumbnailCache(updated);
            } catch (saveErr) {
                logWarn('thumbnail-capture', 'SaveThumbnail failed:', saveErr);
            }
        } finally {
            engine.unBindFramebuffer(rt.renderTarget!);
        }
    } finally {
        // 恢复物理状态
        if (states && savedStates) {
            states.set(savedStates);
        }
        rt.dispose();
        thumbCam.dispose();
    }
}

// 注意：动作（VMD）缩略图不再有专属封装函数——vmd-loader 在加载动作流程中
// 摆姿（currentAnimation.animate(0)）后直接调用 renderInstanceThumbnail(scene, inst, vmdKey)。

// thumbnail-key.ts — 缩略图缓存 key 的唯一推导源（P0 治理：消除双源拼接反弹）
//
// 历史：写侧（model-loader / props）与读侧（library-core）各自用字符串拼接构造
// `<baseKey>::<resolution>::<aspect>`，任何一侧微调即导致缓存 miss → 缩略图"消失/重生"，
// 形成 12 轮修改反弹。本模块将拼接收敛为唯一纯函数，两侧必须经由它构造 key。
//
// key 格式：`<baseKey>::<resolution>::<aspect>`
//   - baseKey：库引用路径（file_path）；ZIP 内模型追加 `::<zipInner>`。
//   - resolution：缩略图长边像素（默认 512，运行时取 uiState.thumbnailResolution）。
//   - aspect：'16/9'（舞台/场景/道具横屏）或 '2/3'（角色竖屏），由 isStageLike 决定。

import { isStageLike } from '@/core/path';
import type { LibraryModel } from '@/core/types';

export interface ThumbnailBaseKeyInput {
    /** 库引用路径，优先作为 baseKey（等价 LibraryModel.file_path）。 */
    libraryPath?: string;
    /** 实际文件路径（解压临时路径或导入真实路径），libraryPath 缺省或与其相等时回退。 */
    filePath: string;
    /** ZIP 内部相对路径（等价 LibraryModel.zip_inner），存在时追加到 baseKey。 */
    innerPath?: string;
}

/**
 * 由库引用路径 + 内部路径推导 baseKey。
 * 统一了写侧（libraryPath 优先 + innerPath）与读侧（file_path + zip_inner）两种历史写法。
 */
export function thumbnailBaseKey(input: ThumbnailBaseKeyInput): string {
    const { libraryPath, filePath, innerPath } = input;
    let base = libraryPath && libraryPath !== filePath ? libraryPath : filePath;
    if (innerPath) {
        base = `${base}::${innerPath}`;
    }
    return base;
}

/** 由 LibraryModel 推导 baseKey（读侧专用适配器）。 */
export function libraryModelBaseKey(m: LibraryModel): string {
    return thumbnailBaseKey({
        libraryPath: m.file_path,
        filePath: m.file_path,
        innerPath: m.container === 'zip' && m.zip_inner ? m.zip_inner : undefined,
    });
}

export interface ThumbnailKeyInput {
    baseKey: string;
    /** 是否为横屏（舞台/场景/道具）。决定 aspect 后缀。 */
    isStage: boolean;
    /** 缩略图长边分辨率，默认 512。 */
    resolution?: number;
}

/** 唯一缓存 key 构造：`<baseKey>::<resolution>::<aspect>`。 */
export function buildThumbnailKey(input: ThumbnailKeyInput): string {
    const res = input.resolution ?? 512;
    const aspect = input.isStage ? '16/9' : '2/3';
    return `${input.baseKey}::${res}::${aspect}`;
}

/** 便捷：由 kind/type 字符串直接构造完整 key（isStage 判定仍走统一 isStageLike）。 */
function thumbnailKeyForKind(input: {
    libraryPath?: string;
    filePath: string;
    innerPath?: string;
    kind: string;
    resolution?: number;
}): string {
    return buildThumbnailKey({
        baseKey: thumbnailBaseKey(input),
        isStage: isStageLike(input.kind),
        resolution: input.resolution,
    });
}

// [doc:architecture] AnimationRetargeter — 外部动作重定向桥接模块
// 将 Mixamo/VRM/GLB 等外部人形动画重定向到 MMD 骨骼，扩展动作来源。
//
// 工作原理：
// 1. 加载外部动画文件（FBX/GLB/GLTF）→ Babylon.js AnimationGroup
// 2. AnimationRetargeter 重映射骨骼名 → 输出等效 MMD 骨骼动画
// 3. 重定向后的 AnimationGroup 以 additive 模式播放，叠加在 VMD 之上
//
// 与 ADR-061 骨骼映射模块共享 MixamoMmdHumanoidBoneMap / VrmMmdHumanoidBoneMap 预设。

import { AnimationRetargeter } from 'babylon-mmd/esm/Loader/Util/animationRetargeter';
import {
    MixamoMmdHumanoidBoneMap,
    VrmMmdHumanoidBoneMap,
} from 'babylon-mmd/esm/Loader/Util/mmdHumanoidMapper';
import type { AnimationGroup } from '@babylonjs/core/Animations/animationGroup';
import { Scene } from '@babylonjs/core/scene';
import { ImportMeshAsync } from '@babylonjs/core/Loading/sceneLoader';
import { Skeleton } from '@babylonjs/core/Bones/skeleton';
import { modelRegistry } from '@/core/config';
import { feedbackInfo, feedbackStatus } from '@/core/feedback';
import { logWarn } from '@/core/logger';
import { t } from '@/core/i18n/t';

// ======== 类型导出 ========

export type BoneMapPreset = 'mixamo' | 'vrm' | 'custom';

export interface RetargetResult {
    animationGroup: AnimationGroup;
    sourceSkeleton: Skeleton;
    boneMapName: string;
}

/** 当前活跃的 retarget 动画状态（用于场景序列化）。 */
export interface RetargetPlayState {
    /** 动画源文件路径（FBX/GLB/GLTF） */
    filePath: string;
    /** 骨骼映射预设名 */
    boneMapPreset: BoneMapPreset;
}

// ======== 全局状态 ========

let _currentRetarget: RetargetPlayState | null = null;
let _stopCurrentRetarget: (() => void) | null = null;

/** 获取当前活跃的 retarget 动画播放状态，用于场景序列化。 */
export function getRetargetPlayState(): RetargetPlayState | null {
    return _currentRetarget;
}

/** 停止当前 retarget 动画并清理。 */
export function stopCurrentRetarget(): void {
    if (_stopCurrentRetarget) {
        _stopCurrentRetarget();
        _stopCurrentRetarget = null;
    }
    _currentRetarget = null;
}

// ======== 骨骼映射预设 ========

const PRESET_BONE_MAPS: Record<Exclude<BoneMapPreset, 'custom'>, Record<string, string>> = {
    mixamo: MixamoMmdHumanoidBoneMap as unknown as Record<string, string>,
    vrm: VrmMmdHumanoidBoneMap as unknown as Record<string, string>,
};

/** 获取可用骨骼映射预设列表。 */
function getBoneMapPresets(): Array<{ id: string; label: string }> {
    return [
        { id: 'mixamo', label: 'Mixamo' },
        { id: 'vrm', label: 'VRM' },
        { id: 'custom', label: t('motion.retarget.customMap') },
    ];
}

/**
 * 从外部动画文件加载并重定向到 MMD 骨骼。
 *
 * @param scene        Babylon.js 场景
 * @param url          动画文件 URL（FBX/GLB/GLTF）
 * @param targetSkeleton 目标 MMD 模型的骨骼
 * @param boneMapPreset 骨骼映射预设名
 * @param customBoneMap 自定义骨骼映射（仅 preset='custom' 时使用）
 * @returns 重定向后的 AnimationGroup + 源骨骼信息
 */
export async function loadAndRetargetAnimation(
    scene: Scene,
    url: string,
    targetSkeleton: Skeleton,
    boneMapPreset: BoneMapPreset,
    customBoneMap?: Record<string, string>
): Promise<RetargetResult | null> {
    // 1. 加载外部动画文件
    feedbackStatus('motion.retarget.loading', undefined, false);
    let result: {
        meshes: import('@babylonjs/core/Meshes/abstractMesh').AbstractMesh[];
        animationGroups: AnimationGroup[];
    };
    try {
        result = await ImportMeshAsync(url, scene, {
            onProgress: (evt) => {
                if (evt.lengthComputable) {
                    // 可选：显示加载进度
                }
            },
        });
    } catch (err) {
        logWarn('retarget', 'load animation failed:', err);
        feedbackStatus('motion.retarget.loadFailed', undefined, false);
        return null;
    }

    // 2. 提取动画组和源骨骼
    const animationGroups = result.animationGroups;
    if (!animationGroups || animationGroups.length === 0) {
        logWarn('retarget', 'no animation groups found');
        feedbackStatus('motion.retarget.noAnimation', undefined, false);
        _cleanupTempMeshes(result.meshes);
        return null;
    }

    const animationGroup = animationGroups[0];
    // 从加载的网格中查找第一个骨骼
    let sourceSkeleton: Skeleton | null = null;
    for (const mesh of result.meshes) {
        if (mesh.skeleton) {
            sourceSkeleton = mesh.skeleton;
            break;
        }
    }
    if (!sourceSkeleton) {
        logWarn('retarget', 'no skeleton found in loaded file');
        feedbackStatus('motion.retarget.noSkeleton', undefined, false);
        _cleanupTempMeshes(result.meshes);
        return null;
    }

    // 3. 获取骨骼映射
    let boneNameMap: Record<string, string>;
    if (boneMapPreset === 'custom' && customBoneMap) {
        boneNameMap = customBoneMap;
    } else {
        boneNameMap = PRESET_BONE_MAPS[boneMapPreset === 'custom' ? 'mixamo' : boneMapPreset];
    }

    // 4. 执行重定向
    feedbackStatus('motion.retarget.retargeting', undefined, false);
    try {
        const retargeter = new AnimationRetargeter();
        retargeter.setBoneMap(boneNameMap);
        retargeter.setSourceSkeleton(sourceSkeleton);
        retargeter.setTargetSkeleton(targetSkeleton);
        const retargeted = retargeter.retargetAnimation(animationGroup, {
            cloneAnimation: true,
            removeBoneRotationOffset: false,
        });
        if (!retargeted) {
            logWarn('retarget', 'retargetAnimation returned null');
            feedbackStatus('motion.retarget.failed', undefined, false);
            _cleanupTempMeshes(result.meshes);
            return null;
        }
        feedbackInfo('motion.retarget.success', undefined);
        // retarget 成功且 cloneAnimation:true 后，源 mesh 不再需要（动画已克隆到目标骨骼）
        _cleanupTempMeshes(result.meshes);
        return {
            animationGroup: retargeted,
            sourceSkeleton,
            boneMapName: boneMapPreset,
        };
    } catch (err) {
        logWarn('retarget', 'retargetAnimation failed:', err);
        feedbackStatus('motion.retarget.failed', undefined, false);
        _cleanupTempMeshes(result.meshes);
        return null;
    }
}

/**
 * 播放重定向后的动画（additive 模式，叠加在 VMD 之上）。
 * 自动停止前一个 retarget 动画，并保存播放状态供场景序列化使用。
 *
 * @param scene   Babylon.js 场景
 * @param result  重定向结果
 * @param filePath 动画源文件路径（用于状态记录）
 * @param loop    是否循环播放
 * @returns stop 函数
 */
export function playRetargetedAnimation(
    _scene: Scene,
    result: RetargetResult,
    filePath: string,
    loop = true
): () => void {
    // 停止前一个 retarget 动画
    stopCurrentRetarget();

    const { animationGroup, boneMapName } = result;
    animationGroup.isAdditive = true;
    animationGroup.weight = 1;
    animationGroup.play(loop);

    // 保存状态
    _currentRetarget = {
        filePath,
        boneMapPreset: boneMapName as BoneMapPreset,
    };

    let stopped = false;
    _stopCurrentRetarget = () => {
        if (stopped) {
            return;
        }
        stopped = true;
        animationGroup.stop();
        animationGroup.dispose();
        _currentRetarget = null;
        _stopCurrentRetarget = null;
    };

    return _stopCurrentRetarget;
}

/** 清理加载动画时创建的临时网格。 */
function _cleanupTempMeshes(
    meshes: import('@babylonjs/core/Meshes/abstractMesh').AbstractMesh[]
): void {
    for (const mesh of meshes) {
        mesh.dispose();
    }
}

/**
 * 从已加载的模型恢复 retarget 动画（场景反序列化用）。
 * 自动停止前一个 retarget 动画，查找目标模型的骨骼，加载并播放。
 *
 * @param filePath      动画源文件路径
 * @param boneMapPreset 骨骼映射预设
 * @param modelId       目标模型运行时 ID
 * @returns 恢复成功返回 true
 */
export async function restoreRetargetAnimation(
    filePath: string,
    boneMapPreset: BoneMapPreset,
    modelId: string
): Promise<boolean> {
    const inst = modelRegistry.get(modelId);
    if (!inst || !inst.mmdModel) {
        logWarn('retarget', 'restore: model not found or no mmdModel, id=', modelId);
        return false;
    }

    const mesh = inst.mmdModel.mesh;
    if (!mesh || !mesh.skeleton) {
        logWarn('retarget', 'restore: model has no skeleton, id=', modelId);
        return false;
    }

    const scene = mesh.getScene();
    const result = await loadAndRetargetAnimation(scene, filePath, mesh.skeleton, boneMapPreset);
    if (!result) {
        return false;
    }

    playRetargetedAnimation(scene, result, filePath);
    return true;
}

// [doc:architecture] Bone Override — 逐骨骼覆盖系统
// 职责: 维护 overrideMap，在动画后逐骨骼覆盖局部旋转，支持 Quaternion.Slerp 混合
// 与 ADR-051 boneFilter 互补：boneFilter=屏蔽动画，Override=设定目标值
// 依赖: scene.ts (懒加载避免循环依赖)

import { Quaternion, Matrix, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';
import type { MmdRuntimeBoneExtended } from '@/core/types';
import { clamp01 } from '@/core/clamp';
import { triggerAutoSave } from '@/core/config';
import { observe, type ObserverHandle } from '@/core/observer-handle';
import { safeDispose } from '@/core/dispose-helpers';
import { getMotionPipeline } from './motion-pipeline';
import { focusedModelId } from '@/core/state';
import { isWasmRuntime, feetDebug } from './perception-shared';
import { logInfo, logWarn } from '@/core/logger';
import {
    matchBone,
    BONE_LEG_IK_L_CANDIDATES,
    BONE_LEG_IK_R_CANDIDATES,
} from '@/motion-algos/proc-motion-shared';

/** 持久化的单条骨骼覆盖配置 */
export type BoneOverrideEntry = {
    boneName: string;
    /** 欧拉角（度），[pitch, yaw, roll] */
    euler: [number, number, number];
    /** 混合权重 0–1，1=硬覆盖 */
    weight: number;
    /** 启用/禁用 */
    enabled: boolean;
    /** [doc:adr-116] 可选位置覆盖 [x, y, z]（P2 引擎扩展，支持 height/fwdBack 等语义参数） */
    position?: [number, number, number];
    /** [doc:adr-123 P1] 绝对覆盖模式：true=替换 oldRotation，false/undefined=复合 */
    absolute?: boolean;
};

/** 运行时缓存：四元数 + 混合参数 + 可选位置 */
interface _OverrideSlot {
    quat: Quaternion;
    weight: number;
    enabled: boolean;
    /** [doc:adr-116] 可选位置覆盖（P2 引擎扩展）。undefined=不动位置，沿用动画值 */
    pos?: Vector3;
    /**
     * [doc:adr-116 P1] 是否覆盖动画旋转。
     * - true：按 weight 混合/硬覆盖旋转（setBoneOverride / setBoneOverrideQuat 设置）
     * - false：沿用动画旋转，仅叠加位置偏移（setBoneOverridePosition 设置）
     * undefined 视为 false（安全默认：绝不静默抹除动画旋转）
     */
    overrideRotation?: boolean;
    /**
     * [doc:adr-123 P1] 绝对覆盖模式。
     * - true：weight≥1 时完全替换 oldRotation（不复合父骨传播）
     * - false/undefined：复合模式（默认，oldRotation × slot.quat）
     * 仅 weight≥1 时生效；weight<1 时始终走 Slerp。
     *
     * ⚠️ 警告：absolute=true 会丢弃父骨传播的旋转变换，若用于**中间层级骨骼**
     * （如「上半身」「左肩」），子骨（腕、手）的传播可能产生视觉跳跃。
     * 建议仅对**叶骨**（如「左腕」「左目」）使用 absolute 模式，中间骨保持
     * 复合模式（absolute=false/undefined）以确保骨骼链完整。（审计 P2 风险）
     */
    absolute?: boolean;
}

// ── 管理器（per-model） ──

let _observerHandle: (() => void) | null = null; // 已注册层的 unregister 句柄
let _driverHandle: ObserverHandle | null = null; // 单一驱动 observer 句柄
let _driverScene: import('@babylonjs/core/scene').Scene | null = null; // 驱动所绑定的 scene（随重建更新）
const _overrideMaps = new Map<string, Map<string, _OverrideSlot>>();
/** 运行时骨骼查询回调（由 startBoneOverride 注入，供 dumpBoneHierarchy 使用） */
let _getRuntimeBones: (() => readonly IMmdRuntimeBone[]) | null = null;
/**
 * [ADR-202 A-class] WASM IK 重解回调（由 scene 注入）。
 * WASM 模式下 MmdWasmRuntimeBone 无 ikSolver 字段（仅有 ikSolverIndex），
 * applyBoneOverrideIK 在 ikSolver 缺失时经此回调调用 mmdModelSolveIk 导出重解 IK。
 * 签名：(modelId, ikSolverIndex, usePhysics) => void；null=未注入（JS 模式或未初始化）。
 */
let _wasmIkResolver:
    ((modelId: string, ikSolverIndex: number, usePhysics: boolean) => void) | null = null;

/**
 * [ADR-202 §六] WASM IK 重解守护：检测同帧内同一 (modelId, ikSolverIndex) 重复调用。
 * 仅在 feetDebug.value=true 时启用。日志节流：每帧最多 warn 1 次 + 每 2 秒最多 1 条，
 * 避免刷爆控制台（互斥被持续破坏时，60fps 下每秒最多 0.5 条 warn）。
 * 互斥不变量由编排层保证（POS slot 有覆盖 → feet-adjustment skip），守护是运行时断言，
 * 触发即说明编排层互斥被破坏。
 */
const _ikResolveFrameLog = new Map<string, number>();
let _ikResolveWarnSuppressed = false;
let _ikResolveLastWarnTime = 0;
const _IK_RESOLVE_WARN_INTERVAL_MS = 2000; // 时间窗口节流：2 秒最多 1 条 warn

/** 帧首重置守护状态（bone-override callback order=0 调用，覆盖整个 bone-override stage） */
function _resetIkResolveGuard(): void {
    if (_ikResolveFrameLog.size > 0) {
        _ikResolveFrameLog.clear();
    }
    _ikResolveWarnSuppressed = false;
}

/** 包装 resolver：feetDebug 开启时检测同帧重复调用，双重节流（帧内 1 条 + 时间窗口 2 秒 1 条） */
function _guardedResolve(
    raw: (modelId: string, ikSolverIndex: number, usePhysics: boolean) => void,
    modelId: string,
    ikSolverIndex: number,
    usePhysics: boolean
): void {
    if (feetDebug.value) {
        const key = `${modelId}:${ikSolverIndex}`;
        const prev = _ikResolveFrameLog.get(key) ?? 0;
        if (prev >= 1 && !_ikResolveWarnSuppressed) {
            const now = performance.now();
            if (now - _ikResolveLastWarnTime >= _IK_RESOLVE_WARN_INTERVAL_MS) {
                logWarn(
                    'bone-override',
                    `[守护] 同帧重复调用 mmdModelSolveIk: model=${modelId} ikIdx=${ikSolverIndex} ` +
                        `(第 ${prev + 1} 次)。互斥不变量被破坏：检查 bone-override POS slot 与 ` +
                        'feet-adjustment 是否同时激活（应满足 POS slot 有覆盖 → feet-adjustment skip）'
                );
                _ikResolveLastWarnTime = now;
            }
            _ikResolveWarnSuppressed = true; // 本帧后续不再 warn
        }
        _ikResolveFrameLog.set(key, prev + 1);
    }
    raw(modelId, ikSolverIndex, usePhysics);
}
/** [doc:adr-116 P3] 每帧钩子条目：由时间驱动模块（riding/left-hand/right-hand）注册，渲染回调每帧调用。
 *  原实现用 Set 按插入序遍历，钩子间同骨获胜者依赖模块注册次序（隐式定序，R2 病灶）。
 *  改为带 order 的数组并按 order 升序执行，顺序由声明决定，与注册时序解耦。 */
/** 帧钩子条目（含注册来源信息，供 UI 查询） */
interface _FrameHookEntry {
    order: number;
    /** 注册来源模块名（用于 UI 管线时序一览展示） */
    source: string;
    hook: (timeSec: number, modelId: string) => void;
}
const _frameHooks: _FrameHookEntry[] = [];
let _frameHooksSorted = false;
const _qPool = [new Quaternion(), new Quaternion(), new Quaternion(), new Quaternion()];
let _qIdx = 0;

// JS 路径弃用标志：每个 session 最多 warn 一次，避免每帧 flood 控制台
let _jsPathWarned = false;
// 覆盖着色诊断标志：首次调用 getOverrideType 时输出一次诊断信息
let _overrideTypeDiagnosed = false;
function _q(): Quaternion {
    return _qPool[_qIdx++ % _qPool.length];
}

// ── Matrix / Vector3 复用池（WASM 路径，消除每帧 Matrix.FromArray / new Matrix 分配） ──
// 所有 _m() / _v() 调用必须在同一帧的 callback 内完成，帧首 _mReset() / _vReset() 重置计数器。
// 池大小 8192 = 5 根覆盖骨 × (3 主路径 + 4 × ~400 子骨传播)，安全覆盖任何 MMD 模型。
// 若 _mIdx 溢出则回绕并 warn（安全兜底，不应发生）。
const _mPool = Array.from({ length: 8192 }, () => new Matrix());
let _mIdx = 0;
function _m(): Matrix {
    if (_mIdx >= _mPool.length) {
        console.warn('[bone-override] _mPool 溢出，回绕。请增大池大小。');
        _mIdx = 0;
    }
    return _mPool[_mIdx++];
}
function _mReset(): void {
    _mIdx = 0;
}

const _vPool = Array.from({ length: 8 }, () => new Vector3());
let _vIdx = 0;
function _v(): Vector3 {
    return _vPool[_vIdx++ % _vPool.length];
}
function _vReset(): void {
    _vIdx = 0;
}

/** 复用常量，避免 Matrix.ComposeToRef 每次 new Vector3(1,1,1) */
const _ONE = new Vector3(1, 1, 1);

/** 懒加载获取指定模型的 override map */
function _getOverrideMap(modelId: string): Map<string, _OverrideSlot> {
    let map = _overrideMaps.get(modelId);
    if (!map) {
        map = new Map();
        _overrideMaps.set(modelId, map);
        logInfo(
            'bone-override',
            '_getOverrideMap 首次为模型创建覆盖索引',
            JSON.stringify({
                modelId,
                existingModels: Array.from(_overrideMaps.keys()),
            })
        );
        // 重置诊断标志，允许 getOverrideType 在写入后重新输出诊断信息
        _overrideTypeDiagnosed = false;
    }
    return map;
}

// ── 工具：欧拉角 → 四元数（ZYX 顺序：yaw→pitch→roll） ──
// Babylon Euler 顺序：Quaternion.FromEulerAngles(pitch, yaw, roll) = YXZ
// MMD 惯例用 ZXY，但为 UI 直观用 Babylon 默认 YXZ
function _eulerToQuat(pitchDeg: number, yawDeg: number, rollDeg: number): Quaternion {
    return Quaternion.FromEulerAngles(
        (pitchDeg * Math.PI) / 180,
        (yawDeg * Math.PI) / 180,
        (rollDeg * Math.PI) / 180
    );
}

// ── WASM 运行时辅助 ──
// isWasmRuntime 已迁移至 perception-shared.ts，被本文件 + 感知层共用

/**
 * 递归传播子骨骼变换（WASM 模式）。
 * 覆盖父骨骼后需更正子骨骼的 worldMatrix 以维持相对变换。
 */
function _propagateChildrenWasm(
    parent: IMmdRuntimeBone,
    parentOldMat: Matrix,
    parentNewMat: Matrix
): void {
    // 用 Matrix.invert 太贵，改为：localMat = childOldMat × parentOld⁻¹
    // 使用 Matrix 运算
    const invMat = _m();
    invMat.copyFrom(parentOldMat);
    invMat.invert();
    for (const child of parent.childBones) {
        const childBuf = (child as MmdRuntimeBoneExtended).worldMatrix;
        if (!childBuf) {
            continue;
        }
        const childOldMat = _m();
        Matrix.FromArrayToRef(childBuf, 0, childOldMat);
        const localMat = _m();
        childOldMat.multiplyToRef(invMat, localMat);
        const childNewMat = _m();
        localMat.multiplyToRef(parentNewMat, childNewMat);
        // 写回 worldMatrix buffer（copyToArray 避免 new Float32Array 分配）
        childNewMat.copyToArray(childBuf, 0);
        _propagateChildrenWasm(child, childOldMat, childNewMat);
    }
}

// ── 纯函数：单槽覆盖合成（P1 抽离，便于单元测试） ──

/** 覆盖槽的最小形态，供 _computeOverride 接收（与内部 _OverrideSlot 结构兼容） */
export interface OverrideSlotLike {
    quat: Quaternion;
    weight: number;
    pos?: Vector3;
    overrideRotation?: boolean;
    /** [doc:adr-123 P1] 绝对覆盖模式：true=替换 oldRotation，false/undefined=复合 */
    absolute?: boolean;
}

/**
 * [doc:adr-116 P1] 计算单槽覆盖后的平移与旋转。
 * - 平移：slot.pos 存在时 = 动画平移 + 偏移（加法语义）；否则沿用动画平移。
 * - 旋转：仅当 overrideRotation 为 true 才覆盖；否则沿用动画旋转。
 * - [doc:adr-123 P1] absolute 模式：weight≥1 且 absolute=true 时完全替换 oldRotation。
 * 抽离为纯函数，无需真实骨骼运行时即可单测。
 */
export function computeOverride(
    oldTranslation: Vector3,
    oldRotation: Quaternion,
    slot: OverrideSlotLike
): { translation: Vector3; rotation: Quaternion } {
    const translation = slot.pos ? oldTranslation.add(slot.pos) : oldTranslation;
    const rotation = slot.overrideRotation
        ? slot.weight >= 1
            ? slot.absolute
                ? slot.quat // 绝对覆盖：完全替换 oldRotation（不复合父骨传播）
                : oldRotation.multiply(slot.quat) // 复合：父骨传播旋转 × 本骨覆盖，不丢失父骨变换
            : Quaternion.Slerp(oldRotation, slot.quat, slot.weight)
        : oldRotation;
    return { translation, rotation };
}

// ── 核心 API ──
// 所有 API 均支持可选 modelId 参数，不传则作用于当前聚焦模型。
// 内部使用 per-model Map 存储，避免多模型场景下互相串扰。

function _resolveModelId(modelId?: string): string | null {
    if (modelId) {
        return modelId;
    }
    // 懒加载 focusedModelId（避免静态循环依赖，已从 @/core/state 直接导入）
    return focusedModelId ?? null;
}

/**
 * 设置单条骨骼覆盖。
 * @param boneName 目标骨骼名
 * @param euler 欧拉角（度）[pitch, yaw, roll]
 * @param weight 混合权重 0–1
 * @param enabled 是否启用
 * @param modelId 目标模型 ID（可选，默认聚焦模型）
 */
export function setBoneOverride(
    boneName: string,
    euler: [number, number, number],
    weight: number,
    enabled = true,
    modelId?: string,
    /** [doc:adr-123 P1] 绝对覆盖模式：true=替换 oldRotation，false/undefined=复合 */
    absolute?: boolean
): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    const map = _getOverrideMap(mid);
    const existing = map.get(boneName);
    map.set(boneName, {
        quat: _eulerToQuat(euler[0], euler[1], euler[2]),
        weight: clamp01(weight),
        enabled,
        // [doc:adr-116 P1] 保留既有位置覆盖，避免旋转覆盖静默清除位置
        pos: existing?.pos,
        overrideRotation: true,
        absolute,
    });
}

/**
 * [doc:adr-122 P1] IK 感知的骨骼覆盖。
 * 先写入骨骼覆盖（同 setBoneOverride），再检测该骨骼是否挂载 IK 求解器，
 * 若有则调用 ikSolver.solve() 重解 IK，使覆盖与 IK 解算器协调。
 * 无 IK 求解器时回退为普通覆盖，不报错。
 *
 * @param getRuntimeBones 返回模型运行时骨骼列表的回调（由调用方注入，避免循环依赖）
 */
export function applyBoneOverrideIK(
    boneName: string,
    euler: [number, number, number],
    weight: number,
    enabled = true,
    modelId?: string,
    getRuntimeBones?: () => readonly IMmdRuntimeBone[]
): void {
    // 1. 写入骨骼覆盖（同 setBoneOverride 语义）
    setBoneOverride(boneName, euler, weight, enabled, modelId);

    // 2. 检测 IK 求解器，有则重解
    if (!getRuntimeBones) {
        return;
    }
    const bones = getRuntimeBones();
    const rb = bones.find((b) => b.name === boneName);
    if (rb) {
        const solver = (rb as MmdRuntimeBoneExtended).ikSolver;
        if (solver) {
            solver.solve(false);
        } else if (_wasmIkResolver) {
            // [ADR-202 A-class] WASM 模式：ikSolver 字段缺失，改用 ikSolverIndex 经 mmdModelSolveIk 导出重解
            const resolvedMid = _resolveModelId(modelId);
            if (resolvedMid) {
                const ikSolverIndex = (rb as { ikSolverIndex?: number }).ikSolverIndex;
                if (typeof ikSolverIndex === 'number' && ikSolverIndex >= 0) {
                    _wasmIkResolver(resolvedMid, ikSolverIndex, false);
                }
            }
        }
    }
}

/**
 * 设置单条骨骼覆盖（直接传四元数）。
 */
export function setBoneOverrideQuat(
    boneName: string,
    quat: Quaternion,
    weight: number,
    enabled = true,
    modelId?: string
): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    const map = _getOverrideMap(mid);
    const existing = map.get(boneName);
    map.set(boneName, {
        quat: quat.clone(),
        weight: clamp01(weight),
        enabled,
        // [doc:adr-116 P1] 保留既有位置覆盖，避免旋转覆盖静默清除位置
        pos: existing?.pos,
        overrideRotation: true,
    });
}

/**
 * [doc:adr-116] 设置单条骨骼的位置覆盖（P2 引擎扩展）。
 * 保留现有旋转覆盖（若已有 slot），仅更新 pos 字段。
 * 用于 body-posture 的 height/fwdBack 等需要位置偏移的语义参数。
 *
 * @param boneName 目标骨骼名
 * @param position 位置 [x, y, z]
 * @param weight 混合权重 0–1（当前实现为硬覆盖，权重保留用于未来插值扩展）
 * @param enabled 是否启用
 * @param modelId 目标模型 ID（可选，默认聚焦模型）
 */
export function setBoneOverridePosition(
    boneName: string,
    position: [number, number, number],
    weight: number,
    enabled = true,
    modelId?: string
): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    const map = _getOverrideMap(mid);
    let slot = map.get(boneName);
    if (!slot) {
        // 新建 slot：旋转用 Identity 且 overrideRotation=false（不覆盖动画旋转），仅叠加位置偏移
        slot = {
            quat: Quaternion.Identity(),
            weight: clamp01(weight),
            enabled,
            overrideRotation: false,
        };
        map.set(boneName, slot);
    }
    slot.pos = new Vector3(position[0], position[1], position[2]);
    slot.weight = clamp01(weight);
    slot.enabled = enabled;
    // overrideRotation 保持原值：若既有 slot 由 setBoneOverride 创建（旋转覆盖）则保留 true；
    // 若本就为位置覆盖则保持 false。勿在此处强制赋值，以免破坏「旋转+位置」组合覆盖。
}

/** 清除指定骨骼的覆盖。 */
export function clearBoneOverride(boneName: string, modelId?: string): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    _getOverrideMap(mid).delete(boneName);
}

/** [doc:adr-116] 将运行时 slot 转为持久化条目（getOverride / getAllOverrides 共用，避免重复反推欧拉角） */
function _slotToEntry(boneName: string, slot: _OverrideSlot): BoneOverrideEntry {
    const euler = slot.quat.toEulerAngles();
    return {
        boneName,
        euler: [(euler.x * 180) / Math.PI, (euler.y * 180) / Math.PI, (euler.z * 180) / Math.PI],
        weight: slot.weight,
        enabled: slot.enabled,
        position: slot.pos ? [slot.pos.x, slot.pos.y, slot.pos.z] : undefined,
        // [doc:adr-123 P1] 序列化 absolute 标志
        absolute: slot.absolute,
    };
}

/** [doc:adr-116] 读取单条骨骼的覆盖条目（用于 UI 回填）。不存在返回 undefined。 */
export function getOverride(boneName: string, modelId?: string): BoneOverrideEntry | undefined {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return undefined;
    }
    const slot = _overrideMaps.get(mid)?.get(boneName);
    if (!slot) {
        return undefined;
    }
    return _slotToEntry(boneName, slot);
}

/** 骨骼覆盖类型（零分配，适合每帧查询） */
export type OverrideType = 'rotation' | 'position' | 'both';

/**
 * 查询骨骼覆盖类型（零分配）。
 * 与 getOverride 的区别：不创建 BoneOverrideEntry 对象，仅返回覆盖类型枚举，
 * 适合在渲染循环 / bone overlay updateFn 中每帧高频调用。
 *
 * @returns 覆盖类型，未覆盖时返回 null
 */
export function getOverrideType(boneName: string, modelId?: string): OverrideType | null {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return null;
    }
    const map = _overrideMaps.get(mid);
    const slot = map?.get(boneName);

    // 诊断：首次调用时输出完整状态，定位着色失效根因。
    // 重置后（覆盖写入触发）允许再次输出，以捕获写入前后的状态差异。
    if (!_overrideTypeDiagnosed) {
        _overrideTypeDiagnosed = true;
        const modelKeys = Array.from(_overrideMaps.keys());
        const entryCount = map?.size ?? 0;
        const entrySample = map
            ? Array.from(map.entries())
                  .slice(0, 5)
                  .map(
                      ([k, s]) =>
                          `${k}(enabled=${s.enabled},rot=${s.overrideRotation},pos=${!!s.pos})`
                  )
            : [];
        logInfo(
            'bone-override',
            'getOverrideType 诊断',
            JSON.stringify(
                {
                    queryModelId: mid,
                    queryBone: boneName,
                    allMapKeys: modelKeys,
                    modelKeyMatch: modelKeys.includes(mid),
                    entriesInMap: entryCount,
                    entrySample,
                    slotFound: !!slot,
                    slotEnabled: slot?.enabled,
                    slotRot: slot?.overrideRotation,
                    slotPos: !!slot?.pos,
                },
                null,
                2
            )
        );
    }

    if (!slot?.enabled) {
        return null;
    }
    if (slot.overrideRotation && slot.pos) {
        return 'both';
    }
    if (slot.overrideRotation) {
        return 'rotation';
    }
    if (slot.pos) {
        return 'position';
    }
    return null;
}

/** 清除所有骨骼覆盖。 */
export function clearAllOverrides(modelId?: string): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    _getOverrideMap(mid).clear();
}

// ── IK 位置保护：防止父骨传播覆盖 IK 目标的世界坐标 ──

/**
 * 受保护的骨骼名称集合（每帧重置）。
 * 帧钩子在 _runFrameHooks 期间注册，主循环传播后恢复。
 */
const _protectedIkBoneNames = new Set<string>();

/**
 * 注册骨骼位置保护（帧钩子内调用）。
 * 主循环完成传播后，被保护骨骼的 worldMatrix 将恢复到覆盖前的值。
 * 用于 body-posture 移动センター时防止足 IK 目标跟随平移。
 */
export function protectIkPosition(boneName: string): void {
    _protectedIkBoneNames.add(boneName);
}

/** 快照受保护骨骼的当前 worldMatrix（帧钩子后、覆盖循环前调用） */
function _snapshotProtectedPositions(
    boneMap: Map<string, IMmdRuntimeBone>
): Map<string, Float32Array> {
    const snapshots = new Map<string, Float32Array>();
    for (const boneName of _protectedIkBoneNames) {
        const rb = boneMap.get(boneName);
        if (!rb) {
            continue;
        }
        const buf = (rb as MmdRuntimeBoneExtended).worldMatrix;
        if (buf) {
            const snap = new Float32Array(16);
            snap.set(buf.subarray(0, 16));
            snapshots.set(boneName, snap);
        }
    }
    return snapshots;
}

/** 恢复受保护骨骼的 worldMatrix（覆盖循环后调用） */
function _restoreProtectedPositions(
    boneMap: Map<string, IMmdRuntimeBone>,
    snapshots: Map<string, Float32Array>,
    overrideMap: Map<string, _OverrideSlot>
): void {
    for (const [boneName, snap] of snapshots) {
        const rb = boneMap.get(boneName);
        if (!rb) {
            continue;
        }
        const buf = (rb as MmdRuntimeBoneExtended).worldMatrix;
        if (!buf) {
            continue;
        }

        const slot = overrideMap.get(boneName);
        if (slot?.enabled && slot.pos) {
            // 受保护骨骼自身有位置覆盖（如 foot-modules 的 footPosX/Y/Z）。
            // 需要的结果是「动画位置 + slot.pos」：
            // snapshotT = 覆盖前的位置（= 动画位置）
            // finalT = snapshotT + slot.pos
            // 旋转保持快照值。
            const snapshotT = _v();
            Matrix.FromArrayToRef(snap, 0, _m()).getTranslationToRef(snapshotT);
            const finalT = snapshotT.add(slot.pos);
            buf[12] = finalT.x;
            buf[13] = finalT.y;
            buf[14] = finalT.z;
            const rotMat = _m();
            Matrix.FromArrayToRef(snap, 0, _m()).getRotationMatrixToRef(rotMat);
            const oldQ = _q();
            Quaternion.FromRotationMatrixToRef(rotMat, oldQ);
            const newMat = _m();
            Matrix.ComposeToRef(_ONE, oldQ, finalT, newMat);
            newMat.copyToArray(buf, 0);
        } else {
            // 无自身覆盖：直接恢复到动画位置（完全撤销传播）
            buf.set(snap);
        }
    }
}

// ── [ADR-202 §六] WASM POS slot IK 重解（方案A，原方案C 已淘汰）──
// WASM 模式下 babylon-mmd 的 IkSolver 不可用（ikSolver 字段为 null），
// 脚部位置偏移写入 IK 目标骨后，髋、膝旋转不会跟随重解。
// 本函数在主循环 _restoreProtectedPositions 之后调用，
// 对所有有启用的位置覆盖的 IK 目标骨，经 mmdModelSolveIk 重解原生 IK 链。

/** IK 目标骨候选名（左右足IK），用于识别哪些 slot 需要 IK 重解 */
const _IK_TARGET_CANDIDATES = [BONE_LEG_IK_L_CANDIDATES, BONE_LEG_IK_R_CANDIDATES];

/**
 * [ADR-202 §六] WASM 模式 POS slot IK 重解。
 *
 * 触发条件：isWasm && IK 目标骨有启用的 slot.pos。
 * 对每个有位置覆盖的 IK 目标骨，读其 ikSolverIndex，调 _wasmIkResolver 重解原生 IK 链。
 * mmdModelSolveIk 内部会读 IK 目标骨的 worldMatrix（已含 slot.pos 偏移）作为目标，
 * 解出髋/膝/踝旋转并回写全链 worldMatrix。
 */
function _solvePosSlotIkWasm(
    boneMap: Map<string, IMmdRuntimeBone>,
    overrideMap: Map<string, _OverrideSlot>,
    modelId: string
): void {
    if (!_wasmIkResolver) {
        return;
    }

    const boneNames = Array.from(boneMap.keys());
    for (const cands of _IK_TARGET_CANDIDATES) {
        const ikBoneName = matchBone(boneNames, cands as string[]);
        if (!ikBoneName) {
            continue;
        }
        const slot = overrideMap.get(ikBoneName);
        // 仅在 IK 目标骨有启用的位置覆盖时重解（纯旋转覆盖不触发）
        if (!slot?.enabled || !slot.pos) {
            continue;
        }
        const ikBone = boneMap.get(ikBoneName);
        if (!ikBone) {
            continue;
        }
        const ikSolverIndex = (ikBone as { ikSolverIndex?: number }).ikSolverIndex;
        if (typeof ikSolverIndex === 'number' && ikSolverIndex >= 0) {
            _wasmIkResolver(modelId, ikSolverIndex, false);
        }
    }
}

/**
 * [doc:adr-116 P3] 注册每帧渲染钩子。
 * 时间驱动模块（riding/left-hand/right-hand）用以逐帧更新自身骨骼覆盖（如踏板循环、手臂位置偏移）。
 * 钩子签名 (timeSec, modelId)：timeSec 为 performance.now()/1000（秒）。
 * 返回注销函数，模块 disable/卸载时必须调用以避免泄漏。
 *
 * @param order 同帧内执行序（升序优先）。治理 R2：取代原 Set 插入序的隐式定序，
 *   使「同骨获胜者」由声明顺序决定，不依赖模块注册先后。建议从 {@link FRAME_HOOK_ORDER} 取值。
 */
export const FRAME_HOOK_ORDER = {
    /** 脚部位置偏移：脚部 IK 位置，最先写入（bake 写旋转后由帧钩子写位置） */
    FEET: 0,
    /** 身体位置偏移（センター 平移）：最基础的身体变换 */
    BODY_POSITION: 5,
    /** 下肢/骑行踏板：身体基础姿态 */
    RIDING: 10,
    /** 身体摇摆：在下肢之上叠加 */
    SWAY: 20,
    /** 手部对称：上肢末端，最后写入 */
    HAND_SYMMETRY: 30,
} as const;

export function registerBoneOverrideFrameHook(
    hook: (timeSec: number, modelId: string) => void,
    order = 0,
    source = '(anonymous)'
): () => void {
    const entry: _FrameHookEntry = { order, source, hook };
    _frameHooks.push(entry);
    _frameHooksSorted = false;
    return () => {
        const idx = _frameHooks.indexOf(entry);
        if (idx >= 0) {
            _frameHooks.splice(idx, 1);
        }
    };
}

/** 帧钩子快照（供 UI 查询管线时序一览） */
export interface FrameHookSnapshot {
    order: number;
    source: string;
}

/** 按 order 升序返回当前注册的所有帧钩子快照（不含 hook 函数本身）。 */
export function getFrameHooksSnapshot(): FrameHookSnapshot[] {
    if (!_frameHooksSorted) {
        _frameHooks.sort((a, b) => a.order - b.order);
        _frameHooksSorted = true;
    }
    return _frameHooks.map((e) => ({ order: e.order, source: e.source }));
}

/** 获取当前所有覆盖的条目列表（用于持久化/UI 展示）。 */
export function getAllOverrides(modelId?: string): BoneOverrideEntry[] {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return [];
    }
    const map = _overrideMaps.get(mid);
    if (!map) {
        return [];
    }
    const result: BoneOverrideEntry[] = [];
    for (const [boneName, slot] of map) {
        if (!slot.enabled) {
            continue;
        }
        result.push(_slotToEntry(boneName, slot));
    }
    return result;
}

/**
 * 从持久化的条目列表批量恢复覆盖。
 */
export function restoreOverrides(entries: BoneOverrideEntry[], modelId?: string): void {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return;
    }
    const map = _getOverrideMap(mid);
    map.clear();
    for (const e of entries) {
        map.set(e.boneName, {
            quat: _eulerToQuat(e.euler[0], e.euler[1], e.euler[2]),
            weight: clamp01(e.weight),
            enabled: e.enabled,
            pos: e.position ? new Vector3(e.position[0], e.position[1], e.position[2]) : undefined,
            // [doc:adr-116 P1] 含位置字段的条目必为位置覆盖（来自 setBoneOverridePosition），
            // 不应覆盖动画旋转；纯旋转条目（手动覆盖）overrideRotation=true。
            overrideRotation: !e.position,
            // [doc:adr-123 P1] 反序列化 absolute 标志
            absolute: e.absolute,
        });
    }
}

// ── 渲染循环钩子 ──

/** [doc:adr-116 P3] 执行每帧钩子（时间驱动模块在此更新自身 slot）。
 *  按 order 升序遍历（治理 R2 隐式定序）；快照遍历以支持钩子执行期间安全注销/注册。 */
function _runFrameHooks(focusedId: string): void {
    const t = performance.now() / 1000;
    if (!_frameHooksSorted) {
        _frameHooks.sort((a, b) => a.order - b.order);
        _frameHooksSorted = true;
    }
    for (const entry of _frameHooks.slice()) {
        entry.hook(t, focusedId);
    }
}

/** WASM 单骨覆盖：直写 worldMatrix（使用池复用，零分配） */
function _applyWasmOverride(slot: _OverrideSlot, rb: IMmdRuntimeBone): void {
    const buf = (rb as MmdRuntimeBoneExtended).worldMatrix;
    if (!buf) {
        return;
    }
    const oldMat = _m();
    Matrix.FromArrayToRef(buf, 0, oldMat);
    const oldT = _v();
    oldMat.getTranslationToRef(oldT);
    const rotMat = _m();
    oldMat.getRotationMatrixToRef(rotMat);
    const oldQ = _q();
    Quaternion.FromRotationMatrixToRef(rotMat, oldQ);
    const { translation, rotation } = computeOverride(oldT, oldQ, slot);
    const newMat = _m();
    Matrix.ComposeToRef(_ONE, rotation, translation, newMat);
    newMat.copyToArray(buf, 0);
    _propagateChildrenWasm(rb, oldMat, newMat);
}

/**
 * JS 单骨覆盖：写 linkedBone rotationQuaternion / position。
 * @deprecated 自 2026-07-25 弃用。JS 路径不递归传播子骨骼（子骨骼 worldMatrix 不跟随），
 *   且在现代运行环境中 WASM 覆盖率接近 100%。保留此函数仅作极端兜底，
 *   任何新开发工作应使用 WASM 路径（`_applyWasmOverride`）。
 *   调试骨骼状态请改用 `dumpBoneHierarchy()` 或控制台 `await window.__dumpBones()`。
 */
function _applyJsOverride(slot: _OverrideSlot, rb: IMmdRuntimeBone): void {
    // IMmdRuntimeBone.linkedBone 已声明为 IMmdRuntimeLinkedBone (duck-typed abstraction)，
    // 但运行时 babylon-mmd MmdRuntimeBone 的 linkedBone 是完整的 Babylon.js Bone 实例。
    // 此处保留一小步类型断言以获取 getSkeleton() 等原生 Bone API。
    // [doc:adr-116 P1] 旋转覆盖使用 linked (IMmdRuntimeLinkedBone) 的 rotationQuaternion,
    //         位置覆盖 / skeleton dirty 用 bone (Babylon Bone) 的 getPosition/setPosition/getSkeleton。
    const linked = rb.linkedBone;
    // 运行时守卫：极边缘情况下 linkedBone 可能为 null（如骨架未完全初始化）

    if (!linked) {
        return;
    }
    const bone = linked as unknown as import('@babylonjs/core/Bones/bone').Bone;

    // [doc:adr-116 P1] 旋转覆盖：复合当前旋转 × 覆盖旋转，不丢失父骨传播变换（与 WASM 路径 _computeOverride 一致）
    if (slot.overrideRotation) {
        const cur = linked.rotationQuaternion ?? Quaternion.Identity();
        if (slot.weight >= 1) {
            linked.rotationQuaternion = cur.multiply(slot.quat);
        } else {
            const target = cur.multiply(slot.quat);
            linked.rotationQuaternion = Quaternion.Slerp(cur, target, slot.weight);
        }
    }

    // 位置覆盖：叠加偏移（加法语义）
    if (slot.pos) {
        const curPos = bone.getPosition();
        curPos.addInPlace(slot.pos);
        bone.setPosition(curPos);
    }

    // 更新骨骼世界矩阵并递归传播子骨骼（与 WASM 路径 _propagateChildrenWasm 等效）
    // force = true 强制父骨变换传播给子骨，避免 JS 路径骨骼链断裂（审计 P3 fix）
    (rb as MmdRuntimeBoneExtended).updateWorldMatrix?.(true, false);

    // 标记脏标记
    const skeleton = bone.getSkeleton();
    skeleton?._markAsDirty?.();
}

/**
 * 启动覆盖系统：注册 onBeforeRenderObservable 回调。
 * 必须在动画写入之后执行，因此注册在 gaze tracking 之后。
 */
/**
 * [ADR-202 A-class] 注入 WASM IK 重解回调。
 * 由 scene 在 startBoneOverride 后调用，注入一个 (modelId, ikSolverIndex, usePhysics) => void
 * 的回调，内部解析 wasmInstance + model.ptr 并调用 mmdModelSolveIk 导出。
 * 传 null 清除（场景销毁时）。
 */
export function setWasmIkResolver(
    resolver: ((modelId: string, ikSolverIndex: number, usePhysics: boolean) => void) | null
): void {
    // [ADR-202 §六] 包装守护：所有调用方（bone-override 内部 + feet-adjustment 经 getWasmIkResolver）
    // 都走 _guardedResolve，统一检测同帧双调用。feetDebug 关闭时守护 no-op（仅多一次 Map.get）。
    if (resolver) {
        _wasmIkResolver = (modelId, ikSolverIndex, usePhysics) =>
            _guardedResolve(resolver, modelId, ikSolverIndex, usePhysics);
    } else {
        _wasmIkResolver = null;
    }
}

/**
 * [ADR-202 §六] 获取 WASM IK 重解回调（供 feet-adjustment 等外部模块调用）。
 * 返回 null 表示未注入（JS 模式或未初始化）。
 */
export function getWasmIkResolver():
    ((modelId: string, ikSolverIndex: number, usePhysics: boolean) => void) | null {
    return _wasmIkResolver;
}

export function startBoneOverride(
    getRuntimeBones: () => readonly IMmdRuntimeBone[],
    scene: import('@babylonjs/core/scene').Scene
): void {
    if (_observerHandle) {
        return;
    } // 已启动

    // 保存回调供 dumpBoneHierarchy 使用
    _getRuntimeBones = getRuntimeBones;

    const callback = () => {
        // 帧首重置 Matrix/Vector3 池（WASM 路径复用，避免每帧分配）
        _mReset();
        _vReset();
        // [ADR-202 §六] 帧首重置 IK 重解守护状态（覆盖整个 bone-override stage，含 feet-adjustment order=5）
        _resetIkResolveGuard();

        // 只对当前聚焦模型生效（per-model 存储，单模型应用）
        const focusedId = _resolveModelId();
        if (!focusedId) {
            return;
        }

        _runFrameHooks(focusedId);

        const overrideMap = _overrideMaps.get(focusedId);
        if (!overrideMap || overrideMap.size === 0) {
            return;
        }
        const bones = getRuntimeBones();
        if (bones.length === 0) {
            return;
        }

        // 构建 boneName → bone 索引（O(1) 查找，替代 O(n²) bones.find）
        const boneMap = new Map<string, IMmdRuntimeBone>();
        for (const b of bones) {
            boneMap.set(b.name, b);
        }
        const isWasm = isWasmRuntime(bones[0]);

        // 非 WASM 运行时：一次性弃用警告 + 替代调试路径提示
        if (!isWasm && !_jsPathWarned) {
            _jsPathWarned = true;
            console.warn(
                '[bone-override] JS 骨骼覆盖路径已弃用，当前运行在非 WASM 模式下。' +
                    'JS 路径不递归传播子骨骼，可能导致骨骼链断裂。' +
                    '调试骨骼状态请使用控制台：await window.__dumpBones()'
            );
        }

        // IK 位置保护：快照受保护骨骼的原始 worldMatrix（帧钩子已注册保护集合）
        const ikSnapshots = isWasm ? _snapshotProtectedPositions(boneMap) : null;

        for (const [boneName, slot] of overrideMap) {
            if (!slot.enabled) {
                continue;
            }
            const rb = boneMap.get(boneName);
            if (!rb) {
                continue;
            }
            if (isWasm) {
                _applyWasmOverride(slot, rb);
            } else {
                _applyJsOverride(slot, rb);
            }
        }

        // IK 位置保护：恢复受保护骨骼的 worldMatrix（撤销传播造成的偏移）
        if (ikSnapshots && ikSnapshots.size > 0) {
            _restoreProtectedPositions(boneMap, ikSnapshots, overrideMap);
        }

        // [ADR-202 §六] WASM POS slot IK 重解（方案A）：
        // IK 目标骨位置已确定（动画位置 + slot.pos），但 WASM 内部 IK 不会重解。
        // 经 mmdModelSolveIk 重解原生 IK 链，让髋/膝/踝跟随 IK 目标骨偏移。
        // JS 运行时由原版 IkSolver.solve() 处理，无需手动求解。
        if (isWasm) {
            _solvePosSlotIkWasm(boneMap, overrideMap, focusedId);
        }

        _protectedIkBoneNames.clear();
    };

    // 单一驱动 observer：每帧按 (stage, order) 显式调度所有骨骼写入层，
    // 取代原先 bone-override 与 perception 各自注册 onBeforeRenderObservable 的隐式定序（治理 R1）
    if (!_driverHandle || _driverScene !== scene) {
        _driverHandle = safeDispose(_driverHandle);
        _driverScene = scene;
        _driverHandle = observe(scene.onBeforeRenderObservable, () =>
            getMotionPipeline().runFrame({ scene })
        );
    }
    _observerHandle = getMotionPipeline().register({
        id: 'bone-override',
        stage: 'bone-override',
        order: 0,
        run: callback,
    });
}

/** 停止覆盖系统。 */
export function stopBoneOverride(): void {
    if (_observerHandle) {
        _observerHandle();
        _observerHandle = null;
    }
    // 释放单一驱动 observer，避免 stop 后每帧仍触发 runFrame（残留旧场景 observer 泄漏；ADR-147 审核 P2）
    _driverHandle = safeDispose(_driverHandle);
    _driverScene = null;
    _frameHooks.length = 0;
    _frameHooksSorted = false;
    _jsPathWarned = false;
    _overrideTypeDiagnosed = false;
    _getRuntimeBones = null;
    _wasmIkResolver = null;
    // 清空前自动保存当前覆盖配置，避免场景重建时丢失未存盘的覆盖修改（审计 P3 fix）
    triggerAutoSave();
    clearAllOverrides();
}

// ── 调试工具 ──

/** 单根骨骼的层级与覆盖状态（dumpBoneHierarchy 输出元素） */
export interface BoneHierarchyNode {
    /** 骨骼在 runtimeBones 数组中的索引 */
    index: number;
    /** 骨骼名称 */
    name: string;
    /** 父骨骼的索引，-1 表示根骨骼 */
    parentIndex: number;
    /** 子骨骼数量 */
    childCount: number;
    /** 是否挂载 IK 求解器 */
    hasIkSolver: boolean;
    /** 是否受物理驱动（transformAfterPhysics） */
    afterPhysics: boolean;
    /** 当前是否被覆盖 */
    isOverridden: boolean;
    /** 当前覆盖条目（仅 isOverridden 时存在） */
    overrideEntry?: BoneOverrideEntry;
}

/** 骨骼层级导出结果 */
export interface BoneHierarchyDump {
    modelId: string;
    timestamp: string;
    totalBones: number;
    totalOverridden: number;
    bones: BoneHierarchyNode[];
}

/**
 * 导出当前聚焦模型的骨骼层级与覆盖状态。
 * 用于开发调试、用户 issue 提交、模块开发时确认骨骼命名。
 *
 * @param modelId 目标模型 ID（可选，默认聚焦模型）
 * @returns 骨骼层级导出结果，模型不存在时返回 null
 */
export function dumpBoneHierarchy(modelId?: string): BoneHierarchyDump | null {
    const mid = _resolveModelId(modelId);
    if (!mid) {
        return null;
    }
    const bones = _getRuntimeBones?.() ?? [];
    if (bones.length === 0) {
        return null;
    }
    const overrideMap = _overrideMaps.get(mid);

    // 构建 name → index 映射（O(1) 查找父骨骼索引）
    const indexMap = new Map<string, number>();
    for (let i = 0; i < bones.length; i++) {
        indexMap.set(bones[i].name, i);
    }

    const result: BoneHierarchyNode[] = [];
    let totalOverridden = 0;
    for (let i = 0; i < bones.length; i++) {
        const b = bones[i];
        const parentIndex = b.parentBone ? (indexMap.get(b.parentBone.name) ?? -1) : -1;
        const slot = overrideMap?.get(b.name);
        const isOverridden = slot?.enabled ?? false;
        if (isOverridden) {
            totalOverridden++;
        }
        result.push({
            index: i,
            name: b.name,
            parentIndex,
            childCount: b.childBones.length,
            hasIkSolver: !!(b as MmdRuntimeBoneExtended).ikSolver,
            afterPhysics: b.transformAfterPhysics,
            isOverridden,
            overrideEntry: isOverridden && slot ? _slotToEntry(b.name, slot) : undefined,
        });
    }

    return {
        modelId: mid,
        timestamp: new Date().toISOString(),
        totalBones: bones.length,
        totalOverridden,
        bones: result,
    };
}

// [doc:adr-085] Feet Adjustment — 脚部地面跟随（MMD-native IK，JS/WASM 统一走原生求解器）
// 职责: 每帧驱动左/右足IK 骨骼世界坐标到地面 + 重解该腿 IK
// 注册为 MotionPipeline bone-override 层（order=5），在帧钩子（RIDING=10）之前执行，
// 脚 IK 为自动约束基础，手动 Override 叠加其上。
// 依赖: env-impl.getGroundHeightAt / proc-motion-shared 骨骼候选 / babylon-mmd IkSolver
//       / bone-override.getWasmIkResolver（WASM 模式经 mmdModelSolveIk 重解）
//
// 关键机制（2026-07-11 复核, 2026-07-29 方案A 迁移）:
//   MMD 模型自带腿部 IK —— 左足IK/右足IK 是 IK 目标骨骼，babylon-mmd 的 IkSolver 在
//   MmdRuntimeModel._update() 内、动画应用后同帧解出。本模块在动画解算后，把 IK 目标骨骼的
//   世界坐标 setWorldTranslation 到地面，再重解该腿 IK。
//   - JS 模式：调用 ikSolver.solve()（solve 内部回写踝 + 链骨骼 worldMatrix）
//   - WASM 模式：经 mmdModelSolveIk 导出重解原生 IK 链（ADR-202 §六，方案C 已淘汰）

import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';
import type { MmdRuntimeBoneExtended, FeetState } from '@/core/types';
import { getGroundHeightAt } from '@/scene/env/env-impl';
import {
    BONE_LEG_IK_L_CANDIDATES,
    BONE_LEG_IK_R_CANDIDATES,
    matchBone,
} from '@/motion-algos/proc-motion-shared';
// [ADR-202 §六] WASM 模式经 mmdModelSolveIk 重解原生 IK 链
import { getWasmIkResolver, getOverride } from './bone-override';
// 运动模块状态查询（用于 feet-adjustment 感知用户手动覆盖）
import { getModuleState } from './motion-modules/registry';
// 纯数学解算（无 Babylon 依赖，便于单测）见 motion-algos/feet-adjustment-math.ts
import { solveFootTarget } from '@/motion-algos/feet-adjustment-math';
// 落地判定（无 Babylon 依赖，便于单测）见 motion-algos/footstep-detect.ts
import { detectFootLanding } from '@/motion-algos/footstep-detect';
import { logWarn } from '../../core/logger';
import { getMotionPipeline } from './motion-pipeline';
import { isWasmRuntime, feetDebug } from './perception-shared';
export { solveFootTarget };
export type { SolveFootInput, SolveFootOutput } from '@/motion-algos/feet-adjustment-math';

// ======== WASM 调试开关 ========
// feetDebug 已迁移至 perception-shared.ts（供 bone-override 守护共用，避免循环依赖）

// ======== 引擎钩子 ========

/** 注入：返回需要处理脚部调整的模型及其 runtime bones */
export type FeetModelProvider = () => Iterable<{
    id: string;
    feet: FeetState;
    runtimeBones: readonly IMmdRuntimeBone[];
}>;

interface _ModelCache {
    lName: string | null;
    rName: string | null;
    lTargetY: number | null;
    rTargetY: number | null;
    /** 模型中心骨骼（センター）世界 Y，用于自然脚高推算 */
    centerY: number | null;
    // 落地事件检测状态（ADR-088）：脚 IK 贴地上升沿 + 去抖
    lPrevGrounded: boolean;
    rPrevGrounded: boolean;
    lFootYPrev: number;
    rFootYPrev: number;
    lLastLandTime: number;
    rLastLandTime: number;
}

const _cache = new Map<string, _ModelCache>();
let _unregisterHandle: (() => void) | null = null;
// ADR-088 落地事件回调（setOnFootLand 注入）；脚步声消费此事件
let _onFootLand: ((e: FootLandEvent) => void) | null = null;
// 帧间隔计时（供落地垂直速度估算）
let _lastTickTime = 0;
// 同脚两次落地最小间隔（ms），去抖防抖动误触发
const FOOT_STEP_MIN_INTERVAL = 120;

let _feetDbgFrame = 0;
let _feetTick = 0;
/** [ADR-202 §六] 一次性诊断已输出标记（避免刷屏） */
let _feetWarnOnce = false;

// 大腿根候选（用于估算髋位置与腿长）
// 日文 PMX 标准名：左足/右足（MMD 惯例）；部分模型用 左大腿/右大腿 或 左腿/右腿
const BONE_THIGH_L = ['左足', '左大腿', '左腿', 'left leg', 'LeftLeg', 'LeftThigh', 'left thigh'];
const BONE_THIGH_R = [
    '右足',
    '右大腿',
    '右腿',
    'right leg',
    'RightLeg',
    'RightThigh',
    'right thigh',
];

const _vFoot = new Vector3();
const _vHip = new Vector3();
const _vTarget = new Vector3();

function _getCache(id: string): _ModelCache {
    let c = _cache.get(id);
    if (!c) {
        c = {
            lName: '',
            rName: '',
            lTargetY: null,
            rTargetY: null,
            centerY: null,
            lPrevGrounded: false,
            rPrevGrounded: false,
            lFootYPrev: 0,
            rFootYPrev: 0,
            lLastLandTime: 0,
            rLastLandTime: 0,
        };
        _cache.set(id, c);
    }
    return c;
}

/** 落地事件：脚从空中接触地面的瞬间（ADR-088 供脚步声消费）。 */
export interface FootLandEvent {
    modelId: string;
    foot: 'L' | 'R';
    groundY: number;
    /** 落地垂直速度（单位/秒），>=0，用于脚步声音量映射 */
    impactSpeed: number;
    worldX: number;
    worldZ: number;
}

/** 注入落地事件回调（null 取消）。脚步声控制器调用。 */
export function setOnFootLand(cb: ((e: FootLandEvent) => void) | null): void {
    _onFootLand = cb;
}

/** 查询脚部跟随系统是否正在运行（observer 已注册）。 */
export function isFeetAdjustmentRunning(): boolean {
    return _unregisterHandle !== null;
}

/** 找大腿根骨骼（用于估算髋世界坐标与腿长）。
 *  优先沿 IK 骨 parent 链向上找（兼容非标准层级）；
 *  降级到全量 bone list 按名匹配（标准 MMD：IK 骨 direct child of 全ての親）。 */
function _findHip(
    ik: IMmdRuntimeBone,
    allBones: readonly IMmdRuntimeBone[],
    side: 'L' | 'R'
): IMmdRuntimeBone | null {
    const cands = side === 'L' ? BONE_THIGH_L : BONE_THIGH_R;

    // 1) 沿 IK 骨 parent 链向上
    let cur: IMmdRuntimeBone | null = ik.parentBone;
    let depth = 0;
    while (cur && depth < 6) {
        if (cands.includes(cur.name)) {
            return cur;
        }
        cur = cur.parentBone;
        depth++;
    }

    // 2) 全量搜索——标准 MMD 中左足ＩＫ的 parent 是全ての親，不是左足
    for (const b of allBones) {
        if (cands.includes(b.name)) {
            return b;
        }
    }

    // 3) 回退：取 ik 上方第 3 级父
    cur = ik.parentBone;
    for (let i = 0; i < 2 && cur; i++) {
        cur = cur.parentBone;
    }
    return cur;
}

function _adjustFoot(
    bones: readonly IMmdRuntimeBone[],
    ikName: string | null,
    side: 'L' | 'R',
    cache: _ModelCache,
    feet: FeetState,
    modelId: string,
    dt: number
): void {
    if (!ikName) {
        return;
    }
    const ik = bones.find((b) => b.name === ikName);
    if (!ik) {
        return;
    }

    ik.getWorldTranslationToRef(_vFoot); // 当前 IK 目标（动画驱动）世界坐标
    const groundY = getGroundHeightAt(_vFoot.x, _vFoot.z);

    // 估算髋世界坐标 + 腿长（用于 reachAngle / maxAngle）
    let hipToFootDist = 0;
    let legLength = 1;
    let hip: IMmdRuntimeBone | null = null;
    {
        const h = _findHip(ik, bones, side);
        if (h) {
            h.getWorldTranslationToRef(_vHip);
            hipToFootDist = Vector3.Distance(_vFoot, _vHip);
            legLength = Math.max(hipToFootDist, 1e-3);
            hip = h;
        }
    }

    const res = solveFootTarget({
        footY: _vFoot.y,
        groundY,
        hipToFootDist,
        legLength,
        centerY: cache.centerY ?? 0,
        prevTargetY: side === 'L' ? cache.lTargetY : cache.rTargetY,
        feet,
    });

    // ADR-088：落地事件（贴地上升沿 + 去抖）。grounded = 本帧未跳过 IK 重解（脚被拉到地面）
    const grounded = !res.skip;
    const now = performance.now();
    const footYPrev = side === 'L' ? cache.lFootYPrev : cache.rFootYPrev;
    const prevGrounded = side === 'L' ? cache.lPrevGrounded : cache.rPrevGrounded;
    const prevStepTime = side === 'L' ? cache.lLastLandTime : cache.rLastLandTime;
    const det = detectFootLanding({
        prevGrounded,
        grounded,
        footYPrev,
        footY: _vFoot.y,
        dt,
        prevStepTime,
        now,
        minInterval: FOOT_STEP_MIN_INTERVAL,
    });
    if (det.landed && _onFootLand) {
        _onFootLand({
            modelId,
            foot: side,
            groundY,
            impactSpeed: det.impactSpeed,
            worldX: _vFoot.x,
            worldZ: _vFoot.z,
        });
    }
    // 更新上一帧状态（无论是否落地都更新，供下一帧上升沿判定）
    if (side === 'L') {
        cache.lPrevGrounded = grounded;
        cache.lFootYPrev = _vFoot.y;
        if (det.landed) {
            cache.lLastLandTime = now;
        }
    } else {
        cache.rPrevGrounded = grounded;
        cache.rFootYPrev = _vFoot.y;
        if (det.landed) {
            cache.rLastLandTime = now;
        }
    }

    if (feetDebug.value && _feetDbgFrame++ % 60 === 0) {
        const solver = (ik as MmdRuntimeBoneExtended).ikSolver;
        logWarn(
            'feet',
            `[WASM] ${modelId} ${side} ` +
                `ik=${ikName} ` +
                `footY=${_vFoot.y.toFixed(3)} ` +
                `groundY=${groundY.toFixed(3)} ` +
                `targetY=${res.targetY.toFixed(3)} ` +
                `skip=${res.skip} ` +
                `solver=${solver ? 'present' : 'null'} ` +
                `hip=${hip ? hip.name : 'null<-fallback'} ` +
                `centerY=${cache.centerY !== null ? cache.centerY.toFixed(3) : '?'} ` +
                `legLen=${legLength.toFixed(3)}`
        );
    }

    // [ADR-202 §六] 如果对应脚的运动模块有非零参数，或 IK 目标骨有激活的 bone override，
    // 跳过自动贴地（用户手动覆盖优先于 always-on 地面跟随）
    const moduleId = side === 'L' ? 'left-foot' : 'right-foot';
    const st = getModuleState(modelId, moduleId);
    const fp = st?.params;
    const hasModParams =
        fp &&
        ((fp.pitch as number) !== 0 ||
            (fp.yaw as number) !== 0 ||
            (fp.roll as number) !== 0 ||
            (fp.footPosX as number) !== 0 ||
            (fp.footPosY as number) !== 0 ||
            (fp.footPosZ as number) !== 0);
    if (hasModParams) {
        return;
    }
    // 二重检查：遍历所有候选骨名，检测 _overrideMaps 是否有激活的覆盖
    const cands = side === 'L' ? BONE_LEG_IK_L_CANDIDATES : BONE_LEG_IK_R_CANDIDATES;
    let foundOverride = false;
    for (const cand of cands as string[]) {
        const ov = getOverride(cand, modelId);
        if (ov?.enabled) {
            foundOverride = true;
            break;
        }
    }
    if (foundOverride) {
        return;
    }
    // [ADR-202 §六 debug] 仅在 feetDebug 开启时输出一次诊断（_feetWarnOnce 跨帧复用）
    if (feetDebug.value && !_feetWarnOnce) {
        _feetWarnOnce = true;
        logWarn(
            'feet',
            `[A-skip] ${side} modParams=${hasModParams} cands=${cands.length} ` +
                `pitch=${fp?.pitch} yaw=${fp?.yaw} roll=${fp?.roll} ` +
                `posY=${fp?.footPosY} overrideFound=${foundOverride} ` +
                `skip=${res.skip}`
        );
    }

    if (res.skip) {
        if (side === 'L') {
            cache.lTargetY = null;
        } else {
            cache.rTargetY = null;
        }
        return;
    }

    // 驱动 IK 目标骨骼世界坐标（保留 XZ，仅调整 Y）
    _vTarget.set(_vFoot.x, res.targetY, _vFoot.z);
    ik.setWorldTranslation(_vTarget);

    // 重解该腿 IK（ADR-202 §六：JS/WASM 统一走原生求解器）
    // JS 模式：ikSolver.solve() 直接调用（solve 内部回写踝 + 链骨骼 worldMatrix）
    // WASM 模式：经 mmdModelSolveIk 导出重解原生 IK 链（setWorldTranslation 已写入同一 bone buffer）
    if (isWasmRuntime(bones[0])) {
        const ikSolverIndex = (ik as { ikSolverIndex?: number }).ikSolverIndex;
        const resolver = getWasmIkResolver();
        if (resolver && typeof ikSolverIndex === 'number' && ikSolverIndex >= 0) {
            resolver(modelId, ikSolverIndex, false);
        } else if (feetDebug.value && _feetDbgFrame % 60 === 0) {
            logWarn(
                'feet',
                `[WASM] ${modelId} ${side} IK 未重解: resolver=${resolver ? 'ok' : 'null'}, ikSolverIndex=${ikSolverIndex ?? 'null'}`
            );
        }
    } else {
        const solver = (ik as MmdRuntimeBoneExtended).ikSolver;
        if (solver) {
            // 腿部链通常为 FollowBone（骨骼驱动刚体），usePhysics=false 即正确；
            // 物理驱动模式下 canSkipWhenPhysicsEnabled=true → solve 自动跳过（已知限制）
            solver.solve(false);
        }
    }

    // JS 运行时：通知 skeleton 重算蒙皮（WASM 直写 worldTransformMatrices buffer，无需）
    const lb = (
        ik as unknown as { linkedBone?: { getSkeleton?: () => { _markAsDirty?: () => void } } }
    ).linkedBone;
    lb?.getSkeleton?.()._markAsDirty?.();

    if (side === 'L') {
        cache.lTargetY = res.targetY;
    } else {
        cache.rTargetY = res.targetY;
    }
}

/**
 * 启动脚部调整系统：注册为 MotionPipeline bone-override 层（order=5）。
 * 在帧钩子（RIDING=10）之前执行：脚 IK 为自动约束基础，手动 Override 叠加其上。
 */
export function startFeetAdjustment(getModels: FeetModelProvider): void {
    if (_unregisterHandle) {
        return;
    }

    const callback = () => {
        const now = performance.now();
        const dt = _lastTickTime ? Math.min((now - _lastTickTime) / 1000, 0.1) : 1 / 60;
        _lastTickTime = now;
        if (feetDebug.value && _feetTick++ % 90 === 0) {
            const summary = [...getModels()]
                .map((m) => `${m.id}:en=${m.feet.enabled},n=${m.runtimeBones.length}`)
                .join(' ');
            logWarn('feet', '[WASM] models', summary);
        }
        for (const m of getModels()) {
            const cache = _getCache(m.id);
            const feet = m.feet;
            if (!feet.enabled || feet.intensity <= 0 || m.runtimeBones.length === 0) {
                // 禁用时清空平滑状态，避免重新启用跳变
                cache.lTargetY = null;
                cache.rTargetY = null;
                cache.lPrevGrounded = false;
                cache.rPrevGrounded = false;
                cache.lLastLandTime = 0;
                cache.rLastLandTime = 0;
                continue;
            }
            // 解析 IK 骨骼名（按模型缓存，首次解析）
            if (cache.lName === '') {
                const names = m.runtimeBones.map((b) => b.name);
                cache.lName = matchBone(names, BONE_LEG_IK_L_CANDIDATES);
                cache.rName = matchBone(names, BONE_LEG_IK_R_CANDIDATES);
                // 缓存中心骨骼世界 Y（用于 solveFootTarget 推算自然脚高）
                const centerBone =
                    m.runtimeBones.find((b) => b.name === 'センター') ??
                    m.runtimeBones.find((b) => b.name === '全ての親');
                if (centerBone) {
                    const v = new Vector3();
                    centerBone.getWorldTranslationToRef(v);
                    cache.centerY = v.y;
                } else {
                    cache.centerY = null;
                }
                // 启动诊断：始终输出，不论 debug 开关
                const lMatchResult = cache.lName ?? '<null>';
                const rMatchResult = cache.rName ?? '<null>';
                const centerYStr = cache.centerY !== null ? cache.centerY.toFixed(3) : '?';
                logWarn(
                    'feet',
                    `[WASM] IK 匹配结果 for ${m.id}: L="${lMatchResult}" R="${rMatchResult}" ` +
                        `(total bones=${names.length}) ` +
                        `centerWorldY=${centerYStr}`
                );
                if (cache.lName === null || cache.rName === null) {
                    const hints = names
                        .filter((n) => /足|ＩＫ|IK|Leg|leg|Foot|foot/.test(n))
                        .slice(0, 16);
                    logWarn('feet', '  模型中含"足/IK"的骨骼名：', hints);
                }
            }
            _adjustFoot(m.runtimeBones, cache.lName, 'L', cache, feet, m.id, dt);
            _adjustFoot(m.runtimeBones, cache.rName, 'R', cache, feet, m.id, dt);
        }
    };

    _unregisterHandle = getMotionPipeline().register({
        id: 'feet-adjustment',
        stage: 'bone-override',
        order: 5,
        run: callback,
    });
}

/** 停止脚部调整系统并清空缓存。 */
export function stopFeetAdjustment(): void {
    if (_unregisterHandle) {
        _unregisterHandle();
        _unregisterHandle = null;
    }
    _cache.clear();
    _lastTickTime = 0; // 重置时间戳，避免重启后首帧 dt 异常
}

// [doc:adr-121] 全局动作意图（Scene-level Motion Intent）
// [doc:adr-167] 场景级动作库（Scene Motion Library）— 多主动作平等共存
// 职责: 场景级 _sceneMotions 动作库 + _activeMotionId 默认动作 + 每实例继承/覆盖 + 广播/兼容性解析
// 设计: 轻量 singleton（非 EnvState），规避 Go struct 同步 + wails 绑定重生成本
// 依赖方向: 不 import 任何 UI 模块；由 broadcastMotion 遍历 modelRegistry 写入 inst.vmd*

import type { SceneMotionIntent, MotionModuleState } from '@/core/types';
import { matchBone } from '@/motion-algos/proc-motion-shared';

// ── 场景级 store（轻量 singleton，非 EnvState）──

let _sceneMotions: SceneMotionIntent[] = []; // 场景级主动作库（多主动作平等共存，ADR-167）
let _activeMotionId: string | null = null; // 默认动作 id；null = 无默认（新角色静止）
let _motionGen = 0; // generation counter，每次变更递增，用于守护异步广播竞态

// [doc:adr-207] 场景级程序化动作可加载集合
// 'none' 始终存在且不可卸载（系统保底状态）
export type LoadableProcId = 'none' | 'idle' | 'autodance';
const ALL_LOADABLE_PROC: LoadableProcId[] = ['none', 'idle', 'autodance'];
let _loadedProceduralMotions: Set<LoadableProcId> = new Set(['none', 'idle', 'autodance']);

/** 生成场景动作 id（稳定唯一，用于引用与序列化） */
function genMotionId(): string {
    return `motion_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

/**
 * 获取当前默认动作（派生自 _activeMotionId）。
 * 保持原签名以最小化下游改动（playback/vmd-loader/vmd-layers 链路无感知）。
 * null = 无默认动作（静态场景）。
 */
export function getActiveMotion(): SceneMotionIntent | null {
    if (!_activeMotionId) {
        return null;
    }
    return _sceneMotions.find((m) => m.id === _activeMotionId) ?? null;
}

/** 获取场景级动作库（所有主动作列表）。 */
export function getSceneMotions(): SceneMotionIntent[] {
    return _sceneMotions;
}

/** 获取当前默认动作 id。null = 无默认。 */
export function getActiveMotionId(): string | null {
    return _activeMotionId;
}

/** 获取当前 generation 值。用于异步操作中判断是否为最新广播。 */
export function getMotionGen(): number {
    return _motionGen;
}

// ── [doc:adr-207] 程序化动作可加载集合 API ──

/** 获取全部可加载的程序化动作 ID 列表（含未加载的）。 */
export function getAllLoadableProcMotions(): LoadableProcId[] {
    return ALL_LOADABLE_PROC;
}

/** 获取当前已加载的程序化动作集合。 */
export function getLoadedProceduralMotions(): Set<LoadableProcId> {
    return _loadedProceduralMotions;
}

/** 加载一个程序化动作到集合。 */
export function loadProceduralMotion(id: LoadableProcId): void {
    _loadedProceduralMotions.add(id);
}

/** 卸载一个程序化动作。'none' 不可卸载。 */
export function unloadProceduralMotion(id: LoadableProcId): void {
    if (id === 'none') {
        return;
    }
    _loadedProceduralMotions.delete(id);
}

/** 设置已加载集合（用于场景反序列化）。始终保证 'none' 存在。 */
export function setLoadedProceduralMotions(ids: LoadableProcId[]): void {
    _loadedProceduralMotions = new Set(ids);
    _loadedProceduralMotions.add('none');
}

// ── 广播回调（调用方注册，避免循环依赖）──

let _broadcastCallback:
    | ((intent: SceneMotionIntent | null, gen: number, prev: SceneMotionIntent | null) => void)
    | null = null;
let _callbackInitialized = false;

/**
 * 初始化广播回调。由 bootstrap 点（如 scene.ts initScene）调用一次。
 * 回调负责遍历 modelRegistry 并按每实例 assignment 策略应用意图。
 * 回调模式避免 motion-intent 直接依赖 scene 模块。
 * 幂等守卫：多次调用不重复注册。
 */
export function initMotionIntent(
    cb: (intent: SceneMotionIntent | null, gen: number, prev: SceneMotionIntent | null) => void
): void {
    if (_callbackInitialized) {
        return;
    }
    _broadcastCallback = cb;
    _callbackInitialized = true;
}

/**
 * @deprecated 请使用 initMotionIntent() 替代。此函数仅保留供测试覆写：
 * 测试用例间需 setBroadcastCallback(null) 隔离回调，而 initMotionIntent 的幂等守卫不允许置空。
 * 生产代码应使用 initMotionIntent()。
 */
export function setBroadcastCallback(
    cb:
        | ((intent: SceneMotionIntent | null, gen: number, prev: SceneMotionIntent | null) => void)
        | null
): void {
    _broadcastCallback = cb;
}

// ── 场景动作库 API（ADR-167）──

/**
 * 新增主动作到场景库。
 * - 若 intent 无 id，自动生成
 * - 若 _sceneMotions 为空（首次添加），自动设为默认
 * - 触发广播：所有 sceneMotionId===undefined 的 inherit 角色套用新默认（若默认变更）
 * @returns 新增动作的 id
 */
export function addSceneMotion(intent: SceneMotionIntent): string {
    const id = intent.id ?? genMotionId();
    const withId: SceneMotionIntent = { ...intent, id };
    _sceneMotions.push(withId);

    // 首次添加自动设为默认
    const prev = getActiveMotion();
    if (_activeMotionId === null && _sceneMotions.length === 1) {
        _activeMotionId = id;
    }

    _motionGen++;
    _broadcastCallback?.(getActiveMotion(), _motionGen, prev);
    return id;
}

/**
 * 移除场景库中的某个主动作。
 * - 若移除的是当前默认动作：_activeMotionId 直接置 null（不再回退到列表第一项），全部 inherit 模型随之变「无动作」。
 * - 引用该 id 的角色由调用方（broadcastMotion）处理回退（置 sceneMotionId=undefined）
 */
export function removeSceneMotion(id: string): void {
    const prev = getActiveMotion();
    _sceneMotions = _sceneMotions.filter((m) => m.id !== id);

    if (_activeMotionId === id) {
        // [fix] 删除基础/默认动作 → 直接清空为无动作，不再静默顶替列表第一项。
        // 否则模型详情「动作根」卡片会显示其他动作名，永远到不了「无动作」。
        _activeMotionId = null;
    }

    _motionGen++;
    _broadcastCallback?.(getActiveMotion(), _motionGen, prev);
}

/**
 * 更新场景库中某个主动作的数据（如改其 vmdLayers）。
 * - 保留原 id 不变
 * - 触发广播：引用该 id 的角色重建 composite animation
 */
function updateSceneMotion(id: string, patch: Partial<SceneMotionIntent>): void {
    const idx = _sceneMotions.findIndex((m) => m.id === id);
    if (idx < 0) {
        return;
    }
    _sceneMotions[idx] = { ..._sceneMotions[idx], ...patch, id }; // 保留 id
    _motionGen++;
    _broadcastCallback?.(getActiveMotion(), _motionGen, null);
}

/**
 * 设置默认动作 id。
 * - null = 清空默认（新角色静止，但场景库保留）
 * - 触发广播：所有 sceneMotionId===undefined 的 inherit 角色重新套用
 */
export function setDefaultMotion(id: string | null): void {
    const prev = getActiveMotion();
    _activeMotionId = id;
    _motionGen++;
    _broadcastCallback?.(getActiveMotion(), _motionGen, prev);
}

/**
 * 清空整个场景动作库 + 默认动作。
 * 用于「清除场景动作」UI。
 */
export function clearAllSceneMotions(): void {
    const prev = getActiveMotion();
    _sceneMotions = [];
    _activeMotionId = null;
    _motionGen++;
    _broadcastCallback?.(null, _motionGen, prev);
}

/**
 * [doc:adr-121 P4-1] 在 intent.motionModules 中查找或创建模块状态。
 * 收敛 mutate 入口：外部模块（如 registry）不再直接 push intent.motionModules，
 * 而是通过此函数获取引用，保持写入路径可追踪。
 */
export function findOrCreateModuleState(
    intent: SceneMotionIntent,
    moduleId: string
): MotionModuleState {
    if (!intent.motionModules) {
        intent.motionModules = [];
    }
    let state = intent.motionModules.find((m) => m.id === moduleId);
    if (!state) {
        state = { id: moduleId, enabled: false, params: {} };
        intent.motionModules.push(state);
    }
    return state;
}

/**
 * [adr-169] 原位替换默认动作。
 *
 * 「从文件装载动作」的统一语义：装载的动作成为新默认，旧默认被原位顶替。
 * 是 removeSceneMotion + addSceneMotion + setDefaultMotion 的原子组合，
 * 保证「移除旧默认 → 加入/复用新动作 → 设默认 → 广播」在一次 generation
 * 递增内完成，避免中间态被并发广播读到。
 *
 * ⚠️ vmdPath 为 null/undefined 时直接返回空字符串（不作任何操作），
 * 防止占位路径污染场景库（见 vmd-loader.ts !mmdRuntime 路径）。
 *
 * - 装载路径已是库中候选 → 复用该候选（提升为默认），不重复添加
 * - 否则新增动作，插入到旧默认原位置（保持库顺序稳定）
 * - 旧默认（若存在且非复用项）从库中移除
 * - 触发广播：跟随默认 / 引用旧默认的角色切到新动作
 *
 * @returns 新默认动作的 id；若 vmdPath 为空返回 ''
 */
export function replaceDefaultMotion(intent: SceneMotionIntent): string {
    // [doc:adr-169] 无 vmdPath 的占位动作拒绝装载，避免污染场景库
    if (!intent.vmdPath) {
        return '';
    }
    const prev = getActiveMotion();
    const prevId = _activeMotionId;

    // 去重：装载路径已是库中候选 → 复用（提升为默认）
    const existing = _sceneMotions.find((m) => m.vmdPath === intent.vmdPath);

    let newId: string;
    if (existing) {
        newId = existing.id;
        // 旧默认若非复用项本身，从库中移除
        if (prevId !== null && prevId !== newId) {
            _sceneMotions = _sceneMotions.filter((m) => m.id !== prevId);
        }
    } else {
        newId = intent.id ?? genMotionId();
        const withId: SceneMotionIntent = { ...intent, id: newId };
        if (prevId !== null) {
            // 原位插入到旧默认位置，保持库顺序稳定
            const idx = _sceneMotions.findIndex((m) => m.id === prevId);
            _sceneMotions = _sceneMotions.filter((m) => m.id !== prevId);
            _sceneMotions.splice(idx >= 0 ? idx : _sceneMotions.length, 0, withId);
        } else {
            _sceneMotions.push(withId);
        }
    }

    _activeMotionId = newId;
    _motionGen++;
    _broadcastCallback?.(getActiveMotion(), _motionGen, prev);
    return newId;
}

// ── 兼容性解析 ──

const MIN_STANDARD_BONE_MATCH = 3;
const MIN_VMD_BONE_MATCH_RATIO = 0.5;

const STANDARD_MMD_BONES = [
    '全ての親',
    'センター',
    'グルーブ',
    '腰',
    '上半身',
    '下半身',
    '頭',
    '右肩',
    '右腕',
    '右ひじ',
    '右手首',
    '左肩',
    '左腕',
    '左ひじ',
    '左手首',
    '右足',
    '右ひざ',
    '右足首',
    '左足',
    '左ひざ',
    '左足首',
    '首',
    '両目',
    'まぶた',
    '左目',
    '右目',
    '下あご',
];

function countBoneMatches(actualBones: string[], candidates: string[]): number {
    let count = 0;
    for (const candidate of candidates) {
        if (matchBone(actualBones, [candidate])) {
            count++;
        }
    }
    return count;
}

/**
 * 兼容性解析：判断指定模型的骨骼列表是否兼容某 VMD 动作。
 * 复用 proc-motion-shared.matchBone 进行骨骼名匹配（全角/半角/英文变体）。
 *
 * 匹配策略（两级）：
 * 1. 传入 vmdBoneNames（VMD 实际引用的骨骼名）→ VMD 级匹配，
 *    命中率 ≥ MIN_VMD_BONE_MATCH_RATIO 视为兼容；
 * 2. 未传 vmdBoneNames → 人形预筛（STANDARD_MMD_BONES ≥ MIN_STANDARD_BONE_MATCH 命中）
 *
 * @param actualBones   模型的实际骨骼名列表
 * @param intent        待解析的动作意图（null=静态，始终兼容）
 * @param vmdBoneNames  可选，VMD 实际引用的骨骼名数组
 * @returns 兼容性结果
 */
export function resolveCompatibility(
    actualBones: string[],
    intent: SceneMotionIntent | null,
    vmdBoneNames?: string[]
): { compatible: boolean; reason?: string } {
    if (!intent) {
        return { compatible: true };
    }
    if (actualBones.length === 0) {
        return { compatible: false, reason: '模型无骨骼数据' };
    }
    if (vmdBoneNames && vmdBoneNames.length > 0) {
        const matched = countBoneMatches(actualBones, vmdBoneNames);
        const ratio = matched / vmdBoneNames.length;
        if (ratio >= MIN_VMD_BONE_MATCH_RATIO) {
            return { compatible: true };
        }
        return {
            compatible: false,
            reason: `VMD 骨骼命中率 ${(ratio * 100).toFixed(0)}%（${matched}/${vmdBoneNames.length}），不兼容当前动作`,
        };
    }
    const matched = countBoneMatches(actualBones, STANDARD_MMD_BONES);
    if (matched >= MIN_STANDARD_BONE_MATCH) {
        return { compatible: true };
    }
    return {
        compatible: false,
        reason: `仅匹配到 ${matched}/${MIN_STANDARD_BONE_MATCH} 个标准骨骼，不兼容当前动作`,
    };
}

// [doc:adr-116 重构] Hand Modules — 左手/右手独立控制模块
// 职责: 合并原 hand-symmetry（单侧手腕旋转+位置偏移）与 finger-pose（单侧手指预设），
//       使左右手完全独立可调（不再强制镜像）。
// 骨骼: 手腕旋转(手首) + 手臂位置(肩根骨 FK 平移 / 腕 IK 重解) + 手指姿势(5 指 × 3 节)
// 帧钩子: 手臂位置偏移需每帧驱动（与旧 hand-symmetry 同构），手指/手腕为静态 bake。

import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';
import type { MmdRuntimeBoneExtended, ParamValue } from '@/core/types';
import { modelRegistry } from '@/core/state';
import {
    setBoneOverride,
    setBoneOverridePosition,
    clearBoneOverride,
    registerBoneOverrideFrameHook,
    FRAME_HOOK_ORDER,
} from '../bone-override';
import {
    matchBone,
    BONE_ARM_IK_L_CANDIDATES,
    BONE_ARM_IK_R_CANDIDATES,
    BONE_SHOULDER_L_CANDIDATES,
    BONE_SHOULDER_R_CANDIDATES,
} from '@/motion-algos/proc-motion-shared';
import { getModuleState } from './registry';
import type { MotionOverrideModule, ModuleMeta, ModuleDef } from './types';
import {
    createModuleBase,
    createFrameHookManager,
    createModuleShell,
    prepareBake,
} from './module-base';

// ── 手指预设（与原 finger-pose 一致）──

type FingerPreset = 'relax' | 'fist' | 'point' | 'peace' | 'rock';

const PRESETS: Record<FingerPreset, number[]> = {
    relax: [0.2, 0.3, 0.3, 0.3, 0.3],
    fist: [0.8, 1.0, 1.0, 1.0, 1.0],
    point: [0.2, 0.0, 1.0, 1.0, 1.0],
    peace: [0.2, 0.0, 0.0, 1.0, 1.0],
    rock: [0.2, 0.0, 1.0, 1.0, 0.0],
};

const FINGER_BASES = ['親指', '人差指', '中指', '薬指', '小指'];
const PHALANX_SUFFIXES = ['０', '１', '２', '第一', '第二', '第三'];
const PHALANX_WEIGHTS = [0.5, 0.3, 0.2];

// ── 共享帧钩子管理器（左右手共用一个 Map，按 modelId 注册一次）──

const _handFrameHooks = createFrameHookManager();

/** 手臂骨名缓存（per-model） */
interface _ArmIkCache {
    lIk?: string | null;
    rIk?: string | null;
    lRoot?: string | null;
    rRoot?: string | null;
}
const _armIkCache = new Map<string, _ArmIkCache>();
function _getArmIkCache(modelId: string): _ArmIkCache {
    let c = _armIkCache.get(modelId);
    if (!c) {
        c = {};
        _armIkCache.set(modelId, c);
    }
    return c;
}

const _vOffset = new Vector3();

// ── 工厂函数 ──

interface HandSideConfig {
    side: 'L' | 'R';
    moduleId: string;
    wristBone: string;
    shoulderBone: string;
    fingerPrefix: string;
    labelKey: string;
    icon: string;
}

/** 构建单侧手指候选骨骼名 */
function buildFingerBones(prefix: string): string[] {
    const bones: string[] = [];
    for (const base of FINGER_BASES) {
        for (const suffix of PHALANX_SUFFIXES) {
            bones.push(`${prefix}${base}${suffix}`);
        }
    }
    return bones;
}

/** 创建左手或右手模块 */
function createHandModuleFactory(cfg: HandSideConfig) {
    return (modelId: string): MotionOverrideModule => {
        const fingerBones = buildFingerBones(cfg.fingerPrefix);
        const managedBones = [cfg.wristBone, cfg.shoulderBone, ...fingerBones];

        const DEFAULTS: Record<string, ParamValue> = {
            pitch: 0,
            yaw: 0,
            roll: 0,
            handPosX: 0,
            handPosY: 0,
            handPosZ: 0,
            fingerPreset: 'relax',
            fingerIntensity: 1,
        };

        const META: ModuleMeta = {
            labelKey: cfg.labelKey,
            icon: cfg.icon,
            defaults: DEFAULTS,
        };

        // ── bake：手腕旋转 + 手指姿势 ──
        function bake(modelId: string): void {
            const prep = prepareBake(modelId, cfg.moduleId, managedBones);
            if (!prep) {
                return;
            }
            const { state, claimed } = prep;

            // 手腕旋转
            const pitch = (state.params.pitch as number) ?? 0;
            const yaw = (state.params.yaw as number) ?? 0;
            const roll = (state.params.roll as number) ?? 0;
            if (claimed.includes(cfg.wristBone)) {
                setBoneOverride(cfg.wristBone, [pitch, yaw, roll], 1, true, modelId);
            }

            // 手指姿势
            const presetName = (state.params.fingerPreset as string) ?? 'relax';
            const intensity = (state.params.fingerIntensity as number) ?? 1;
            const preset = PRESETS[presetName as FingerPreset] ?? PRESETS.relax;

            for (let fingerIdx = 0; fingerIdx < FINGER_BASES.length; fingerIdx++) {
                const base = FINGER_BASES[fingerIdx];
                const curl = preset[fingerIdx] * intensity;
                const phalanges: string[] = [];
                for (const suffix of PHALANX_SUFFIXES) {
                    const boneName = `${cfg.fingerPrefix}${base}${suffix}`;
                    if (claimed.includes(boneName)) {
                        phalanges.push(boneName);
                    }
                }
                phalanges.forEach((boneName, rank) => {
                    const w = PHALANX_WEIGHTS[Math.min(rank, PHALANX_WEIGHTS.length - 1)];
                    setBoneOverride(boneName, [curl * 90 * w, 0, 0], 1, true, modelId);
                });
            }
        }

        // ── 帧钩子：手臂位置偏移（FK 父根骨平移 / IK 重解）──
        function ensureActive(modelId: string): void {
            if (_handFrameHooks.has(modelId)) {
                return;
            }
            bake(modelId);

            const unregister = registerBoneOverrideFrameHook(
                (_t, mid) => {
                    if (mid !== modelId) {
                        return;
                    }
                    const st = getModuleState(modelId, cfg.moduleId);
                    if (!st.enabled) {
                        return;
                    }
                    const inst = modelRegistry.get(modelId);
                    const bones = inst?.mmdModel?.runtimeBones;
                    if (!bones?.length) {
                        return;
                    }

                    const hx = (st.params.handPosX as number) ?? 0;
                    const hy = (st.params.handPosY as number) ?? 0;
                    const hz = (st.params.handPosZ as number) ?? 0;
                    if (hx === 0 && hy === 0 && hz === 0) {
                        return;
                    }

                    const cache = _getArmIkCache(modelId);
                    const ikCandidates =
                        cfg.side === 'L' ? BONE_ARM_IK_L_CANDIDATES : BONE_ARM_IK_R_CANDIDATES;
                    const shoulderCandidates =
                        cfg.side === 'L' ? BONE_SHOULDER_L_CANDIDATES : BONE_SHOULDER_R_CANDIDATES;

                    const ikKey = cfg.side === 'L' ? 'lIk' : 'rIk';
                    const rootKey = cfg.side === 'L' ? 'lRoot' : 'rRoot';

                    if (cache[ikKey] === undefined) {
                        cache[ikKey] = matchBone(
                            bones.map((b) => b.name),
                            ikCandidates
                        );
                    }
                    if (cache[rootKey] === undefined) {
                        cache[rootKey] = matchBone(
                            bones.map((b) => b.name),
                            shoulderCandidates
                        );
                    }

                    const rootName = cache[rootKey] ?? cfg.shoulderBone;
                    _driveArm(bones, cache[ikKey], rootName, [hx, hy, hz], modelId);
                },
                FRAME_HOOK_ORDER.HAND_SYMMETRY,
                cfg.moduleId
            );
            _handFrameHooks.set(modelId, unregister);
        }

        /** 驱动单臂位置偏移（FK 父根骨平移主路径 + IK 重解增强路径） */
        function _driveArm(
            bones: readonly IMmdRuntimeBone[],
            ikName: string | null | undefined,
            rootName: string,
            offset: [number, number, number],
            modelId: string
        ): void {
            if (ikName) {
                const ik = bones.find((b) => b.name === ikName);
                const solver = ik ? (ik as MmdRuntimeBoneExtended).ikSolver : undefined;
                if (ik && solver) {
                    ik.getWorldTranslationToRef(_vOffset);
                    _vOffset.x += offset[0];
                    _vOffset.y += offset[1];
                    _vOffset.z += offset[2];
                    ik.setWorldTranslation(_vOffset);
                    solver.solve(false);
                    const lb = (
                        ik as unknown as {
                            linkedBone?: { getSkeleton?: () => { _markAsDirty?: () => void } };
                        }
                    ).linkedBone;
                    lb?.getSkeleton?.()._markAsDirty?.();
                    return;
                }
            }
            setBoneOverridePosition(rootName, offset, 1, true, modelId);
        }

        const base = createModuleBase(modelId, cfg.moduleId, DEFAULTS, bake, {
            action: ensureActive,
            onDisable: (mid) => {
                _handFrameHooks.unregister(mid);
            },
        });

        return createModuleShell({
            id: cfg.moduleId,
            meta: META,
            priority: 1,
            managedBones,
            buildSchema: () => [
                // ── 手腕旋转 ──
                {
                    id: `${cfg.moduleId}:pitch`,
                    kind: 'slider',
                    label: 'param.pitch',
                    icon: 'lucide:move-vertical',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.pitch`,
                        min: -90,
                        max: 90,
                        step: 1,
                        onChange: (v) => base.setParam('pitch', v as number),
                    },
                },
                {
                    id: `${cfg.moduleId}:yaw`,
                    kind: 'slider',
                    label: 'param.yaw',
                    icon: 'lucide:move-horizontal',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.yaw`,
                        min: -90,
                        max: 90,
                        step: 1,
                        onChange: (v) => base.setParam('yaw', v as number),
                    },
                },
                {
                    id: `${cfg.moduleId}:roll`,
                    kind: 'slider',
                    label: 'param.roll',
                    icon: 'lucide:rotate-cw',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.roll`,
                        min: -90,
                        max: 90,
                        step: 1,
                        onChange: (v) => base.setParam('roll', v as number),
                    },
                },
                // ── 手臂位置偏移 ──
                {
                    id: `${cfg.moduleId}:posSection`,
                    kind: 'sectionTitle',
                    label: 'section.handPosition',
                },
                {
                    id: `${cfg.moduleId}:handPosX`,
                    kind: 'slider',
                    label: 'param.handPosX',
                    icon: 'lucide:move-horizontal',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.handPosX`,
                        min: -10,
                        max: 10,
                        step: 0.1,
                        onChange: (v) => base.setParam('handPosX', v as number),
                    },
                },
                {
                    id: `${cfg.moduleId}:handPosY`,
                    kind: 'slider',
                    label: 'param.handPosY',
                    icon: 'lucide:move-vertical',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.handPosY`,
                        min: -10,
                        max: 10,
                        step: 0.1,
                        onChange: (v) => base.setParam('handPosY', v as number),
                    },
                },
                {
                    id: `${cfg.moduleId}:handPosZ`,
                    kind: 'slider',
                    label: 'param.handPosZ',
                    icon: 'lucide:move',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.handPosZ`,
                        min: -10,
                        max: 10,
                        step: 0.1,
                        onChange: (v) => base.setParam('handPosZ', v as number),
                    },
                },
                // ── 手指姿势 ──
                {
                    id: `${cfg.moduleId}:fingerSection`,
                    kind: 'sectionTitle',
                    label: 'section.fingerPose',
                },
                {
                    id: `${cfg.moduleId}:fingerPreset`,
                    kind: 'modeSlider',
                    label: 'motion.preset',
                    icon: 'lucide:list',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.fingerPreset`,
                        options: [
                            { value: 'relax', label: 'motion.fingerPreset.relax' },
                            { value: 'fist', label: 'motion.fingerPreset.fist' },
                            { value: 'point', label: 'motion.fingerPreset.point' },
                            { value: 'peace', label: 'motion.fingerPreset.peace' },
                            { value: 'rock', label: 'motion.fingerPreset.rock' },
                        ],
                        onChange: (v) => base.setParam('fingerPreset', v as string),
                    },
                },
                {
                    id: `${cfg.moduleId}:fingerIntensity`,
                    kind: 'slider',
                    label: 'motion.intensity',
                    icon: 'lucide:gauge',
                    control: {
                        bind: `motionModule.${cfg.moduleId}.fingerIntensity`,
                        min: 0,
                        max: 1,
                        step: 0.05,
                        onChange: (v) => base.setParam('fingerIntensity', v as number),
                    },
                },
            ],
            base,
        });
    };
}

