// [doc:adr-145] Motion Preset — 多模块协同预设：一键启用组合姿态
// 职责：定义 applyMotionPreset + 转换函数
// MotionPreset / PresetModuleState 类型定义在 core/types.ts（因 ModelInstance 引用）

import type { MotionModuleState, MotionPreset } from '@/core/types';
import { setModuleEnabled, setModuleParam, createModule } from './registry';

/** 序列化格式（含版本号，用于文件/库存储） */
interface MotionPresetFile {
    version: 1;
    presetName?: string;
    preset: MotionPreset;
}

/** MotionModuleState[] → MotionPreset['modules'] */
export function modulesToPresetMap(states: MotionModuleState[]): MotionPreset['modules'] {
    const map: MotionPreset['modules'] = {};
    for (const s of states) {
        map[s.id] = { enabled: s.enabled, params: { ...s.params } };
    }
    return map;
}

/** MotionPreset['modules'] → MotionModuleState[] */
function presetMapToModules(map: MotionPreset['modules']): MotionModuleState[] {
    return Object.entries(map).map(([id, state]) => ({
        id,
        enabled: state.enabled,
        params: { ...state.params },
    }));
}

/**
 * 应用预设到指定模型。
 * 命名加「Motion」前缀，避免与 model-preset.ts 的 applyPresetFromLib 命名冲突。
 * 遍历 preset.modules → setModuleEnabled + setModuleParam + createModule().enable()
 */
export function applyMotionPreset(modelId: string, preset: MotionPreset): void {
    for (const [moduleId, mod] of Object.entries(preset.modules)) {
        if (!mod) {
            continue;
        }
        setModuleEnabled(modelId, moduleId, mod.enabled);
        for (const [key, value] of Object.entries(mod.params)) {
            setModuleParam(modelId, moduleId, key, value);
        }
        const instance = createModule(moduleId, modelId);
        if (instance) {
            if (mod.enabled) {
                instance.enable();
            } else {
                instance.disable();
            }
        }
    }
}

/** 生成唯一预设 ID */
let _presetIdCounter = 0;
export function generatePresetId(): string {
    _presetIdCounter++;
    return `preset_${Date.now()}_${_presetIdCounter}`;
}

// [doc:adr-129] Motion Override Module Registry — 模块注册表 + 场景级配置管理
// 职责: 注册模块工厂、创建模块实例、管理场景级模块配置、ownedBones 冲突仲裁
// 架构变更: 配置存储从 per-model 改为 per-motion（随动作走）
// 冲突仲裁: 每条骨骼同一时刻只能被一个模块 owned；bake 时若骨骼已被其他模块占用，console.warn 跳过
// [doc:adr-166] Perception 模块（perception.*）免于注册表管理，其骨骼由 perception.ts
// 的 _claimPerceptionBones / _releasePerceptionBones 直接通过 BoneOverrideStore 管理，
// 注册表仅作 releaseOwnedBones 的透传入口（claimBones 在 perception.ts 内部绕过本注册表）。

import type { MotionModuleState, ParamValue } from '@/core/types';
import { triggerAutoSave } from '@/core/config';
import type { MotionOverrideModule, ModuleFactory, ModuleMeta } from './types';
import { getBoneOverrideStore } from '../bone-override-store';
import type { ModuleDef } from './types';
import { BODY_POSTURE_DEF } from './body-posture';
import { LEFT_HAND_DEF, RIGHT_HAND_DEF } from './hand-modules';
import { RIDING_MODEL_DEF } from './riding-model';
import { LEFT_FOOT_DEF, RIGHT_FOOT_DEF } from './foot-modules';

// ── 注册表 ──

interface RegistryEntry {
    factory: ModuleFactory;
    meta: ModuleMeta;
    priority: number;
}

/** [doc:pose-debug] 无 VMD 时的模块状态回退存储，确保覆盖/预设面板可用 */
const _fallbackModuleStates = new Map<string, MotionModuleState>();

const _registry = new Map<string, RegistryEntry>();

/** 注册一个动作覆盖模块 */
export function registerModule(
    id: string,
    meta: ModuleMeta,
    priority: number,
    factory: ModuleFactory
): void {
    _registry.set(id, { factory, meta, priority });
}

/** 注销模块 */
export function unregisterModule(id: string): void {
    _registry.delete(id);
}

/** 获取所有已注册模块的元信息（按优先级排序） */
export function getRegisteredModules(): Array<{ id: string; meta: ModuleMeta; priority: number }> {
    return Array.from(_registry.entries())
        .map(([id, entry]) => ({ id, meta: entry.meta, priority: entry.priority }))
        .sort((a, b) => a.priority - b.priority);
}

/** 为指定模型创建模块实例 */
export function createModule(id: string, modelId: string): MotionOverrideModule | null {
    initMotionModules(); // 幂等兜底：确保注册表已就绪
    const entry = _registry.get(id);
    if (!entry) {
        return null;
    }
    return entry.factory(modelId);
}

// ── 场景级配置管理（per-motion，随动作走）──

import { getActiveMotion, findOrCreateModuleState } from '../motion-intent';

/**
 * 获取当前动作的模块配置（不存在则创建默认状态，种入 defaults）。
 * [doc:adr-121 P4-4] _modelId 未使用：ADR-129 将配置存储从 per-model 改为 per-motion（随动作走），
 * 保留参数仅为维持接口兼容（UI 调用方均传入 modelId）。
 */
export function getModuleState(_modelId: string, moduleId: string): MotionModuleState {
    initMotionModules(); // 幂等兜底
    const intent = getActiveMotion();

    // [doc:pose-debug] 无 VMD 时使用回退存储，避免 enable/bake 读写不一致
    if (!intent) {
        let state = _fallbackModuleStates.get(moduleId);
        if (!state) {
            state = { id: moduleId, enabled: false, params: {} };
            const entry = _registry.get(moduleId);
            if (entry?.meta.defaults) {
                state.params = { ...entry.meta.defaults };
            }
            _fallbackModuleStates.set(moduleId, state);
        }
        return state;
    }

    // 快速路径：已存在则直接返回
    if (intent.motionModules) {
        const existing = intent.motionModules.find((m) => m.id === moduleId);
        if (existing) {
            return existing;
        }
    }

    // 创建路径：通过 findOrCreateModuleState 收敛 mutate 入口 [doc:adr-121 P4-1]
    const state = findOrCreateModuleState(intent, moduleId);

    // 将模块注册的默认值种入 params，避免 schema 首次渲染读到 undefined
    const entry = _registry.get(moduleId);
    const defs = entry?.meta.defaults;
    if (defs) {
        state.params = { ...defs };
    }
    return state;
}

/**
 * [doc:adr-116] 读取模块注册的默认参数值。
 * 供菜单滑块在未 seed（inst.motionOverrideModules 为空）时回退，
 * 避免 getStateValue 返回 undefined 导致滑块显示成负值 min（Q2 修复）。
 */
export function getModuleDefaultParam(moduleId: string, paramKey: string): ParamValue | undefined {
    const entry = _registry.get(moduleId);
    return entry?.meta.defaults?.[paramKey];
}

/** 写入模块参数到场景动作意图 */
export function setModuleParam(
    _modelId: string,
    moduleId: string,
    param: string,
    value: ParamValue
): void {
    const state = getModuleState(_modelId, moduleId);
    state.params[param] = value;
    // 仅持久化：配置已写入 intent.motionModules（随动作走）。
    // 注意：不再调用 setActiveMotion 重新广播——否则会触发 VMD 重载 + seekAnimation(0)，
    // 每次调参都把动画重启到帧 0，表现为角色持续抖动 + 进度重置（ADR-129 回归）。
    triggerAutoSave();
}

/** 设置模块启用/禁用状态到场景动作意图 */
export function setModuleEnabled(_modelId: string, moduleId: string, enabled: boolean): void {
    const state = getModuleState(_modelId, moduleId);
    state.enabled = enabled;
    // 仅持久化（原因同 setModuleParam：避免重新广播导致 VMD 重载抖动）
    triggerAutoSave();
}

/**
 * 为模块声明对一组骨骼的所有权（bake 前调用）。
 * 冲突仲裁: 按 priority 抢占（数值越小优先级越高）。
 * - 若新模块 priority < 冲突方，则抢占（清落败方 ownedBones + 引擎 slot）
 * - 否则跳过并 console.warn
 * 返回实际成功 claim 的骨骼列表。
 *
 * [doc:adr-147 Phase 2 step 2] 所有权与冲突状态现已委托 BoneOverrideStore 单例，
 * 本文件仅作 thin facade（保留旧公开签名与 {bone,byModule} 冲突形状，供 UI/测试兼容）。
 */
export function claimBones(modelId: string, moduleId: string, bones: readonly string[]): string[] {
    const myPriority = _registry.get(moduleId)?.priority ?? 999;
    return getBoneOverrideStore().claimBones(modelId, moduleId, myPriority, bones);
}

/** 获取模块当前 owned 的骨骼（disable 时用于精确清除） */
export function getOwnedBones(modelId: string, moduleId: string): Set<string> {
    return getBoneOverrideStore().getOwnedBones(modelId, moduleId);
}

// ── 骨骼冲突查询（供 UI 冲突可视化；[doc:adr-116 conflict-visibility]）──
// 冲突状态由 BoneOverrideStore 存储（store.getConflicts 返回 loser/winner 视角），
// 此处重新映射回旧 {bone, byModule} 形状并按 loser 分组，保持 UI/测试兼容。

export interface BoneConflict {
    /** 被抢占的骨骼名 */
    bone: string;
    /** 抢占方模块 id */
    byModule: string;
    /** [doc:timing P1 fix] 抢占方优先级（数值越小优先级越高），用于 UI 显示覆盖者优先级编号 */
    winnerPriority: number;
    /** [doc:timing P1 fix] 落败方优先级 */
    loserPriority: number;
}

/** 获取某模块被其他模块抢占的骨骼明细（loser 视角：本模块想要但被谁抢） */
export function getModuleConflicts(modelId: string, moduleId: string): BoneConflict[] {
    return getBoneOverrideStore()
        .getConflicts(modelId)
        .filter((c) => c.loserModuleId === moduleId)
        .map((c) => ({
            bone: c.bone,
            byModule: c.winnerModuleId,
            winnerPriority: c.winnerPriority,
            loserPriority: c.loserPriority,
        }));
}

/** 获取某模型全部模块的冲突明细（按 loser 模块分组） */
export function getAllConflicts(
    modelId: string
): Array<{ moduleId: string; conflicts: BoneConflict[] }> {
    const byLoser = new Map<string, BoneConflict[]>();
    for (const c of getBoneOverrideStore().getConflicts(modelId)) {
        const entry: BoneConflict = {
            bone: c.bone,
            byModule: c.winnerModuleId,
            winnerPriority: c.winnerPriority,
            loserPriority: c.loserPriority,
        };
        const list = byLoser.get(c.loserModuleId);
        if (list) {
            list.push(entry);
        } else {
            byLoser.set(c.loserModuleId, [entry]);
        }
    }
    return Array.from(byLoser.entries()).map(([mid, conflicts]) => ({ moduleId: mid, conflicts }));
}

/** 获取某模型冲突总数（骨骼数） */
export function getConflictCount(modelId: string): number {
    return getBoneOverrideStore().getConflicts(modelId).length;
}

/**
 * [doc:adr-116 P3] 判定指定骨骼是否被「其他模块」占用（无副作用、不 warn）。
 * 用于时间驱动模块（sway/riding）的帧钩子做让位判定：
 * 若被高优先级模块占用则让位，否则可安全重新认领。区别于 claimBones（会触发 warn / 抢占副作用）。
 */
function isBoneOwnedByOther(modelId: string, moduleId: string, bone: string): boolean {
    const owner = getBoneOverrideStore().getBoneOwnerModule(modelId, bone);
    return owner !== null && owner !== moduleId;
}

/** 释放模块的 ownedBones 记录并级联清引擎槽（由 store.releaseBones 负责清除） */
export function releaseOwnedBones(modelId: string, moduleId: string): Set<string> {
    return getBoneOverrideStore().releaseBones(modelId, moduleId);
}

// ── 模型切换管理 ──

let _currentModelId: string | null = null;

/**
 * 切换目标模型：禁用当前模型的所有模块覆盖，启用新模型已保存的模块状态。
 * [doc:adr-129] 现在模块配置随动作走，此函数主要用于清理 ownedBones
 */
export function setTargetModel(modelId: string | null): void {
    initMotionModules(); // 幂等兜底：确保注册表已就绪
    if (_currentModelId === modelId) {
        return;
    }

    // 清理旧模型的 ownedBones（配置已随动作，不需要同步）
    if (_currentModelId) {
        for (const moduleId of _registry.keys()) {
            const mod = createModule(moduleId, _currentModelId);
            if (mod) {
                // 禁用模块，释放 ownedBones
                mod.disable();
            }
        }
    }

    _currentModelId = modelId;

    // 启用新模型的模块（从场景级配置读取状态）
    if (modelId) {
        const intent = getActiveMotion();
        if (intent?.motionModules) {
            for (const state of intent.motionModules) {
                if (state.enabled) {
                    const mod = createModule(state.id, modelId);
                    if (mod) {
                        mod.enable();
                        // 应用参数
                        for (const [key, value] of Object.entries(state.params)) {
                            mod.setParam?.(key, value);
                        }
                    }
                }
            }
        }
    }
}

/** 清除指定模型的所有模块覆盖（删除模型时调用） */
export function clearAllModulesForModel(modelId: string): void {
    // 释放并清除所有 ownedBones + 引擎槽（委托 store.disposeModel）
    getBoneOverrideStore().disposeModel(modelId);
}

/**
 * [doc:adr-129] 将场景级模块配置应用到指定模型
 * 用于动作广播时应用配置到所有 inherit 模型
 */
export function applyMotionModulesToModel(modelId: string): void {
    const intent = getActiveMotion();
    if (!intent?.motionModules) {
        return;
    }

    for (const state of intent.motionModules) {
        const mod = createModule(state.id, modelId);
        if (!mod) {
            continue;
        }

        if (state.enabled) {
            mod.enable();
            // 应用参数
            for (const [key, value] of Object.entries(state.params)) {
                mod.setParam?.(key, value);
            }
        } else {
            mod.disable();
        }
    }
}

// ── 内置模块自动注册 ──

let _initialized = false;

/**
 * 内置模块定义聚合（供 initMotionModules 批量注册，消除 6 个 registerXxx 分散调用）。
 * 使用惰性求值函数而非顶层数组字面量：registry 与工厂模块存在循环依赖
 * （工厂 import registry 取 getModuleState/claimBones，registry import 工厂取 DEF），
 * 若顶层字面量在模块求值期捕获 DEF 值，当某工厂被先于 registry 求值时会出现 TDZ
 * （典型：测试先 import hand-modules 再 import registry → LEFT_HAND_DEF 为 undefined）。
 * 改为在 initMotionModules 调用时（所有模块已加载完成）读取绑定，规避求值顺序问题。
 */
export function getBuiltinModuleDefs(): ModuleDef[] {
    return [
        BODY_POSTURE_DEF,
        LEFT_HAND_DEF,
        RIGHT_HAND_DEF,
        RIDING_MODEL_DEF,
        LEFT_FOOT_DEF,
        RIGHT_FOOT_DEF,
    ];
}

/** 注册所有内置模块（幂等，重复调用安全） */
export function initMotionModules(): void {
    if (_initialized) {
        return;
    }
    for (const def of getBuiltinModuleDefs()) {
        registerModule(def.id, def.meta, def.priority, def.factory);
    }
    _initialized = true;
}

// [doc:adr-079] 感知层 — 重心微动（躯干骨骼平衡微晃，从 proc-motion-idle.ts 迁移）

import { Quaternion } from '@babylonjs/core/Maths/math.vector';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';

import {
    BONE_CENTER_CANDIDATES,
    BONE_UPPER2_CANDIDATES,
    BONE_WAIST_CANDIDATES,
    BONE_ALLPARENT_CANDIDATES,
    matchBone,
} from '../../motion-algos/proc-motion-shared';
import { _q } from './perception-shared';
import type {
    BalanceSwayState,
    MmdModelLike,
    PerceptionContext,
    PerceptionTier,
} from './perception-shared';

/** 重心微动周期（秒，从 idle loopFrames=120@60fps 转换：120/60=2s） */
const _BALANCE_SWAY_PERIOD = 2.0;
/** 重心微动各骨骼振幅（从 idle 算法提取，已削至微动量级，intensity 固定 1.0） */
const SWAY_AMP = {
    center_rz: 0.05, // center 慢速摆动（削半：原 0.1 → 0.05，避免 VMD 播放时过晃）
    center_rx: 0.02, // center 微动（原 0.03）
    center_bobY: 0.03, // center 上下浮动（原 0.04）
    upper2_rx: 0.015, // 上半身2 前后倾（不变）
    waist_rz: 0.015, // 腰 左右摆（原 0.02，配合 center_rz 削幅）
    allParent_rx: 0.005, // 全ての親 微倾（不变）
    allParent_rz: 0.005, // （不变）
};

/** 旋转增量缩放系数（<1.0 使微动更柔和，保留 VMD 基准旋转） */
const SWAY_DELTA_FACTOR = 0.6;

/** 重置增量状态到默认值（每个模型 context 独立持有 balanceState，避免跨模型污染） */
export function _resetBalanceSwayState(state: BalanceSwayState): void {
    state.lastBobY = 0;
    state.swayCenterName = null;
    state.lastCenterRz = 0;
    state.lastCenterRx = 0;
    state.lastUpperRx = 0;
    state.lastWaistRz = 0;
    state.lastAllParentRx = 0;
    state.lastAllParentRz = 0;
}

export function _applyBalanceSway(
    mmdModel: MmdModelLike,
    time: number,
    ctx: PerceptionContext,
    centerClaimed?: readonly string[],
    upper2Claimed?: readonly string[],
    waistClaimed?: readonly string[],
    tier?: PerceptionTier
): void {
    const enabled = ctx.state.balanceSwayEnabled;
    const period = ctx.state.balanceSwayPeriod;
    const amplitude = ctx.state.balanceSwayAmplitude;
    const balanceState = ctx.lastOffsets.balance;
    // [doc:adr-164] tier 守卫：low 跳过
    if (tier === 'low') {
        return;
    }
    const boneNames: string[] = mmdModel.runtimeBones.map((b: IMmdRuntimeBone) => b.name);
    const centerName = matchBone(boneNames, BONE_CENTER_CANDIDATES);
    const upper2Name = matchBone(boneNames, BONE_UPPER2_CANDIDATES);
    const waistName = matchBone(boneNames, BONE_WAIST_CANDIDATES);
    const allParentName = matchBone(boneNames, BONE_ALLPARENT_CANDIDATES);

    // 关闭时撤销 center position 的 bob 残留 + 重置增量状态（避免残留冻结）
    if (!enabled || amplitude === 0) {
        if (balanceState.lastBobY !== 0 && balanceState.swayCenterName) {
            const bone = mmdModel.runtimeBones.find(
                (b: IMmdRuntimeBone) => b.name === balanceState.swayCenterName
            );
            if (bone?.linkedBone) {
                bone.linkedBone.position.y -= balanceState.lastBobY;
            }
        }
        _resetBalanceSwayState(balanceState);
        return;
    }

    const phase = ((time % period) / period) * Math.PI * 2;
    const slowPhase = phase * 0.5;

    // center: position bobY + rotation rz/rx
    if (centerName) {
        const bone = mmdModel.runtimeBones.find((b: IMmdRuntimeBone) => b.name === centerName);
        if (bone?.linkedBone && (!centerClaimed || centerClaimed.includes(centerName))) {
            const bobY = Math.sin(phase) * SWAY_AMP.center_bobY * amplitude;
            // 增量叠加：先撤上帧 bob，再加本帧 bob，保持基准 position.y 不变（修复塌到地面）
            bone.linkedBone.position.y = bone.linkedBone.position.y - balanceState.lastBobY + bobY;
            balanceState.lastBobY = bobY;
            balanceState.swayCenterName = centerName;

            const rz = Math.sin(slowPhase) * SWAY_AMP.center_rz * amplitude;
            const rx = Math.sin(phase * 0.37 + 0.5) * SWAY_AMP.center_rx * amplitude;
            // rotation 增量叠加（deltaQ * currentQ × SWAY_DELTA_FACTOR，
            // 避免 Slerp 平均吃掉非零基准旋转 / VMD 旋转，同时控制振幅感知）
            const deltaCenterRz = (rz - balanceState.lastCenterRz) * SWAY_DELTA_FACTOR;
            const deltaCenterRx = (rx - balanceState.lastCenterRx) * SWAY_DELTA_FACTOR;
            if (
                (deltaCenterRz !== 0 || deltaCenterRx !== 0) &&
                bone.linkedBone.rotationQuaternion
            ) {
                const deltaQ = _q().copyFrom(
                    Quaternion.FromEulerAngles(deltaCenterRx, 0, deltaCenterRz)
                );
                const localQ = _q().copyFrom(bone.linkedBone.rotationQuaternion);
                deltaQ.multiplyToRef(localQ, localQ);
                bone.linkedBone.rotationQuaternion.copyFrom(localQ);
            }
            balanceState.lastCenterRz = rz;
            balanceState.lastCenterRx = rx;
        }
    }

    // upper2: rotation rx
    if (upper2Name) {
        const bone = mmdModel.runtimeBones.find((b: IMmdRuntimeBone) => b.name === upper2Name);
        if (bone?.linkedBone && (!upper2Claimed || upper2Claimed.includes(upper2Name))) {
            const rx = Math.sin(phase * 0.7 + 0.3) * SWAY_AMP.upper2_rx * amplitude;
            const deltaRx = (rx - balanceState.lastUpperRx) * SWAY_DELTA_FACTOR;
            if (deltaRx !== 0 && bone.linkedBone.rotationQuaternion) {
                const deltaQ = _q().copyFrom(Quaternion.FromEulerAngles(deltaRx, 0, 0));
                const localQ = _q().copyFrom(bone.linkedBone.rotationQuaternion);
                deltaQ.multiplyToRef(localQ, localQ);
                bone.linkedBone.rotationQuaternion.copyFrom(localQ);
            }
            balanceState.lastUpperRx = rx;
        }
    }

    // waist: rotation rz
    if (waistName) {
        const bone = mmdModel.runtimeBones.find((b: IMmdRuntimeBone) => b.name === waistName);
        if (bone?.linkedBone && (!waistClaimed || waistClaimed.includes(waistName))) {
            const rz = Math.sin(phase + 0.5) * SWAY_AMP.waist_rz * amplitude;
            const deltaRz = (rz - balanceState.lastWaistRz) * SWAY_DELTA_FACTOR;
            if (deltaRz !== 0 && bone.linkedBone.rotationQuaternion) {
                const deltaQ = _q().copyFrom(Quaternion.FromEulerAngles(0, 0, deltaRz));
                const localQ = _q().copyFrom(bone.linkedBone.rotationQuaternion);
                deltaQ.multiplyToRef(localQ, localQ);
                bone.linkedBone.rotationQuaternion.copyFrom(localQ);
            }
            balanceState.lastWaistRz = rz;
        }
    }

    // allParent: rotation rx/rz（归属 perception.balance.center）
    if (allParentName) {
        const bone = mmdModel.runtimeBones.find((b: IMmdRuntimeBone) => b.name === allParentName);
        if (bone?.linkedBone && (!centerClaimed || centerClaimed.includes(allParentName))) {
            const rx = Math.sin(phase * 0.2 + 1.1) * SWAY_AMP.allParent_rx * amplitude;
            const rz = Math.sin(phase * 0.3 + 2.3) * SWAY_AMP.allParent_rz * amplitude;
            const deltaRx = (rx - balanceState.lastAllParentRx) * SWAY_DELTA_FACTOR;
            const deltaRz = (rz - balanceState.lastAllParentRz) * SWAY_DELTA_FACTOR;
            if ((deltaRx !== 0 || deltaRz !== 0) && bone.linkedBone.rotationQuaternion) {
                const deltaQ = _q().copyFrom(Quaternion.FromEulerAngles(deltaRx, 0, deltaRz));
                const localQ = _q().copyFrom(bone.linkedBone.rotationQuaternion);
                deltaQ.multiplyToRef(localQ, localQ);
                bone.linkedBone.rotationQuaternion.copyFrom(localQ);
            }
            balanceState.lastAllParentRx = rx;
            balanceState.lastAllParentRz = rz;
        }
    }
}

// [doc:adr-071] 感知层 — 视线追踪 JS 路径写入策略
// 共用骨架见 perception-gaze.ts:_applyHeadGazeCore / _applyEyeGazeCore
// 本文件仅实现 JS 路径的写入差异：改 linkedBone + 调 updateWorldMatrix

import { Quaternion, Matrix } from '@babylonjs/core/Maths/math.vector';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';

import type { MmdRuntimeBoneExtended } from '@/core/types';
import { _m, _q, type GazeCache } from './perception-shared';
import { _updateBoneChain } from './perception-breathing';
import {
    _applyHeadGazeCore,
    _applyEyeGazeCore,
    type HeadGazeWriteStrategy,
    type EyeGazeWriteStrategy,
} from './perception-gaze';

/** JS 路径头部写入策略：改 linkedBone.rotationQuaternion + _updateBoneChain 传播 */
const _jsHeadStrategy: HeadGazeWriteStrategy = {
    writeHead(headRuntime, finalQ, _headPos, _oldHeadMat, parentWorldQ): void {
        // localQ = invParentQ × finalQ（core 已算过一次，但 strategy 不知道；这里重算以保持策略自包含）
        const parentBone = headRuntime.parentBone;
        const parentWorldInv = _m();
        if (parentBone) {
            const parentMat = _m().copyFrom(Matrix.FromArray(parentBone.worldMatrix));
            parentMat.invertToRef(parentWorldInv);
        } else {
            Matrix.IdentityToRef(parentWorldInv);
        }
        const parentInvQ = Quaternion.FromRotationMatrix(parentWorldInv);
        const localQ = _q();
        parentInvQ.multiplyToRef(finalQ, localQ);

        // 写入既有实例，不外泄池引用
        const headQ = headRuntime.linkedBone.rotationQuaternion;
        if (headQ) {
            headQ.copyFrom(localQ);
        }
        _updateBoneChain(headRuntime);
    },
};

/** JS 路径眼部写入策略：改 linkedBone.rotationQuaternion + updateWorldMatrix 传播 */
const _jsEyeStrategy: EyeGazeWriteStrategy = {
    writeEye(eyeRb, _finalEyeQ, localQ, _eyeMat, _parentWorldQ): void {
        const eyeQ = eyeRb.linkedBone.rotationQuaternion;
        if (eyeQ) {
            eyeQ.copyFrom(localQ);
        }
        (eyeRb as MmdRuntimeBoneExtended).updateWorldMatrix?.(false, false);
    },
};

/** JS 模式：头部跟随（薄包装：调用 core + 注入 JS 写入策略） */
export function _applyHeadGazeJS(
    headRuntime: IMmdRuntimeBone,
    gazeTarget: import('@babylonjs/core/Maths/math.vector').Vector3,
    dt: number,
    cache?: GazeCache
): void {
    _applyHeadGazeCore(headRuntime, gazeTarget, dt, cache, _jsHeadStrategy);
}

/** JS 模式：眼部跟随（薄包装：调用 core + 注入 JS 写入策略） */
export function _applyEyeGazeJS(
    eyeRuntimes: IMmdRuntimeBone[],
    gazeTarget: import('@babylonjs/core/Maths/math.vector').Vector3,
    dt: number,
    cache?: GazeCache
): void {
    _applyEyeGazeCore(eyeRuntimes, gazeTarget, dt, cache, _jsEyeStrategy);
}

// [doc:adr-071] 感知层 — 视线追踪（头部跟随 + 眼部跟随，WASM/JS 双路径调度）
// WASM 路径实现 → perception-gaze-wasm.ts
// JS   路径实现 → perception-gaze-js.ts

import { Quaternion, Vector3, Matrix } from '@babylonjs/core/Maths/math.vector';
import { Camera } from '@babylonjs/core/Cameras/camera';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';

import type { MmdRuntimeBoneExtended } from '@/core/types';
import { isARActive } from '../ar/ar-camera';
import { transformWorldToRootLocal } from '@/core/mmd-adapter';
import type {
    MeshMetadata,
    GazeConfig,
    MmdModelLike,
    PerceptionTier,
    GazeCache,
} from './perception-shared';
import {
    _v3,
    _q,
    _m,
    _gazeAlpha,
    _gazeLog,
    _qAngleDeg,
    _isWasmRuntime,
