    _writeMatToBuffer,
    _propagateChildrenWasm,
    _isWasmRuntime,
    _gazeAlpha,
    setGazeAngles,
    PerceptionPerfMonitor,
    _createPerceptionPool,
} from './perception-shared';
import {
