import {
    MmdCompositeAnimation,
    MmdAnimationSpan,
} from 'babylon-mmd/esm/Runtime/Animation/mmdCompositeAnimation';
import type { VmdLayer } from '@/core/types';
import {
    mmdRuntime,
    modelRegistry,
    focusedModelId,
    setStatus,
    triggerAutoSave,
    isPlaying,
    autoLoop,
    setIsPlaying,
