function getScene() {
    return import('../scene') as Promise<typeof import('../scene')>;
}

// 缓存已加载的同名伴音，避免重复加载
const _companionAudioCache = new Set<string>();

// Generation counter: per-model，每次 loadVMDMotion 调用递增，await 后检查是否过期
// 全局单例会导致多模型同时加载时互相干扰（慢的被错误判定为过期）
const _vmdLoadGenMap = new Map<string, number>();

// VMD 签名：前 25 字节为 "Vocaloid Motion Data 0002"，共 30 字节（含 \0 填充）
const VMD_SIGNATURE = 'Vocaloid Motion Data 0002';
const VMD_HEADER_MIN = 50; // 30(签名+模型名) + 4(骨骼帧数) 的最小合法头部

/** 验证 ArrayBuffer 是否为合法 VMD 格式：检查签名前缀。
 *  程序化生成的 VMD 也使用此签名（vmd-writer.ts SIGNATURE 常量）。 */
function isValidVmd(data: ArrayBuffer): boolean {
    if (data.byteLength < VMD_HEADER_MIN) {
        return false;
    }
    const sig = new TextDecoder('ascii').decode(new Uint8Array(data, 0, 25));
    return sig === VMD_SIGNATURE;
}

// ======== VMD Loading ========
export async function loadVMDMotion(
    data: ArrayBuffer,
    name: string,
    targetModelId?: string,
    signal?: AbortSignal,
    _vmdPath?: string
): Promise<void> {
    if (signal?.aborted) {
        throw new DOMException('Aborted', 'AbortError');
    }
    if (!isValidVmd(data)) {
        feedbackStatus('scene.vmd.loadFailed', undefined, false);
        logWarn('vmd-loader', 'Invalid VMD signature, rejected:', name);
        return;
    }
    const {
        scene,
        focusedMmdModel: _focusedMmdModel,
        isProcVmdActive,
        stopProcMotion,
        focusedModel: _focusedModel,
    } = await getScene();
    if (signal?.aborted) {
        throw new DOMException('Aborted', 'AbortError');
    }
    if (!mmdRuntime) {
        // [doc:adr-169] 运行时未就绪，不污染场景库；仅提示用户等待
        feedbackStatus('scene.vmd.cachedWaiting', undefined, false);
        return;
    }
    const targetId = targetModelId || focusedModelId;
    if (!targetId) {
        feedbackStatus('scene.vmd.noTargetModel', undefined, false);
        return;
    }
    const inst = modelRegistry.get(targetId);
    if (!inst) {
        feedbackStatus('scene.vmd.targetNotFound', undefined, false);
        return;
    }
    const prevGen = _vmdLoadGenMap.get(targetId) ?? 0;
    const capturedGen = prevGen + 1;
    _vmdLoadGenMap.set(targetId, capturedGen);
    try {
        // Load VMD from buffer using VmdLoader
        const vmdLoader = new VmdLoader(scene);
        const mmdAnimation = await vmdLoader.loadFromBufferAsync(name, data);
        // babylon-mmd fork 的 VmdLoader 无实例状态需释放（解析结果已转移到 mmdAnimation），
        // 不存在 dispose() API；loader 为局部引用，GC 自动回收，无需手动释放。

        // 检查是否在 await 期间有新的 loadVMDMotion 调用（同模型），过期则丢弃
        if (_vmdLoadGenMap.get(targetId) !== capturedGen) {
            logWarn('vmd-loader', 'Stale loadVMDMotion result discarded:', name);
            feedbackStatus('scene.vmd.loadFailed', undefined, false);
            return;
        }

        // Create runtime animation from the loaded data
        // WASM 版需 MmdWasmAnimation 包装；JS 版直接用 mmdAnimation（实现 IMmdBindableModelAnimation）
        let runtimeAnimation: import('babylon-mmd/esm/Runtime/Animation/IMmdBindableAnimation').IMmdBindableModelAnimation;
        if (mmdRuntime instanceof MmdWasmRuntime) {
            runtimeAnimation = new MmdWasmAnimation(mmdAnimation, mmdRuntime.wasmInstance, scene);
        } else {
            runtimeAnimation = mmdAnimation;
        }

        // Extract camera track from VMD and apply to MmdCamera
        try {
            loadCameraVmd(mmdAnimation, '', name);
        } catch {
            // 程序化动作的 VMD 不含相机轨道，此处跳过是正常行为
        }

        // Bind to model
        if (!inst.mmdModel) {
            // 动画已创建但模型是 Stage，无法绑定 — 清理避免泄漏（仅 WASM 版有资源需释放）
            if (runtimeAnimation instanceof MmdWasmAnimation) {
                try {
                    runtimeAnimation.dispose?.();
                } catch {
                    // Intentionally empty — 舞台模型动画句柄清理失败不影响后续流程
                }
            }
            feedbackStatus('scene.vmd.stageNoVmd', undefined, false);
            return;
        }
        // 切换 VMD：释放旧句柄 + 绑定新动画 + 归零时钟（封装于 mmd-adapter PlaybackContract，见 ADR-192）。
        // 固化 setRuntimeAnimation 不重置时钟 + WASM 句柄需显式 dispose 的 babylon-mmd 行为缺陷。
        await switchAnimation(mmdRuntime, inst.mmdModel, runtimeAnimation);

        inst.vmdData = data;
        // 停止程序化动作（延迟到 vmdData 赋值后，确保 stopProcMotion 内 userVmdPresent=true，
        // 不会清空刚绑定的动画——否则缩略图截帧时动画已被清空，截到空姿态）
        if (isProcVmdActive() && name !== PROC_VMD_NAME_IDLE && name !== PROC_VMD_NAME_AUTODANCE) {
            stopProcMotion();
        }
        _companionAudioCache.clear();
        inst.vmdName = name;
        // Convert from 30fps frames to seconds（异常 VMD 兜底，避免 NaN 时长）
        const endFrame = Number(mmdAnimation.endFrame);
        inst.animationDuration = Number.isFinite(endFrame) && endFrame > 0 ? endFrame / 30 : 0;

        if (!isPlaying && autoLoop) {
            await mmdRuntime.playAnimation();
            setIsPlaying(true);
        }
        // [doc:adr-feedback] VMD 加载是中间步骤，走状态栏；若为模型替换流程的伴音 VMD，
        // 后续 loadCompanionAudio 完成时仍由状态栏汇总反馈，避免与"模型已替换"toast 叠加。
        feedbackStatus('scene.vmd.loaded', undefined, undefined, { name });
        triggerAutoSave();
    } catch (err) {
        console.error('VMD load failed:', err);
        feedbackStatus('scene.vmd.loadFailed', undefined, false);
    }
}

export async function loadVMDFromPath(
    path: string,
    targetModelId?: string,
    signal?: AbortSignal,
    skipSceneIntent?: boolean
): Promise<void> {
    const { focusedMmdModel, focusedModel } = await getScene();
    await withLoadingIndicator('scene.loader.vmdLoading', async () => {
        try {
            const vmdBytes = await readFileBytes(path);
            if (!vmdBytes) {
                return;
            }
            const vmdData = vmdBytes.buffer as ArrayBuffer;
            const vmdName = getBaseName(path) || '';
            const vmdDisplayName = vmdName.replace(/\.vmd$/i, '');

            if (mmdRuntime && (targetModelId || focusedMmdModel())) {
                await loadVMDMotion(
                    vmdData,
                    vmdName.replace(/\.vmd$/i, ''),
                    targetModelId,
                    signal,
                    path
                );
                const foc = targetModelId ? modelRegistry.get(targetModelId) : focusedModel();
                if (foc) {
                    foc.vmdPath = path;
                }
                // 设置场景级默认动作（守卫：避免同路径重复触发广播）
                // [fix:adr-167] skipSceneIntent 时跳过：per-model 应用（applyIntentToModel /
                // 程序化切回）不应触碰场景库。
                // [adr-169] 用 replaceDefaultMotion 原位替换默认：旧默认被顶替移除，
                // 其余主动作保留（取代已废弃的 setActiveMotion 单例清库语义）。
                if (!skipSceneIntent) {
                    const cur = getActiveMotion();
                    if (!cur || cur.vmdPath !== path) {
                        replaceDefaultMotion({
                            vmdPath: path,
                            vmdName: vmdName.replace(/\.vmd$/i, ''),
                            vmdLayers: [],
                            source: 'vmd',
                        });
                    }
                }
            } else if (!skipSceneIntent) {
                replaceDefaultMotion({
                    vmdPath: path,
                    vmdName: vmdName.replace(/\.vmd$/i, ''),
                    vmdLayers: [],
                    source: 'vmd',
                });
                feedbackStatus('scene.vmd.cachedAutoApply', undefined, false);
            }

            // 记录最近使用动作
            addRecentMotion(path, vmdDisplayName);

            // 尝试加载同目录下的同名音频文件
            const audioTargetId = targetModelId || focusedModelId;
            await _tryLoadCompanionAudio(path, path, audioTargetId);
        } catch (err) {
            // 中止（AbortError）不算失败：loadVMDMotion 在 signal 中止时抛此错，
            // 此时 vmdPath/addRecentMotion/音频等副作用已被 throw 跳过，无需报错 UI
            if ((err as DOMException)?.name === 'AbortError') {
                return;
            }
            console.error('loadVMDFromPath:', err);
            feedbackStatus('scene.vmd.loadFailed', undefined, false);
        }
    });
}

/** 尝试加载 VMD 同目录下的同名音频文件（.mp3/.wav/.ogg/.flac）。 */
async function _tryLoadCompanionAudio(
    vmdPath: string,
    vmdUrl: string,
    targetModelId?: string
): Promise<void> {
    if (!isAutoLoadCompanionAudioEnabled()) {
        return;
    }
    // [doc:adr-057] vmdUrl 形如 http://127.0.0.1:port/?f=<base64>
    // 提取 origin+port 作为音频探针的基地址，文件名通过 ?f= 查询参数传递
    const urlObj = new URL(vmdUrl);
    const baseOrigin = `${urlObj.protocol}//${urlObj.host}`;
    const basePath = vmdPath.replace(/\.vmd$/i, '');
    if (_companionAudioCache.has(basePath)) {
        return;
    }

    // 记录加载前的 generation 值，加载完成后校验是否过期
    // （用户在加载期间切换了 VMD 则丢弃本次伴音结果）
    const genBefore = _vmdLoadGenMap.get(targetModelId || '') ?? 0;

    const exts = ['.mp3', '.wav', '.ogg', '.flac', '.wma'];

    // 并行 HEAD 探针，取首个成功的扩展名（Promise.any 只取最快的成功结果）
    const probes = exts.map(async (ext) => {
        const audioPath = basePath + ext;
        const audioName = getBaseName(audioPath) || '';
        const probeUrl = `${baseOrigin}/?f=${encodeFileRef(audioName)}`;
        const resp = await fetch(probeUrl, { method: 'HEAD' });
        if (!resp.ok) {
            throw new Error(`HTTP ${resp.status}`);
        }
        return { audioPath, audioName };
    });

    try {
        const { audioPath, audioName } = await Promise.any(probes);

        // 竞态检查：加载期间模型 VMD 是否被切换
        const tid = targetModelId || '';
        if (tid && _vmdLoadGenMap.get(tid) !== genBefore) {
            return; // VMD 已被切换，丢弃本次伴音
        }

        await loadAudioFile(audioPath);
        _companionAudioCache.add(basePath);
        // [doc:adr-feedback] 伴音加载是中间步骤，走状态栏；模型替换的最终态由"模型已替换"toast 承担。
        feedbackStatus('scene.vmd.loadedWithAudio', undefined, undefined, { name: audioName });
        // 确保播放栏可见
        const { updatePlaybackUI } = await import('./playback');
        updatePlaybackUI();
    } catch {
        // 所有扩展名都未找到，静默跳过
    }
}

export async function loadCameraVmdFromPath(path: string, _signal?: AbortSignal): Promise<void> {
    const { scene } = await getScene();
    await withLoadingIndicator('scene.loader.cameraVmdLoading', async () => {
        try {
            const vmdBytes = await readFileBytes(path);
            if (!vmdBytes) {
                return;
            }
            const vmdData = vmdBytes.buffer as ArrayBuffer;
            const vmdName = getBaseName(path) || '';

            const vmdLoader = new VmdLoader(scene);
            const mmdAnimation = await vmdLoader.loadFromBufferAsync(vmdName, vmdData);
            // VmdLoader 无实例状态需释放（解析结果已转移到 mmdAnimation），GC 自动回收
            loadCameraVmd(mmdAnimation, path, vmdName.replace(/\.vmd$/i, ''));
            showInfoToast(t('scene.vmd.cameraLoaded', { name: vmdName }));
            triggerAutoSave();
        } catch (err) {
            console.error('loadCameraVmdFromPath:', err);
            feedbackStatus('scene.vmd.cameraLoadFailed', undefined, false);
        }
    });
}

export async function loadVPDPose(
    path: string,
    targetModelId?: string,
    _signal?: AbortSignal
): Promise<void> {
    const { focusedModel, stopProcMotion, isProcVmdActive } = await getScene();
    await withLoadingIndicator('scene.loader.vpdLoading', async () => {
        try {
            const rawBytes = await readFileBytes(path);
            if (!rawBytes) {
                return;
            }
            const rawData = rawBytes.buffer as ArrayBuffer;
            const poseName = getBaseName(path) || '';

            // 停掉程序化动作（VPD 姿势不被动画干扰）
            if (isProcVmdActive()) {
                stopProcMotion();
            }

            // 解析 VPD 并作为静态姿势应用（不生成 VMD 动画）
            const { decodeVPDData, parseVPDText } = await import('../../motion-algos/vpd-parser');
            const { applyVPDPose } = await import('../manager/model-ops');
            const text = decodeVPDData(rawData);
            const pose = parseVPDText(text);
            const id = targetModelId || focusedModelId;
            if (!id) {
                feedbackInfo('scene.vmd.loadModelFirst', undefined);
                return;
            }
            applyVPDPose(id, pose.bones, pose.morphs);

            const foc = targetModelId ? modelRegistry.get(targetModelId) : focusedModel();
            if (foc) {
                foc.vmdPath = path; // 记录姿势文件路径
            }
            showInfoToast(t('scene.vmd.poseLoaded', { name: poseName }));
        } catch (err) {
            console.error('loadVPDPose:', err);
            feedbackStatus('scene.vmd.poseFailed', undefined, false);
        }
    });
}

// [doc:adr-056] WASM 图层混合器 — JS 帧流合并让 WASM 拿到多图层能力
// 复用 perception.ts 的 _isWasmRuntime / _writeMatToBuffer / _propagateChildrenWasm
//
// 职责: 注册为 MotionPipeline vmd-layers 层，在 bone-override 之前执行图层混合。
// gaze 覆写已由 perception 层统一处理（参见 ADR-071），本模块不再涉及 gaze。
//
// 时序治理（ADR-147）：
// - wasm-layers-blender 原为独立 onBeforeRenderObservable 观察者，
//   注册时机晚于 Pipeline 驱动（setupWasmLayersBlender 在运行时被调用），
//   导致 vmd-layers 阶段（②）在 bone-override（⑤）和 perception（⑥）之后执行，
//   图层混合的世界矩阵写入覆盖了骨骼覆盖/感知层的输出。
// - 修复：注册为 Pipeline 的 vmd-layers 层，由 MotionPipeline 按 (stage, order) 统一调度。

import type { Scene } from '@babylonjs/core/scene';
import { Quaternion, Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Matrix } from '@babylonjs/core/Maths/math';
import { _isWasmRuntime, _writeMatToBuffer, _propagateChildrenWasm } from './perception';
import type { MmdRuntimeBoneExtended } from '@/core/types';
import {
    createVmdEvaluator,
    type VmdEvaluator,
    type VmdBoneFrame,
} from '@/motion-algos/vmd-evaluator';
import { DEFAULT_LAYER_BONE_FILTER } from './wasm-layers-config';
import type { IMmdRuntimeBone } from 'babylon-mmd/esm/Runtime/IMmdRuntimeBone';
import { clamp01 } from '@/core/clamp';
import { getMotionPipeline } from './motion-pipeline';
import type { ModelManager } from '../manager/model-manager';

// ── 依赖注入：打破 wasm-layers-blender → scene.ts 的静态循环依赖 ──
// vmd-layers.ts 在调用 setupWasmLayersBlender 前必须调用 initWasmLayersBlender。
// 所有引用 scene.ts 的函数通过 _requireDeps() 获取，而非静态 import。

interface BlenderDeps {
    scene: Scene;
    modelManager: ModelManager;
    loadVMDMotion: (data: ArrayBuffer, name: string, modelId?: string) => Promise<void>;
}

let _deps: BlenderDeps | null = null;

function _requireDeps(): BlenderDeps {
    if (!_deps) {
        throw new Error(
            'WASM layers blender not initialized — call initWasmLayersBlender before setupWasmLayersBlender'
        );
    }
    return _deps;
}

/** 初始化 blender 的场景级依赖（必须在 setupWasmLayersBlender 之前调用）。
 *  此函数打破 wasm-layers-blender → scene.ts 的循环依赖链。 */
export function initWasmLayersBlender(deps: BlenderDeps): void {
    _deps = deps;
}

export { DEFAULT_LAYER_BONE_FILTER } from './wasm-layers-config';

export interface WasmLayerConfig {
    id: string;
    data: ArrayBuffer;
    weight: number;
    boneFilter?: string[];
    name?: string;
}

interface WasmLayerEntry {
    evaluator: VmdEvaluator;
    weight: number;
    boneFilter: string[];
    name: string;
}

interface BlenderState {
    modelId: string;
    layers: Map<string, WasmLayerEntry>;
    enabled: boolean;
    baseAnimationName: string;
    animationFrame: number;
}

const _blenderStates = new Map<string, BlenderState>();

const VMD_FPS = 30;

// ── Pipeline vmd-layers 层 ──────────────────────────────────────────────
// 注册一次，在 bone-override 之前执行所有活跃模型的 WASM 图层混合。
let _vmdLayersRegistered = false;

function _ensureVmdLayersLayer(): void {
    if (_vmdLayersRegistered) {
        return;
    }
    _vmdLayersRegistered = true;
    getMotionPipeline().register({
        id: 'wasm-vmd-layers',
        stage: 'vmd-layers',
        order: 0,
        run: () => {
            for (const [modelId, state] of _blenderStates) {
                if (!state.enabled) {
                    continue;
                }
                const dt = _requireDeps().scene.deltaTime || 16.67;
                state.animationFrame += (dt / 1000) * VMD_FPS;
                _applyLayersBlending(modelId);
            }
        },
    });
}

// ── 公开 API ────────────────────────────────────────────────────────────

export async function setupWasmLayersBlender(
    modelId: string,
    baseData: ArrayBuffer,
    baseName: string
): Promise<void> {
    teardownWasmLayersBlender(modelId);

    const inst = _requireDeps().modelManager.get(modelId);
    if (!inst?.mmdModel) {
        throw new Error(`Model ${modelId} not found`);
    }

    // 确保 vmd-layers 管线段已注册（幂等）
    _ensureVmdLayersLayer();

    _blenderStates.set(modelId, {
        modelId,
        layers: new Map(),
        enabled: true,
        baseAnimationName: baseName,
        animationFrame: 0,
    });

    await _requireDeps().loadVMDMotion(baseData, baseName, modelId);
}

export function teardownWasmLayersBlender(modelId: string): void {
    const state = _blenderStates.get(modelId);
    if (!state) {
        return;
    }

    // 无独立 observer 需 dispose — 由 Pipeline vmd-layers 层统一调度
    for (const [, layer] of state.layers) {
        layer.evaluator.dispose();
    }
    state.layers.clear();

    _blenderStates.delete(modelId);
}

export function isWasmLayersBlenderActive(modelId: string): boolean {
    return _blenderStates.has(modelId) && _blenderStates.get(modelId)!.enabled;
}

export async function addWasmLayer(modelId: string, config: WasmLayerConfig): Promise<void> {
    const state = _blenderStates.get(modelId);
    if (!state) {
        throw new Error(`Blender not setup for model ${modelId}`);
    }

    if (state.layers.has(config.id)) {
        removeWasmLayer(modelId, config.id);
    }

    const evaluator = await createVmdEvaluator(config.data);
    state.layers.set(config.id, {
        evaluator,
        weight: config.weight,
        boneFilter: config.boneFilter ?? DEFAULT_LAYER_BONE_FILTER,
        name: config.name ?? config.id,
    });
}

export function removeWasmLayer(modelId: string, layerId: string): void {
    const state = _blenderStates.get(modelId);
    if (!state) {
        return;
    }

    const layer = state.layers.get(layerId);
    if (layer) {
        layer.evaluator.dispose();
        state.layers.delete(layerId);
    }
}

export function updateWasmLayerWeight(modelId: string, layerId: string, weight: number): void {
    const state = _blenderStates.get(modelId);
    if (!state) {
        return;
    }

    const layer = state.layers.get(layerId);
    if (layer) {
        layer.weight = clamp01(weight);
    }
}

// ── 内部实现 ────────────────────────────────────────────────────────────

function _applyLayersBlending(modelId: string): void {
    const state = _blenderStates.get(modelId);
    if (!state || state.layers.size === 0) {
        return;
    }

    const inst = _requireDeps().modelManager.get(modelId);
    if (!inst?.mmdModel) {
        return;
    }

    const bones = inst.mmdModel.runtimeBones;
    if (!bones || bones.length === 0) {
        return;
    }

    const frame = state.animationFrame;

    const allFrames = new Map<string, Array<{ frame: VmdBoneFrame; weight: number }>>();

    for (const [, layer] of state.layers) {
        const frameMap = layer.evaluator.evalAllBones(frame);
        for (const [boneName, frameData] of frameMap) {
            if (!layer.boneFilter.includes('*') && !layer.boneFilter.includes(boneName)) {
                continue;
            }
            if (!allFrames.has(boneName)) {
                allFrames.set(boneName, []);
            }
            allFrames.get(boneName)!.push({ frame: frameData, weight: layer.weight });
        }
    }

    for (const [boneName, entries] of allFrames) {
        const bone = bones.find((b: IMmdRuntimeBone) => b.name === boneName);
        if (!bone || !_isWasmRuntime(bone)) {
            continue;
        }

        const totalWeight = entries.reduce((sum, e) => sum + e.weight, 0);
        if (totalWeight <= 0) {
            continue;
        }

        let blendedRot: Quaternion | null = null;
        let blendedPos: Vector3 | null = null;

        // 权重混合：使用累积权重 Slerp，避免逐次 Slerp 偏向首层。
        // 第 i 层的 effectiveWeight = weight_i / totalWeight，
        // 累积权重 cumWeight 用于 Slerp 的插值因子 = effectiveWeight / (已累积权重)。
        let cumWeight = 0;
        for (const entry of entries) {
            const effectiveWeight = entry.weight / totalWeight;
            cumWeight += effectiveWeight;
            const { rotation, position } = entry.frame;

            if (blendedRot === null) {
                blendedRot = rotation.clone();
            } else {
                // 插值因子 = 本层权重 / 累积权重，保证加权平均语义
                const t = effectiveWeight / cumWeight;
                blendedRot = Quaternion.Slerp(blendedRot, rotation, t);
            }

            if (position !== null) {
                if (blendedPos === null) {
                    blendedPos = position.clone();
                } else {
                    const t = effectiveWeight / cumWeight;
                    blendedPos.x += (position.x - blendedPos.x) * t;
                    blendedPos.y += (position.y - blendedPos.y) * t;
                    blendedPos.z += (position.z - blendedPos.z) * t;
                }
            }
        }

        if (blendedRot !== null) {
            const oldMat = Matrix.FromArray(bone.worldMatrix as Float32Array);

            const newMat = new Matrix();
            if (blendedPos !== null) {
                newMat.copyFrom(Matrix.Compose(Vector3.One(), blendedRot, blendedPos));
            } else {
                const pos = oldMat.getTranslation();
                newMat.copyFrom(Matrix.Compose(Vector3.One(), blendedRot, pos));
            }

            // perception.ts 扩展了 MmdRuntimeBone 添加 worldMatrix 属性，
            // babylon-mmd 类型声明未包含此扩展，需类型断言
            const buf = (bone as MmdRuntimeBoneExtended).worldMatrix;
            _writeMatToBuffer(buf, newMat);

            _propagateChildrenWasm(bone, oldMat, newMat);
        }
    }
}

/**
 * skirt-analyzer.ts — ADR-084 Phase 1: 裙摆拓扑分析
 *
 * 纯几何模块，无 Babylon.js / babylon-mmd / WASM 依赖。
 * 输入 mesh 顶点 + 索引数据，输出虚拟裙骨链结构。
 *
 * 算法管线:
 *   1. 包围盒计算 → 确定 Y 轴裙摆区域阈值
 *   2. edge→triangle 映射 → boundary edge 检测
 *   3. boundary edge 连通分量 → 裙边环识别
 *   4. 角度聚类 → 径向分链
 *   5. Y 轴分层 → 每链骨节
 *   6. 顶点→骨节最近邻映射 + 距离衰减权重
 *
 * 关联: ADR-084, ADR-081 (physics-bridge 复用)
 */

import { clampInt } from '@/core/clamp';

// ============================================================================
// 类型定义
// ============================================================================

export interface SkirtSegment {
    /** Rest pose 位置 [x, y, z] */
    readonly restPosition: [number, number, number];
    /** 该骨节关联的顶点索引 */
    readonly vertexIndices: number[];
    /** 每个关联顶点的权重（与 vertexIndices 并行，和为 1） */
    readonly weights: number[];
    /** 碰撞球半径（由 mesh 尺寸推算） */
    readonly radius: number;
}

export interface SkirtChain {
    /** 链上的骨节序列（从裙边 hem 到腰部 waist，Y 递增） */
    readonly segments: SkirtSegment[];
}

export interface SkirtAnalysisResult {
    /** 虚拟裙骨链列表 */
    readonly chains: SkirtChain[];
    /** 总骨节数 */
    readonly totalSegments: number;
    /** 裙摆区域顶点数 */
    readonly skirtVertexCount: number;
    /** 诊断: 检测到的 boundary edge 数 */
    readonly boundaryEdgeCount: number;
    /** 使用的方法 */
    readonly method: 'boundary-edge' | 'y-threshold' | 'none';
    /** 是否检测到已有裙骨（有则跳过自动生成） */
    readonly hasExistingSkirtBones: boolean;
}

export interface SkirtAnalyzerOptions {
    /** 期望链数（默认 12，范围 4-32） */
    chains?: number;
    /** 每链骨节数（默认 8，范围 4-16） */
    segmentsPerChain?: number;
    /** 裙摆区域 Y 阈值比例（默认 0.3 = 模型高度 30% 以下） */
    skirtYRatio?: number;
    /** 已知骨骼名列表（用于检测是否已有裙骨） */
    boneNames?: string[];
    /** 碰撞球半径（默认 auto，按 mesh 尺寸推算） */
    collisionRadius?: number;
}

// ============================================================================
// 常量
// ============================================================================

/** 裙骨名匹配正则（英文/中文/日文） */
const SKIRT_BONE_PATTERN = /skirt|裾|スカート|sukato/i;

/** 默认参数 */
const DEFAULT_CHAINS = 12;
const DEFAULT_SEGMENTS_PER_CHAIN = 8;
const DEFAULT_SKIRT_Y_RATIO = 0.3;
/** 最少裙摆顶点数，低于此数判定无裙摆 */
const MIN_SKIRT_VERTICES = 6;
/** 连通分量最少顶点数，低于此数忽略 */
const MIN_COMPONENT_SIZE = 3;

// ============================================================================
// Union-Find
// ============================================================================

class UnionFind {
    private parent: Map<number, number> = new Map();

    find(x: number): number {
        if (!this.parent.has(x)) {
            this.parent.set(x, x);
            return x;
        }
        let root = x;
        while (this.parent.get(root)! !== root) {
            root = this.parent.get(root)!;
        }
        // 路径压缩
        let cur = x;
        while (this.parent.get(cur)! !== root) {
            const next = this.parent.get(cur)!;
            this.parent.set(cur, root);
            cur = next;
        }
        return root;
    }

    union(a: number, b: number): void {
        const ra = this.find(a);
        const rb = this.find(b);
        if (ra !== rb) {
            this.parent.set(ra, rb);
        }
    }

    /** 获取所有连通分量 → Set<number>[] */
    components(): Map<number, number[]> {
        const groups = new Map<number, number[]>();
        for (const key of this.parent.keys()) {
            const root = this.find(key);
            const arr = groups.get(root);
            if (arr) {
                arr.push(key);
            } else {
                groups.set(root, [key]);
            }
        }
        return groups;
    }
}

// ============================================================================
// 工具函数
// ============================================================================

function edgeKey(a: number, b: number): string {
    return a < b ? `${a}_${b}` : `${b}_${a}`;
}

// clampInt 已收敛至 @/core/clamp

// ============================================================================
// 主分析函数
// ============================================================================

/**
 * 分析 mesh 拓扑，识别裙摆区域并生成虚拟骨骼链。
 *
 * @param positions 顶点位置数组 [x0,y0,z0, x1,y1,z1, ...]
 * @param indices 三角形索引数组 [i0,i1,i2, i3,i4,i5, ...]
 * @param options 分析选项
 * @returns 裙摆分析结果
 */
export function analyzeSkirt(
    positions: Float32Array | number[],
    indices: Uint32Array | number[] | Int32Array,
    options?: SkirtAnalyzerOptions
): SkirtAnalysisResult {
    const empty: SkirtAnalysisResult = {
        chains: [],
        totalSegments: 0,
        skirtVertexCount: 0,
        boundaryEdgeCount: 0,
        method: 'none',
        hasExistingSkirtBones: false,
    };

    // --- 参数解析 ---
    const chainCount = clampInt(options?.chains ?? DEFAULT_CHAINS, 4, 32);
    const segmentsPerChain = clampInt(
        options?.segmentsPerChain ?? DEFAULT_SEGMENTS_PER_CHAIN,
        4,
        16
    );
    const skirtYRatio = Math.min(1, Math.max(0.1, options?.skirtYRatio ?? DEFAULT_SKIRT_Y_RATIO));

    // --- 输入校验 ---
    const posArr = positions instanceof Float32Array ? positions : new Float32Array(positions);
    const idxArr =
        indices instanceof Uint32Array
            ? indices
            : indices instanceof Int32Array
              ? new Uint32Array(indices)
              : new Uint32Array(indices);

    const vertexCount = posArr.length / 3;
    const triangleCount = idxArr.length / 3;
    if (vertexCount < 3 || triangleCount < 1) {
        return empty;
    }

    // --- 1. 已有裙骨检测 ---
    if (options?.boneNames && options.boneNames.length > 0) {
        const hasSkirt = options.boneNames.some((n) => SKIRT_BONE_PATTERN.test(n));
        if (hasSkirt) {
            return { ...empty, hasExistingSkirtBones: true };
        }
    }

    // --- 2. 包围盒计算 ---
    let minY = Infinity;
    let maxY = -Infinity;
    let minX = Infinity,
        maxX = -Infinity;
    let minZ = Infinity,
        maxZ = -Infinity;
    for (let i = 0; i < posArr.length; i += 3) {
        const x = posArr[i];
        const y = posArr[i + 1];
        const z = posArr[i + 2];
        if (y < minY) {
            minY = y;
        }
        if (y > maxY) {
            maxY = y;
        }
        if (x < minX) {
            minX = x;
        }
        if (x > maxX) {
            maxX = x;
        }
        if (z < minZ) {
            minZ = z;
        }
        if (z > maxZ) {
            maxZ = z;
        }
    }
    const modelHeight = Math.max(maxY - minY, 1e-6);
    const skirtYThreshold = minY + modelHeight * skirtYRatio;
    const modelWidth = Math.max(maxX - minX, maxZ - minZ, 1e-6);
    const collisionRadius = options?.collisionRadius ?? Math.max(modelWidth * 0.015, 0.01);

    // --- 3. edge→triangle 映射 ---
    const edgeCounts = new Map<string, number>();
    for (let t = 0; t < triangleCount; t++) {
        const i0 = idxArr[t * 3];
        const i1 = idxArr[t * 3 + 1];
        const i2 = idxArr[t * 3 + 2];
        for (const [a, b] of [
            [i0, i1],
            [i1, i2],
            [i2, i0],
        ] as const) {
            const key = edgeKey(a, b);
            edgeCounts.set(key, (edgeCounts.get(key) ?? 0) + 1);
        }
    }

    // --- 4. boundary edges（仅被 1 个三角形引用的边） ---
    const boundaryEdges: Array<[number, number]> = [];
    for (const [key, count] of edgeCounts) {
        if (count === 1) {
            const sep = key.indexOf('_');
            boundaryEdges.push([parseInt(key.slice(0, sep), 10), parseInt(key.slice(sep + 1), 10)]);
        }
    }

    // --- 5. boundary edge 连通分量 ---
    const uf = new UnionFind();
    for (const [a, b] of boundaryEdges) {
        uf.union(a, b);
    }

    // 取所有 boundary 顶点
    const boundaryVertices = new Set<number>();
    for (const [a, b] of boundaryEdges) {
        boundaryVertices.add(a);
        boundaryVertices.add(b);
    }

    // 连通分量分组
    const components = uf.components();

    // P2a 防误判（穿裤模型）：先收集所有「底部」连通分量（Y 均值 ≤ 裙摆阈值且规模达标）。
    // 真实裙摆底部为单个连续环（开放 hem）；裤子/连体衣底部为 ≥2 个分离环（左右腿洞）。
    // 多环 → 判定非裙摆，安全跳过自动生成，避免对腿部误注入虚拟裙骨。
    const bottomComponents: number[][] = [];
    for (const [, verts] of components) {
        if (verts.length < MIN_COMPONENT_SIZE) {
            continue;
        }
        let sumY = 0;
        for (const v of verts) {
            sumY += posArr[v * 3 + 1];
        }
        const avgY = sumY / verts.length;
        if (avgY <= skirtYThreshold) {
            bottomComponents.push(verts);
        }
    }
    if (bottomComponents.length >= 2) {
        // 多底部环 → 裤子/连体衣，非裙摆，安全跳过
        return { ...empty, boundaryEdgeCount: boundaryEdges.length, hasExistingSkirtBones: false };
    }
    // 取唯一的底部连通分量作为裙边环（无底部环则进入 fallback）
    const hemComponent: number[] | null =
        bottomComponents.length === 1 ? bottomComponents[0] : null;
    const hemAvgY = hemComponent ? skirtYThreshold : Infinity;

    // --- 6. 确定裙摆区域顶点 ---
    let skirtVertices: number[];
    let method: 'boundary-edge' | 'y-threshold';

    if (hemComponent && hemComponent.length >= MIN_COMPONENT_SIZE && hemAvgY <= skirtYThreshold) {
        // boundary edge 方法: 从 hem 顶点 BFS 向上扩展，收集裙摆区域所有顶点
        // 构建顶点邻接表
        const adjacency = new Map<number, Set<number>>();
        for (let t = 0; t < triangleCount; t++) {
            const i0 = idxArr[t * 3];
            const i1 = idxArr[t * 3 + 1];
            const i2 = idxArr[t * 3 + 2];
            for (const [a, b] of [
                [i0, i1],
                [i1, i2],
                [i2, i0],
            ] as const) {
                if (!adjacency.has(a)) {
                    adjacency.set(a, new Set());
                }
                if (!adjacency.has(b)) {
                    adjacency.set(b, new Set());
                }
                adjacency.get(a)!.add(b);
                adjacency.get(b)!.add(a);
            }
        }
        // BFS from hem vertices, only going upward (Y >= hem vertex Y)
        const visited = new Set<number>(hemComponent);
        const queue = [...hemComponent];
        const hemMaxY = hemAvgY + modelHeight * 0.35; // 裙摆区域上限: hem 平均 Y + 35% 模型高度
        while (queue.length > 0) {
            const v = queue.shift()!;
            const vy = posArr[v * 3 + 1];
            if (vy > hemMaxY) {
                continue;
            }
            const neighbors = adjacency.get(v);
            if (!neighbors) {
                continue;
            }
            for (const n of neighbors) {
                if (visited.has(n)) {
                    continue;
                }
                const ny = posArr[n * 3 + 1];
                if (ny >= vy - 0.001 && ny <= hemMaxY) {
                    // 允许微小误差，向上扩展
                    visited.add(n);
                    queue.push(n);
                }
            }
        }
        skirtVertices = Array.from(visited);
        method = 'boundary-edge';
    } else {
        // 无清晰底部 boundary edge 时返回空结果，由调用方决定是否跳过
        return { ...empty, boundaryEdgeCount: boundaryEdges.length, hasExistingSkirtBones: false };
    }

    if (skirtVertices.length < MIN_SKIRT_VERTICES) {
        return { ...empty, boundaryEdgeCount: boundaryEdges.length };
    }

    // --- 7. 角度聚类 → 分链 ---
    // 计算裙摆顶点在 XZ 平面的质心
    let cx = 0,
        cz = 0;
    for (const v of skirtVertices) {
        cx += posArr[v * 3];
        cz += posArr[v * 3 + 2];
    }
    cx /= skirtVertices.length;
    cz /= skirtVertices.length;

    // 每个顶点的角度
    const vertexAngles = new Map<number, number>();
    for (const v of skirtVertices) {
        const angle = Math.atan2(posArr[v * 3 + 2] - cz, posArr[v * 3] - cx);
        vertexAngles.set(v, angle);
    }

    // 按角度排序
    const sortedByAngle = [...skirtVertices].sort(
        (a, b) => vertexAngles.get(a)! - vertexAngles.get(b)!
    );

    // 分成 chainCount 个组（每个组 = 一条链）
    const chainGroups: number[][] = [];
    const verticesPerChain = Math.ceil(sortedByAngle.length / chainCount);
    for (let i = 0; i < chainCount; i++) {
        const start = i * verticesPerChain;
        const end = Math.min(start + verticesPerChain, sortedByAngle.length);
        if (start >= sortedByAngle.length) {
            chainGroups.push([]);
        } else {
            chainGroups.push(sortedByAngle.slice(start, end));
        }
    }

    // --- 8. 每链分层 → 骨节 ---
    const chains: SkirtChain[] = [];
    // P3d: 收集所有骨节（跨链），用于第 9 步全局顶点映射，消除链间缝隙
    const allSegments: SkirtSegment[] = [];

    for (const group of chainGroups) {
        if (group.length === 0) {
            chains.push({ segments: [] });
            continue;
        }

        // 按 Y 升序排序（裙边 → 腰部）
        const sortedByY = [...group].sort((a, b) => posArr[a * 3 + 1] - posArr[b * 3 + 1]);

        // 分成 segmentsPerChain 层
        const actualSegments = Math.min(segmentsPerChain, sortedByY.length);
        const verticesPerSegment = Math.ceil(sortedByY.length / actualSegments);
        const segments: SkirtSegment[] = [];

        for (let s = 0; s < actualSegments; s++) {
            const start = s * verticesPerSegment;
            const end = Math.min(start + verticesPerSegment, sortedByY.length);
            const segVertices = sortedByY.slice(start, end);
            if (segVertices.length === 0) {
                continue;
            }

            // 骨节 rest 位置 = 该层顶点的平均位置
            let sx = 0,
                sy = 0,
                sz = 0;
            for (const v of segVertices) {
                sx += posArr[v * 3];
                sy += posArr[v * 3 + 1];
                sz += posArr[v * 3 + 2];
            }
            const restPosition: [number, number, number] = [
                sx / segVertices.length,
                sy / segVertices.length,
                sz / segVertices.length,
            ];

            const seg: SkirtSegment = {
                restPosition,
                vertexIndices: [],
                weights: [],
                radius: collisionRadius,
            };
            segments.push(seg);
            allSegments.push(seg); // P3d: 跨链收集同一引用
        }

        chains.push({ segments });
    }

    // --- 9. 顶点→骨节映射（全局，跨链，P3d 链间缝隙修复）---
    // 相比原「每链内映射」，全局映射让链边界处的顶点同时受相邻两条链的骨节影响，
    // 消除相邻链各自独立位移导致的撕裂。每个顶点取全局最近的 2 个骨节，
    // 按距离反比分配权重（和为 1）。
    for (const v of skirtVertices) {
        const vx = posArr[v * 3];
        const vy = posArr[v * 3 + 1];
        const vz = posArr[v * 3 + 2];

        // 找最近的 2 个骨节（全局）
        const distances = allSegments.map((seg, idx) => {
            const dx = vx - seg.restPosition[0];
            const dy = vy - seg.restPosition[1];
            const dz = vz - seg.restPosition[2];
            return { idx, dist: Math.sqrt(dx * dx + dy * dy + dz * dz) };
        });
        distances.sort((a, b) => a.dist - b.dist);

        // 取最近 2 个（或 1 个如果只有 1 个骨节）
        const k = Math.min(2, distances.length);
        let totalInvDist = 0;
        const invDists: number[] = [];
        for (let i = 0; i < k; i++) {
            const d = Math.max(distances[i].dist, 1e-6);
            const inv = 1 / d;
            invDists.push(inv);
            totalInvDist += inv;
        }

        for (let i = 0; i < k; i++) {
            const seg = allSegments[distances[i].idx];
            const weight = invDists[i] / totalInvDist;
            seg.vertexIndices.push(v);
            seg.weights.push(weight);
        }
    }

    const totalSegments = chains.reduce((sum, c) => sum + c.segments.length, 0);

    return {
        chains,
        totalSegments,
        skirtVertexCount: skirtVertices.length,
        boundaryEdgeCount: boundaryEdges.length,
        method,
        hasExistingSkirtBones: false,
    };
}

/**
 * virtual-skirt.ts — ADR-084 Phase 2-3: WASM Bullet 注入 + 顶点回写
 *
 * 运行时将 Phase 1 拓扑分析得到的虚拟裙骨链，注入 WASM Bullet 物理世界：
 *   · 链头 Kinematic 盒子锚定体（跟随腰骨）
 *   · 链身 Dynamic 球体 + Generic6DofSpringConstraint 弹簧链
 *   · 每帧 PerFrameUpdateRegistry 调度：锚定体跟随腰骨 + 读刚体位移 → 写回 mesh 顶点
 *
 * 设计约束（ADR-081 教训）：本模块不被 scene.ts 启动期 eager 导入，
 * 仅由用户显式开启虚拟裙骨时按需 `await import()`。
 *
 * 关联：skirt-analyzer.ts（Phase 1）、physics-bridge.ts（PerFrameUpdateRegistry / getBoneWorldPosition）
 */

import { Matrix, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import { VertexBuffer } from '@babylonjs/core/Buffers/buffer';
import type { IMmdModel } from 'babylon-mmd/esm/Runtime/IMmdModel';
import type { MmdWasmRuntime } from 'babylon-mmd/esm/Runtime/Optimized/mmdWasmRuntime';
import { MmdWasmPhysicsRuntimeImpl } from 'babylon-mmd/esm/Runtime/Optimized/Physics/mmdWasmPhysicsRuntimeImpl';
import type { MmdWasmPhysicsRuntime } from 'babylon-mmd/esm/Runtime/Optimized/Physics/mmdWasmPhysicsRuntime';
import { RigidBody } from 'babylon-mmd/esm/Runtime/Optimized/Physics/Bind/rigidBody';
import { RigidBodyConstructionInfo } from 'babylon-mmd/esm/Runtime/Optimized/Physics/Bind/rigidBodyConstructionInfo';
import { Generic6DofSpringConstraint } from 'babylon-mmd/esm/Runtime/Optimized/Physics/Bind/constraint';
import {
    PhysicsSphereShape,
    PhysicsBoxShape,
} from 'babylon-mmd/esm/Runtime/Optimized/Physics/Bind/physicsShape';
import { MotionType } from 'babylon-mmd/esm/Runtime/Optimized/Physics/Bind/motionType';
import { analyzeSkirt } from './skirt-analyzer';
import { PerFrameUpdateRegistry, getBoneWorldPosition } from '../../physics/physics-bridge';
import { getCachedCapabilities } from '../../core/backend';
import { logWarn } from '../../core/logger';

// ============================================================================
// 配置
// ============================================================================

export interface VirtualSkirtConfig {
    /** 开关 */
    enabled: boolean;
    /** 质量档位（auto 在无 crossOriginIsolated（单线程物理）时自动降为 low，多线程时 high） */
    quality: VirtualSkirtQuality;
    /** 链数（4-32） */
    chains: number;
    /** 每链骨节数（4-16） */
    segmentsPerChain: number;
    /** 弹簧刚度（10-200） */
    stiffness: number;
    /** 弹簧阻尼（0-1） */
    damping: number;
    /** 单骨节质量（0.01-0.5） */
    mass: number;
    /** 碰撞球半径（0 = 自动推算） */
    radius: number;
    /** 顶点数上限（性能保护，默认 2000；会被质量档位进一步收紧） */
    maxVertices: number;
    /** Y 阈值比例（裙摆区域判定） */
    skirtYRatio: number;
}

/** 质量档位：auto 按平台自动解析，其余为固定档 */
export type VirtualSkirtQuality = 'auto' | 'high' | 'medium' | 'low';

/** 质量档位 → LOD 上限 + 降频步长 + 顶点硬上限 */
interface QualityPreset {
    /** 链数上限（LOD：物理刚体数量上限） */
    chainsCap: number;
    /** 每链骨节数上限（LOD） */
    segmentsCap: number;
    /** 顶点回写降频：每 N 帧写回一次（1 = 每帧） */
    throttleEvery: number;
    /** 顶点数硬上限（超过则跳过该模型） */
    maxVertices: number;
}

export const QUALITY_PRESETS: Record<Exclude<VirtualSkirtQuality, 'auto'>, QualityPreset> = {
    high: { chainsCap: 32, segmentsCap: 16, throttleEvery: 1, maxVertices: 4000 },
    medium: { chainsCap: 16, segmentsCap: 10, throttleEvery: 2, maxVertices: 2500 },
    low: { chainsCap: 10, segmentsCap: 6, throttleEvery: 3, maxVertices: 1500 },
};

/**
 * Phase 5: 解析有效质量档位。
 * `auto` 在 Android 上降为 `low`（低端机减负），桌面保持 `high`。
 * 纯函数，便于单测，且不依赖运行期平台探测副作用。
 */
export function resolveVirtualSkirtQuality(
    quality: VirtualSkirtQuality,
    singleThread: boolean
): Exclude<VirtualSkirtQuality, 'auto'> {
    if (quality === 'auto') {
        return singleThread ? 'low' : 'high';
    }
    return quality;
}

// ============================================================================
// P1: 坐标空间转换纯函数（WASM 物理世界为世界坐标，mesh 顶点 Buffer 为局部坐标）
// ============================================================================

/**
 * 局部坐标 → 世界坐标（点变换，含平移）。
 * 用于把 Phase 1 分析得到的局部 rest 顶点位置，转到 WASM 物理世界所用的世界空间。
 */
export function localToWorld(local: Vector3, world: Matrix, out: Vector3): Vector3 {
    const m = world.m;
    out.x = m[0] * local.x + m[4] * local.y + m[8] * local.z + m[12];
    out.y = m[1] * local.x + m[5] * local.y + m[9] * local.z + m[13];
    out.z = m[2] * local.x + m[6] * local.y + m[10] * local.z + m[14];
    return out;
}

/**
 * 世界位移向量 → 局部位移向量（仅取旋转/缩放分量，忽略平移）。
 * 用于把物理模拟得到的世界位移，还原为应写回局部顶点 Buffer 的偏移量，
 * 从而消除模型整体平移/旋转带来的偏差（裙摆随模型移动而不漂移）。
 */
export function worldDeltaToLocal(delta: Vector3, worldInv: Matrix, out: Vector3): Vector3 {
    const m = worldInv.m;
    out.x = m[0] * delta.x + m[4] * delta.y + m[8] * delta.z;
    out.y = m[1] * delta.x + m[5] * delta.y + m[9] * delta.z;
    out.z = m[2] * delta.x + m[6] * delta.y + m[10] * delta.z;
    return out;
}

export const defaultVirtualSkirtConfig: VirtualSkirtConfig = {
    enabled: false,
    quality: 'auto',
    chains: 12,
    segmentsPerChain: 8,
    stiffness: 50,
    damping: 0.3,
    mass: 0.05,
    radius: 0,
    maxVertices: 2000,
    skirtYRatio: 0.3,
};

/** 腰骨候选名（按优先级） */
const WAIST_BONE_CANDIDATES = ['Waist', 'センター', 'Center', '腰', '上半身'];
/** 期望锚定体半尺寸（米） */
const ANCHOR_HALF_SIZE = 0.08;

// ============================================================================
// worldId 回收（P1 修复：ADR-084 §九 已知限制 — WASM Bullet 无 worldId 释放 API，
// 本项目侧用 freeList 缓解：dispose 时归还，build 时优先复用，避免 nextWorldId 单调增长）
// ============================================================================
const _worldIdFreeList: number[] = [];

function acquireWorldId(physicsRuntime: MmdWasmPhysicsRuntime): number {
    const reused = _worldIdFreeList.pop();
    if (reused !== undefined) {
        return reused;
    }
    return physicsRuntime.nextWorldId++;
}

function releaseWorldId(id: number): void {
    if (id >= 0 && !_worldIdFreeList.includes(id)) {
        _worldIdFreeList.push(id);
    }
}

// ============================================================================
// 控制器
// ============================================================================

/**
 * 虚拟裙骨物理控制器。
 * 生命周期：build() 注入 → 每帧 _update() → dispose() 释放。
 */
export class VirtualSkirtController {
    private impl: MmdWasmPhysicsRuntimeImpl | null = null;
    private worldId = -1;

    private anchorRb: RigidBody | null = null;
    private anchorInfo: RigidBodyConstructionInfo | null = null;
    private anchorShape: PhysicsBoxShape | null = null;

    private readonly segmentRbs: RigidBody[] = [];
    private readonly segmentInfos: RigidBodyConstructionInfo[] = [];
    private readonly segmentShapes: PhysicsSphereShape[] = [];
    private readonly constraints: Generic6DofSpringConstraint[] = [];

    private analysis: ReturnType<typeof analyzeSkirt> | null = null;
    private registry: PerFrameUpdateRegistry | null = null;
    /** mesh rest pose 快照（Phase 3 顶点回写基准） */
    private restPositions: Float32Array | null = null;
    /** 重建后 new 出来的对象类型标记，供 tsc 推断 */
    private readonly _tmpMatrix = new Matrix();
    /** 每帧回写复用的临时矩阵缓冲（避免 per-frame GC） */
    private readonly _tmpArray = new Float32Array(16);
    /** 每帧回写复用的顶点工作缓冲（避免 per-frame alloc） */
    private _workBuf: Float32Array | null = null;
    /** Phase 5: 降频帧计数器 */
    private _frame = 0;
    /** Phase 5: 解析后的有效质量档位 */
    private _effectiveQuality: VirtualSkirtQuality = 'high';
    /** Phase 5: 有效降频步长（每 N 帧写回） */
    private _throttleEvery = 1;
    /** Phase 5: LOD 生效后的有效链数（供状态读取） */
    private _effectiveChains = 0;
    /** Phase 5: LOD 生效后的有效骨节数（供状态读取） */
    private _effectiveSegments = 0;
    private _disposed = false;

    /** P1: mesh 世界矩阵（每帧刷新，模型可平移/旋转） */
    private readonly _meshWorld = Matrix.Identity();
    /** P1: mesh 世界逆矩阵（世界位移 → 局部位移 转换用） */
    private readonly _meshWorldInv = Matrix.Identity();
    /** P1: 复用局部向量 */
    private readonly _tmpLocal = new Vector3();
    /** P1: 复用世界向量（兼作 localSway 输出） */
    private readonly _tmpVec = new Vector3();
    /** P1: 复用世界位移向量 */
    private readonly _tmpDelta = new Vector3();
    /** P3e: 缓存的腰骨对象引用（build() 解析，_update() 复用，避免每帧遍历查找） */
    private _waistBone: { name: string; worldMatrix: Float32Array } | null = null;

    constructor(
        private readonly model: IMmdModel,
        private readonly scene: Scene,
        private readonly wasmRuntime: MmdWasmRuntime,
        private readonly config: VirtualSkirtConfig
    ) {}

    /**
     * 注入虚拟裙骨链到 WASM Bullet 物理世界。
     * @returns 是否成功注入（false = 模型已有裙骨 / 无裙摆 / 物理不可用）
     */
    build(): boolean {
        if (this._disposed) {
            return false;
        }

        // Phase 5: 质量档位解析 → LOD 上限 + 降频步长 + 顶点硬上限
        // [doc:adr-178] 走能力层：无 crossOriginIsolated（安卓应用 / 网页模式无 MPR）即单线程物理，自动降品质
        const effQuality = resolveVirtualSkirtQuality(
            this.config.quality,
            !getCachedCapabilities().crossOriginIsolated
        );
        const preset = QUALITY_PRESETS[effQuality];
        this._effectiveQuality = effQuality;
        this._throttleEvery = preset.throttleEvery;
        const effChains = Math.min(this.config.chains, preset.chainsCap);
        const effSegments = Math.min(this.config.segmentsPerChain, preset.segmentsCap);
        this._effectiveChains = effChains;
        this._effectiveSegments = effSegments;
        const maxVerts = Math.min(this.config.maxVertices, preset.maxVertices);
        this._frame = 0;

        const mesh = this.model.mesh;
        const positions = mesh.getVerticesData(VertexBuffer.PositionKind);
        const rawIndices = mesh.getIndices();
        if (!positions || !rawIndices) {
            return false;
        }
        const indices =
            rawIndices instanceof Uint32Array ? rawIndices : new Uint32Array(rawIndices);

        // 顶点数上限保护（质量档位可进一步收紧）
        if (positions.length / 3 > maxVerts) {
            return false;
        }

        const boneNames = this.model.runtimeBones?.map((b) => b.name) ?? [];
        const result = analyzeSkirt(positions, indices, {
            chains: effChains,
            segmentsPerChain: effSegments,
            skirtYRatio: this.config.skirtYRatio,
            boneNames,
            collisionRadius: this.config.radius > 0 ? this.config.radius : undefined,
        });

        if (result.hasExistingSkirtBones) {
            return false;
        }
        if (result.totalSegments === 0) {
            return false;
        }
        this.analysis = result;

        // 获取物理运行时 impl
        const physicsRuntime = this.wasmRuntime.physics as MmdWasmPhysicsRuntime | null;
        if (!physicsRuntime) {
            return false;
        }
        const impl = physicsRuntime.getImpl(MmdWasmPhysicsRuntimeImpl);
        if (!impl) {
            return false;
        }
        this.impl = impl;

        // P1: 捕获 mesh 世界矩阵（WASM 物理世界为世界坐标，骨节初始位置与写回均依赖它）
        const mw0 = this.model.mesh.getWorldMatrix();
        this._meshWorld.copyFrom(mw0);
        mw0.invertToRef(this._meshWorldInv);

        // worldId：始终分配专用 world（不与 PMX 刚体同 world，避免坐标系/碰撞干扰；
        // 也规避 _physicsModel 私有字段访问的脆弱性，见 ADR-084 §九 P1 修复）
        // P1-fix: 优先从 freeList 复用，避免 nextWorldId 单调增长
        this.worldId = acquireWorldId(physicsRuntime);

        try {
            const wasmInstance = impl.wasmInstance;

            // --- 锚定体（Kinematic 盒子，跟随腰骨） ---
            const waistName = WAIST_BONE_CANDIDATES.find((n) =>
                this.model.runtimeBones?.some((b) => b.name === n)
            );
            // P3e: 解析并缓存腰骨对象引用，_update() 每帧复用，避免重复遍历 runtimeBones
            this._waistBone = waistName
                ? (this.model.runtimeBones?.find((b) => b.name === waistName) ?? null)
                : null;
            const waistPos = waistName ? getBoneWorldPosition(this.model, waistName) : null;
            const ax = waistPos?.x ?? 0;
            const ay = waistPos?.y ?? 0.8;
            const az = waistPos?.z ?? 0;

            this.anchorShape = new PhysicsBoxShape(
                impl,
                new Vector3(ANCHOR_HALF_SIZE, ANCHOR_HALF_SIZE * 0.5, ANCHOR_HALF_SIZE)
            );
            this.anchorInfo = new RigidBodyConstructionInfo(wasmInstance);
            this.anchorInfo.shape = this.anchorShape;
            this.anchorInfo.motionType = MotionType.Kinematic;
            this.anchorInfo.mass = 0;
            this.anchorInfo.setInitialTransform(Matrix.Translation(ax, ay, az));
            this.anchorRb = new RigidBody(impl, this.anchorInfo);
            if (!impl.addRigidBody(this.anchorRb, this.worldId)) {
                logWarn('virtual-skirt', 'addRigidBody(anchor) failed', {
                    worldId: this.worldId,
                });
                this.dispose();
                return false;
            }

            // --- 链身：Dynamic 球体 + 弹簧约束 ---
            const radius =
                this.config.radius > 0
                    ? this.config.radius
                    : (this.analysis.chains[0]?.segments[0]?.radius ?? 0.02);

            for (const chain of this.analysis.chains) {
                let parent: RigidBody = this.anchorRb;
                for (const seg of chain.segments) {
                    const shape = new PhysicsSphereShape(impl, seg.radius || radius);
                    const info = new RigidBodyConstructionInfo(wasmInstance);
                    info.shape = shape;
                    info.motionType = MotionType.Dynamic;
                    info.mass = this.config.mass;
                    info.linearDamping = 0.1;
                    info.angularDamping = 0.3;
                    info.friction = 0.5;
                    info.restitution = 0.0;
                    info.disableDeactivation = true;
                    // P1: 骨节初始位置必须从局部 rest 转换到世界空间（WASM 物理世界为世界坐标）
                    this._tmpLocal.set(
                        seg.restPosition[0],
                        seg.restPosition[1],
                        seg.restPosition[2]
                    );
                    localToWorld(this._tmpLocal, this._meshWorld, this._tmpVec);
                    info.setInitialTransform(
                        Matrix.Translation(this._tmpVec.x, this._tmpVec.y, this._tmpVec.z)
                    );
                    const rb = new RigidBody(impl, info);
                    // 先 push 到数组，addRigidBody 失败时 dispose 能清理已分配资源
                    this.segmentRbs.push(rb);
                    this.segmentInfos.push(info);
                    this.segmentShapes.push(shape);
                    if (!impl.addRigidBody(rb, this.worldId)) {
                        logWarn('virtual-skirt', 'addRigidBody(segment) failed', {
                            worldId: this.worldId,
                            idx: this.segmentRbs.length - 1,
                        });
                        this.dispose();
                        return false;
                    }

                    const spring = new Generic6DofSpringConstraint(
                        impl,
                        parent,
                        rb,
                        Matrix.Identity(),
                        Matrix.Identity(),
                        false
                    );
                    spring.enableSpring(0, true);
                    spring.setStiffness(0, this.config.stiffness);
                    spring.enableSpring(1, true);
                    spring.setStiffness(1, this.config.stiffness);
                    spring.enableSpring(2, true);
                    spring.setStiffness(2, this.config.stiffness);
                    spring.enableSpring(3, true);
                    spring.setStiffness(3, this.config.stiffness * 0.6);
                    spring.enableSpring(4, true);
                    spring.setStiffness(4, this.config.stiffness * 0.6);
                    spring.enableSpring(5, false); // Z 角锁定防扭转
                    spring.setDamping(0, this.config.damping);
                    spring.setDamping(1, this.config.damping);
                    spring.setDamping(2, this.config.damping);
                    this.constraints.push(spring);
                    if (!impl.addConstraint(spring, this.worldId, true)) {
                        logWarn('virtual-skirt', 'addConstraint failed', {
                            worldId: this.worldId,
                            idx: this.constraints.length - 1,
                        });
                        this.dispose();
                        return false;
                    }

                    parent = rb;
                }
            }
        } catch (e) {
            // P3a: 注入中途异常 → 释放已分配的刚体/约束/构造信息/形状，避免半初始化泄漏
            logWarn('virtual-skirt', 'build failed, disposing partial resources', e);
            this.dispose();
            return false;
        }

        // --- Phase 3 准备：rest pose 快照 ---
        this.restPositions =
            positions instanceof Float32Array ? positions.slice() : Float32Array.from(positions);

        // --- 每帧更新 ---
        this.registry = new PerFrameUpdateRegistry(this.scene);
        this.registry.register('virtual-skirt', () => this._update());

        return true;
    }

    /** 每帧回调：锚定体跟随腰骨 + 顶点回写 */
    private _update(): void {
        // 模型被外部卸载（如切换/删除）时，mesh 已销毁，必须 self-dispose 避免悬空回写
        if (this.model.mesh.isDisposed?.()) {
            this.dispose();
            return;
        }
        if (!this.impl || !this.anchorRb || !this.analysis) {
            return;
        }

        // P1: 每帧刷新 mesh 世界矩阵（模型可能被平移/旋转），供写回坐标转换
        const mw = this.model.mesh.getWorldMatrix();
        this._meshWorld.copyFrom(mw);
        mw.invertToRef(this._meshWorldInv);

        // 锚定体跟随腰骨（Kinematic）— P3e: 复用 build() 缓存的腰骨引用，不再每帧遍历查找
        const m = this._waistBone?.worldMatrix;
        if (m) {
            this._tmpMatrix.fromArray(m);
            this.anchorRb.setTransformMatrix(this._tmpMatrix);
        }

        // Phase 5: 降频 — 锚定体每帧跟随腰部，顶点写回按 _throttleEvery 降频
        // (低端机每 N 帧才向 GPU 上传一次位移，物理仍在 WASM 内持续模拟)
        if (this._frame % this._throttleEvery === 0) {
            this._writeBackVertices();
        }
        this._frame++;
    }

    /** Phase 3：读刚体世界位移 → 按权重写回 mesh 顶点 */
    private _writeBackVertices(): void {
        if (!this.restPositions || !this.analysis || this.segmentRbs.length === 0) {
            return;
        }

        const rest = this.restPositions;
        // 复用类成员工作缓冲，避免每帧 new Float32Array（GC 压力）
        if (!this._workBuf || this._workBuf.length !== rest.length) {
            this._workBuf = new Float32Array(rest.length);
        }
        const buf = this._workBuf;
        buf.set(rest); // 基准 = 静态 rest pose
        const tmp = this._tmpArray;
        let rbIdx = 0;

        for (const chain of this.analysis.chains) {
            for (const seg of chain.segments) {
                const rb = this.segmentRbs[rbIdx++];
                rb.getTransformMatrixToArray(tmp, 0);
                // P1: 世界位移 = 刚体世界坐标 − (局部 rest 经 mesh 世界矩阵转出的世界 rest)
                this._tmpLocal.set(seg.restPosition[0], seg.restPosition[1], seg.restPosition[2]);
                localToWorld(this._tmpLocal, this._meshWorld, this._tmpVec);
                this._tmpDelta.set(
                    tmp[12] - this._tmpVec.x,
                    tmp[13] - this._tmpVec.y,
                    tmp[14] - this._tmpVec.z
                );
                // 世界位移 → 局部位移（仅旋转/缩放分量，消除模型整体变换；裙摆随模型移动不漂移）
                worldDeltaToLocal(this._tmpDelta, this._meshWorldInv, this._tmpVec);
                const lsx = this._tmpVec.x;
                const lsy = this._tmpVec.y;
                const lsz = this._tmpVec.z;
                for (let i = 0; i < seg.vertexIndices.length; i++) {
                    const v = seg.vertexIndices[i];
                    const w = seg.weights[i];
                    buf[v * 3] += lsx * w;
                    buf[v * 3 + 1] += lsy * w;
                    buf[v * 3 + 2] += lsz * w;
                }
            }
        }

        this.model.mesh.updateVerticesData(VertexBuffer.PositionKind, buf, false, false);
        // P3f: 顶点位移后刷新包围盒，保证视锥剔除 / 拾取在裙摆飘动后仍正确
        this.model.mesh.refreshBoundingInfo?.();
    }

    /**
     * 释放所有物理资源。顺序（ADR-084 §五）：
     * removeConstraint → removeRigidBody → rb.dispose → constraint.dispose → info.dispose → shape.dispose
     */
    dispose(): void {
        if (this._disposed) {
            return;
        }
        this._disposed = true;

        this.registry?.unregister('virtual-skirt');
        this.registry = null;

        const impl = this.impl;
        if (!impl) {
            return;
        }
        const worldId = this.worldId;

        // remove 阶段：impl 可能已被 WASM runtime 销毁（场景切换/HMR），
        // 单个 remove 失败不阻断后续 dispose，避免资源链路断裂
        for (const c of this.constraints) {
            try {
                impl.removeConstraint(c, worldId);
            } catch (e) {
                logWarn('virtual-skirt', 'removeConstraint failed', e);
            }
        }
        for (const rb of this.segmentRbs) {
            try {
                impl.removeRigidBody(rb, worldId);
            } catch (e) {
                logWarn('virtual-skirt', 'removeRigidBody failed', e);
            }
        }
        if (this.anchorRb) {
            try {
                impl.removeRigidBody(this.anchorRb, worldId);
            } catch (e) {
                logWarn('virtual-skirt', 'removeRigidBody(anchor) failed', e);
            }
        }

        for (const c of this.constraints) {
            c.dispose();
        }
        this.constraints.length = 0;

        for (const rb of this.segmentRbs) {
            rb.dispose();
        }
        this.segmentRbs.length = 0;
        if (this.anchorRb) {
            this.anchorRb.dispose();
        }
        this.anchorRb = null;

        for (const info of this.segmentInfos) {
            info.dispose();
        }
        this.segmentInfos.length = 0;
        if (this.anchorInfo) {
            this.anchorInfo.dispose();
        }
        this.anchorInfo = null;

        for (const s of this.segmentShapes) {
            s.dispose();
        }
        this.segmentShapes.length = 0;
        if (this.anchorShape) {
            this.anchorShape.dispose();
        }
        this.anchorShape = null;

        // P1-fix: 归还 worldId 到 freeList，供下次 build 复用
        releaseWorldId(this.worldId);
        this.worldId = -1;
        this.impl = null;
        this.analysis = null;
        this.restPositions = null;
        this._workBuf = null;
        this._waistBone = null;
        this._frame = 0;
    }

    /** 已注入的骨节总数 */
    get segmentCount(): number {
        return this.segmentRbs.length;
    }

    /** 已注入的约束总数 */
    get constraintCount(): number {
        return this.constraints.length;
    }

    /** Phase 5: 解析后的有效质量档位 */
    get effectiveQuality(): VirtualSkirtQuality {
        return this._effectiveQuality;
    }

    /** Phase 5: LOD 生效后的有效链数 */
    get effectiveChains(): number {
        return this._effectiveChains;
    }

    /** Phase 5: LOD 生效后的有效骨节数 */
    get effectiveSegments(): number {
        return this._effectiveSegments;
    }

    /** Phase 5: 当前降频步长（每 N 帧写回一次） */
    get throttleEvery(): number {
        return this._throttleEvery;
    }
}

// [doc:adr-168] Personal Lights — 角色专属跟随灯
// 职责: 每个 actor 模型自动获得一盏 SpotLight，跟随其根节点移动。
// 注册于 initLighting（onBeforeRenderObservable），disposeLighting 时释放。

import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { SpotLight } from '@babylonjs/core/Lights/spotLight';
import { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { MeshBuilder } from '@babylonjs/core/Meshes/meshBuilder';
import { StandardMaterial } from '@babylonjs/core/Materials/standardMaterial';
import { lightingState } from './lighting-state';
import { modelRegistry, type ModelInstance } from '@/core/config';
import { safeDispose } from '@/core/dispose-helpers';
import { getBoneWorldPosition } from '../../physics/physics-bridge';
import { setTransformMetadata } from '../transform/transform-pick';
import {
    registerTransformAdapter,
    isGizmoDragging,
    getGizmoTargetId,
} from '../transform/transform-adapter';
import {
    createLightCone,
    updateLightConeTransform,
    updateLightConeUniforms,
    rebuildLightConeGeometry,
    setLightConeEnabled,
    disposeLightCone,
    type LightConeEntry,
} from './light-cone';

export interface PersonalLightSettings {
    enabled: boolean;
    intensity: number;
    color: [number, number, number];
    angle: number;
    height: number;
    offsetX: number;
    offsetZ: number;
    coneEnabled: boolean;
    coneIntensity: number;
    coneLength: number;
    coneSoftness: number;
    /** [doc:adr-168] 跟随骨骼名（null = 自动匹配腰骨候选） */
    boneName: string | null;
}

interface PersonalLightEntry {
    light: SpotLight;
    shadowGen: ShadowGenerator;
    settings: PersonalLightSettings;
    currentPos: Vector3;
    cone: LightConeEntry | null;
    indicator: Mesh | null;
    waistName: string | null;
}

const _entries = new Map<string, PersonalLightEntry>();

const _tmpTarget = Vector3.Zero();
const _tmpPos = Vector3.Zero();

/** 腰骨候选名（按优先级），用于个人灯跟随躯干而非脚底 */
const WAIST_CANDIDATES = ['Waist', 'センター', 'Center', '腰', '上半身'];

export const DEFAULT_PERSONAL_LIGHT: PersonalLightSettings = {
    // 默认开启个人灯：当前默认参数（强度 1.2 / 角度 0.7 / 仅 actor、跟随腰骨候选）
    // 已避免多角色互相照射过度曝光，故解除历史 P2-fix 的默认关闭限制
    enabled: true,
    intensity: 1.2,
    color: [1, 1, 1],
    angle: 0.7,
    height: 35,
    offsetX: 0,
    offsetZ: 0,
    coneEnabled: true,
    coneIntensity: 0.6,
    coneLength: 30,
    coneSoftness: 0.5,
    boneName: null,
};

// ======== 用户个人灯默认值（localStorage 持久化） ========

const PERSONAL_LIGHT_DEFAULT_KEY = 'miku.personalLightDefault';

let _userPersonalLightDefault: PersonalLightSettings | null = null;

function _loadPersonalLightDefault(): PersonalLightSettings | null {
    try {
        const raw = localStorage.getItem(PERSONAL_LIGHT_DEFAULT_KEY);
        if (raw) {
            return JSON.parse(raw) as PersonalLightSettings;
        }
    } catch {
        /* ignore */
    }
    return null;
}

// 模块加载时即恢复
_userPersonalLightDefault = _loadPersonalLightDefault();

/**
 * 将当前个人灯参数保存为用户默认值。
 * 后续新加载的模型将以此值为初始值。
 */
export function setPersonalLightDefault(settings: PersonalLightSettings): void {
    _userPersonalLightDefault = { ...settings };
    try {
        localStorage.setItem(PERSONAL_LIGHT_DEFAULT_KEY, JSON.stringify(_userPersonalLightDefault));
    } catch {
        /* ignore */
    }
}

/** 获取用户保存的个人灯默认值，无则返回 null。 */
export function getPersonalLightDefault(): PersonalLightSettings | null {
    return _userPersonalLightDefault ? { ..._userPersonalLightDefault } : null;
}

/** 重置用户默认值回出厂硬编码值。 */
export function resetPersonalLightDefault(): void {
    _userPersonalLightDefault = null;
    try {
        localStorage.removeItem(PERSONAL_LIGHT_DEFAULT_KEY);
    } catch {
        /* ignore */
    }
}

/** 返回实际生效的默认值：用户覆盖 > 硬编码。 */
function _effectivePersonalLightDefault(): PersonalLightSettings {
    return _userPersonalLightDefault
        ? { ..._userPersonalLightDefault }
        : { ...DEFAULT_PERSONAL_LIGHT };
}

/** 取个人灯跟随基准点：用户指定骨骼 → 腰骨候选 → 根节点（兜底） */
function _getLightBasePos(model: ModelInstance, waistName: string | null): Vector3 {
    if (waistName && model.mmdModel) {
        const p = getBoneWorldPosition(model.mmdModel, waistName);
        if (p) {
            return p;
        }
    }
    return model.rootMesh.getAbsolutePosition();
}

export function attachPersonalLight(
    modelId: string,
    overrides?: Partial<PersonalLightSettings>
): void {
    if (_entries.has(modelId)) {
        return;
    }
    const scene = lightingState.scene;
    if (!scene) {
        return;
    }

    const settings: PersonalLightSettings = { ..._effectivePersonalLightDefault(), ...overrides };
    const model = modelRegistry.get(modelId);
    if (!model) {
        return;
    }

    const waistName = settings.boneName
        ? settings.boneName
        : model.mmdModel
          ? (WAIST_CANDIDATES.find((n) =>
                model.mmdModel!.runtimeBones?.some((b) => b.name === n)
            ) ?? null)
          : null;
    const basePos = _getLightBasePos(model, waistName);
    const startPos = new Vector3(
        basePos.x + settings.offsetX,
        basePos.y + settings.height,
        basePos.z + settings.offsetZ
    );

    const light = new SpotLight(
        `personalLight_${modelId}`,
        startPos,
        new Vector3(0, -1, 0),
        settings.angle,
        2,
        scene
    );
    light.intensity = settings.enabled ? settings.intensity : 0;
    light.diffuse = new Color3(settings.color[0], settings.color[1], settings.color[2]);
    light.specular = new Color3(0.3, 0.3, 0.3);
    light.range = settings.height * 3;

    const shadowGen = new ShadowGenerator(512, light);
    shadowGen.usePercentageCloserFiltering = true;
    shadowGen.bias = 0.001;
    for (const m of model.meshes) {
        if (m instanceof Mesh) {
            shadowGen.addShadowCaster(m);
            m.receiveShadows = true;
        }
    }

    const indicator = _createPersonalLightIndicator(settings);
    setTransformMetadata(indicator, 'personalLight', modelId);
    indicator.position.copyFrom(startPos);

    _entries.set(modelId, {
        light,
        shadowGen,
        settings,
        currentPos: startPos.clone(),
        cone: null,
        indicator,
        waistName,
    });

    _ensurePersonalCone(modelId);
}

function _createPersonalLightIndicator(_settings: PersonalLightSettings): Mesh {
    const mesh = MeshBuilder.CreateSphere(
        'personalLightIndicator',
        { diameter: 0.4, segments: 8 },
        lightingState.scene!
    );
    const mat = new StandardMaterial('personalLightIndicatorMat', lightingState.scene!);
    mat.emissiveColor = new Color3(1, 0.85, 0.4);
    mat.disableLighting = true;
    mat.alpha = 0.8;
    mesh.material = mat;
    mesh.isPickable = true;
    return mesh;
}

function _updatePersonalLightIndicator(id: string): void {
    const entry = _entries.get(id);
    const model = modelRegistry.get(id);
    if (!entry || !model) {
        return;
    }
    const basePos = _getLightBasePos(model, entry.waistName);
    const target = new Vector3(
        basePos.x + entry.settings.offsetX,
        basePos.y + entry.settings.height,
        basePos.z + entry.settings.offsetZ
    );
    if (entry.indicator) {
        entry.indicator.position.copyFrom(target);
    }
}

export function detachPersonalLight(modelId: string): void {
    const entry = _entries.get(modelId);
    if (!entry) {
        return;
    }
    if (entry.cone) {
        disposeLightCone(entry.cone);
        entry.cone = null;
    }
    safeDispose(entry.indicator);
    safeDispose(entry.shadowGen);
    safeDispose(entry.light);
    _entries.delete(modelId);
}

export function setPersonalLightState(
    modelId: string,
    partial: Partial<PersonalLightSettings>
): void {
    const entry = _entries.get(modelId);
    if (!entry) {
        return;
    }
    const boneChanged = 'boneName' in partial && partial.boneName !== entry.settings.boneName;
    Object.assign(entry.settings, partial);
    if (boneChanged) {
        // 重新解析跟随骨骼
        const model = modelRegistry.get(modelId);
        if (model) {
            entry.waistName = entry.settings.boneName
                ? entry.settings.boneName
                : model.mmdModel
                  ? (WAIST_CANDIDATES.find((n) =>
                        model.mmdModel!.runtimeBones?.some((b) => b.name === n)
                    ) ?? null)
                  : null;
        }
    }
    const { settings, light } = entry;
    light.intensity = settings.enabled ? settings.intensity : 0;
    light.diffuse.set(settings.color[0], settings.color[1], settings.color[2]);
    light.angle = settings.angle;
    light.range = settings.height * 3;
    _updatePersonalLightIndicator(modelId);
    _ensurePersonalCone(modelId);
}

export function getPersonalLightState(modelId: string): PersonalLightSettings | null {
    return _entries.get(modelId)?.settings ?? null;
}

export function tickPersonalLights(): void {
    const smoothing = 0.15;

    for (const [modelId, entry] of _entries) {
        if (!entry.settings.enabled) {
            continue;
        }
        // 拖拽模式下正在被 gizmo 拖动的个人灯，跳过 tick 避免位置抢夺
        if (isGizmoDragging() && getGizmoTargetId() === modelId) {
            continue;
        }

        const model = modelRegistry.get(modelId);
        if (!model) {
            continue;
        }

        const basePos = _getLightBasePos(model, entry.waistName);
        _tmpTarget.set(
            basePos.x + entry.settings.offsetX,
            basePos.y + entry.settings.height,
            basePos.z + entry.settings.offsetZ
        );
        Vector3.LerpToRef(entry.currentPos, _tmpTarget, smoothing, entry.currentPos);
        entry.light.position.copyFrom(entry.currentPos);

        entry.light.setDirectionToTarget(basePos);

        if (entry.indicator) {
            entry.indicator.position.copyFrom(_tmpTarget);
        }

        if (entry.cone) {
            updateLightConeTransform(entry.cone, entry.light, entry.settings.coneLength);
        }
    }
}

function _ensurePersonalCone(modelId: string): void {
    const entry = _entries.get(modelId);
    if (!entry) {
        return;
    }
    const { settings, light } = entry;
    const scene = lightingState.scene;
    if (!scene) {
        return;
    }

    if (!settings.enabled || !settings.coneEnabled) {
        if (entry.cone) {
            disposeLightCone(entry.cone);
            entry.cone = null;
        }
        return;
    }

    const color = new Color3(settings.color[0], settings.color[1], settings.color[2]);

    if (entry.cone) {
        rebuildLightConeGeometry(entry.cone, scene, light, settings.coneLength);
        updateLightConeTransform(entry.cone, light, settings.coneLength);
        updateLightConeUniforms(
            entry.cone,
            color,
            settings.coneIntensity,
            settings.coneSoftness,
            settings.coneLength
        );
        setLightConeEnabled(entry.cone, true);
        return;
    }

    entry.cone = createLightCone(
        scene,
        light,
        color,
        settings.coneIntensity,
        settings.coneLength,
        settings.coneSoftness
    );
}

export function disposeAllPersonalLights(): void {
    for (const [id] of _entries) {
        detachPersonalLight(id);
    }
}

// ======== Serialization (ADR-168) ========

interface SerializedPersonalLight {
    modelUuid: string;
    settings: PersonalLightSettings;
}

/** 导出所有个人灯状态（仅非默认值差异落盘由调用方决定） */
export function getAllPersonalLights(): Array<{
    modelId: string;
    settings: PersonalLightSettings;
}> {
    const result: Array<{ modelId: string; settings: PersonalLightSettings }> = [];
    for (const [modelId, entry] of _entries) {
        result.push({ modelId, settings: { ...entry.settings } });
    }
    return result;
}

/** 场景反序列化后，按 modelId 恢复个人灯设置（attach 已由 onModelLoaded 触发，此处仅覆盖参数） */
export function restorePersonalLights(
    entries: Array<{ modelId: string; settings: Partial<PersonalLightSettings> }>
): void {
    for (const { modelId, settings } of entries) {
        if (_entries.has(modelId)) {
            setPersonalLightState(modelId, settings);
        }
    }
}

// ======== Transform Adapter (Gizmo 支持) ========

registerTransformAdapter({
    kinds: ['personalLight'],
    getNode: (id) => _entries.get(id)?.indicator ?? null,
    gizmoTypes: () => ['position'],
    onPositionDragEnd: (id, node) => {
        const entry = _entries.get(id);
        const model = modelRegistry.get(id);
        if (!entry || !model) {
            return;
        }
        const basePos = _getLightBasePos(model, entry.waistName);
        const pos = (node as unknown as { position: Vector3 }).position;
        entry.settings.offsetX = pos.x - basePos.x;
        entry.settings.offsetZ = pos.z - basePos.z;
        entry.settings.height = Math.max(5, pos.y - basePos.y);
        entry.currentPos.copyFrom(pos);
        entry.light.position.copyFrom(pos);
    },
    capabilities: [],
});

// ======== Stage Light Follow Tick (ADR-168) ========

const _stageTmpTarget = Vector3.Zero();
const _stageTmpCurrent = Vector3.Zero();

/** 舞台灯追光 tick：更新所有绑定了 followTarget 的舞台灯 */
export function tickStageLightFollow(): void {
    for (const [, entry] of lightingState.stageLights) {
        const ft = entry.state.followTarget;
        if (!ft) {
            continue;
        }

        const model = modelRegistry.get(ft.modelId);
        if (!model) {
            continue;
        }

        // 解析目标位置
        // P3-fix: boneName=null 时用 cachedWaistBone 缓存，避免每帧 find 遍历骨骼
        let boneName = ft.boneName;
        if (!boneName) {
            if (ft.cachedWaistBone === undefined) {
                // 兼容旧数据：cachedWaistBone 字段未初始化时视为 null 触发首次匹配
                ft.cachedWaistBone = null;
            }
            if (ft.cachedWaistBone) {
                boneName = ft.cachedWaistBone;
            } else if (model.mmdModel) {
                const matched =
                    WAIST_CANDIDATES.find((n) =>
                        model.mmdModel!.runtimeBones?.some((b) => b.name === n)
                    ) ?? null;
                ft.cachedWaistBone = matched;
                boneName = matched;
            }
        }

        const basePos = _getLightBasePos(model, boneName);
        _stageTmpTarget.set(
            basePos.x + ft.offset[0],
            basePos.y + ft.offset[1],
            basePos.z + ft.offset[2]
        );

        // 保存上一帧 smoothed target（moveWithTarget 位移计算需要帧间差值）
        const prevTargetX = entry.state.targetX;
        const prevTargetY = entry.state.targetY;
        const prevTargetZ = entry.state.targetZ;

        // 平滑插值
        _stageTmpCurrent.set(prevTargetX, prevTargetY, prevTargetZ);
        Vector3.LerpToRef(_stageTmpCurrent, _stageTmpTarget, ft.smoothing, _stageTmpCurrent);

        // 更新 target
        entry.state.targetX = _stageTmpCurrent.x;
        entry.state.targetY = _stageTmpCurrent.y;
        entry.state.targetZ = _stageTmpCurrent.z;

        // 应用方向更新（SpotLight / DirectionalLight 有 setDirectionToTarget；PointLight 无方向）
        if ('setDirectionToTarget' in entry.light) {
            (entry.light as SpotLight).setDirectionToTarget(_stageTmpCurrent);
        }

        // moveWithTarget: 灯位置跟随 target 的帧间位移（而非持续向 target 靠近导致飞走）
        // P2-fix: 原 delta = target - smoothed 会导致灯位置每帧累加 (1-smoothing) 比例的差值，
        // 持续向 target 方向移动并穿过，灯"飞走"。修正为 delta = 当前smoothed - 上一帧smoothed
        if (ft.moveWithTarget) {
            const currentPos = entry.light.position;
            currentPos.x += _stageTmpCurrent.x - prevTargetX;
            currentPos.y += _stageTmpCurrent.y - prevTargetY;
            currentPos.z += _stageTmpCurrent.z - prevTargetZ;

            entry.state.posX = currentPos.x;
            entry.state.posY = currentPos.y;
            entry.state.posZ = currentPos.z;
        }
    }
}

// [doc:architecture] Lighting — 舞台灯（增删/状态/指示器/光锥）
// 状态集中于 lightingState，本文件不再持有任何模块级可变状态。
// 注意: _defaultStageLightState 由 ./lighting 导出（主光 init 与 stage 共用）。

import { SpotLight } from '@babylonjs/core/Lights/spotLight';
import { PointLight } from '@babylonjs/core/Lights/pointLight';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { MeshBuilder } from '@babylonjs/core/Meshes/meshBuilder';
import type { LinesMesh } from '@babylonjs/core/Meshes/linesMesh';
import { StandardMaterial } from '@babylonjs/core/Materials/standardMaterial';
import {
    createLightCone,
    updateLightConeTransform,
    updateLightConeUniforms,
    rebuildLightConeGeometry,
    setLightConeEnabled,
    disposeLightCone,
} from './light-cone';
import {
    lightingState,
    StageLightEntry,
    SHADOW_REBUILD_KEYS,
    CONE_UPDATE_KEYS,
} from './lighting-state';
import { _defaultStageLightState, type StageLightState, type StageLightType } from './lighting';
import { _ensureStageShadow, _disposeStageShadow } from './lighting-shadow';
import { col3FromTriple } from '@/core/color-helpers';
import { logWarn } from '@/core/logger';
import {
    registerTransformAdapter,
    attachGizmoForKind,
    isGizmoActive as _isGizmoActive,
    getGizmoTargetId as _getGizmoTargetId,
} from '../transform/transform-adapter';
import { setTransformMetadata } from '../transform/transform-pick';

// _createStageLight / _createIndicator / _createDirLine 均仅在 addStageLight
// 中调用，而 addStageLight 在 scene === null 时 early return，
// 故此处 scene! 断言安全。
export function _createStageLight(
    type: StageLightType,
    state: StageLightState
): SpotLight | PointLight | DirectionalLight {
    const pos = new Vector3(state.posX, state.posY, state.posZ);
    const target = new Vector3(state.targetX, state.targetY, state.targetZ);
    const diffuse = col3FromTriple(state.color);
    const intensity = state.enabled ? state.intensity : 0;

    if (type === 'spot') {
        const light = new SpotLight(
            state.id,
            pos,
            new Vector3(0, -1, 0),
            state.angle,
            state.exponent,
            lightingState.scene!
        );
        light.intensity = intensity;
        light.diffuse = diffuse;
        light.specular = new Color3(0.3, 0.3, 0.3);
        light.setDirectionToTarget(target);
        return light;
    }
    if (type === 'point') {
        const light = new PointLight(state.id, pos, lightingState.scene!);
        light.intensity = intensity;
        light.diffuse = diffuse;
        light.specular = new Color3(0.3, 0.3, 0.3);
        light.range = state.range;
        return light;
    }
    // directional
    const dir = target.subtract(pos);
    // 零向量守卫：target === pos 时 fallback 向下
    if (dir.lengthSquared() < 1e-6) {
        dir.set(0, -1, 0);
    } else {
        dir.normalize();
    }
    const light = new DirectionalLight(state.id, dir, lightingState.scene!);
    light.intensity = intensity;
    light.diffuse = diffuse;
    light.specular = new Color3(0.3, 0.3, 0.3);
    light.position = pos.clone();
    return light;
}

// ======== Stage Light Indicator ========

/** 模块级临时向量（避免 _updateIndicator 拖拽时 60fps 分配临时对象） */

function _createIndicator(): Mesh {
    const mesh = MeshBuilder.CreateSphere(
        'lightIndicator',
        { diameter: 0.5, segments: 8 },
        lightingState.scene!
    );
    const mat = new StandardMaterial('lightIndicatorMat', lightingState.scene!);
    mat.emissiveColor = new Color3(1, 1, 1);
    mat.disableLighting = true;
    mesh.material = mat;
    mesh.isPickable = true;
    return mesh;
}

function _createDirLine(): LinesMesh {
    const mesh = MeshBuilder.CreateLines(
        'lightDirLine',
        {
            points: [Vector3.Zero(), new Vector3(0, -2, 0)],
            updatable: true, // 允许后续通过 instance 更新顶点
        },
        lightingState.scene!
    );
    mesh.color = new Color3(1, 1, 0.5);
    mesh.isPickable = false;
    return mesh;
}

export function _updateIndicator(entry: StageLightEntry): void {
    if (!lightingState.scene) {
        return;
    }
    const { state, light } = entry;

    // 更新球体指示器
    if (state.enabled) {
        if (!entry.indicator) {
            entry.indicator = _createIndicator();
            setTransformMetadata(entry.indicator, 'light', state.id);
        }
        entry.indicator.position.copyFrom(light.position);
        entry.indicator.scaling.setAll(state.indicatorScale);
        // 防御：material 可能被外部清理（scene 重置 / material cache 清除等），
        // 此时重建而非崩溃。
        if (!entry.indicator.material) {
            const mat = new StandardMaterial('lightIndicatorMat', lightingState.scene!);
            mat.emissiveColor = new Color3(1, 1, 1);
            mat.disableLighting = true;
            entry.indicator.material = mat;
        }
        const indMat = entry.indicator.material as StandardMaterial;
        indMat.alpha = state.indicatorOpacity;
        entry.indicator.setEnabled(true);

        // 聚光灯：显示方向线（通过 instance 更新顶点，避免每帧 dispose+rebuild）
        if (state.type === 'spot' && light instanceof SpotLight) {
            if (!entry.dirLine) {
                entry.dirLine = _createDirLine();
            }
            lightingState.tmpTarget.set(state.targetX, state.targetY, state.targetZ);
            lightingState.tmpTarget.subtractToRef(light.position, lightingState.tmpDir);
            lightingState.tmpDir.normalize().scaleInPlace(3);
            // 使用 instance 参数原地更新几何，不创建新 Mesh
            MeshBuilder.CreateLines(
                'lightDirLine',
                { points: [Vector3.Zero(), lightingState.tmpDir], instance: entry.dirLine },
                lightingState.scene!
            );
            entry.dirLine.position.copyFrom(light.position);
            entry.dirLine.setEnabled(true);
        } else {
            if (entry.dirLine) {
                entry.dirLine.dispose();
                entry.dirLine = null;
            }
        }
    } else {
        if (entry.indicator) {
            entry.indicator.setEnabled(false);
        }
        if (entry.dirLine) {
            entry.dirLine.setEnabled(false);
        }
    }
}

function _disposeIndicator(entry: StageLightEntry): void {
    if (entry.indicator) {
        entry.indicator.material?.dispose();
        entry.indicator.dispose();
        entry.indicator = null;
    }
    if (entry.dirLine) {
        entry.dirLine.dispose();
        entry.dirLine = null;
    }
}

export function getStageLights(): StageLightState[] {
    const result: StageLightState[] = [];
    for (const [, entry] of lightingState.stageLights) {
        result.push(_readStageLightState(entry));
    }
    return result;
}

export function getActiveStageLightId(): string | null {
    return lightingState.activeStageLightId;
}

export function setActiveStageLightId(id: string): void {
    if (lightingState.stageLights.has(id)) {
        lightingState.activeStageLightId = id;
    }
}

export function getStageLightState(id?: string): StageLightState {
    const entry = _getEntry(id);
    if (!entry) {
        return _defaultStageLightState('light-1', '主光');
    }
    return _readStageLightState(entry);
}

export function setStageLightState(s: Partial<StageLightState>, id?: string): void {
    const targetId = id ?? s.id ?? lightingState.activeStageLightId;
    if (!targetId) {
        return;
    }
    const entry = lightingState.stageLights.get(targetId);
    if (!entry || !lightingState.triggerAutoSave) {
        return;
    }

    // 类型切换：dispose 旧灯 + 旧阴影 + 旧光锥 + 创建新灯
    if (s.type !== undefined && s.type !== entry.state.type) {
        Object.assign(entry.state, s);
        entry.light.dispose();
        _disposeStageShadow(targetId);
        _disposeStageCone(targetId);
        entry.light = _createStageLight(s.type, entry.state);
        _ensureStageShadow(targetId);
        _ensureStageCone(targetId);
        _updateIndicator(entry);
        // 类型切换后 gizmo 仍指向旧灯（已 dispose），通过适配器重新附着到新灯
        if (_isGizmoActive() && _getGizmoTargetId() === targetId) {
            attachGizmoForKind('light', targetId);
        }
        lightingState.triggerAutoSave();
        return;
    }

    Object.assign(entry.state, s);
    _applyStageLightParams(entry, s);

    // 阴影重建条件
    let needShadowRebuild = false;
    for (const key of SHADOW_REBUILD_KEYS) {
        if ((s as Record<string, unknown>)[key] !== undefined) {
            needShadowRebuild = true;
            break;
        }
    }
    if (needShadowRebuild) {
        _ensureStageShadow(targetId);
    }

    // 光锥重建/更新条件
    let needConeUpdate = false;
    for (const key of CONE_UPDATE_KEYS) {
        if ((s as Record<string, unknown>)[key] !== undefined) {
            needConeUpdate = true;
            break;
        }
    }
    if (needConeUpdate) {
        _ensureStageCone(targetId);
    }

    // 更新指示器
    _updateIndicator(entry);

    if (!lightingState.skipLightAutoSave) {
        lightingState.triggerAutoSave();
    }
}

/** 释放单个舞台灯 entry 的全部资源（指示器 + 灯 + 阴影 + 光锥）。 */
export function _disposeStageLightEntry(id: string, entry: StageLightEntry): void {
    _disposeIndicator(entry);
    entry.light.dispose();
    _disposeStageShadow(id);
    _disposeStageCone(id);
}

/** 注册舞台灯 entry：写入映射 + 生成阴影/光锥 + 更新指示器。 */
function _registerStageLight(id: string, entry: StageLightEntry): void {
    lightingState.stageLights.set(id, entry);
    _ensureStageShadow(id);
    _ensureStageCone(id);
    _updateIndicator(entry);
}

export function addStageLight(
    type: StageLightType = 'spot',
    preset?: Partial<StageLightState>
): string {
    // P2-fix: 光源数量上限保护（Babylon StandardMaterial 默认 maxSimultaneousLights=4，
    // 超出会静默不渲染部分灯；主光+半球光已占 2 槽，故舞台灯上限 6 留余量）
    const MAX_STAGE_LIGHTS = 6;
    if (lightingState.stageLights.size >= MAX_STAGE_LIGHTS) {
        return '';
    }
    lightingState.stageLightCounter++;
    const id = `light-${lightingState.stageLightCounter}`;
    const defaultNames: Record<StageLightType, string> = {
        spot: '聚光灯',
        point: '点光源',
        directional: '平行光',
    };
    const name = `${defaultNames[type]} ${lightingState.stageLightCounter}`;
    const state = { ..._defaultStageLightState(id, name), type, ...preset, id, name };
    state.posX = lightingState.stageLightCounter * 2 - 2;
    state.orbitAzimuth = 180 + (lightingState.stageLightCounter - 1) * 30;
    const light = _createStageLight(type, state);
    const entry: StageLightEntry = { state, light, indicator: null, dirLine: null };
    _registerStageLight(id, entry);
    lightingState.activeStageLightId = id;
    if (lightingState.triggerAutoSave && !lightingState.skipLightAutoSave) {
        lightingState.triggerAutoSave();
    }
    return id;
}

export function removeStageLight(id: string): boolean {
    const entry = lightingState.stageLights.get(id);
    if (!entry) {
        return false;
    }
    if (lightingState.stageLights.size <= 1) {
        return false;
    }
    _disposeStageLightEntry(id, entry);
    lightingState.stageLights.delete(id);
    if (lightingState.activeStageLightId === id) {
        lightingState.activeStageLightId = lightingState.stageLights.keys().next().value ?? null;
    }
    if (lightingState.triggerAutoSave && !lightingState.skipLightAutoSave) {
        lightingState.triggerAutoSave();
    }
    return true;
}

/** 批量加载舞台灯（反序列化用），会清空现有灯 */
export function loadStageLights(states: StageLightState[]): void {
    // 清空旧灯（含各自的指示器/阴影/光锥）
    for (const [lid, entry] of lightingState.stageLights) {
        _disposeStageLightEntry(lid, entry);
    }
    lightingState.stageLights.clear();
    lightingState.stageShadows.clear();
    lightingState.stageCones.clear();

    if (states.length === 0) {
        const def = _defaultStageLightState('light-1', '主光');
        const light = _createStageLight(def.type, def);
        const entry: StageLightEntry = { state: def, light, indicator: null, dirLine: null };
        _registerStageLight(def.id, entry);
        lightingState.activeStageLightId = def.id;
        lightingState.stageLightCounter = 1;
        return;
    }

    let maxNum = 0;
    for (const s of states) {
        // 旧存档迁移：volumetric* → cone*（与 _readStageLightState 保持一致）
        const raw = s as unknown as Record<string, unknown>;
        const migrated: StageLightState = {
            ...s,
            coneEnabled: s.coneEnabled ?? (raw.volumetricEnabled as boolean | undefined) ?? false,
            coneIntensity:
                s.coneIntensity ??
                Math.min(2, ((raw.volumetricExposure as number | undefined) ?? 1) * 0.5),
            coneLength: s.coneLength ?? 30,
            coneSoftness:
                s.coneSoftness ?? 1 - ((raw.volumetricDensity as number | undefined) ?? 0.5),
        };
        const light = _createStageLight(migrated.type, migrated);
        const entry: StageLightEntry = { state: migrated, light, indicator: null, dirLine: null };
        _registerStageLight(migrated.id, entry);
        const m = migrated.id.match(/light-(\d+)/);
        if (m) {
            maxNum = Math.max(maxNum, parseInt(m[1], 10));
        }
    }
    lightingState.stageLightCounter = maxNum;
    lightingState.activeStageLightId = states[0].id;
}

/** 重建所有舞台灯的阴影投射者列表（模型/道具变化时调用） */
export function rebuildStageLightShadows(): void {
    for (const [id] of lightingState.stageLights) {
        _ensureStageShadow(id);
    }
}

// —— 内部辅助 ——

function _getEntry(id?: string): StageLightEntry | null {
    const targetId = id ?? lightingState.activeStageLightId;
    if (!targetId) {
        return null;
    }
    return lightingState.stageLights.get(targetId) ?? null;
}

function _readStageLightState(entry: StageLightEntry): StageLightState {
    const { state, light } = entry;
    const base: StageLightState = {
        ...state,
        indicatorScale: state.indicatorScale ?? 1,
        indicatorOpacity: state.indicatorOpacity ?? 1,
        // 光锥字段（兼容旧存档 volumetric* → cone*）
        coneEnabled:
            state.coneEnabled ??
            ((state as unknown as Record<string, unknown>).volumetricEnabled as boolean) ??
            false,
        coneIntensity:
            state.coneIntensity ??
            Math.min(
                2,
                (((state as unknown as Record<string, unknown>).volumetricExposure as
                    number | undefined) ?? 1) * 0.5
            ),
        coneLength: state.coneLength ?? 20,
        coneSoftness:
            state.coneSoftness ??
            1 -
                (((state as unknown as Record<string, unknown>).volumetricDensity as
                    number | undefined) ?? 0.5),
        intensity: light.intensity,
        color: [light.diffuse.r, light.diffuse.g, light.diffuse.b],
        posX: light.position.x,
        posY: light.position.y,
        posZ: light.position.z,
        orbitAzimuth: (Math.atan2(light.position.x, light.position.z) * 180) / Math.PI,
        orbitElevation:
            (Math.asin(light.position.y / Math.max(0.1, light.position.length())) * 180) / Math.PI,
        orbitDistance: light.position.length(),
    };
    if (state.type === 'spot' && light instanceof SpotLight) {
        base.angle = light.angle;
        base.exponent = light.exponent;
    }
    if (state.type === 'point' && light instanceof PointLight) {
        base.range = light.range;
    }
    return base;
}

function _applyStageLightParams(entry: StageLightEntry, s: Partial<StageLightState>): void {
    const { state, light } = entry;
    const type = state.type;

    if (s.enabled !== undefined) {
        light.intensity = s.enabled ? state.intensity : 0;
    }
    if (s.intensity !== undefined && state.enabled) {
        light.intensity = s.intensity;
    }
    if (s.color !== undefined) {
        light.diffuse = col3FromTriple(s.color);
    }

    if (type === 'spot' && light instanceof SpotLight) {
        if (s.angle !== undefined) {
            light.angle = s.angle;
        }
        if (s.exponent !== undefined) {
            light.exponent = s.exponent;
        }
    }
    if (type === 'point' && light instanceof PointLight) {
        if (s.range !== undefined) {
            light.range = s.range;
        }
    }

    if (
        s.orbitAzimuth !== undefined ||
        s.orbitElevation !== undefined ||
        s.orbitDistance !== undefined
    ) {
        const az = ((s.orbitAzimuth ?? state.orbitAzimuth) * Math.PI) / 180;
        const el = ((s.orbitElevation ?? state.orbitElevation) * Math.PI) / 180;
        const dist = s.orbitDistance ?? state.orbitDistance;
        light.position = new Vector3(
            dist * Math.cos(el) * Math.sin(az),
            dist * Math.sin(el),
            dist * Math.cos(el) * Math.cos(az)
        );
        if (type === 'spot' && light instanceof SpotLight) {
            light.setDirectionToTarget(new Vector3(state.targetX, state.targetY, state.targetZ));
        }
        if (type === 'directional' && light instanceof DirectionalLight) {
            const dir = new Vector3(
                state.targetX - light.position.x,
                state.targetY - light.position.y,
                state.targetZ - light.position.z
            ).normalize();
            light.direction = dir;
        }
    }
    if (s.posX !== undefined || s.posY !== undefined || s.posZ !== undefined) {
        light.position = new Vector3(
            s.posX ?? light.position.x,
            s.posY ?? light.position.y,
            s.posZ ?? light.position.z
        );
    }
    if (s.targetX !== undefined || s.targetY !== undefined || s.targetZ !== undefined) {
        if (type === 'spot' && light instanceof SpotLight) {
            light.setDirectionToTarget(
                new Vector3(
                    s.targetX ?? state.targetX,
                    s.targetY ?? state.targetY,
                    s.targetZ ?? state.targetZ
                )
            );
        }
        if (type === 'directional' && light instanceof DirectionalLight) {
            const dir = new Vector3(
                (s.targetX ?? state.targetX) - light.position.x,
                (s.targetY ?? state.targetY) - light.position.y,
                (s.targetZ ?? state.targetZ) - light.position.z
            ).normalize();
            light.direction = dir;
        }
    }

    // 指示器缩放/透明度 — 在 _updateIndicator 中应用，这里只标记状态已更新
}

// ======== 真实光锥（替代 ADR-152 的屏幕后处理假体积光） =====

/**
 * 确保指定舞台灯的光锥与 state 同步（按需创建/销毁/更新）。
 * 仅 SpotLight 支持光锥；PointLight / DirectionalLight 自动跳过。
 */
function _ensureStageCone(id: string): void {
    if (!lightingState.scene) {
        return;
    }
    const entry = lightingState.stageLights.get(id);
    if (!entry) {
        _disposeStageCone(id);
        return;
    }
    const state = entry.state;

    // 关闭或非 SpotLight → 释放
    if (!state.enabled || !state.coneEnabled || state.type !== 'spot') {
        _disposeStageCone(id);
        return;
    }

    const light = entry.light;
    if (!(light instanceof SpotLight)) {
        _disposeStageCone(id);
        return;
    }

    const existing = lightingState.stageCones.get(id);
    const color = col3FromTriple(state.color);

    if (existing) {
        // 锥长/锥角变化 → 重建几何
        rebuildLightConeGeometry(existing, lightingState.scene, light, state.coneLength);
        // 更新 transform（位置/朝向）
        updateLightConeTransform(existing, light, state.coneLength);
        // 更新 uniforms
        updateLightConeUniforms(
            existing,
            color,
            state.coneIntensity,
            state.coneSoftness,
            state.coneLength
        );
        setLightConeEnabled(existing, true);
        return;
    }

    // 创建新光锥
    try {
        const cone = createLightCone(
            lightingState.scene,
            light,
            color,
            state.coneIntensity,
            state.coneLength,
            state.coneSoftness
        );
        lightingState.stageCones.set(id, cone);
    } catch (e) {
        logWarn('light-cone', `create light cone failed for ${id}: ${e}`);
    }
}

/** 释放指定舞台灯的光锥 */
function _disposeStageCone(id: string): void {
    const cone = lightingState.stageCones.get(id);
    if (cone) {
        disposeLightCone(cone);
        lightingState.stageCones.delete(id);
    }
}

// ======== Transform Adapter (ADR-126) ========

registerTransformAdapter({
    kinds: ['light'],
    getNode: (id) => lightingState.stageLights.get(id)?.light ?? null,
    gizmoTypes: (id) =>
        lightingState.stageLights.get(id)?.state.type !== 'point'
            ? ['position', 'rotation']
            : ['position'],
    onPositionDragEnd: (id, n) => {
        const v = (n as unknown as { position: Vector3 }).position;
        setStageLightState({ posX: v.x, posY: v.y, posZ: v.z }, id);
    },
    onRotationDragEnd: (id) => {
        const entry = lightingState.stageLights.get(id);
        if (!entry) {
            return;
        }
        const pos = entry.light.position;
        if (entry.state.type === 'spot' && entry.light instanceof SpotLight) {
            const curDir = entry.light.direction;
            const target = pos.add(curDir.scale(10));
            setStageLightState({ targetX: target.x, targetY: target.y, targetZ: target.z }, id);
        }
        if (entry.state.type === 'directional' && entry.light instanceof DirectionalLight) {
            const dir = entry.light.direction;
            const target = pos.add(dir.scale(10));
            setStageLightState({ targetX: target.x, targetY: target.y, targetZ: target.z }, id);
        }
    },
    capabilities: ['slider-scale', 'slider-opacity'],
    getScale: (id) => getStageLightState(id).indicatorScale,
    setScale: (id, v) => setStageLightState({ indicatorScale: v }, id),
    getOpacity: (id) => getStageLightState(id).indicatorOpacity,
    setOpacity: (id, v) => setStageLightState({ indicatorOpacity: v }, id),
});

// [doc:architecture] Lighting — 预设过渡动画（tween）与预设应用
// 状态集中于 lightingState，本文件不再持有任何模块级可变状态。

import { Color3 } from '@babylonjs/core/Maths/math.color';
import { lightingState, type LightingTween } from './lighting-state';
import { col3FromTriple } from '@/core/color-helpers';
import { addStageLight, removeStageLight, setStageLightState } from './lighting-stage';
import { LIGHTING_PRESETS } from './lighting-presets';
import { getAllPersonalLights, setPersonalLightState } from './lighting-follow';
import type { PersonalLightSettings } from './lighting-follow';

export function _cancelAllLightingTweens(): void {
    for (const [, tw] of lightingState.activeTweens) {
        tw.cancel();
    }
    lightingState.activeTweens.clear();
}

export function _tweenValue(
    from: number,
    to: number,
    durationMs: number,
    onUpdate: (v: number) => void,
    onComplete?: () => void
): LightingTween {
    const id = ++lightingState.tweenIdCounter;
    let cancelled = false;
    const start = performance.now();

    const tick = () => {
        if (cancelled) {
            return;
        }
        const t = Math.min(1, (performance.now() - start) / durationMs);
        const eased = t * (2 - t); // ease-out quad
        onUpdate(from + (to - from) * eased);
        if (t >= 1) {
            lightingState.activeTweens.delete(id);
            onComplete?.();
        } else {
            // 未完成时重新注册下一帧
            lightingState.scene?.onBeforeRenderObservable.addOnce(tick);
        }
    };

    const tw: LightingTween = {
        id,
        cancel: () => {
            cancelled = true;
            lightingState.activeTweens.delete(id);
        },
    };
    lightingState.activeTweens.set(id, tw);
    lightingState.scene!.onBeforeRenderObservable.addOnce(tick);
    return tw;
}

export function _tweenColor3(
    from: Color3,
    to: Color3,
    durationMs: number,
    onUpdate: (c: Color3) => void,
    onComplete?: () => void
): void {
    const result = new Color3(0, 0, 0);
    _tweenValue(
        0,
        1,
        durationMs,
        (t) => {
            result.r = from.r + (to.r - from.r) * t;
            result.g = from.g + (to.g - from.g) * t;
            result.b = from.b + (to.b - from.b) * t;
            onUpdate(result);
        },
        onComplete
    );
}

// ======== Lighting Preset Application ========

/**
 * 应用灯光预设——复用现有灯光，平滑过渡参数。
 * 由 EnvBridge 在 lightingPresetName 变化时调用。
 */
export function applyLightingPresetFromEnv(presetName: string | null): void {
    if (!presetName) {
        return;
    }
    const preset = LIGHTING_PRESETS[presetName];
    if (!preset) {
        return;
    }

    _cancelAllLightingTweens();

    const targetCount = preset.lights.length;

    // 1. 补齐灯光数量
    while (Array.from(lightingState.stageLights.keys()).length < targetCount) {
        const idx = Array.from(lightingState.stageLights.keys()).length;
        const pl = preset.lights[idx];
        addStageLight(pl.type, pl.state as Partial<import('./lighting').StageLightState>);
    }

    // 2. 删除多余灯光
    while (Array.from(lightingState.stageLights.keys()).length > targetCount) {
        const ids = Array.from(lightingState.stageLights.keys());
        removeStageLight(ids[ids.length - 1]);
    }

    // 3. 平滑过渡每盏灯的参数
    // 动画期间抑制自动保存（tween 每帧触发 setStageLightState，避免大量写盘）
    lightingState.skipLightAutoSave = true;
    // 追踪活跃 tween 数量，全部完成后恢复自动保存
    let pendingTweens = 0;
    const onTweenDone = () => {
        pendingTweens--;
        if (pendingTweens <= 0) {
            lightingState.skipLightAutoSave = false;
            if (lightingState.triggerAutoSave) {
                lightingState.triggerAutoSave();
            }
        }
    };
    const ids = Array.from(lightingState.stageLights.keys());
    for (let i = 0; i < ids.length; i++) {
        const entry = lightingState.stageLights.get(ids[i]);
        if (!entry) {
            continue;
        }
        const pl = preset.lights[i];

        // 切换类型（需要重建，跳过 tween）
        if (pl.type !== entry.state.type) {
            setStageLightState(
                { type: pl.type, ...pl.state } as Partial<import('./lighting').StageLightState>,
                ids[i]
            );
            continue;
        }

        // 位置过渡（orbit 参数）
        if (
            pl.state.orbitAzimuth !== undefined ||
            pl.state.orbitElevation !== undefined ||
            pl.state.orbitDistance !== undefined
        ) {
            const fromAz = entry.state.orbitAzimuth;
            const fromEl = entry.state.orbitElevation;
            const fromDist = entry.state.orbitDistance;
            const toAz = (pl.state.orbitAzimuth as number) ?? fromAz;
            const toEl = (pl.state.orbitElevation as number) ?? fromEl;
            const toDist = (pl.state.orbitDistance as number) ?? fromDist;
            pendingTweens++;
            _tweenValue(
                0,
                1,
                500,
                (t) => {
                    setStageLightState(
                        {
                            orbitAzimuth: fromAz + (toAz - fromAz) * t,
                            orbitElevation: fromEl + (toEl - fromEl) * t,
                            orbitDistance: fromDist + (toDist - fromDist) * t,
                        },
                        ids[i]
                    );
                },
                onTweenDone
            );
        }

        // 强度过渡
        if (pl.state.intensity !== undefined) {
            const from = entry.state.intensity;
            const to = pl.state.intensity as number;
            pendingTweens++;
            _tweenValue(
                from,
                to,
                300,
                (v) => {
                    setStageLightState({ intensity: v }, ids[i]);
                },
                onTweenDone
            );
        }

        // 颜色过渡
        if (pl.state.color !== undefined) {
            const from = new Color3(
                entry.state.color[0],
                entry.state.color[1],
                entry.state.color[2]
            );
            const tc = pl.state.color as [number, number, number];
            const to = col3FromTriple(tc);
            pendingTweens++;
            _tweenColor3(
                from,
                to,
                300,
                (c) => {
                    setStageLightState({ color: [c.r, c.g, c.b] }, ids[i]);
                },
                onTweenDone
            );
        }

        // 直接设置的参数（无 tween）
        const directKeys = [
            'angle',
            'exponent',
            'range',
            'shadowEnabled',
            'shadowType',
            'shadowResolution',
            'shadowBias',
            'enabled',
        ] as const;
        const directUpdates: Record<string, unknown> = {};
        let hasDirect = false;
        for (const key of directKeys) {
            if (pl.state[key] !== undefined) {
                directUpdates[key] = pl.state[key];
                hasDirect = true;
            }
        }
        if (hasDirect) {
            setStageLightState(
                directUpdates as Partial<import('./lighting').StageLightState>,
                ids[i]
            );
        }
    }

    // [doc:adr-168] 预设联动个人灯：平滑过渡 intensity / color / angle
    if (preset.personalLight) {
        const plOverride = preset.personalLight as Partial<PersonalLightSettings>;
        const allLights = getAllPersonalLights();
        for (const { modelId, settings } of allLights) {
            if (plOverride.intensity !== undefined) {
                const from = settings.intensity;
                const to = plOverride.intensity;
                pendingTweens++;
                _tweenValue(
                    from,
                    to,
                    300,
                    (v) => {
                        setPersonalLightState(modelId, { intensity: v });
                    },
                    onTweenDone
                );
            }
            if (plOverride.color !== undefined) {
                const from = new Color3(settings.color[0], settings.color[1], settings.color[2]);
                const to = col3FromTriple(plOverride.color);
                pendingTweens++;
                _tweenColor3(
                    from,
                    to,
                    300,
                    (c) => {
                        setPersonalLightState(modelId, { color: [c.r, c.g, c.b] });
                    },
                    onTweenDone
                );
            }
            if (plOverride.angle !== undefined) {
                setPersonalLightState(modelId, { angle: plOverride.angle });
            }
        }
    }

    // 所有舞台灯与个人灯 tween 均已注册后，再决定是否恢复自动保存。
    if (pendingTweens <= 0) {
        lightingState.skipLightAutoSave = false;
        lightingState.triggerAutoSave?.();
    }
}

// [doc:architecture] Scene Lighting — 光照、阴影、太阳盘（barrel + 主光管理）
// 职责: 方向光/半球光管理、阴影生成器、太阳圆盘可视化
// 注意: 从 scene.ts 静态导入但仅在函数体内访问，ES module live binding 保证安全。
// 子文件（lighting-stage/-shadow/-sun/-tween）通过单一 `lightingState` 共享全部模块状态。

import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { HemisphericLight } from '@babylonjs/core/Lights/hemisphericLight';
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight';
import type { Scene } from '@babylonjs/core/scene';
import type { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';

import { observe } from '@/core/observer-handle';
import { onBoneMatricesUpdated } from '@/core/mmd-adapter';
import { initTransformGizmo } from './transform-gizmo';
import { scheduleRefresh } from '@/core/reactivity';
import { resetPerformanceSnapshot, isSnapshotResetSuppressed } from './performance';
import { setKey } from '@/core/set-key';
import { safeDispose } from '@/core/dispose-helpers';
import { col3FromTriple } from '@/core/color-helpers';
import { envState } from '@/core/config';
import { lightingState } from './lighting-state';
import { _createStageLight, _updateIndicator, _disposeStageLightEntry } from './lighting-stage';
import { _ensureShadow } from './lighting-shadow';
import { _updateSunDisc, _disposeSunDisc } from './lighting-sun';
import { _cancelAllLightingTweens } from './lighting-tween';
import {
    tickPersonalLights,
    disposeAllPersonalLights,
    tickStageLightFollow,
} from './lighting-follow';

// ======== Light State ========

export interface LightState {
    hemiIntensity: number;
    dirIntensity: number;
    dirX: number;
    dirY: number;
    dirZ: number;
    dirColor: [number, number, number];
    hemiColor: [number, number, number];
    groundColor: [number, number, number];
    shadowEnabled: boolean;
    shadowType: 'hard' | 'soft' | 'pcf';
    shadowCascades: number;
    shadowResolution: number; // 新增
    shadowBias: number; // 新增
}

export type StageLightType = 'spot' | 'point' | 'directional';

export interface StageLightState {
    id: string; // 唯一标识
    name: string; // 显示名
    enabled: boolean;
    type: StageLightType; // 灯光类型
    intensity: number;
    color: [number, number, number];
    // SpotLight 专属
    angle: number; // 锥角（弧度）
    exponent: number; // 衰减指数
    // PointLight 专属
    range: number; // 衰减距离
    // 阴影投射
    shadowEnabled: boolean;
    shadowType: 'hard' | 'soft' | 'pcf';
    shadowResolution: number;
    shadowBias: number;
    // 位置
    posX: number;
    posY: number;
    posZ: number;
    // 目标点（spot 用；directional 用其反推方向）
    targetX: number;
    targetY: number;
    targetZ: number;
    // 轨道控制参数（从 posX/Y/Z 实时推导，写回时反算）
    orbitAzimuth: number; // -180~180 度，水平绕 Y 轴
    orbitElevation: number; // -90~90 度，垂直仰角
    orbitDistance: number; // 距原点距离
    // 指示球体缩放/透明度（UI 大统一 — 与模型/道具共享 buildTransformCard）
    indicatorScale: number;
    indicatorOpacity: number;
    // 真实光锥（锥形光柱可视化）
    coneEnabled: boolean;
    coneIntensity: number; // 0-2, default 0.5
    coneLength: number; // 1-50, default 20
    coneSoftness: number; // 0-1, default 0.5
    // [doc:adr-168] 跟随目标（null = 静态模式，向后兼容）
    followTarget: {
        modelId: string;
        boneName: string | null;
        offset: [number, number, number];
        smoothing: number; // 0-1, default 0.15
        moveWithTarget: boolean; // default false
        // P3-fix: 缓存自动匹配的腰骨名，避免 tickStageLightFollow 每帧 find
        // boneName 非 null 时此字段不使用；boneName=null 首次匹配后缓存
        cachedWaistBone: string | null;
    } | null;
}

export function _defaultStageLightState(id: string, name: string): StageLightState {
    return {
        id,
        name,
        enabled: false,
        type: 'spot',
        intensity: 0.8,
        color: [1, 1, 1],
        angle: 0.8,
        exponent: 2,
        range: 50,
        shadowEnabled: false,
        shadowType: 'soft',
        shadowResolution: 1024,
        shadowBias: 0.0001,
        posX: 0,
        posY: 35,
        posZ: 0,
        targetX: 0,
        targetY: 0,
        targetZ: 0,
        orbitAzimuth: 180,
        orbitElevation: 90,
        orbitDistance: 35,
        indicatorScale: 1,
        indicatorOpacity: 1,
        // 光锥默认关闭
        coneEnabled: false,
        coneIntensity: 0.5,
        coneLength: 30,
        coneSoftness: 0.5,
        // [doc:adr-168] 默认静态模式
        followTarget: null, // 注意：创建 followTarget 时须初始化 cachedWaistBone: null
    };
}

// ======== Lights (module-level state) ========

/** 主半球光（未初始化时为 null）。导出 getter 替代原 `export let`，消除导出可变绑定。 */
export function getHemiLight(): HemisphericLight | null {
    return lightingState.hemiLight;
}

/** 主方向光（未初始化时为 null）。 */
export function getDirLight(): DirectionalLight | null {
    return lightingState.dirLight;
}

/** 预设动画期间临时抑制 setLightState 内的自动保存，由 applyEnvPreset 控制 */
export function setSkipLightAutoSave(skip: boolean): void {
    lightingState.skipLightAutoSave = skip;
}

export function initLighting(
    scene: Scene,
    envSysShadow: { generator: ShadowGenerator | null },
    saveCb: () => void
): void {
    // 防御重复调用（正常流程由 disposeScene 保证，此处为模块级安全网）
    if (lightingState.scene) {
        disposeLighting();
    }
    lightingState.scene = scene;
    initTransformGizmo(scene);
    lightingState.envSysShadow = envSysShadow;
    lightingState.triggerAutoSave = saveCb;

    lightingState.hemiLight = new HemisphericLight('hemi', new Vector3(0.5, 1, 0.5), scene);
    lightingState.hemiLight.intensity = 0.8;
    lightingState.hemiLight.diffuse = new Color3(1, 1, 1);
    lightingState.hemiLight.groundColor = new Color3(0.3, 0.3, 0.4);

    lightingState.dirLight = new DirectionalLight('dir', new Vector3(0, -1, 0), scene);
    lightingState.dirLight.intensity = 0.4;
    lightingState.dirLight.position = new Vector3(0, 40, 0);

    const def = _defaultStageLightState('light-1', '主光');
    const light = _createStageLight(def.type, def);
    lightingState.stageLights.set(def.id, { state: def, light, indicator: null, dirLine: null });
    lightingState.activeStageLightId = def.id;
    lightingState.stageLightCounter = 1;
    _updateIndicator(lightingState.stageLights.get(def.id)!);

    // 每帧更新光锥的相机位置 uniform（fresnel 计算需要）
    lightingState.coneUpdateHandle = observe(lightingState.scene.onBeforeRenderObservable, () => {
        const cam = lightingState.scene?.activeCamera;
        if (!cam) {
            return;
        }
        for (const [, cone] of lightingState.stageCones) {
            cone.material.setVector3('u_cameraPos', cam.position);
        }
    });

    // [doc:adr-192] 个人灯 tick 必须在骨骼 worldMatrix 更新后读取（onBeforeRender 时序）。
    // 时序契约固化于 mmd-adapter BoneFrameClock.onBoneMatricesUpdated（原逆工程注释已收口）。
    lightingState.personalLightTickHandle = onBoneMatricesUpdated(
        lightingState.scene,
        tickPersonalLights
    );

    // [doc:adr-168] 舞台灯追光 tick：更新绑定了 followTarget 的舞台灯
    // P1-fix: 保存句柄，disposeLighting 时显式释放（原 observe 返回值被丢弃导致泄漏）
    lightingState.stageFollowTickHandle = observe(
        lightingState.scene.onBeforeRenderObservable,
        tickStageLightFollow
    );
}

function _defaultLightState(): LightState {
    return {
        hemiIntensity: 0.8,
        dirIntensity: 0.4,
        dirX: 0,
        dirY: 1,
        dirZ: 0,
        dirColor: [1, 1, 1],
        hemiColor: [1, 1, 1],
        groundColor: [0.3, 0.3, 0.4],
        shadowEnabled: false,
        shadowType: 'soft',
        shadowCascades: 2,
        shadowResolution: 1024, // 新增
        shadowBias: 0.0001, // 新增
    };
}

/** [doc:adr-132] 当 envBrightness 变化时 rebake 存储的光照强度 */
export function rebakeEnvBrightness(ratio: number): void {
    if (!lightingState.hemiLight || !lightingState.dirLight || ratio <= 0) {
        return;
    }
    lightingState.hemiLight.intensity *= ratio;
    lightingState.dirLight.intensity *= ratio;
}

export function getLightState(): LightState {
    const envBrightness = Math.max(0.01, envState.globalBrightness ?? 1);
    if (!lightingState.hemiLight || !lightingState.dirLight || !lightingState.envSysShadow) {
        const base = _defaultLightState();
        return {
            ...base,
            shadowEnabled: lightingState.shadowEnabled,
            shadowType: lightingState.shadowType,
            shadowCascades: lightingState.shadowCascades,
            shadowResolution: lightingState.shadowResolution,
            shadowBias: lightingState.shadowBias,
        };
    }
    return {
        hemiIntensity: lightingState.hemiLight.intensity / envBrightness,
        dirIntensity: lightingState.dirLight.intensity / envBrightness,
        dirX: -lightingState.dirLight.direction.x,
        dirY: -lightingState.dirLight.direction.y,
        dirZ: -lightingState.dirLight.direction.z,
        dirColor: [
            lightingState.dirLight.diffuse.r,
            lightingState.dirLight.diffuse.g,
            lightingState.dirLight.diffuse.b,
        ],
        hemiColor: [
            lightingState.hemiLight.diffuse.r,
            lightingState.hemiLight.diffuse.g,
            lightingState.hemiLight.diffuse.b,
        ],
        groundColor: [
            lightingState.hemiLight.groundColor.r,
            lightingState.hemiLight.groundColor.g,
            lightingState.hemiLight.groundColor.b,
        ],
        shadowEnabled: lightingState.envSysShadow.generator !== null,
        shadowType: lightingState.shadowType,
        shadowCascades: lightingState.shadowCascades,
        shadowResolution: lightingState.shadowResolution, // 新增
        shadowBias: lightingState.shadowBias, // 新增
    };
}

export function setLightState(s: Partial<LightState>): void {
    if (!lightingState.hemiLight || !lightingState.dirLight || !lightingState.triggerAutoSave) {
        return;
    }

    const envBrightness = Math.max(0.01, envState.globalBrightness ?? 1);
    if (s.hemiIntensity !== undefined) {
        lightingState.hemiLight.intensity = s.hemiIntensity * envBrightness;
    }
    if (s.dirIntensity !== undefined) {
        lightingState.dirLight.intensity = s.dirIntensity * envBrightness;
    }
    if (s.dirX !== undefined || s.dirY !== undefined || s.dirZ !== undefined) {
        const dir = new Vector3(
            -(s.dirX ?? -lightingState.dirLight.direction.x),
            -(s.dirY ?? -lightingState.dirLight.direction.y),
            -(s.dirZ ?? -lightingState.dirLight.direction.z)
        );
        dir.normalize();
        lightingState.dirLight.direction = dir;
    }
    if (s.dirColor !== undefined) {
        lightingState.dirLight.diffuse = col3FromTriple(s.dirColor);
    }
    if (s.hemiColor !== undefined) {
        lightingState.hemiLight.diffuse = col3FromTriple(s.hemiColor);
    }
    if (s.groundColor !== undefined) {
        lightingState.hemiLight.groundColor = col3FromTriple(s.groundColor);
    }
    if (s.shadowEnabled !== undefined) {
        lightingState.shadowEnabled = s.shadowEnabled;
    }
    if (s.shadowType !== undefined) {
        lightingState.shadowType = s.shadowType;
    }
    let needRebuildShadow = false;
    if (s.shadowCascades !== undefined) {
        lightingState.shadowCascades = s.shadowCascades;
        needRebuildShadow = true;
    }
    if (s.shadowResolution !== undefined && s.shadowResolution !== lightingState.shadowResolution) {
        lightingState.shadowResolution = s.shadowResolution;
        needRebuildShadow = true;
    }
    if (s.shadowBias !== undefined) {
        lightingState.shadowBias = s.shadowBias;
        // 如果阴影生成器已存在，直接更新 bias（避免重建）
        if (lightingState.envSysShadow?.generator) {
            lightingState.envSysShadow.generator.bias = lightingState.shadowBias;
        } else {
            needRebuildShadow = true; // 还未创建，重建时会应用
        }
    }
    if (s.shadowEnabled !== undefined || s.shadowType !== undefined || needRebuildShadow) {
        _ensureShadow();
    }
    _updateSunDisc();
    if (!lightingState.skipLightAutoSave) {
        lightingState.triggerAutoSave();
        // 用户手动修改灯光/阴影设置：清除自动降级快照，避免 auto 模式后续降级覆盖用户意图。
        // applyDegrade 触发的 setLightState 通过 _suppressSnapshotReset 跳过，防止降级→恢复→再降级循环。
        if (!isSnapshotResetSuppressed()) {
            resetPerformanceSnapshot();
        }
    }
    scheduleRefresh();
}

/** 平滑过渡当前灯光到目标灯光参数，默认 2 秒 */
export function transitionLighting(
    target: Partial<LightState>,
    duration: number = 2000,
    onComplete?: () => void
): void {
    if (
        !lightingState.hemiLight ||
        !lightingState.dirLight ||
        !lightingState.triggerAutoSave ||
        !lightingState.scene
    ) {
        return;
    }
    const source = getLightState(); // 当前完整状态
    const startTime = performance.now();
    // 需要重建阴影生成器的参数 — 动画进行中跳，仅结束时一次性应用
    const rebuildShadowKeys = new Set<string>(['shadowResolution', 'shadowType', 'shadowEnabled']);

    // P4-fix: 取消任何在途过渡，避免重复调用堆叠多个渲染循环 observer（并发打架、旧动画覆盖新值）
    if (lightingState.activeTransitionObs) {
        lightingState.activeTransitionObs.dispose();
        lightingState.activeTransitionObs = null;
    }

    const animLoop = () => {
        // 防御：场景/主光已被销毁（disposeLighting 已清理）则立即退出并移除 observer，避免对已释放对象操作
        if (!lightingState.scene || !lightingState.hemiLight || !lightingState.dirLight) {
            lightingState.activeTransitionObs?.dispose();
            lightingState.activeTransitionObs = null;
            return;
        }
        const elapsed = performance.now() - startTime;
        const t = Math.min(elapsed / duration, 1.0);
        const lerp = (a: number, b: number) => a + (b - a) * t;

        const interpState: Partial<LightState> = {};
        // 仅对 target 中存在的字段插值
        for (const key of Object.keys(target) as (keyof LightState)[]) {
            // 跳过会触发每帧重建阴影生成器的参数，在动画结束时统一处理
            if (rebuildShadowKeys.has(key) && t < 1) {
                continue;
            }
            const a = source[key];
            const b = target[key];
            if (typeof a === 'number' && typeof b === 'number') {
                setKey(interpState, key, lerp(a, b) as LightState[typeof key]);
            } else if (Array.isArray(a) && Array.isArray(b)) {
                setKey(interpState, key, a.map((v, i) => lerp(v, b[i])) as LightState[typeof key]);
            } else {
                // 布尔等类型，在动画结束时才切换
                setKey(interpState, key, (t >= 1 ? b : a) as LightState[typeof key]);
            }
        }
        // 动画结束时一次性应用被跳过的阴影重建参数
        if (t >= 1) {
            for (const key of Object.keys(target) as (keyof LightState)[]) {
                if (rebuildShadowKeys.has(key)) {
                    setKey(interpState, key, target[key] as LightState[typeof key]);
                }
            }
        }
        setLightState(interpState);
        if (t >= 1) {
            // 动画结束，移除自身 observer
            lightingState.activeTransitionObs?.dispose();
            lightingState.activeTransitionObs = null;
            if (onComplete) {
                onComplete();
            }
        }
    };

    // 注册到渲染循环，每帧驱动插值
    lightingState.activeTransitionObs = observe(
        lightingState.scene.onBeforeRenderObservable,
        animLoop
    );
}

/** 整体清理光照模块（场景销毁时调用） */
export function disposeLighting(): void {
    _cancelAllLightingTweens();
    // P1-fix: 预设动画中途销毁场景时，被取消的 tween 不会触发 onTweenDone，
    // 必须显式重置标志，否则重新初始化后自动保存永久失效。
    lightingState.skipLightAutoSave = false;
    // 清理舞台灯（含各自的指示器/阴影/光锥）
    for (const [lid, entry] of lightingState.stageLights) {
        _disposeStageLightEntry(lid, entry);
    }
    lightingState.stageLights.clear();
    lightingState.stageShadows.clear();
    lightingState.stageCones.clear();
    if (lightingState.coneUpdateHandle) {
        lightingState.coneUpdateHandle.dispose();
        lightingState.coneUpdateHandle = null;
    }
    // [doc:adr-168] 释放个人灯 tick observer + 所有个人灯
    if (lightingState.personalLightTickHandle) {
        lightingState.personalLightTickHandle.dispose();
        lightingState.personalLightTickHandle = null;
    }
    disposeAllPersonalLights();
    // [doc:adr-168] 释放舞台灯追光 tick observer（P1-fix：原句柄未保存导致泄漏）
    if (lightingState.stageFollowTickHandle) {
        lightingState.stageFollowTickHandle.dispose();
        lightingState.stageFollowTickHandle = null;
    }
    // P4-fix: 释放在途主光过渡 observer，避免场景销毁后其仍挂在旧 scene 的渲染循环上
    if (lightingState.activeTransitionObs) {
        lightingState.activeTransitionObs.dispose();
        lightingState.activeTransitionObs = null;
    }
    lightingState.stageLightCounter = 0;
    lightingState.activeStageLightId = null;
    // 清理主灯光
    lightingState.hemiLight = safeDispose(lightingState.hemiLight);
    lightingState.dirLight = safeDispose(lightingState.dirLight);
    // 清理太阳盘（含材质释放，避免 StandardMaterial 泄漏）
    _disposeSunDisc();
    // 清理场景灯光的阴影生成器
    if (lightingState.envSysShadow?.generator) {
        lightingState.envSysShadow.generator = safeDispose(lightingState.envSysShadow.generator);
    }
    lightingState.scene = null;
    lightingState.triggerAutoSave = null;
    // 补全阴影参数重置：避免场景重建后携带上一场景的脏值
    lightingState.shadowEnabled = false;
    lightingState.shadowType = 'soft';
    lightingState.shadowCascades = 2;
    lightingState.shadowResolution = 1024;
    lightingState.shadowBias = 0.0001;
    lightingState.skipLightAutoSave = false;
}

// ======== barrel: 子文件公开 API 透传 ========

export * from './lighting-stage';
export * from './lighting-shadow';
export * from './lighting-sun';
export * from './lighting-tween';
export * from './lighting-follow';

// [doc:architecture] Performance Monitor — FPS 监控 + 自动降级
// 在渲染循环中调用，根据帧率自动调整渲染质量。
// 注意：模块级状态假定单例场景，不适用于多渲染上下文。

import type { LightState } from './lighting';
import type { RenderState } from './renderer';
import type { EnvState } from '@/core/config';
import { envState } from '@/core/config';
import { formatTimestamp } from '@/core/format-timestamp';
import { uiState, setUIState } from '@/core/state';
import type { UIState } from '@/core/types';
import { setAutoDegradingReflection, setEnvStateForPerformance } from './performance-env-bridge';
import { resolveQualityProfile } from './quality-profile';

// ======== 渲染桥接（ADR-159 P3-A：消除 performance↔scene 静态依赖）========
// 由 scene.ts 在 initScene() 时注入，单向依赖 scene → performance。
// 未注册时各成员为安全默认，避免 bridge 未就绪调用崩溃。

export interface RenderBridge {
    engine: { getFps: () => number };
    setLightState: (state: Partial<LightState>) => void;
    setRenderState: (state: Partial<RenderState>) => void;
    getLightState: () => LightState;
    getRenderState: () => RenderState;
}

let _bridgeEngine: { getFps: () => number } | null = null;
let _bridgeSetLightState: (state: Partial<LightState>) => void = () => {};
let _bridgeSetRenderState: (state: Partial<RenderState>) => void = () => {};
let _bridgeGetLightState: () => LightState = () => ({}) as LightState;
let _bridgeGetRenderState: () => RenderState = () => ({}) as RenderState;

/** ADR-159 P3-A：延迟绑定渲染桥接，由 scene.ts 在 initScene() 时注入。 */
export function registerRenderBridge(bridge: RenderBridge): void {
    _bridgeEngine = bridge.engine;
    _bridgeSetLightState = bridge.setLightState;
    _bridgeSetRenderState = bridge.setRenderState;
    _bridgeGetLightState = bridge.getLightState;
    _bridgeGetRenderState = bridge.getRenderState;
}

// ======== Types ========

export type PerformanceMode = 'auto' | 'quality' | 'balanced' | 'performance' | 'custom';

/** Degradation level applied when FPS drops. */
type DegradeLevel = 0 | 1 | 2 | 3;

// ======== State ========

let _mode: PerformanceMode = 'auto';
const _degradeCooldownMs = 3000; // 降级后冷却 3 秒（缩短以加快响应）
const _recoveryCooldownMs = 2000; // 恢复冷却 2 秒（缩短以加快响应）
let _lastDegradeTime = 0;
let _lastRecoveryTime = 0;
let _currentLevel: DegradeLevel = 0;

// FPS smoothing
const _fpsSamples: number[] = [];
// P3-fix: 采样窗口动态化，按参考刷新率 0.5s 计算，避免 120Hz 下窗口过短误触发降级
let _fpsSampleSize = 30; // 默认 60Hz × 0.5s，updatePerformance 中按 getReference() 重算
let _lastFpsLog = 0;
let _fpsReady = false; // 累积足够样本后设为 true

// Snapshot of settings before degradation (to restore to user's original state)
let _snapshot: {
    light: Partial<LightState>;
    render: Partial<RenderState>;
    env?: Partial<EnvState>;
} | null = null;

// 抑制标志：applyDegrade 调 setLightState/setRenderState 时置 true，防止
// setLightState/setRenderState 内部的 resetPerformanceSnapshot() 反向恢复快照，
// 形成「降级→恢复→再降级」的反馈循环。
let _suppressSnapshotReset = false;

// ======== renderScale 像素比杠杆（ADR-118 扩展）========
// 降级到 Level 2/3 时自动降低像素比至 0.7，是最有效的 GPU 减负杠杆。
// render-loop.ts 的 applyScaling() 会读取此乘数并与用户 renderScale 相乘。
let _perfRenderScaleMul = 1.0;

/** 降级系统对 renderScale 的乘数（1.0=无影响，0.7=降级时降至 70%）。 */
export function getPerfRenderScaleMul(): number {
    return _perfRenderScaleMul;
}

/** 供 setLightState/setRenderState 检查是否应跳过 resetPerformanceSnapshot。 */
export function isSnapshotResetSuppressed(): boolean {
    return _suppressSnapshotReset;
}

// ======== 每级完整目标状态 ========
// 定义每个质量级别下的渲染/光照配置全集。
// 降级时应用目标级别的完整状态；恢复时计算当前级别与目标级别的差集，仅应用变化。

interface LevelConfig {
    shadowResolution: number;
    shadowEnabled: boolean;
    bloomEnabled: boolean;
    dofEnabled: boolean;
    vignetteEnabled: boolean;
    fxaaEnabled: boolean;
    outlineEnabled: boolean;
    chromaticAberrationEnabled: boolean;
    grainEnabled: boolean;
    glowEnabled: boolean;
    ssaoEnabled: boolean;
    /** ADR-130 Phase 2.3: 统一质量档位，反射/云/粒子等从此派生 */
    qualityProfile?: 'high' | 'medium' | 'low';
    label: string;
}

/** 反射质量档位序（降级上限守卫用：off < low < medium < high） */
const REFLECTION_QUALITY_ORDER: Record<string, number> = { off: 0, low: 1, medium: 2, high: 3 };

const LEVEL_CONFIGS: Record<DegradeLevel, LevelConfig> = {
    0: {
        shadowResolution: 2048,
        shadowEnabled: true,
        bloomEnabled: true,
        dofEnabled: true,
        vignetteEnabled: true,
        fxaaEnabled: true,
        outlineEnabled: true,
        chromaticAberrationEnabled: true,
        grainEnabled: true,
        glowEnabled: true,
        ssaoEnabled: true,
        qualityProfile: 'high',
        label: '正常',
    },
    1: {
        shadowResolution: 512,
        shadowEnabled: true,
        // P3-fix: DoF 需要深度图开销最重，Level 1 优先关 DoF 保留轻量 bloom
        bloomEnabled: true,
        dofEnabled: false,
        vignetteEnabled: true,
        fxaaEnabled: true,
        outlineEnabled: true,
        chromaticAberrationEnabled: false,
        grainEnabled: false,
        glowEnabled: false,
        ssaoEnabled: true,
        qualityProfile: 'medium',
        label: '轻度降级',
    },
    2: {
        shadowResolution: 512,
        shadowEnabled: false,
        bloomEnabled: false,
        dofEnabled: false,
        vignetteEnabled: false,
        fxaaEnabled: false,
        outlineEnabled: true,
        chromaticAberrationEnabled: false,
        grainEnabled: false,
        glowEnabled: false,
        ssaoEnabled: false,
        qualityProfile: 'low',
        label: '中度降级',
    },
    3: {
        shadowResolution: 512,
        shadowEnabled: false,
        bloomEnabled: false,
        dofEnabled: false,
        vignetteEnabled: false,
        fxaaEnabled: false,
        outlineEnabled: false,
        chromaticAberrationEnabled: false,
        grainEnabled: false,
        glowEnabled: false,
        ssaoEnabled: false,
        qualityProfile: 'low',
        label: '重度降级',
    },
};

/** 比较两个级别配置，返回从 prev 切换到 next 所需的变化集合。 */
function levelDiff(
    prev: LevelConfig,
    next: LevelConfig
): { light: Partial<LightState>; render: Partial<RenderState>; env?: Partial<EnvState> } {
    const light: Partial<LightState> = {};
    const render: Partial<RenderState> = {};
    const env: Partial<EnvState> = {};
    if (prev.shadowResolution !== next.shadowResolution) {
        light.shadowResolution = next.shadowResolution;
    }
    if (prev.shadowEnabled !== next.shadowEnabled) {
        light.shadowEnabled = next.shadowEnabled;
    }
    if (prev.bloomEnabled !== next.bloomEnabled) {
        render.bloomEnabled = next.bloomEnabled;
    }
    if (prev.dofEnabled !== next.dofEnabled) {
        render.dofEnabled = next.dofEnabled;
    }
    if (prev.vignetteEnabled !== next.vignetteEnabled) {
        render.vignetteEnabled = next.vignetteEnabled;
    }
    if (prev.fxaaEnabled !== next.fxaaEnabled) {
        render.fxaaEnabled = next.fxaaEnabled;
    }
    if (prev.outlineEnabled !== next.outlineEnabled) {
        render.outlineEnabled = next.outlineEnabled;
    }
    if (prev.chromaticAberrationEnabled !== next.chromaticAberrationEnabled) {
        render.chromaticAberrationEnabled = next.chromaticAberrationEnabled;
    }
    if (prev.grainEnabled !== next.grainEnabled) {
        render.grainEnabled = next.grainEnabled;
    }
    if (prev.glowEnabled !== next.glowEnabled) {
        render.glowEnabled = next.glowEnabled;
    }
    if (prev.ssaoEnabled !== next.ssaoEnabled) {
        render.ssaoEnabled = next.ssaoEnabled;
    }
    // ADR-130 Phase 2.3: 统一质量档位
    // 注意：不传播 qualityProfile 本身——它只由用户手动更改，auto-degrade 只动子字段，
    // 避免「用户设 reflectionQuality=off，degrade 后 qualityProfile 漂移为 low」的漂移 bug。
    if (next.qualityProfile) {
        const prevR = resolveQualityProfile(prev.qualityProfile || 'high');
        const nextR = resolveQualityProfile(next.qualityProfile);
        if (prevR.reflectionQuality !== nextR.reflectionQuality) {
            env.reflectionQuality = nextR.reflectionQuality;
        }
        if (prevR.cloudQuality !== nextR.cloudQuality) {
            env.cloudQuality = nextR.cloudQuality;
        }
        if (prevR.particleQuality !== nextR.particleQuality) {
            env.particleQuality = nextR.particleQuality;
        }
    }
    return { light, render, env };
}

// ======== Apply Degradation ========

/**
 * 恢复快照到用户原始设置的公共逻辑（applyDegrade level=0 与 resetPerformanceSnapshot 共用）。
 * 先提取 + 清空 `_snapshot` 再应用，避免 setLightState → resetPerformanceSnapshot 死循环；
 * 全程置 `_suppressSnapshotReset` 防止反向恢复反馈。
 * @returns 是否存在快照（存在才实际执行了恢复）
 */
function _restoreSnapshot(): boolean {
    if (!_snapshot) {
        return false;
    }
    const light = _snapshot.light;
    const render = _snapshot.render;
    const snapEnv = _snapshot.env;
    _snapshot = null;
    _suppressSnapshotReset = true;
    try {
        _bridgeSetLightState(light);
        _bridgeSetRenderState(render);
        if (snapEnv && Object.keys(snapEnv).length > 0) {
            setAutoDegradingReflection(true);
            try {
                setEnvStateForPerformance(snapEnv, true);
            } finally {
                setAutoDegradingReflection(false);
            }
        }
    } finally {
        _suppressSnapshotReset = false;
    }
    // 恢复 renderScale 乘数
    _perfRenderScaleMul = 1.0;
    return true;
}

/**
 * 应用指定级别的降级/恢复。
 * @param level 目标级别
 * @param force 若为 true，绕过冷却检查（用于强制模式切换）
 */
function applyDegrade(level: DegradeLevel, force = false): void {
    if (level === _currentLevel) {
        return;
    }

    const now = performance.now();

    // 冷却检查：强制模式（来自 setPerformanceMode）绕过冷却
    if (!force) {
        if (level > _currentLevel) {
            // 降级方向：受 degrade cooldown 限制
            if (now - _lastDegradeTime < _degradeCooldownMs) {
                return;
            }
        } else {
            // 恢复方向：受 recovery cooldown 限制，防止帧率抖动
            if (now - _lastRecoveryTime < _recoveryCooldownMs) {
                return;
            }
        }
    }

    // 首次降级时保存快照（用户原始设置）
    if (!_snapshot && level > 0) {
        _snapshot = {
            light: _bridgeGetLightState(),
            render: _bridgeGetRenderState(),
            env: {
                qualityProfile: envState.qualityProfile,
                reflectionQuality: envState.reflectionQuality,
                cloudQuality: envState.cloudQuality,
                particleQuality: envState.particleQuality,
            },
        };
    }

    // 恢复到 Level 0：使用快照还原用户原始设置
    if (level === 0 && _snapshot) {
        _restoreSnapshot();
        _currentLevel = 0;
        _lastRecoveryTime = now;
        if (import.meta.env.DEV) {
            console.info(`[${formatTimestamp()}] [Performance] Restored to full quality`);
        }
        return;
    }

    // 恢复到 0 但无快照：无需操作
    if (level === 0 && !_snapshot) {
        _currentLevel = 0;
        return;
    }

    // 计算当前级别配置与目标级别配置的差集
    const prevCfg = LEVEL_CONFIGS[_currentLevel];
    const nextCfg = LEVEL_CONFIGS[level];
    const changes = levelDiff(prevCfg, nextCfg);

    if (Object.keys(changes.light).length > 0 || Object.keys(changes.render).length > 0) {
        _suppressSnapshotReset = true;
        try {
            if (Object.keys(changes.light).length > 0) {
                _bridgeSetLightState(changes.light);
            }
            if (Object.keys(changes.render).length > 0) {
                _bridgeSetRenderState(changes.render);
            }
        } finally {
            _suppressSnapshotReset = false;
        }
    }

    // ADR-151 收口：反射降级上限守卫 —— 降级目标不得高于用户原始 reflectionQuality，
    // 避免「用户关了反射，降级却把反射打开」的反直觉行为。
    if (changes.env && changes.env.reflectionQuality !== undefined) {
        const userQ = _snapshot?.env?.reflectionQuality;
        if (userQ !== undefined) {
            if (
                (REFLECTION_QUALITY_ORDER[changes.env.reflectionQuality] ?? 0) >
                (REFLECTION_QUALITY_ORDER[userQ] ?? 0)
            ) {
                changes.env.reflectionQuality = userQ;
            }
        }
    }

    // ADR-130 Phase 2.3: 反射质量联动（水面/地面）
    if (changes.env && Object.keys(changes.env).length > 0) {
        setAutoDegradingReflection(true);
        try {
            setEnvStateForPerformance(changes.env, true);
        } finally {
            setAutoDegradingReflection(false);
        }
    }

    const prevLevel = _currentLevel;
    _currentLevel = level;

    if (level > prevLevel) {
        // 实际发生了降级
        _lastDegradeTime = now;
    } else {
        // 实际发生了恢复
        _lastRecoveryTime = now;
    }

    // renderScale 像素比杠杆：Level 2/3 自动降至 0.7，Level 0/1 恢复 1.0
    const targetMul = level >= 2 ? 0.7 : 1.0;
    if (_perfRenderScaleMul !== targetMul) {
        _perfRenderScaleMul = targetMul;
        if (import.meta.env.DEV) {
            console.info(`[${formatTimestamp()}] [Performance] renderScale mul → ${targetMul}`);
        }
    }
    if (import.meta.env.DEV) {
        console.info(
            `[${formatTimestamp()}] [Performance] Level ${level}: ${LEVEL_CONFIGS[level].label}`
        );
    }
}

// ======== Thresholds with Hysteresis ========

// Phase 1: 刷新率感知——将阈值按 refRate/60 缩放，使高刷设备获得正确校准。
// 60Hz 下 RSCALE=1，行为与历史完全一致（零回归）。
// Phase 2: 运行时峰值校准——启动后 ~3s 预热期后滚动 maxFPS 作为 observedCeiling，
// 综合基准 reference = max(hardwareRefRate, observedCeiling) 防止首帧卡顿污染天花板。
// `screen.refreshRate` 是非标准属性（仅部分 Chromium/特供浏览器暴露，WebView2 运行时不支持），
// 故以异常安全方式读取，缺失/非有限正数/访问异常时一律回退 60Hz。
interface ScreenWithRefreshRate extends Screen {
    refreshRate?: number;
}
function detectRefreshRate(): number {
    try {
        const r = (window.screen as ScreenWithRefreshRate).refreshRate;
        if (typeof r === 'number' && Number.isFinite(r) && r > 0) {
            return r;
        }
    } catch {
        // screen 在受限环境不可访问，走下方默认
    }
    return 60;
}
function clampRate(v: number, lo: number, hi: number): number {
    return Math.min(hi, Math.max(lo, v));
}

// ===== Phase 2: 运行时峰值校准 =====

/** 硬件刷新率（模块加载时定一次，resize 时可重读）。 */
let _hardwareRefRate = clampRate(detectRefreshRate(), 30, 240);

/** 稳态滚动 maxFPS（预热期后开始累积）。 */
let _steadyMaxFps = 0;

/** 运行时观测峰值，用于综合基准计算。 */
let _observedCeiling = 0;

/** 预热期标志：启动后前 ~3s 不追踪天花板，避免首帧卡顿污染。 */
let _warmup = true;

/** 预热开始时间戳。 */
let _warmupStartTime = 0;

/** 综合基准参考值：取硬件刷新率与观测峰值的较大者，上限 240 防止空场景 FPS 飙升永久禁用降级。 */
function getReference(): number {
    return Math.min(Math.max(_hardwareRefRate, _observedCeiling), 240);
}

/** 阈值缩放因子：reference / 60。 */
function getRScale(): number {
    return getReference() / 60;
}

/** 降级阈值（帧率低于此值则降级），按 reference 动态缩放。 */
function getDegradeThreshold(level: DegradeLevel): number {
    // P3-fix: 28fps 已明显卡顿（用户感知阈值约 30fps），上调至 32/24/16
    // 60Hz→32/24/16；120Hz→64/48/32
    return [Infinity, 32, 24, 16][level] * getRScale();
}

/** 恢复阈值（帧率高于此值才允许恢复），按 reference 动态缩放。 */
function getRecoveryThreshold(level: DegradeLevel): number {
    // P3-fix: 扩大滞回带防抖动，38/28/20
    // 60Hz→38/28/20；120Hz→76/56/40
    return [Infinity, 38, 28, 20][level] * getRScale();
}

/**
 * 重新计算刷新率基准（外接显示器变化时由 render-loop resize 触发）。
 * 仅当硬件刷新率实际下降时收敛 ceiling，避免 WebView2 回退 60Hz 误钳高刷 ceiling。
 */
export function recalcPerformanceReference(): void {
    const prev = _hardwareRefRate;
    _hardwareRefRate = clampRate(detectRefreshRate(), 30, 240);
    if (_hardwareRefRate < prev) {
        const cap = _hardwareRefRate * 1.1;
        if (_observedCeiling > cap) {
            _observedCeiling = cap;
            _steadyMaxFps = cap;
        }
    }
}

// ======== Public API ========

/**
 * 每帧调用（渲染循环内）。
 * 采集平滑 FPS 并根据帧率触发降级/恢复。
 */
export function updatePerformance(): void {
    if (_mode === 'quality' || _mode === 'custom') {
        return;
    }
    // ADR-159 P3-A：bridge 未注册（initScene 尚未完成）时安全跳过，不触发降级
    if (!_bridgeEngine) {
        return;
    }

    // 采集 FPS 样本
    const fps = _bridgeEngine.getFps();
    // P3-fix: 按 reference 动态调整采样窗口（0.5s 窗口），高刷设备不误触发
    const targetSampleSize = Math.max(15, Math.round(getReference() * 0.5));
    if (targetSampleSize !== _fpsSampleSize) {
        _fpsSampleSize = targetSampleSize;
    }
    _fpsSamples.push(fps);
    if (_fpsSamples.length > _fpsSampleSize) {
        _fpsSamples.shift();
    }

    // Issue #7: 累积足够样本后再开始评估
    if (!_fpsReady) {
        if (_fpsSamples.length >= _fpsSampleSize) {
            _fpsReady = true;
        } else {
            return; // 样本不足，跳过
        }
    }

    // 每 ~500ms 评估一次，避免抖动
    const now = performance.now();
    if (now - _lastFpsLog < 500) {
        return;
    }
    _lastFpsLog = now;

    const avgFps = _fpsSamples.reduce((a, b) => a + b, 0) / _fpsSamples.length;

    // Phase 2: 运行时峰值校准（预热期后滚动 maxFPS）
    if (_warmup) {
        if (_warmupStartTime === 0) {
            _warmupStartTime = now;
        } else if (now - _warmupStartTime > 3000) {
            _warmup = false;
            _steadyMaxFps = avgFps;
        }
    } else {
        if (avgFps > _steadyMaxFps) {
            _steadyMaxFps = avgFps;
        } else {
            _steadyMaxFps = Math.max(avgFps, _steadyMaxFps * 0.998);
        }
        _observedCeiling = _steadyMaxFps;
    }

    // 确定目标级别
    let targetLevel: DegradeLevel;
    if (_mode === 'performance') {
        targetLevel = 2;
    } else if (_mode === 'balanced') {
        targetLevel = 1;
    } else {
        // Auto 模式：以当前级别为锚点，严格双阈值滞回
        // - 降级：当 FPS 低于下一级的降级阈值，则降一级
        // - 恢复：当 FPS 高于当前级别的恢复阈值，则升一级
        // - 两端互不干扰，避免阈值附近的来回跳变
        targetLevel = _currentLevel;
        if (
            _currentLevel < 3 &&
            avgFps < getDegradeThreshold((_currentLevel + 1) as DegradeLevel)
        ) {
            targetLevel = (_currentLevel + 1) as DegradeLevel;
        } else if (
            _currentLevel > 0 &&
            avgFps > getRecoveryThreshold(_currentLevel as DegradeLevel)
        ) {
            targetLevel = (_currentLevel - 1) as DegradeLevel;
        }
    }

    applyDegrade(targetLevel);
}

/**
 * 设置性能模式。
 * - "auto": 监控 FPS 自动降级/恢复
 * - "quality": 强制最高质量，永不降级
 * - "balanced": 强制 Level 1 降级
 * - "performance": 强制 Level 2 降级
 * - "custom": 冻结当前 RenderState/LightState 为用户权威配置，停止自动降级
 */
export function setPerformanceMode(mode: PerformanceMode): void {
    _mode = mode;

    // [fix:ghost-state] 同步 uiState.performanceMode 并触发持久化，
    // 修复原「用户切换模式只写 _mode、uiState 不变」导致重启后设置丢失的漂移。
    // setUIState 内部 Object.assign 合并字段 + 调用 _uiPersistCb 持久化。
    if (uiState.performanceMode !== mode) {
        setUIState({ performanceMode: mode } as UIState);
    }

    // Issue #2: 强制模式调用时绕过冷却
    if (mode === 'quality') {
        applyDegrade(0, true);
    } else if (mode === 'balanced') {
        applyDegrade(1, true);
    } else if (mode === 'performance') {
        applyDegrade(2, true);
    } else if (mode === 'custom') {
        // Custom 模式：冻结当前渲染/光照状态为权威配置。
        // 恢复自动降级遗留的快照（若有），使后续不再被降级覆盖；
        // updatePerformance 已在 custom 模式下早返，不会再次降级。
        resetPerformanceSnapshot();
    }
    if (import.meta.env.DEV) {
        console.info(`[${formatTimestamp()}] [Performance] Mode set to: ${mode}`);
    }
}

export function getPerformanceMode(): PerformanceMode {
    return _mode;
}

export function getCurrentDegradeLevel(): DegradeLevel {
    return _currentLevel;
}

/**
 * 重置性能快照（用户手动修改渲染/光照设置后调用）。
 * Issue #4: 重置前先恢复到全质量，避免状态卡死在降级画质。
 */
export function resetPerformanceSnapshot(): void {
    _restoreSnapshot();
    _currentLevel = 0;
    _lastDegradeTime = 0;
    _lastRecoveryTime = 0;
}

// [doc:architecture] Scene Renderer — 渲染管线、后处理、渲染状态
// 职责: DefaultRenderingPipeline 管理、后处理开关、场景背景色、边缘高亮
// 注意: 从 scene.ts 静态导入但仅在函数体内访问，ES module live binding 保证安全。

